@dataclass
class Vector2D:
    x: float = 0.0
    y: float = 0.0

    def __add__(self, other):
        return Vector2D(self.x + other.x, self.y + other.y)

    def __sub__(self, other):
        return Vector2D(self.x - other.x, self.y - other.y)

    def __mul__(self, scalar):
        return Vector2D(self.x * scalar, self.y * scalar)

    def __truediv__(self, scalar):
        if scalar == 0:
            return Vector2D(0, 0)
        return Vector2D(self.x / scalar, self.y / scalar)

    def magnitude(self):
        return math.sqrt(self.x**2 + self.y**2)

    def normalize(self):
        mag = self.magnitude()
        if mag == 0:
            return Vector2D(0, 0)
        return self / mag

    def distance_to(self, other):
        return (self - other).magnitude()

    def copy(self):
        return Vector2D(self.x, self.y)

@dataclass
class Robot:
    id: int
    team: Team
    role: Role
    position: Vector2D
    velocity: Vector2D = field(default_factory=lambda: Vector2D(0, 0))
    health: float = 100.0
    max_health: float = 100.0
    shield: float = 0.0
    max_shield: float = 50.0
    speed: float = 150.0
    weapon: 'Weapon' = None
    cooldown: float = 0.0
    last_action_time: float = 0.0
    vision_radius: float = 200.0
    is_alive: bool = True
    objectives: List[ObjectiveType] = field(default_factory=list)
    strategy_memory: List[Dict] = field(default_factory=list)
    learning_rate: float = 0.1
    experience: float = 0.0
    team_cooperation_score: float = 0.0
    last_seen_enemies: List[int] = field(default_factory=list)
    last_heard_sounds: List[str] = field(default_factory=list)
    power_ups: Dict[PowerUpType, float] = field(default_factory=dict)

    def __post_init__(self):
        if self.weapon is None:
            # Default weapon based on role
            if self.role == Role.ATTACKER:
                self.weapon = Weapon(WeaponType.RANGED, 25, 1.0, 10, "Rifle")
            elif self.role == Role.DEFENDER:
                self.weapon = Weapon(WeaponType.MELEE, 40, 2.0, 5, "Hammer")
            elif self.role == Role.SUPPORT:
                self.weapon = Weapon(WeaponType.SUPPORT, 0, 3.0, 0, "MedKit")
            elif self.role == Role.Scout:
                self.weapon = Weapon(WeaponType.RANGED, 20, 0.8, 15, "Sniper")
            else:  # CONTROLLER
                self.weapon = Weapon(WeaponType.EXPLOSIVE, 30, 1.5, 8, "Grenade")

        # Initialize power-ups
        self.power_ups = {power: 0.0 for power in PowerUpType}

    def take_damage(self, damage: float) -> float:
        """Apply damage to robot, considering shield"""
        if self.shield > 0:
            shield_absorbed = min(damage, self.shield)
            self.shield -= shield_absorbed
            damage -= shield_absorbed

        if damage > 0:
            self.health -= damage
            if self.health <= 0:
                self.is_alive = False
                self.health = 0

        return damage

    def heal(self, amount: float):
        """Heal the robot"""
        self.health = min(self.max_health, self.health + amount)

    def apply_power_up(self, power_type: PowerUpType, duration: float):
        """Apply a power-up effect"""
        self.power_ups[power_type] = duration

    def update_power_ups(self, delta_time: float):
        """Update power-up timers"""
        for power_type in list(self.power_ups.keys()):
            if self.power_ups[power_type] > 0:
                self.power_ups[power_type] -= delta_time
                if self.power_ups[power_type] <= 0:
                    self.remove_power_up(power_type)

    def remove_power_up(self, power_type: PowerUpType):
        """Remove a power-up effect"""
        if power_type == PowerUpType.SPEED:
            self.speed = self.speed / 1.5  # Return to base speed
        elif power_type == PowerUpType.DAMAGE:
            self.weapon.damage = self.weapon.base_damage
        elif power_type == PowerUpType.SHIELD:
            self.max_shield = 50.0
            self.shield = min(self.shield, self.max_shield)
        self.power_ups[power_type] = 0.0

    def get_effective_speed(self) -> float:
        """Get current speed with power-up modifiers"""
        speed = self.speed
        if self.power_ups[PowerUpType.SPEED] > 0:
            speed *= 1.5
        return speed

    def get_effective_damage(self) -> float:
        """Get current damage with power-up modifiers"""
        damage = self.weapon.damage
        if self.power_ups[PowerUpType.DAMAGE] > 0:
            damage *= 1.5
        return damage

    def can_attack(self) -> bool:
        """Check if robot can attack based on cooldown"""
        return self.cooldown <= 0

    def update(self, delta_time: float):
        """Update robot state"""
        # Update cooldown
        if self.cooldown > 0:
            self.cooldown -= delta_time

        # Update power-ups
        self.update_power_ups(delta_time)

        # Apply power-up effects
        if self.power_ups[PowerUpType.SPEED] > 0:
            self.speed = 225.0  # 50% speed boost
        else:
            self.speed = 150.0

        if self.power_ups[PowerUpType.DAMAGE] > 0:
            self.weapon.damage = self.weapon.base_damage * 1.5
        else:
            self.weapon.damage = self.weapon.base_damage

        if self.power_ups[PowerUpType.SHIELD] > 0:
            self.max_shield = 75.0
            if self.shield > self.max_shield:
                self.shield = self.max_shield
        else:
            self.max_shield = 50.0

        # Regenerate health if power-up active
        if self.power_ups[PowerUpType.REGEN] > 0:
            self.heal(0.5 * delta_time)

        # Random behavior for idle robots
        if self.is_alive and random.random() < 0.01 and len(self.last_seen_enemies) == 0:
            self.velocity = Vector2D(
                random.uniform(-1, 1), 
                random.uniform(-1, 1)
            ).normalize() * self.get_effective_speed()

    def __str__(self):
        return f"Robot({self.id}, {self.team.value}, {self.role.value}, HP:{self.health:.1f}, SH:{self.shield:.1f})"

@dataclass
class Weapon:
    type: WeaponType
    damage: float
    fire_rate: float  # seconds between shots
    range: float
    name: str
    base_damage: float = 0.0

    def __post_init__(self):
        self.base_damage = self.damage

    def can_fire(self, last_fired: float, current_time: float) -> bool:
        return current_time - last_fired >= self.fire_rate

@dataclass
class Objective:
    type: ObjectiveType
    position: Vector2D
    team: Team
    captured_by: Optional[Team] = None
    progress: float = 0.0
    required_progress: float = 100.0
    radius: float = 30.0
    is_active: bool = True

    def update(self, delta_time: float, robots: List[Robot]):
        """Update progress based on nearby robots"""
        if not self.is_active:
            return

        nearby_robots = [
            robot for robot in robots 
            if robot.is_alive and robot.position.distance_to(self.position) <= self.radius + 50
        ]

        if self.type == ObjectiveType.FLAG_CAPTURE:
            # Flag capture: robots of the same team as objective team increase progress
            friendly_count = sum(1 for r in nearby_robots if r.team == self.team)
            enemy_count = sum(1 for r in nearby_robots if r.team != self.team and r.team != Team.NEUTRAL)

            if friendly_count > 0:
                # Increase progress if friendly robots are present
                self.progress += friendly_count * 2 * delta_time
                # Decrease if enemy robots are present
                self.progress -= enemy_count * 1.5 * delta_time
            elif enemy_count > 0:
                # Enemies can capture if no friendlies
                self.progress -= 2 * delta_time

            self.progress = max(0, min(self.required_progress, self.progress))

            # If captured by a different team
            if self.progress >= self.required_progress:
                self.captured_by = self.team
                self.progress = self.required_progress
            elif self.progress <= 0:
                self.captured_by = None
                self.progress = 0

        elif self.type == ObjectiveType.BASE_DEFENSE:
            # Base defense: progress represents base integrity
            # Enemies attacking decrease progress, friendlies defend and increase
            enemy_attacking = any(
                r for r in nearby_robots 
                if r.team != self.team and r.team != Team.NEUTRAL
            )
            friendly_defending = any(
                r for r in nearby_robots 
                if r.team == self.team
            )

            if enemy_attacking and not friendly_defending:
                self.progress -= 2 * delta_time
            elif friendly_defending:
                self.progress += 0.2 * delta_time

            self.progress = max(0, min(self.required_progress, self.progress))

            if self.progress <= 0:
                self.captured_by = [r.team for r in nearby_robots if r.team != self.team and r.team != Team.NEUTRAL][0] if nearby_robots else None
                self.is_active = False
            elif self.progress >= self.required_progress and self.captured_by != self.team:
                self.captured_by = self.team

        elif self.type == ObjectiveType.ESCAPE_PAYLOAD:
            # Payload escort: progress represents distance traveled
            # Only friendly robots can push payload
            friendly_robots = [r for r in nearby_robots if r.team == self.team]
            if friendly_robots:
                # Calculate average direction of friendly robots
                avg_direction = Vector2D()
                for r in friendly_robots:
                    direction = (r.position - self.position).normalize()
                    avg_direction += direction
                avg_direction = avg_direction.normalize() if len(friendly_robots) > 0 else Vector2D()

                # Move payload in average direction
                self.position += avg_direction * 50 * delta_time
                self.progress += 1.5 * len(friendly_robots) * delta_time

            self.progress = max(0, min(self.required_progress, self.progress))

            if self.progress >= self.required_progress:
                self.captured_by = self.team
                self.is_active = False

    def get_status(self) -> str:
        """Return string representation of objective status"""
        if self.captured_by:
            return f"Captured by {self.captured_by.value}"
        elif self.progress > 0:
            return f"Progress: {self.progress:.1f}%"
        else:
            return "Uncaptured"

@dataclass
class PowerUp:
    type: PowerUpType
    position: Vector2D
    duration: float = 10.0
    active: bool = True
    spawn_time: float = 0.0
    radius: float = 20.0

    def __post_init__(self):
        self.spawn_time = time.time()

    def is_collected(self, robot: Robot) -> bool:
        """Check if robot has collected this power-up"""
        if not self.active:
            return False
        return robot.position.distance_to(self.position) <= self.radius + robot.vision_radius / 2

@dataclass
class EnvironmentalHazard:
    type: str  # "laser", "electric", "toxic", "gravity"
    position: Vector2D
    radius: float
    damage_per_second: float
    active: bool = True
    duration: float = 0.0
    spawn_time: float = 0.0

    def __post_init__(self):
        self.spawn_time = time.time()

    def affects_robot(self, robot: Robot) -> bool:
        """Check if robot is affected by this hazard"""
        if not self.active:
            return False
        return robot.position.distance_to(self.position) <= self.radius + 10

