# ==============================
# AI BEHAVIOR SYSTEM
# ==============================

class AIController:
    def __init__(self, robot: Robot, game_state: 'CyberArena'):
        self.robot = robot
        self.game_state = game_state
        self.target: Optional[Vector2D] = None
        self.current_strategy: str = "patrol"
        self.strategy_history: deque = deque(maxlen=10)
        self.last_update_time = 0

    def update(self, delta_time: float) -> None:
        """Update AI behavior based on game state"""
        self.last_update_time += delta_time

        # Only update every 0.5 seconds to reduce computation
        if self.last_update_time < 0.5:
            return
        self.last_update_time = 0

        # If robot is dead, do nothing
        if not self.robot.is_alive:
            return

        # Update strategy based on learning and current situation
        self._evaluate_strategy()

        # Execute current strategy
        self._execute_strategy()

        # Learn from experience
        self._learn_from_experience()

    def _evaluate_strategy(self) -> None:
        """Determine the best strategy based on current game state"""
        if not self.robot.is_alive:
            self.current_strategy = "dead"
            return

        # Get relevant game state information
        enemies = self.game_state.get_alive_enemies(self.robot.team)
        allies = self.game_state.get_alive_allies(self.robot.team)
        objectives = self.game_state.objectives
        power_ups = self.game_state.power_ups
        hazards = self.game_state.hazards

        # If no enemies, patrol or assist
        if len(enemies) == 0:
            # Look for objectives to capture or defend
            nearest_objective = self._find_nearest_objective(objectives, self.robot.team)
            if nearest_objective and nearest_objective.captured_by != self.robot.team:
                # If objective is uncaptured, try to capture it
                self.current_strategy = "capture_objective"
                self.target = nearest_objective.position
            else:
                # Patrol between key points
                self.current_strategy = "patrol"
                self.target = self._get_patrol_point()

            # Check for power-ups
            nearest_power_up = self._find_nearest_power_up(power_ups)
            if nearest_power_up:
                self.target = nearest_power_up.position
                self.current_strategy = "grab_power_up"

        # If enemies nearby, decide based on role
        elif len(enemies) > 0:
            # Find nearest enemy
            nearest_enemy = self._find_nearest_enemy(enemies)

            # Role-based decisions
            if self.robot.role == Role.ATTACKER:
                # Aggressive attack
                self.current_strategy = "attack"
                self.target = nearest_enemy.position if nearest_enemy else self._get_random_enemy_position()

            elif self.robot.role == Role.DEFENDER:
                # Defend objectives or teammates
                if self._is_defending_needs(self.robot, objectives):
                    # Defend a key objective
                    objective_to_defend = self._find_nearest_defense_objective(objectives, self.robot.team)
                    if objective_to_defend:
                        self.current_strategy = "defend_objective"
                        self.target = objective_to_defend.position
                    else:
                        # Defend nearest ally
                        if allies:
                            nearest_allied = self._find_nearest_allied(allies)
                            self.current_strategy = "defend_ally"
                            self.target = nearest_allied.position
                        else:
                            self.current_strategy = "attack"
                            self.target = nearest_enemy.position

            elif self.robot.role == Role.SUPPORT:
                # Heal allies or provide support
                if allies:
                    lowest_health_ally = self._find_lowest_health_ally(allies)
                    if lowest_health_ally and lowest_health_ally.health < lowest_health_ally.max_health * 0.7:
                        self.current_strategy = "heal_ally"
                        self.target = lowest_health_ally.position
                    else:
                        # Support by attacking or capturing
                        if len(enemies) > 2:
                            self.current_strategy = "attack"
                            self.target = nearest_enemy.position
                        else:
                            self.current_strategy = "capture_objective"
                            self.target = self._find_nearest_objective(objectives, self.robot.team).position
                else:
                    # No allies to support, attack
                    self.current_strategy = "attack"
                    self.target = nearest_enemy.position

            elif self.robot.role == Role.SCAT:
                # Scout: investigate and report
                self.current_strategy = "scout"
                self.target = nearest_enemy.position if nearest_enemy else self._find_nearest_unexplored_area()

            elif self.robot.role == Role.CONTROLLER:
                # Control areas, use explosives
                if len(enemies) > 1:
                    # Use area damage
                    enemy_cluster_center = self._find_enemy_cluster_center(enemies)
                    self.current_strategy = "area_control"
                    self.target = enemy_cluster_center
                else:
                    # Attack or support
                    self.current_strategy = "attack"
                    self.target = nearest_enemy.position

            # Check for power-ups
            nearest_power_up = self._find_nearest_power_up(power_ups)
            if nearest_power_up:
                # Check if power-up is more important than current target
                if (nearest_power_up.type == PowerUpType.HEALTH and self.robot.health < self.robot.max_health * 0.6) or \
                   (nearest_power_up.type == PowerUpType.SHIELD and self.robot.shield < self.robot.max_shield * 0.3) or \
                   (nearest_power_up.type == PowerUpType.SPEED and len(enemies) > 0):
                    self.target = nearest_power_up.position
                    self.current_strategy = "grab_power_up"

        # Check for hazards
        nearby_hazards = [h for h in hazards if h.affects_robot(self.robot)]
        if nearby_hazards:
            # Avoid hazards
            hazard = nearby_hazards[0]
            # Move perpendicular to hazard center
            direction = (self.robot.position - hazard.position).normalize()
            self.target = self.robot.position + direction * 100
            self.current_strategy = "avoid_hazard"

    def _execute_strategy(self) -> None:
        """Execute current strategy by setting robot's movement and actions"""
        if not self.robot.is_alive:
            return

        # Reset velocity
        self.robot.velocity = Vector2D(0, 0)

        # Determine target position
        if self.target is not None:
            # Calculate direction to target
            direction = (self.target - self.robot.position).normalize()

            # Apply movement
            speed = self.robot.get_effective_speed()
            self.robot.velocity = direction * speed

            # Check if close enough to perform action
            distance_to_target = self.robot.position.distance_to(self.target)

            if self.current_strategy == "attack":
                # Attack if in range
                if distance_to_target <= self.robot.weapon.range:
                    self._perform_attack()

            elif self.current_strategy == "defend_objective":
                # Defend by staying near objective and attacking enemies
                if distance_to_target > 50:
                    # Move toward objective
                    pass  # Already moving
                else:
                    # Look for enemies in range
                    enemies = self.game_state.get_alive_enemies(self.robot.team)
                    nearest_enemy = self._find_nearest_enemy(enemies)
                    if nearest_enemy and nearest_enemy.position.distance_to(self.target) < 150:
                        # Attack enemy threatening objective
                        self._perform_attack()

            elif self.current_strategy == "heal_ally":
                # Use support weapon to heal
                if distance_to_target <= 70:
                    self._perform_heal()

            elif self.current_strategy == "area_control":
                # Throw explosive if in range
                if distance_to_target <= self.robot.weapon.range:
                    self._perform_explosive()

            elif self.current_strategy == "grab_power_up":
                # Collect power-up
                if distance_to_target < 30:
                    self.game_state.collect_power_up(self.robot, self.target)
                    self.target = None
                    self.current_strategy = "patrol"

            elif self.current_strategy == "avoid_hazard":
                # Keep moving away from hazard
                if distance_to_target < 10:
                    # Avoidance done, find new target
                    self.target = self._get_patrol_point()
                    self.current_strategy = "patrol"

            elif self.current_strategy == "capture_objective":
                # Capture objective
                if distance_to_target < 30:
                    # Capture progress
                    objective = self._find_nearest_objective(self.game_state.objectives, self.robot.team)
                    if objective and objective.captured_by != self.robot.team:
                        # Add progress
                        self.game_state.progress_objective(objective, self.robot.team)
                else:
                    # Continue moving
                    pass

            elif self.current_strategy == "defend_ally":
                # Stay near ally and attack enemies
                if distance_to_target > 60:
                    # Move closer
                    pass
                else:
                    # Look for enemies
                    enemies = self.game_state.get_alive_enemies(self.robot.team)
                    nearest_enemy = self._find_nearest_enemy(enemies)
                    if nearest_enemy and nearest_enemy.position.distance_to(self.target) < 150:
                        self._perform_attack()

            elif self.current_strategy == "scout":
                # Scout by moving to target and checking for enemies
                if distance_to_target < 20:
                    # Reached scout point, find new one
                    self.target = self._find_nearest_unexplored_area()
                else:
                    # Check for enemies along path
                    enemies = self.game_state.get_alive_enemies(self.robot.team)
                    if enemies and self.robot.position.distance_to(enemies[0].position) < self.robot.vision_radius:
                        # Report to team
                        self._report_enemy_to_team(enemies[0])
                        self.current_strategy = "attack"
                        self.target = enemies[0].position

            elif self.current_strategy == "patrol":
                # Patrol between points
                if distance_to_target < 20:
                    # Reached patrol point, find next
                    self.target = self._get_patrol_point()

        # Update robot's direction based on velocity
        if self.robot.velocity.magnitude() > 0:
            # Normalize velocity for consistent movement
            self.robot.velocity = self.robot.velocity.normalize() * self.robot.get_effective_speed()

    def _perform_attack(self) -> None:
        """Perform attack action"""
        if self.robot.can_attack():
            # Find target for attack
            enemies = self.game_state.get_alive_enemies(self.robot.team)
            if enemies:
                nearest_enemy = self._find_nearest_enemy(enemies)
                if nearest_enemy:
                    # Attack nearest enemy
                    self.robot.cooldown = self.robot.weapon.fire_rate
                    # Simulate attack impact
                    damage = self.robot.get_effective_damage()
                    nearest_enemy.take_damage(damage)
                    # Add to stats
                    self.game_state.stats.add_kill(self.robot.team)
                    # Add assist to nearby allies
                    allies = self.game_state.get_alive_allies(self.robot.team)
                    for ally in allies:
                        if ally.position.distance_to(nearest_enemy.position) < 100:
                            self.game_state.stats.add_assist(self.robot.team)
                            break
                    # Add to memory
                    self.robot.strategy_memory.append({
                        "action": "attack",
                        "target": nearest_enemy.id,
                        "damage": damage,
                        "timestamp": time.time()
                    })

    def _perform_heal(self) -> None:
        """Perform healing action"""
        if self.robot.can_attack() and self.robot.role == Role.SUPPORT:
            # Look for lowest health ally in range
            allies = self.game_state.get_alive_allies(self.robot.team)
            lowest_health_ally = self._find_lowest_health_ally(allies)
            if lowest_health_ally and lowest_health_ally.health < lowest_health_ally.max_health * 0.7:
                # Heal ally
                self.robot.cooldown = self.robot.weapon.fire_rate
                heal_amount = 20
                lowest_health_ally.heal(heal_amount)
                # Add to memory
                self.robot.strategy_memory.append({
                    "action": "heal",
                    "target": lowest_health_ally.id,
                    "amount": heal_amount,
                    "timestamp": time.time()
                })

    def _perform_explosive(self) -> None:
        """Perform explosive attack"""
        if self.robot.can_attack() and self.robot.weapon.type == WeaponType.EXPLOSIVE:
            enemies = self.game_state.get_alive_enemies(self.robot.team)
            if len(enemies) > 1:
                # Find enemy cluster center
                cluster_center = self._find_enemy_cluster_center(enemies)
                # Apply damage to enemies in range
                for enemy in enemies:
                    if enemy.position.distance_to(cluster_center) <= self.robot.weapon.range:
                        damage = self.robot.get_effective_damage() * 0.7
                        enemy.take_damage(damage)
                        self.game_state.stats.add_kill(self.robot.team)

                self.robot.cooldown = self.robot.weapon.fire_rate
                # Add to memory
                self.robot.strategy_memory.append({
                    "action": "explosive",
                    "target": "cluster",
                    "damage": self.robot.get_effective_damage(),
                    "timestamp": time.time()
                })

    def _find_nearest_enemy(self, enemies: List[Robot]) -> Optional[Robot]:
        """Find the nearest enemy robot"""
        if not enemies:
            return None
        return min(enemies, key=lambda e: self.robot.position.distance_to(e.position))

    def _find_nearest_allied(self, allies: List[Robot]) -> Optional[Robot]:
        """Find the nearest allied robot"""
        if not allies:
            return None
        return min(allies, key=lambda a: self.robot.position.distance_to(a.position))

    def _find_lowest_health_ally(self, allies: List[Robot]) -> Optional[Robot]:
        """Find the ally with lowest health"""
        if not allies:
            return None
        return min(allies, key=lambda a: a.health / a.max_health)

    def _find_nearest_objective(self, objectives: List[Objective], team: Team) -> Optional[Objective]:
        """Find the nearest objective"""
        if not objectives:
            return None
        # Only consider objectives that are not captured by the same team
        relevant_objectives = [
            obj for obj in objectives 
            if obj.is_active and obj.captured_by != team
        ]
        if not relevant_objectives:
            # Try to capture an enemy objective or defend our own
            relevant_objectives = [
                obj for obj in objectives 
                if obj.is_active and obj.captured_by != team
            ]
            if not relevant_objectives:
                return None
        return min(relevant_objectives, key=lambda o: self.robot.position.distance_to(o.position))

    def _find_nearest_defense_objective(self, objectives: List[Objective], team: Team) -> Optional[Objective]:
        """Find objectives that need defending (captured by team)"""
        if not objectives:
            return None
        defending_objectives = [
            obj for obj in objectives 
            if obj.is_active and obj.captured_by == team
        ]
        if not defending_objectives:
            return None
        return min(defending_objectives, key=lambda o: self.robot.position.distance_to(o.position))

    def _find_nearest_power_up(self, power_ups: List[PowerUp]) -> Optional[PowerUp]:
        """Find the nearest power-up"""
        if not power_ups:
            return None
        active_power_ups = [pu for pu in power_ups if pu.active]
        if not active_power_ups:
            return None
        return min(active_power_ups, key=lambda pu: self.robot.position.distance_to(pu.position))

    def _find_enemy_cluster_center(self, enemies: List[Robot]) -> Vector2D:
        """Find the center point of enemy cluster"""
        if not enemies:
            return Vector2D(0, 0)

        total_x = sum(e.position.x for e in enemies)
        total_y = sum(e.position.y for e in enemies)
        count = len(enemies)

        return Vector2D(total_x / count, total_y / count)

    def _get_patrol_point(self) -> Vector2D:
        """Get a random patrol point within the map"""
        # Use fixed patrol points for consistency
        patrol_points = [
            Vector2D(300, 200), Vector2D(700, 200), 
            Vector2D(500, 400), Vector2D(300, 600), 
            Vector2D(700, 600)
        ]

        # Pick a random point from patrol points
        return random.choice(patrol_points)

    def _find_nearest_unexplored_area(self) -> Vector2D:
        """Find a direction away from known areas"""
        # Simple implementation: move toward map center if not already there
        map_center = Vector2D(self.game_state.settings.map_size.x / 2, self.game_state.settings.map_size.y / 2)
        return map_center

    def _is_defending_needs(self, robot: Robot, objectives: List[Objective]) -> bool:
        """Check if defending objectives is more important than attacking"""
        # If team has objectives captured, defend them
        for obj in objectives:
