    lighting: Dict[str, Any] = field(default_factory=dict)
    sound_effects: List[str] = field(default_factory=list)

    def __post_init__(self):
        # Initialize base positions
        self.team_bases[Team.RED] = Position(self.width * 0.2, self.height * 0.5)
        self.team_bases[Team.BLUE] = Position(self.width * 0.8, self.height * 0.5)

        # Initialize lighting
        self.lighting = {
            "ambient": 0.3,
            "dynamic": True,
            "intensity": 1.0
        }

        # Create some hazards
        self.hazards.append(Hazard("lava", Position(self.width * 0.5, self.height * 0.3), 20, 2.0))
        self.hazards.append(Hazard("electric_field", Position(self.width * 0.5, self.height * 0.7), 25, 1.5))

        # Create power-ups
        for _ in range(5):
            x = random.uniform(100, self.width - 100)
            y = random.uniform(100, self.height - 100)
            power_up_type = random.choice(list(PowerUpType))
            value = random.uniform(20, 40)
            duration = random.uniform(10, 20)
            self.power_ups.append(PowerUp(power_up_type, Position(x, y), value, duration))

    def update(self, delta_time: float, robots: List[Robot]) -> None:
        """Update environment state."""
        # Update hazards
        for hazard in self.hazards:
            hazard.affect_robots(robots)

        # Update power-ups (respawn after timeout)
        for power_up in self.power_ups:
            if not power_up.active and time.time() - power_up.spawn_time > 30.0:
                # Respawn power-up
                power_up.position = Position(
                    random.uniform(100, self.width - 100),
                    random.uniform(100, self.height - 100)
                )
                power_up.active = True
                power_up.spawn_time = time.time()

        # Update objectives
        for objective in self.objectives:
            objective.update(delta_time, robots)

        # Update lighting based on game state
        if self.lighting["dynamic"]:
            # Adjust ambient lighting based on team dominance
            red_score = sum(1 for o in self.objectives if o.captured_by == Team.RED)
            blue_score = sum(1 for o in self.objectives if o.captured_by == Team.BLUE)
            if red_score > blue_score:
                self.lighting["ambient"] = max(0.2, self.lighting["ambient"] - 0.01)
            elif blue_score > red_score:
                self.lighting["ambient"] = min(0.8, self.lighting["ambient"] + 0.01)
            else:
                self.lighting["ambient"] = 0.5

@dataclass
class GameStats:
    total_battles: int = 0
    team_victories: Dict[Team, int] = field(default_factory=lambda: {Team.RED: 0, Team.BLUE: 0})
    average_battle_duration: float = 0.0
