        elif self.type == PowerUpType.REGEN:
            # Increase energy regeneration rate
            robot.visual_effects.append("regen_effect")

        self.active = False

@dataclass
class Hazard:
    type: str  # "lava", "electric_field", "toxic_gas"
    position: Position
    radius: float
    damage_per_second: float
    active: bool = True

    def affect_robots(self, robots: List[Robot]) -> None:
        """Apply damage to robots in the hazard zone."""
        if not self.active:
            return

        for robot in robots:
            if robot.is_alive and robot.position.distance_to(self.position) < self.radius:
                robot.take_damage(self.damage_per_second * 0.1)  # Damage per tick (0.1s intervals)

