@dataclass
class GameStats:
    total_battles: int = 0
    team_victories: Dict[Team, int] = field(default_factory=lambda: {Team.RED: 0, Team.BLUE: 0})
    average_battle_duration: float = 0.0
    team_scores: Dict[Team, float] = field(default_factory=lambda: {Team.RED: 0.0, Team.BLUE: 0.0})
    robot_performance: Dict[str, Dict[str, float]] = field(default_factory=dict)
    strategies_used: Dict[str, int] = field(default_factory=dict)

    def update_stats(self, winner: Optional[Team], duration: float, team_scores: Dict[Team, float], robot_stats: Dict[str, Dict[str, float]]) -> None:
        """Update game statistics."""
        self.total_battles += 1
        if winner:
            self.team_victories[winner] += 1

        # Update average battle duration
        self.average_battle_duration = ((self.average_battle_duration * (self.total_battles - 1)) + duration) / self.total_battles

        # Update team scores
        for team in Team:
            if team in team_scores:
                self.team_scores[team] = (self.team_scores[team] * (self.total_battles - 1) + team_scores[team]) / self.total_battles

        # Update robot performance
        for robot_id, stats in robot_stats.items():
            if robot_id not in self.robot_performance:
                self.robot_performance[robot_id] = {
                    "kills": 0,
                    "deaths": 0,
                    "assists": 0,
                    "objective_contributions": 0
                }
            for stat_type, value in stats.items():
                self.robot_performance[robot_id][stat_type] += value

        # Track strategies
        for strategy, count in robot_stats.items():
            if strategy != "kills" and strategy != "deaths" and strategy != "assists" and strategy != "objective_contributions":
                self.strategies_used[strategy] = self.strategies_used.get(strategy, 0) + 1

class AIController:
    """Handles AI decision making for robots."""

    def __init__(self, environment: Environment, game_stats: GameStats):
        self.environment = environment
        self.game_stats = game_stats
        self.memory: Dict[str, List[Dict]] = defaultdict(list)  # robot_id -> [past_actions]
        self.learning_rate = 0.1
        self.exploration_rate = 0.3
        self.strategy_weights = {
            "offensive": 1.0,
            "defensive": 1.0,
            "support": 1.0,
            "recon": 1.0
        }

        # Adaptive difficulty parameters
        self.difficulty_level = 1.0  # 1.0 = normal, >1.0 = harder, <1.0 = easier
        self.performance_threshold = 0.7  # When team performance exceeds this, increase difficulty
        self.difficulty_adjustment_rate = 0.05

    def update_difficulty(self, team_performance: Dict[Team, float]) -> None:
        """Adjust AI difficulty based on team performance."""
        # Check if one team is dominating
        if len(team_performance) >= 2:
            teams = list(team_performance.keys())
            perf_red = team_performance.get(teams[0], 0)
            perf_blue = team_performance.get(teams[1], 0)

            # If one team is significantly better, increase difficulty for them
            if perf_red > self.performance_threshold and perf_blue < 0.3:
                self.difficulty_level = min(2.0, self.difficulty_level + self.difficulty_adjustment_rate)
            elif perf_blue > self.performance_threshold and perf_red < 0.3:
                self.difficulty_level = min(2.0, self.difficulty_level + self.difficulty_adjustment_rate)
            elif perf_red < 0.3 and perf_blue < 0.3:
                # Both teams struggling, decrease difficulty
                self.difficulty_level = max(0.5, self.difficulty_level - self.difficulty_adjustment_rate)

    def get_robot_strategy(self, robot: Robot, environment: Environment, robots: List[Robot]) -> str:
        """Determine optimal strategy for robot based on game state."""
        # Get team objective
        team_objectives = [obj for obj in environment.objectives if obj.team == robot.team]
        enemy_objectives = [obj for obj in environment.objectives if obj.team != robot.team and obj.team != Team.NEUTRAL]

        # Get nearest objectives and power-ups
        nearest_obj = None
        min_dist = float('inf')
        for obj in team_objectives + enemy_objectives:
            dist = robot.position.distance_to(obj.position)
            if dist < min_dist:
                min_dist = dist
                nearest_obj = obj

        nearest_powerup = None
        min_pu_dist = float('inf')
        for pu in environment.power_ups:
            if pu.active:
                dist = robot.position.distance_to(pu.position)
                if dist < min_pu_dist:
                    min_pu_dist = dist
