        # Count robots from our team near the objective
        team_robots = [r for r in robots if r.team == self.team and r.is_alive and r.position.distance_to(self.position) < 15.0]
        enemy_robots = [r for r in robots if r.team != self.team and r.team != Team.NEUTRAL and r.is_alive and r.position.distance_to(self.position) < 10.0]

        if self.type == ObjectiveType.CAPTURE_FLAG:
