    def heal(self, amount: float) -> None:
        """Heal robot by amount."""
        if self.is_alive:
            self.health = min(self.max_health, self.health + amount)
            self.visual_effects.append("heal_particle")

    def consume_energy(self, amount: float) -> bool:
        """Consume energy, return True if successful."""
        if self.energy >= amount:
            self.energy -= amount
            return True
        return False

    def regenerate_energy(self, rate: float) -> None:
        """Regenerate energy over time."""
        if self.is_alive:
            self.energy = min(self.max_energy, self.energy + rate)

    def update(self, delta_time: float, environment: 'Environment') -> None:
        """Update robot state."""
        if not self.is_alive:
            return

        # Regenerate health and energy
        self.regenerate_energy(0.5 * delta_time)

        # Update cooldowns
        current_time = time.time()
        for action in list(self.cooldowns.keys()):
            if current_time - self.cooldowns[action] >= 1.0:
                del self.cooldowns[action]

        # Apply visual effects
        self.visual_effects = [effect for effect in self.visual_effects if not self._is_effect_expired(effect, delta_time)]

    def _is_effect_expired(self, effect: str, delta_time: float) -> bool:
        """Check if visual effect has expired."""
        expiry_times = {
            "heal_particle": 1.0,
            "death_explosion": 2.0,
            "shield_effect": 5.0,
        }
        return effect not in expiry_times or expiry_times[effect] <= 0

@dataclass
class Weapon:
    name: str
    weapon_type: WeaponType
    damage: float
    range: float
    fire_rate: float  # shots per second
    energy_cost: float
    cooldown: float = 0.0
    ammo: Optional[int] = None  # None means infinite
    max_ammo: Optional[int] = None

    def can_fire(self, robot: Robot) -> bool:
        """Check if robot can fire this weapon."""
        if not robot.is_alive:
            return False
        if self.energy_cost > robot.energy:
            return False
        if self.ammo is not None and self.ammo <= 0:
            return False
        return robot.can_act(f"fire_{self.name}")

    def fire(self, robot: Robot, target: Position) -> Dict[str, Any]:
        """Fire weapon and return firing results."""
        if not self.can_fire(robot):
            return {"success": False, "reason": "Cannot fire"}

        # Consume energy
        robot.consume_energy(self.energy_cost)

        # Consume ammo if applicable
        if self.ammo is not None:
            self.ammo -= 1

        # Apply cooldown
        robot.apply_cooldown(f"fire_{self.name}", 1.0 / self.fire_rate)

        # Calculate hit chance based on distance
        distance = robot.position.distance_to(target)
        hit_chance = max(0.2, 1.0 - (distance / self.range) * 0.8)

        # Determine if hit
        hit = random.random() < hit_chance

        # Determine damage based on distance (falloff)
        damage = self.damage * (1.0 - (distance / self.range) * 0.5)

        return {
            "success": True,
            "hit": hit,
            "damage": damage,
            "distance": distance,
            "target": target
        }

@dataclass
class Objective:
    type: ObjectiveType
    position: Position
    team: Team
    progress: float = 0.0
    max_progress: float = 100.0
    captured_by: Optional[Team] = None
    is_active: bool = True

    def update(self, delta_time: float, robots: List[Robot]) -> None:
        """Update objective progress based on nearby robots."""
        if not self.is_active:
            return

        # Count robots from our team near the objective
        team_robots = [r for r in robots if r.team == self.team and r.is_alive and r.position.distance_to(self.position) < 15.0]
        enemy_robots = [r for r in robots if r.team != self.team and r.team != Team.NEUTRAL and r.is_alive and r.position.distance_to(self.position) < 10.0]

        if self.type == ObjectiveType.CAPTURE_FLAG:
            if len(team_robots) > 0 and len(enemy_robots) == 0:
                self.progress += 20 * delta_time  # Fast capture
            elif len(team_robots) > 0 and len(enemy_robots) > 0:
                self.progress += 5 * delta_time  # Slow capture
            elif len(enemy_robots) > 0 and len(team_robots) == 0:
                self.progress -= 15 * delta_time  # Enemy capture

        elif self.type == ObjectiveType.DEFEND_BASE:
            if len(team_robots) > 0:
                self.progress += 5 * delta_time
            if len(enemy_robots) > 0:
                self.progress -= 10 * delta_time
                # Damage robots in base
                for robot in enemy_robots:
                    robot.take_damage(0.5 * delta_time)

        elif self.type == ObjectiveType.ESCAPE_PAYLOAD:
            if len(team_robots) > 0:
                # Payload being escorted
                self.progress += 15 * delta_time
            else:
                self.progress -= 5 * delta_time

        # Clamp progress
        self.progress = max(0, min(self.max_progress, self.progress))

        # Capture condition
        if self.progress >= self.max_progress and self.captured_by != self.team:
            self.captured_by = self.team
            self.is_active = False
        elif self.progress <= 0 and self.captured_by is not None:
            self.captured_by = None
            self.progress = 0
            self.is_active = True

@dataclass
class PowerUp:
    type: PowerUpType
    position: Position
    value: float
    duration: float
    active: bool = True
    spawn_time: float = field(default_factory=time.time)

    def apply(self, robot: Robot) -> None:
        """Apply power-up effect to robot."""
        if not robot.is_alive:
            return

        if self.type == PowerUpType.HEAL:
            robot.heal(self.value)
        elif self.type == PowerUpType.SPEED_BOOST:
            robot.speed *= 1.5
            robot.visual_effects.append("speed_boost")
        elif self.type == PowerUpType.SHIELD:
            robot.max_health += self.value
            robot.health += self.value
            robot.visual_effects.append("shield_effect")
        elif self.type == PowerUpType.DAMAGE_BOOST:
            # This would affect weapons, but we'll handle in weapon system
            robot.visual_effects.append("damage_boost")
        elif self.type == PowerUpType.REGEN:
            # Increase energy regeneration rate
            robot.visual_effects.append("regen_effect")

        self.active = False

@dataclass
class Hazard:
    type: str  # "lava", "electric_field", "toxic_gas"
    position: Position
    radius: float
    damage_per_second: float
    active: bool = True

    def affect_robots(self, robots: List[Robot]) -> None:
        """Apply damage to robots in the hazard zone."""
        if not self.active:
            return

        for robot in robots:
            if robot.is_alive and robot.position.distance_to(self.position) < self.radius:
                robot.take_damage(self.damage_per_second * 0.1)  # Damage per tick (0.1s intervals)

@dataclass
class Environment:
    width: int = 1000
    height: int = 800
    objectives: List[Objective] = field(default_factory=list)
    power_ups: List[PowerUp] = field(default_factory=list)
    hazards: List[Hazard] = field(default_factory=list)
    team_bases: Dict[Team, Position] = field(default_factory=dict)
    lighting: Dict[str, Any] = field(default_factory=dict)
    sound_effects: List[str] = field(default_factory=list)

    def __post_init__(self):
        # Initialize base positions
        self.team_bases[Team.RED] = Position(self.width * 0.2, self.height * 0.5)
        self.team_bases[Team.BLUE] = Position(self.width * 0.8, self.height * 0.5)

        # Initialize lighting
        self.lighting = {
            "ambient": 0.3,
            "dynamic": True,
            "intensity": 1.0
        }

        # Create some hazards
        self.hazards.append(Hazard("lava", Position(self.width * 0.5, self.height * 0.3), 20, 2.0))
        self.hazards.append(Hazard("electric_field", Position(self.width * 0.5, self.height * 0.7), 25, 1.5))

        # Create power-ups
        for _ in range(5):
            x = random.uniform(100, self.width - 100)
            y = random.uniform(100, self.height - 100)
            power_up_type = random.choice(list(PowerUpType))
            value = random.uniform(20, 40)
            duration = random.uniform(10, 20)
            self.power_ups.append(PowerUp(power_up_type, Position(x, y), value, duration))

    def update(self, delta_time: float, robots: List[Robot]) -> None:
        """Update environment state."""
        # Update hazards
        for hazard in self.hazards:
            hazard.affect_robots(robots)

        # Update power-ups (respawn after timeout)
        for power_up in self.power_ups:
            if not power_up.active and time.time() - power_up.spawn_time > 30.0:
                # Respawn power-up
                power_up.position = Position(
                    random.uniform(100, self.width - 100),
                    random.uniform(100, self.height - 100)
                )
                power_up.active = True
                power_up.spawn_time = time.time()

        # Update objectives
        for objective in self.objectives:
            objective.update(delta_time, robots)

        # Update lighting based on game state
        if self.lighting["dynamic"]:
            # Adjust ambient lighting based on team dominance
            red_score = sum(1 for o in self.objectives if o.captured_by == Team.RED)
            blue_score = sum(1 for o in self.objectives if o.captured_by == Team.BLUE)
            if red_score > blue_score:
                self.lighting["ambient"] = max(0.2, self.lighting["ambient"] - 0.01)
            elif blue_score > red_score:
                self.lighting["ambient"] = min(0.8, self.lighting["ambient"] + 0.01)
            else:
                self.lighting["ambient"] = 0.5

@dataclass
class GameStats:
    total_battles: int = 0
    team_victories: Dict[Team, int] = field(default_factory=lambda: {Team.RED: 0, Team.BLUE: 0})
    average_battle_duration: float = 0.0
    team_scores: Dict[Team, float] = field(default_factory=lambda: {Team.RED: 0.0, Team.BLUE: 0.0})
    robot_performance: Dict[str, Dict[str, float]] = field(default_factory=dict)
    strategies_used: Dict[str, int] = field(default_factory=dict)

    def update_stats(self, winner: Optional[Team], duration: float, team_scores: Dict[Team, float], robot_stats: Dict[str, Dict[str, float]]) -> None:
        """Update game statistics."""
        self.total_battles += 1
        if winner:
            self.team_victories[winner] += 1

        # Update average battle duration
        self.average_battle_duration = ((self.average_battle_duration * (self.total_battles - 1)) + duration) / self.total_battles

        # Update team scores
        for team in Team:
            if team in team_scores:
                self.team_scores[team] = (self.team_scores[team] * (self.total_battles - 1) + team_scores[team]) / self.total_battles

        # Update robot performance
        for robot_id, stats in robot_stats.items():
            if robot_id not in self.robot_performance:
                self.robot_performance[robot_id] = {
                    "kills": 0,
                    "deaths": 0,
                    "assists": 0,
                    "objective_contributions": 0
                }
            for stat_type, value in stats.items():
                self.robot_performance[robot_id][stat_type] += value

        # Track strategies
        for strategy, count in robot_stats.items():
            if strategy != "kills" and strategy != "deaths" and strategy != "assists" and strategy != "objective_contributions":
                self.strategies_used[strategy] = self.strategies_used.get(strategy, 0) + 1

class AIController:
    """Handles AI decision making for robots."""

    def __init__(self, environment: Environment, game_stats: GameStats):
        self.environment = environment
        self.game_stats = game_stats
        self.memory: Dict[str, List[Dict]] = defaultdict(list)  # robot_id -> [past_actions]
        self.learning_rate = 0.1
        self.exploration_rate = 0.3
        self.strategy_weights = {
            "offensive": 1.0,
            "defensive": 1.0,
            "support": 1.0,
            "recon": 1.0
        }

        # Adaptive difficulty parameters
        self.difficulty_level = 1.0  # 1.0 = normal, >1.0 = harder, <1.0 = easier
        self.performance_threshold = 0.7  # When team performance exceeds this, increase difficulty
        self.difficulty_adjustment_rate = 0.05

    def update_difficulty(self, team_performance: Dict[Team, float]) -> None:
        """Adjust AI difficulty based on team performance."""
        # Check if one team is dominating
        if len(team_performance) >= 2:
            teams = list(team_performance.keys())
            perf_red = team_performance.get(teams[0], 0)
            perf_blue = team_performance.get(teams[1], 0)

            # If one team is significantly better, increase difficulty for them
            if perf_red > self.performance_threshold and perf_blue < 0.3:
                self.difficulty_level = min(2.0, self.difficulty_level + self.difficulty_adjustment_rate)
            elif perf_blue > self.performance_threshold and perf_red < 0.3:
                self.difficulty_level = min(2.0, self.difficulty_level + self.difficulty_adjustment_rate)
            elif perf_red < 0.3 and perf_blue < 0.3:
                # Both teams struggling, decrease difficulty
                self.difficulty_level = max(0.5, self.difficulty_level - self.difficulty_adjustment_rate)

    def get_robot_strategy(self, robot: Robot, environment: Environment, robots: List[Robot]) -> str:
        """Determine optimal strategy for robot based on game state."""
        # Get team objective
        team_objectives = [obj for obj in environment.objectives if obj.team == robot.team]
        enemy_objectives = [obj for obj in environment.objectives if obj.team != robot.team and obj.team != Team.NEUTRAL]

        # Get nearest objectives and power-ups
        nearest_obj = None
        min_dist = float('inf')
        for obj in team_objectives + enemy_objectives:
            dist = robot.position.distance_to(obj.position)
            if dist < min_dist:
                min_dist = dist
                nearest_obj = obj

        nearest_powerup = None
        min_pu_dist = float('inf')
        for pu in environment.power_ups:
            if pu.active:
                dist = robot.position.distance_to(pu.position)
                if dist < min_pu_dist:
                    min_pu_dist = dist
                    nearest_powerup = pu

        # Find enemies and allies
        enemies = [r for r in robots if r.team != robot.team and r.is_alive]
        allies = [r for r in robots if r.team == robot.team and r.is_alive and r.id != robot.id]

        # Calculate strategy based on robot type
        if robot.robot_type == RobotType.RECON:
            # Focus on scouting and objective intel
            if enemies:
                return "recon_attack"
            elif nearest_obj and nearest_obj.captured_by != robot.team:
                return "recon_capture"
            elif nearest_powerup:
                return "recon_powerup"
            else:
                return "recon_patrol"

        elif robot.robot_type == RobotType.SUPPORT:
            # Focus on healing and supporting allies
            low_health_allies = [r for r in allies if r.health < r.max_health * 0.5]
            if low_health_allies:
                return "support_heal"
            elif nearest_powerup and nearest_powerup.type == PowerUpType.HEAL:
                return "support_powerup"
            elif enemies:
                return "support_defend"
            else:
                return "support_patrol"

        elif robot.robot_type == RobotType.ASSAULT:
            # Aggressive offensive behavior
            if enemies:
                # Check if we can kill
                closest_enemy = min(enemies, key=lambda e: robot.position.distance_to(e.position))
                if robot.weapon and robot.weapon.can_fire(robot):
                    return "assault_attack"
                else:
                    return "assault_approach"
            elif nearest_obj and nearest_obj.captured_by != robot.team:
                return "assault_capture"
            elif nearest_powerup:
                return "assault_powerup"
            else:
                return "assault_patrol"

        elif robot.robot_type == RobotType.TANK:
            # Defensive, tanky behavior
            if enemies:
                return "tank_defend"
            elif nearest_obj and nearest_obj.captured_by != robot.team:
                return "tank_capture"
            elif nearest_powerup and nearest_powerup.type == PowerUpType.SHIELD:
                return "tank_powerup"
            else:
                return "tank_patrol"

        # Default fallback
        return "default_patrol"

    def decide_action(self, robot: Robot, environment: Environment, robots: List[Robot], game_state: GameState) -> Dict[str, Any]:
        """Decide the next action for a robot."""
        if not robot.is_alive:
            return {"action": "idle"}

        strategy = self.get_robot_strategy(robot, environment, robots)

        # Memory-based learning: use past successful strategies
        if robot.id in self.memory and len(self.memory[robot.id]) > 5:
            # Look for patterns in past actions
            recent_actions = self.memory[robot.id][-5:]
            success_count = sum(1 for a in recent_actions if a.get("success", False))
            if success_count > 3 and random.random() < 0.7:
                # Repeat successful strategy
                best_strategy = max(recent_actions, key=lambda x: x.get("score", 0))
                strategy = best_strategy.get("strategy", strategy)

        # Exploration: occasionally try a different strategy
        if random.random() < self.exploration_rate:
            all_strategies = ["assault_attack", "assault_approach", "assault_capture", "assault_powerup", "assault_patrol",
                            "support_heal", "support_powerup", "support_defend", "support_patrol",
                            "recon_attack", "recon_capture", "recon_powerup", "recon_patrol",
                            "tank_defend", "tank_capture", "tank_powerup", "tank_patrol", "idle"]
            strategy = random.choice(all_strategies)

        # Record this decision
        decision = {
            "strategy": strategy,
            "timestamp": time.time(),
            "success": False,
            "score": 0.0
        }

        # Execute strategy
        if strategy == "assault_attack":
            # Find closest enemy
            enemies = [r for r in robots if r.team != robot.team and r.is_alive]
            if enemies:
                target = min(enemies, key=lambda e: robot.position.distance_to(e.position))
                if robot.weapon and robot.weapon.can_fire(robot):
                    decision["action"] = "fire"
                    decision["target"] = target.position
                    decision["success"] = True
                    decision["score"] = 1.0
                else:
                    decision["action"] = "move"
                    decision["target"] = target.position
                    decision["score"] = 0.6
            else:
                decision["action"] = "move"
                decision["target"] = self.find_nearest_objective(robot, environment, True)
                decision["score"] = 0.5

        elif strategy == "assault_approach":
            enemies = [r for r in robots if r.team != robot.team and r.is_alive]
            if enemies:
                target = min(enemies, key=lambda e: robot.position.distance_to(e.position))
                decision["action"] = "move"
                decision["target"] = target.position
                decision["score"] = 0.7
            else:
                decision["action"] = "move"
                decision["target"] = self.find_nearest_objective(robot, environment, True)
                decision["score"] = 0.5

        elif strategy == "assault_capture":
            objectives = [obj for obj in environment.objectives if obj.team != robot.team and obj.captured_by != robot.team]
            if objectives:
                target = min(objectives, key=lambda o: robot.position.distance_to(o.position))
                decision["action"] = "move"
                decision["target"] = target.position
                decision["score"] = 0.8
            else:
                decision["action"] = "move"
                decision["target"] = robot.position + Position(10, 10)
                decision["score"] = 0.3

        elif strategy == "assault_powerup":
            powerups = [pu for pu in environment.power_ups if pu.active]
            if powerups:
                target = min(powerups, key=lambda pu: robot.position.distance_to(pu.position))
                decision["action"] = "move"
                decision["target"] = target.position
                decision["score"] = 0.9
            else:
                decision["action"] = "move"
                decision["target"] = self.find_nearest_objective(robot, environment, True)
                decision["score"] = 0.4

        elif strategy == "assault_patrol":
            # Patrol around base
            base_pos = environment.team_bases.get(robot.team, Position(self.environment.width/2, self.environment.height/2))
            patrol_points = [
                Position(base_pos.x + 30, base_pos.y + 30),
