@dataclass
class Position:
    x: float = 0.0
    y: float = 0.0

    def distance_to(self, other: 'Position') -> float:
        return math.sqrt((self.x - other.x)**2 + (self.y - other.y)**2)

    def __add__(self, other: 'Position') -> 'Position':
        return Position(self.x + other.x, self.y + other.y)

    def __sub__(self, other: 'Position') -> 'Position':
        return Position(self.x - other.x, self.y - other.y)

    def normalize(self) -> 'Position':
        mag = math.sqrt(self.x**2 + self.y**2)
        if mag > 0:
            return Position(self.x / mag, self.y / mag)
        return Position(0, 0)

@dataclass
class Robot:
    id: str
    team: Team
    robot_type: RobotType
    position: Position
    health: float = 100.0
    max_health: float = 100.0
    energy: float = 100.0
    max_energy: float = 100.0
    speed: float = 5.0
    weapon: Optional['Weapon'] = None
    inventory: List['Weapon'] = field(default_factory=list)
    objectives: List[ObjectiveType] = field(default_factory=list)
    role: str = "Default"
    last_updated: float = field(default_factory=time.time)
    ai_thoughts: List[str] = field(default_factory=list)
    is_alive: bool = True
    cooldowns: Dict[str, float] = field(default_factory=dict)
    visual_effects: List[str] = field(default_factory=list)

    def can_act(self, action: str) -> bool:
        """Check if robot can perform an action based on cooldowns."""
        if action in self.cooldowns:
            return time.time() - self.cooldowns[action] >= 1.0  # 1 second cooldown
        return True

    def apply_cooldown(self, action: str, duration: float = 1.0) -> None:
        """Apply cooldown to an action."""
        self.cooldowns[action] = time.time()

    def take_damage(self, damage: float) -> float:
        """Apply damage to robot and return remaining health."""
        if not self.is_alive:
            return 0
        self.health = max(0, self.health - damage)
        if self.health <= 0:
            self.is_alive = False
            self.visual_effects.append("death_explosion")
        return self.health

    def heal(self, amount: float) -> None:
        """Heal robot by amount."""
        if self.is_alive:
            self.health = min(self.max_health, self.health + amount)
            self.visual_effects.append("heal_particle")

    def consume_energy(self, amount: float) -> bool:
        """Consume energy, return True if successful."""
        if self.energy >= amount:
            self.energy -= amount
            return True
        return False

    def regenerate_energy(self, rate: float) -> None:
        """Regenerate energy over time."""
        if self.is_alive:
            self.energy = min(self.max_energy, self.energy + rate)

    def update(self, delta_time: float, environment: 'Environment') -> None:
        """Update robot state."""
        if not self.is_alive:
            return

        # Regenerate health and energy
        self.regenerate_energy(0.5 * delta_time)

        # Update cooldowns
        current_time = time.time()
        for action in list(self.cooldowns.keys()):
            if current_time - self.cooldowns[action] >= 1.0:
                del self.cooldowns[action]

        # Apply visual effects
        self.visual_effects = [effect for effect in self.visual_effects if not self._is_effect_expired(effect, delta_time)]

    def _is_effect_expired(self, effect: str, delta_time: float) -> bool:
        """Check if visual effect has expired."""
        expiry_times = {
            "heal_particle": 1.0,
            "death_explosion": 2.0,
            "shield_effect": 5.0,
        }
        return effect not in expiry_times or expiry_times[effect] <= 0

@dataclass
class Weapon:
    name: str
    weapon_type: WeaponType
    damage: float
    range: float
    fire_rate: float  # shots per second
    energy_cost: float
    cooldown: float = 0.0
    ammo: Optional[int] = None  # None means infinite
    max_ammo: Optional[int] = None

    def can_fire(self, robot: Robot) -> bool:
        """Check if robot can fire this weapon."""
        if not robot.is_alive:
            return False
        if self.energy_cost > robot.energy:
            return False
        if self.ammo is not None and self.ammo <= 0:
            return False
        return robot.can_act(f"fire_{self.name}")

    def fire(self, robot: Robot, target: Position) -> Dict[str, Any]:
        """Fire weapon and return firing results."""
        if not self.can_fire(robot):
            return {"success": False, "reason": "Cannot fire"}

        # Consume energy
        robot.consume_energy(self.energy_cost)

        # Consume ammo if applicable
        if self.ammo is not None:
            self.ammo -= 1

        # Apply cooldown
        robot.apply_cooldown(f"fire_{self.name}", 1.0 / self.fire_rate)

        # Calculate hit chance based on distance
        distance = robot.position.distance_to(target)
        hit_chance = max(0.2, 1.0 - (distance / self.range) * 0.8)

        # Determine if hit
        hit = random.random() < hit_chance

        # Determine damage based on distance (falloff)
        damage = self.damage * (1.0 - (distance / self.range) * 0.5)

        return {
            "success": True,
            "hit": hit,
            "damage": damage,
            "distance": distance,
            "target": target
        }

@dataclass
class Objective:
    type: ObjectiveType
    position: Position
    team: Team
    progress: float = 0.0
    max_progress: float = 100.0
    captured_by: Optional[Team] = None
    is_active: bool = True

    def update(self, delta_time: float, robots: List[Robot]) -> None:
        """Update objective progress based on nearby robots."""
        if not self.is_active:
            return

        # Count robots from our team near the objective
        team_robots = [r for r in robots if r.team == self.team and r.is_alive and r.position.distance_to(self.position) < 15.0]
        enemy_robots = [r for r in robots if r.team != self.team and r.team != Team.NEUTRAL and r.is_alive and r.position.distance_to(self.position) < 10.0]

        if self.type == ObjectiveType.CAPTURE_FLAG:
            if len(team_robots) > 0 and len(enemy_robots) == 0:
                self.progress += 20 * delta_time  # Fast capture
            elif len(team_robots) > 0 and len(enemy_robots) > 0:
                self.progress += 5 * delta_time  # Slow capture
            elif len(enemy_robots) > 0 and len(team_robots) == 0:
                self.progress -= 15 * delta_time  # Enemy capture

        elif self.type == ObjectiveType.DEFEND_BASE:
            if len(team_robots) > 0:
                self.progress += 5 * delta_time
            if len(enemy_robots) > 0:
                self.progress -= 10 * delta_time
                # Damage robots in base
                for robot in enemy_robots:
                    robot.take_damage(0.5 * delta_time)

        elif self.type == ObjectiveType.ESCAPE_PAYLOAD:
            if len(team_robots) > 0:
                # Payload being escorted
                self.progress += 15 * delta_time
            else:
                self.progress -= 5 * delta_time

        # Clamp progress
        self.progress = max(0, min(self.max_progress, self.progress))

        # Capture condition
        if self.progress >= self.max_progress and self.captured_by != self.team:
            self.captured_by = self.team
            self.is_active = False
        elif self.progress <= 0 and self.captured_by is not None:
            self.captured_by = None
            self.progress = 0
            self.is_active = True

@dataclass
class PowerUp:
