        """Adjust AI difficulty based on team performance."""
        # Check if one team is dominating
        if len(team_performance) >= 2:
            teams = list(team_performance.keys())
            perf_red = team_performance.get(teams[0], 0)
            perf_blue = team_performance.get(teams[1], 0)

            # If one team is significantly better, increase difficulty for them
            if perf_red > self.performance_threshold and perf_blue < 0.3:
                self.difficulty_level = min(2.0, self.difficulty_level + self.difficulty_adjustment_rate)
            elif perf_blue > self.performance_threshold and perf_red < 0.3:
                self.difficulty_level = min(2.0, self.difficulty_level + self.difficulty_adjustment_rate)
            elif perf_red < 0.3 and perf_blue < 0.3:
