            self.weapon = self._assign_weapon_by_role()
            self.add_to_memory({
                'event': 'strategy_change',
                'old_role': self.role.name,
                'new_role': self.role.name,
                'reason': 'poor_performance'
            })

    def _record_performance(self, game_state: GameState):
        """Record performance metrics for learning"""
        # Calculate performance score based on multiple factors
        score = 0

        # Health preservation
        score += (self.health / MAX_HEALTH) * 0.2

        # Kills
        score += (self.stats.kills / max(1, self.stats.deaths)) * 0.3

        # Objectives completed
        score += (self.stats.objectives_completed / max(1, game_state.round_number)) * 0.2

        # Teamwork
        score += self.stats.teamwork_score * 0.3

        self.stats.last_battle_performance = min(1.0, max(0.0, score))
        self.strategy_history.append({
            'time': game_state.time_elapsed,
            'performance': score,
            'role': self.role.value,
            'kills': self.stats.kills,
            'deaths': self.stats.deaths
        })

        # Keep only last 10 records
        if len(self.strategy_history) > 10:
            self.strategy_history.pop(0)


