class Agent(ABC):
    """Abstract base class for all agents (robots and NPCs)"""

    def __init__(self, name: str, position: Vector2D, team: str):
        self.name = name
        self.position = position
        self.team = team
        self.health = MAX_HEALTH
        self.energy = MAX_ENERGY
        self.max_health = MAX_HEALTH
        self.max_energy = MAX_ENERGY
        self.is_alive = True
        self.last_action_time = 0.0
        self.target: Optional[Agent] = None
        self.current_objective: Optional[Objective] = None
        self.role: RobotRole = RobotRole.ATTACKER
        self.stats = RobotStats()
        self.weapon: Optional[Weapon] = None
        self.inventory: List[PowerUp] = []
        self.cooldowns: Dict[str, float] = {}  # ability_name: time_remaining
        self.vision: List[Agent] = []  # agents currently in view
        self.memory: List[Dict] = []   # recent events for learning
        self.behavior_tree: Optional[BehaviorTree] = None

    @abstractmethod
    def update(self, delta_time: float, game_state: GameState):
        """Update agent state each frame"""
        pass

    @abstractmethod
    def decide_action(self, game_state: GameState) -> str:
        """Decide next action based on perception and state"""
        pass

    def take_damage(self, damage: float, source: Optional['Agent'] = None):
        """Apply damage to agent"""
        if not self.is_alive:
            return
        self.health = max(0, self.health - damage)
        if self.health <= 0:
            self.is_alive = False
            self.health = 0
            if source and source.team != self.team:
                source.stats.kills += 1
                source.stats.teamwork_score += 0.1
            self.stats.deaths += 1

    def heal(self, amount: float):
        """Heal agent"""
        if not self.is_alive:
            return
        self.health = min(self.max_health, self.health + amount)

    def recharge_energy(self, amount: float):
        """Recharge energy"""
        if not self.is_alive:
            return
        self.energy = min(self.max_energy, self.energy + amount)

    def use_ability(self, ability_name: str, cooldown: float):
        """Use an ability with cooldown tracking"""
        if self.energy < 10:  # Minimum energy cost
            return False
        if ability_name in self.cooldowns and self.cooldowns[ability_name] > 0:
            return False
        self.energy -= 10
        self.cooldowns[ability_name] = cooldown
        return True

    def update_cooldowns(self, delta_time: float):
        """Decrement all cooldowns"""
        for ability in list(self.cooldowns.keys()):
            self.cooldowns[ability] = max(0, self.cooldowns[ability] - delta_time)

    def add_to_memory(self, event: Dict):
        """Add event to memory (for learning)"""
        self.memory.append({
            'timestamp': time.time(),
            'event': event
        })
        # Keep only last 100 events
        if len(self.memory) > 100:
            self.memory.pop(0)

    def get_team_mates(self, game_state: GameState) -> List['Robot']:
        """Get all teammates"""
        teammates = []
        for obj in game_state.objects:
            if isinstance(obj, Robot) and obj.team == self.team and obj.is_alive:
                teammates.append(obj)
        return teammates

    def get_enemies(self, game_state: GameState) -> List['Robot']:
        """Get all enemies"""
        enemies = []
        for obj in game_state.objects:
            if isinstance(obj, Robot) and obj.team != self.team and obj.is_alive:
                enemies.append(obj)
        return enemies

    def get_nearest_objective(self, game_state: GameState) -> Optional[Objective]:
        """Find nearest objective"""
        objectives = game_state.objectives
        if not objectives:
            return None
        nearest = min(
            objectives, 
            key=lambda obj: self.position.distance_to(obj.position)
        )
        return nearest if self.position.distance_to(nearest.position) < VISION_RANGE else None

    def get_nearest_power_up(self, game_state: GameState) -> Optional[PowerUp]:
        """Find nearest power-up"""
        power_ups = game_state.power_ups
        if not power_ups:
            return None
        nearest = min(
            power_ups,
            key=lambda pu: self.position.distance_to(pu.position)
        )
        return nearest if self.position.distance_to(nearest.position) < VISION_RANGE else None

    def get_nearest_enemy(self, game_state: GameState) -> Optional['Robot']:
        """Find nearest enemy"""
        enemies = self.get_enemies(game_state)
        if not enemies:
            return None
        nearest = min(
            enemies,
            key=lambda e: self.position.distance_to(e.position)
        )
        return nearest if self.position.distance_to(nearest.position) < VISION_RANGE else None

    def get_nearest_teammate(self, game_state: GameState) -> Optional['Robot']:
        """Find nearest teammate"""
        teammates = self.get_team_mates(game_state)
        if not teammates:
            return None
        nearest = min(
            teammates,
            key=lambda t: self.position.distance_to(t.position)
        )
        return nearest if self.position.distance_to(nearest.position) < VISION_RANGE else None

    def can_see(self, target: Agent) -> bool:
        """Check if agent can see another agent (line of sight)"""
        if target is None:
            return False
        distance = self.position.distance_to(target.position)
        if distance > VISION_RANGE:
            return False
        # Simple line-of-sight: check if any hazard blocks the view
        # For simplicity, we assume no blocking in this implementation
        return True

    def get_perception(self, game_state: GameState) -> Dict:
        """Get a perception snapshot of the environment"""
        return {
            'health': self.health,
            'energy': self.energy,
            'position': self.position,
            'team': self.team,
            'enemies': self.get_enemies(game_state),
            'teammates': self.get_team_mates(game_state),
            'nearest_enemy': self.get_nearest_enemy(game_state),
            'nearest_teammate': self.get_nearest_teammate(game_state),
            'nearest_objective': self.get_nearest_objective(game_state),
            'nearest_power_up': self.get_nearest_power_up(game_state),
            'current_objective': self.current_objective,
            'is_low_health': self.health < MAX_HEALTH * 0.3,
            'is_low_energy': self.energy < MAX_ENERGY * 0.2,
            'alive': self.is_alive
        }

    def __str__(self):
        return f"{self.name} ({self.team}) - HP:{self.health:.0f} EP:{self.energy:.0f} {'ALIVE' if self.is_alive else 'DEAD'}"


class Weapon(ABC):
    """Abstract base class for weapons"""

    def __init__(self, name: str, weapon_type: WeaponType, damage: float, range_: float, cooldown: float, energy_cost: float = 10):
        self.name = name
        self.weapon_type = weapon_type
        self.damage = damage
        self.range = range_
        self.cooldown = cooldown  # seconds
        self.energy_cost = energy_cost
        self.last_fired = 0.0

    def can_fire(self, current_time: float) -> bool:
        return current_time - self.last_fired >= self.cooldown

    def fire(self, shooter: Agent, target: Agent, current_time: float) -> bool:
        if not self.can_fire(current_time):
            return False
        if shooter.energy < self.energy_cost:
            return False
        if shooter.position.distance_to(target.position) > self.range:
            return False

        shooter.energy -= self.energy_cost
        shooter.last_action_time = current_time
        self.last_fired = current_time

        # Apply damage
        target.take_damage(self.damage, shooter)

        # Create visual/audio feedback (simulated)
        shooter.add_to_memory({
            'action': 'fire',
            'target': target.name,
            'weapon': self.name,
            'damage': self.damage
        })

        return True

    @abstractmethod
    def effect(self, shooter: Agent, target: Agent) -> None:
        """Special effect when weapon is fired"""
        pass


class Robot(Agent):
    """Concrete implementation of a robot agent"""

    def __init__(self, name: str, position: Vector2D, team: str, role: RobotRole = RobotRole.ATTACKER):
        super().__init__(name, position, team)
        self.role = role
        self.speed = 1.5  # units per second
        self.direction = Vector2D(1, 0).normalize()  # default facing direction
        self.weapon = self._assign_weapon_by_role()
        self.behavior_tree = BehaviorTree(self)
        self.last_perception = {}
        self.learning_rate = 0.1  # Learning rate for strategy adaptation
        self.strategy_history = []
        self.last_strategy = None

    def _assign_weapon_by_role(self) -> Weapon:
        """Assign weapon based on role"""
        if self.role == RobotRole.ATTACKER:
            return RapidFireRifle("Rapid Fire Rifle", 15.0, 8.0, 0.5, 8)
        elif self.role == RobotRole.DEFENDER:
            return HeavyCannon("Heavy Cannon", 25.0, 20.0, 2.0, 15)
        elif self.role == RobotRole.SUPPORT:
            return HealingBeam("Healing Beam", 5.0, HEAL_RANGE, 1.0, 12)
        elif self.role == RobotRole.SCOUT:
            return SniperRifle("Sniper Rifle", 20.0, 40.0, 1.5, 10)
        elif self.role == RobotRole.CONTROLLER:
            return EMPWeapon("EMP Weapon", 0.0, 25.0, 5.0, 20)  # No damage, disables systems
        return RapidFireRifle("Standard Rifle", 10.0, 20.0, 0.8, 8)

    def update(self, delta_time: float, game_state: GameState):
        """Update robot state"""
        if not self.is_alive:
            return

        # Update cooldowns
        self.update_cooldowns(delta_time)

        # Recharge energy
        self.recharge_energy(BASE_RECHARGE_RATE * delta_time)

        # Update perception
        self.last_perception = self.get_perception(game_state)

        # Update behavior tree
        self.behavior_tree.update(delta_time, game_state)

        # Move based on decision
        self._move_towards_target()

        # Update visual representation (simplified)
        self._update_visuals()

        # Update strategy based on performance
        self._adapt_strategy(game_state)

        # Record recent performance
        if game_state.time_elapsed % 10 < delta_time:  # Every 10 seconds
            self._record_performance(game_state)

    def decide_action(self, game_state: GameState) -> str:
        """Decide next action based on role and current state"""
        perception = self.get_perception(game_state)

        # Role-based decision making
        if self.role == RobotRole.ATTACKER:
            if perception['nearest_enemy'] and perception['enemy'].health > 0:
                return "attack"
            elif perception['nearest_objective'] and perception['objective'].team != self.team:
                return "capture"
            elif perception['nearest_power_up']:
                return "collect_powerup"
            else:
                return "patrol"

        elif self.role == RobotRole.DEFENDER:
            if perception['nearest_enemy'] and perception['enemy'].health > 0:
                return "defend_base"
            elif perception['nearest_objective'] and perception['objective'].team == self.team:
                return "defend_objective"
            elif perception['nearest_power_up']:
                return "collect_powerup"
            else:
                return "patrol"

        elif self.role == RobotRole.SUPPORT:
            low_health_teammates = [t for t in perception['teammates'] if t.health < MAX_HEALTH * 0.5]
            if low_health_teammates:
                return "heal"
            elif perception['nearest_enemy']:
                return "support_attack"
            elif perception['nearest_power_up']:
                return "collect_powerup"
            else:
                return "patrol"

        elif self.role == RobotRole.SCOUT:
            if perception['nearest_enemy']:
                return "recon"
            elif perception['nearest_objective']:
                return "scout_objective"
            else:
                return "patrol"

        elif self.role == RobotRole.CONTROLLER:
            if perception['nearest_enemy']:
                return "disable"
            elif perception['nearest_objective']:
                return "control_objective"
            else:
                return "patrol"

        return "patrol"

    def _move_towards_target(self):
        """Move robot towards current target or objective"""
        if not self.is_alive:
            return

        target_pos = None

        # Priority: follow current objective > follow teammate > chase enemy > patrol
        if self.current_objective:
            target_pos = self.current_objective.position
        elif self.last_perception['nearest_teammate'] and self.role in [RobotRole.SUPPORT, RobotRole.DEFENDER]:
            target_pos = self.last_perception['nearest_teammate'].position
        elif self.last_perception['nearest_enemy'] and self.role in [RobotRole.ATTACKER, RobotRole.SCOUT]:
            target_pos = self.last_perception['nearest_enemy'].position
        elif self.last_perception['nearest_power_up']:
            target_pos = self.last_perception['nearest_power_up'].position
        else:
            # Patrol: move in a random direction, but change direction occasionally
            if random.random() < 0.02:  # 2% chance to change direction
                self.direction = Vector2D(
                    random.uniform(-1, 1),
                    random.uniform(-1, 1)
                ).normalize()
            target_pos = self.position + self.direction * 10

        if target_pos:
            direction_to_target = (target_pos - self.position).normalize()
            self.direction = direction_to_target

            # Move towards target
            movement = direction_to_target * self.speed * 0.0167  # 1/60 second movement
            new_pos = self.position + movement

            # Keep within bounds
            new_pos.x = max(0, min(MAP_SIZE[0], new_pos.x))
            new_pos.y = max(0, min(MAP_SIZE[1], new_pos.y))

            self.position = new_pos

    def _update_visuals(self):
        """Update visual and audio effects (simulated)"""
        # This is a simplified version - in a real implementation, this would trigger
        # actual visual/audio effects through a rendering engine

        # If low on health, pulse red
        if self.health < MAX_HEALTH * 0.3:
            # Visual: red pulse effect
            pass

        # If using weapon, create muzzle flash
        if self.weapon and self.last_fired > 0:
            # Visual: muzzle flash
            # Audio: weapon sound
            pass

        # If healing teammate, create blue aura
        if self.role == RobotRole.SUPPORT and self.last_action_time > 0:
            # Visual: blue aura around robot
            # Audio: healing sound
            pass

    def _adapt_strategy(self, game_state: GameState):
        """Adapt strategy based on learning from previous battles"""
        if not self.memory:
            return

        # Simple reinforcement learning: adjust behavior based on outcomes
        recent_successes = 0
        total_recent_actions = min(len(self.memory), 20)

        for event in self.memory[-total_recent_actions:]:
            if event['event'].get('action') == 'capture' and event['event'].get('success', False):
                recent_successes += 1
            elif event['event'].get('action') == 'heal' and event['event'].get('target_health', 0) > MAX_HEALTH * 0.7:
                recent_successes += 1
            elif event['event'].get('action') == 'kill':
                recent_successes += 1

        success_rate = recent_successes / total_recent_actions if total_recent_actions > 0 else 0.5

        # Adjust learning parameters based on success rate
        if success_rate > 0.7:
            # Successful strategy, reinforce it
            self.learning_rate = min(self.learning_rate + 0.01, 0.3)
        elif success_rate < 0.3:
            # Unsuccessful strategy, try to explore more
            self.learning_rate = max(self.learning_rate - 0.01, 0.05)

        # Change strategy occasionally if performance is poor
        if success_rate < 0.25 and random.random() < 0.1:
            # Randomly change role to adapt
            roles = list(RobotRole)
            self.role = random.choice([r for r in roles if r != self.role])
            self.weapon = self._assign_weapon_by_role()
            self.add_to_memory({
                'event': 'strategy_change',
                'old_role': self.role.name,
                'new_role': self.role.name,
                'reason': 'poor_performance'
            })

    def _record_performance(self, game_state: GameState):
        """Record performance metrics for learning"""
        # Calculate performance score based on multiple factors
        score = 0

        # Health preservation
        score += (self.health / MAX_HEALTH) * 0.2

        # Kills
        score += (self.stats.kills / max(1, self.stats.deaths)) * 0.3

        # Objectives completed
        score += (self.stats.objectives_completed / max(1, game_state.round_number)) * 0.2

        # Teamwork
        score += self.stats.teamwork_score * 0.3

        self.stats.last_battle_performance = min(1.0, max(0.0, score))
        self.strategy_history.append({
            'time': game_state.time_elapsed,
            'performance': score,
            'role': self.role.value,
            'kills': self.stats.kills,
            'deaths': self.stats.deaths
        })

        # Keep only last 10 records
        if len(self.strategy_history) > 10:
            self.strategy_history.pop(0)


class Objective(ABC):
    """Abstract base class for game objectives"""

    def __init__(self, name: str, objective_type: ObjectiveType, position: Vector2D, team: str):
        self.name = name
        self.objective_type = objective_type
        self.position = position
        self.team = team  # Team that owns/controls this objective
        self.progress = 0.0  # 0.0 to 1.0
        self.is_active = True
        self.captured_by = None
        self.radius = 8.0

    @abstractmethod
    def update(self, delta_time: float, game_state: GameState):
        """Update objective state"""
        pass

    @abstractmethod
    def is_completed(self) -> bool:
        """Check if objective is completed"""
        pass

    def get_percentage_complete(self) -> float:
        return self.progress

    def capture(self, team: str) -> bool:
        """Attempt to capture objective"""
        if not self.is_active:
            return False

        if team == self.team:
            self.progress = min(1.0, self.progress + 0.05)
            return True

        else:
            self.progress = max(0.0, self.progress - 0.05)
            self.team = team
            self.captured_by = team
            return True

        return False


class CaptureFlag(Objective):
    """Flag capture objective"""

    def __init__(self, name: str, position: Vector2D, team: str):
        super().__init__(name, ObjectiveType.CAPTURE_FLAG, position, team)
        self.flag_carried_by = None  # Robot carrying the flag
        self.flag_returned = False

    def update(self, delta_time: float, game_state: GameState):
        if not self.is_active:
            return

        # If flag is being carried, update position
        if self.flag_carried_by:
            self.position = self.flag_carried_by.position

        # Auto-progress if team has control and no enemy nearby
        if self.team != "neutral":
            nearby_enemies = 0
            for agent in game_state.objects:
                if isinstance(agent, Robot) and agent.team != self.team and agent.is_alive:
                    if self.position.distance_to(agent.position) < 15:
                        nearby_enemies += 1

            if nearby_enemies == 0 and self.progress < 1.0:
                self.progress += delta_time * 0.02  # Slow progress when uncontested

    def is_completed(self) -> bool:
        return self.progress >= 1.0 and self.team != "neutral"

    def drop_flag(self):
        """Drop flag when carrier dies"""
        self.flag_carried_by = None
        # Randomly place flag near previous position
        self.position = Vector2D(
            self.position.x + random.uniform(-5, 5),
            self.position.y + random.uniform(-5, 5)
        )

    def pick_up_flag(self, robot: Robot):
        """Pick up flag"""
        if self.team == robot.team and self.flag_carried_by is None:
            self.flag_carried_by = robot
            self.flag_returned = False
            return True
        return False

    def return_flag(self):
        """Return flag to base"""
        if self.flag_carried_by and self.flag_carried_by.team == self.team:
            self.flag_returned = True
            self.flag_carried_by = None
            self.progress = 1.0
            return True
        return False


class DefendBase(Objective):
    """Base defense objective"""

    def __init__(self, name: str, position: Vector2D, team: str, health: float = 100.0):
        super().__init__(name, ObjectiveType.DEFEND_BASE, position, team)
        self.base_health = health
        self.max_health = health

    def update(self, delta_time: float, game_state: GameState):
        if not self.is_active:
            return

        # Regenerate base health slowly when no enemies nearby
        nearby_enemies = 0
        for agent in game_state.objects:
            if isinstance(agent, Robot) and agent.team != self.team and agent.is_alive:
                if self.position.distance_to(agent.position) < 20:
                    nearby_enemies += 1

        if nearby_enemies == 0 and self.base_health < self.max_health:
            self.base_health += delta_time * 0.5
            self.base_health = min(self.base_health, self.max_health)

        # Calculate progress based on base health
        self.progress = self.base_health / self.max_health

    def is_completed(self) -> bool:
        return self.base_health >= self.max_health and self.team != "neutral"

    def take_damage(self, damage: float):
        """Take damage to base"""
        self.base_health = max(0, self.base_health - damage)
        if self.base_health <= 0:
            self.is_active = False
            self.team = "neutral"


