class PowerUp:
    """Power-up item that can be collected by robots"""

    def __init__(self, position: Vector2D, power_up_type: PowerUpType, duration: float = 15.0):
        self.position = position
        self.power_up_type = power_up_type
        self.duration = duration
        self.collected = False
        self.is_active = True
        self.spawn_time = time.time()
        self.collected_by = None

    def apply(self, robot: Robot):
        """Apply power-up effect to robot"""
        if self.collected or not self.is_active:
            return False

        self.collected = True
        self.collected_by = robot
        self.is_active = False

        if self.power_up_type == PowerUpType.HEALTH_PACK:
            robot.heal(30)
            robot.add_to_memory({
                'action': 'collect_powerup',
                'type': 'health_pack',
                'amount': 30
            })

        elif self.power_up_type == PowerUpType.ENERGY_PACK:
            robot.recharge_energy(40)
            robot.add_to_memory({
                'action': 'collect_powerup',
                'type': 'energy_pack',
                'amount': 40
            })

        elif self.power_up_type == PowerUpType.SPEED_BOOST:
            robot.speed *= 1.5
            # Schedule speed restoration after duration
            threading.Timer(self.duration, self._restore_speed, [robot]).start()
            robot.add_to_memory({
                'action': 'collect_powerup',
                'type': 'speed_boost',
                'duration': self.duration
            })

        elif self.power_up_type == PowerUpType.DAMAGE_BOOST:
            if robot.weapon:
                robot.weapon.damage *= 1.5
                # Schedule damage restoration after duration
                threading.Timer(self.duration, self._restore_damage, [robot]).start()
            robot.add_to_memory({
                'action': 'collect_powerup',
                'type': 'damage_boost',
                'duration': self.duration
            })

        elif self.power_up_type == PowerUpType.SHIELD:
            robot.max_health = int(robot.max_health * 1.5)
            robot.health = robot.max_health
            # Schedule shield removal after duration
            threading.Timer(self.duration, self._remove_shield, [robot]).start()
            robot.add_to_memory({
                'action': 'collect_powerup',
                'type': 'shield',
                'duration': self.duration
            })

        elif self.power_up_type == PowerUpType.INVISIBILITY:
            # Invisibility (simplified)
            robot._invisibility = True
            threading.Timer(self.duration, self._remove_invisibility, [robot]).start()
            robot.add_to_memory({
                'action': 'collect_powerup',
                'type': 'invisibility',
                'duration': self.duration
            })

        elif self.power_up_type == PowerUpType.TELEPORT:
            # Teleport to random location
            robot.position = Vector2D(
                random.uniform(0, MAP_SIZE[0]),
                random.uniform(0, MAP_SIZE[1])
            )
            robot.add_to_memory({
                'action': 'collect_powerup',
                'type': 'teleport'
            })

        return True

    def _restore_speed(self, robot: Robot):
        robot.speed /= 1.5

    def _restore_damage(self, robot: Robot):
        if robot.weapon:
            robot.weapon.damage /= 1.5

    def _remove_shield(self, robot: Robot):
        robot.max_health = MAX_HEALTH
        robot.health = min(robot.health, MAX_HEALTH)

    def _remove_invisibility(self, robot: Robot):
        robot._invisibility = False


class Hazard:
    """Environmental hazard that affects robots"""

    def __init__(self, position: Vector2D, hazard_type: HazardType, radius: float = 8.0, damage_per_second: float = 5.0):
        self.position = position
        self.hazard_type = hazard_type
        self.radius = radius
        self.damage_per_second = damage_per_second
        self.is_active = True

    def update(self, robots: List[Robot], delta_time: float):
        """Apply hazard effects to robots in range"""
        if not self.is_active:
            return

        for robot in robots:
            if not robot.is_alive:
                continue

            distance = robot.position.distance_to(self.position)
            if distance < self.radius:
                # Apply damage based on hazard type
                damage = self.damage_per_second * delta_time

                if self.hazard_type == HazardType.LAVA:
                    robot.take_damage(damage * 1.5)

                elif self.hazard_type == HazardType.ELECTRIC_FIELD:
                    robot.take_damage(damage * 1.2)
                    robot.energy = max(0, robot.energy - damage * 2)

                elif self.hazard_type == HazardType.TOXIC_GAS:
                    robot.take_damage(damage * 1.1)
                    robot.speed *= 0.9  # Slow down

                elif self.hazard_type == HazardType.GRAVITY_WELL:
                    # Pull robots toward center
                    direction = (self.position - robot.position).normalize()
                    robot.position = robot.position + direction * 0.2 * delta_time
                    robot.take_damage(damage * 1.3)

                # Add to memory
                robot.add_to_memory({
                    'action': 'hazard_damage',
                    'hazard': self.hazard_type.value,
                    'damage': damage
                })


class BehaviorTree:
    """Simple behavior tree implementation for robot decision making"""

    def __init__(self, robot: Robot):
