        self.damage = damage
        self.range = range_
        self.cooldown = cooldown  # seconds
        self.energy_cost = energy_cost
        self.last_fired = 0.0

    def can_fire(self, current_time: float) -> bool:
        return current_time - self.last_fired >= self.cooldown

    def fire(self, shooter: Agent, target: Agent, current_time: float) -> bool:
        if not self.can_fire(current_time):
            return False
        if shooter.energy < self.energy_cost:
            return False
        if shooter.position.distance_to(target.position) > self.range:
            return False

        shooter.energy -= self.energy_cost
        shooter.last_action_time = current_time
