@dataclass
class Vector2D:
    x: float = 0.0
    y: float = 0.0

    def __add__(self, other):
        return Vector2D(self.x + other.x, self.y + other.y)

    def __sub__(self, other):
        return Vector2D(self.x - other.x, self.y - other.y)

    def __mul__(self, scalar):
        return Vector2D(self.x * scalar, self.y * scalar)

    def __truediv__(self, scalar):
        return Vector2D(self.x / scalar, self.y / scalar)

    def length(self):
        return math.sqrt(self.x**2 + self.y**2)

    def normalize(self):
        length = self.length()
        if length == 0:
            return Vector2D(0, 0)
        return self / length

    def distance_to(self, other):
        return (self - other).length()

    def dot(self, other):
        return self.x * other.x + self.y * other.y

    def copy(self):
        return Vector2D(self.x, self.y)

@dataclass
class Weapon:
    name: str
    weapon_type: WeaponType
    damage: float
    range: float
    fire_rate: float  # attacks per second
    ammo: int = -1  # -1 means infinite
    max_ammo: int = -1
    reload_time: float = 0.0
    splash_radius: float = 0.0  # for explosive weapons
    is_active: bool = True

    def can_attack(self, current_time: float, last_attack_time: float) -> bool:
        if not self.is_active:
            return False
        if self.ammo == 0:
            return False
        return (current_time - last_attack_time) >= (1.0 / self.fire_rate)

    def use_ammo(self):
        if self.ammo > 0:
            self.ammo -= 1

