        self.velocity = direction * self.speed

    def move_away(self, target: Vector2D, dt: float):
        if not self.is_alive:
            return

        direction = (self.position - target).normalize()
        self.velocity = direction * self.speed

    def stop(self):
        self.velocity = Vector2D(0, 0)

    def add_strategy_memory(self, decision: Dict):
        """Store decision for learning"""
        self.strategy_memory.append({
            'timestamp': time.time(),
            'decision': decision,
            'outcome': None
        })
        # Keep only last 50 decisions to avoid memory bloat
        if len(self.strategy_memory) > 50:
            self.strategy_memory.pop(0)

    def get_team_coordination_bonus(self) -> float:
        """Returns a multiplier based on team coordination"""
        return 1.0 + (self.team_coordination * 0.5)  # Up to 50% bonus

@dataclass
class Objective:
    type: ObjectiveType
    position: Vector2D
    team: Team = Team.NEUTRAL
    captured_by: Optional[Team] = None
    capture_progress: float = 0.0
    capture_rate: float = 0.5  # per second
    defenders: List[Robot] = field(default_factory=list)
    attackers: List[Robot] = field(default_factory=list)
    is_active: bool = True
    completion_score: float = 100.0

    def update(self, robots: List[Robot], dt: float):
        if not self.is_active:
            return

        # Reset teams
        self.defenders = []
        self.attackers = []

        # Find robots near objective
        for robot in robots:
            if not robot.is_alive:
                continue
            distance = robot.position.distance_to(self.position)
            if distance <= 15.0:  # Capture range
                if robot.team == self.team and self.captured_by != robot.team:
                    # Neutral objective being captured by a team
                    self.attackers.append(robot)
                elif robot.team != self.team and self.captured_by == robot.team:
                    # Already captured, defending
                    self.defenders.append(robot)
                elif robot.team != self.team and self.captured_by != robot.team:
                    # Attacking a captured objective
                    self.attackers.append(robot)

        # Capture logic
        if self.captured_by is None:
            # Neutral objective - capture by any team
            if len(self.attackers) > 0:
                # Capture progress increases based on number of attackers
                progress_increase = len(self.attackers) * self.capture_rate * dt
                self.capture_progress += progress_increase

                if self.capture_progress >= 100.0:
                    # Capture complete
                    self.captured_by = self.attackers[0].team  # First attacker's team
                    self.capture_progress = 100.0
                    logger.info(f"Objective {self.type.value} captured by {self.captured_by.value}!")
        else:
            # Objective is captured - check for recapture
            if len(self.attackers) > 0:
                # Attackers are trying to recapture
                progress_increase = len(self.attackers) * self.capture_rate * dt
                # Reverse the capture progress if attackers are of a different team
                if self.attackers[0].team != self.captured_by:
                    self.capture_progress -= progress_increase
                    if self.capture_progress <= 0:
                        self.captured_by = self.attackers[0].team
                        self.capture_progress = 0
                        logger.info(f"Objective {self.type.value} recaptured by {self.captured_by.value}!")
                else:
                    # Same team defending - increase defense
                    self.capture_progress = min(100.0, self.capture_progress + (len(self.defenders) * 0.1 * dt))

            # Defenders can help maintain capture
            elif len(self.defenders) > 0:
                self.capture_progress = min(100.0, self.capture_progress + (len(self.defenders) * 0.05 * dt))

@dataclass
class PowerUp:
    type: PowerUpType
    position: Vector2D
    duration: float = 10.0
    respawn_time: float = 30.0
    is_active: bool = True
    last_spawned: float = 0.0
    collected_by: Optional[str] = None

    def update(self, current_time: float, robots: List[Robot]) -> Optional[str]:
        if not self.is_active and current_time - self.last_spawned < self.respawn_time:
            return None  # Still respawning

        if not self.is_active:
            # Respawn power-up
            self.is_active = True
            self.collected_by = None
            logger.info(f"Power-up {self.type.value} respawned at {self.position.x:.1f}, {self.position.y:.1f}")

        # Check for collection
        if self.is_active:
            for robot in robots:
                if not robot.is_alive:
                    continue
                distance = robot.position.distance_to(self.position)
                if distance < 3.0:  # Collection radius
                    robot.add_power_up(self.type, self.duration)
                    self.collected_by = robot.id
                    self.is_active = False
                    self.last_spawned = current_time
                    logger.info(f"Robot {robot.id} collected {self.type.value}")
                    return robot.id

        return None

@dataclass
class Hazard:
    type: HazardType
    position: Vector2D
    radius: float = 5.0
    damage_per_second: float = 5.0
    is_active: bool = True

    def update(self, robots: List[Robot], dt: float):
        if not self.is_active:
            return

        for robot in robots:
            if not robot.is_alive:
                continue
            distance = robot.position.distance_to(self.position)
            if distance < self.radius:
                # Apply damage over time
                robot.take_damage(self.damage_per_second * dt)

@dataclass
class GameState:
    current_time: float = 0.0
    round_duration: float = 300.0  # 5 minutes
    score: Dict[Team, float] = field(default_factory=lambda: {Team.RED: 0, Team.BLUE: 0})
    objectives: List[Objective] = field(default_factory=list)
    power_ups: List[PowerUp] = field(default_factory=list)
    hazards: List[Hazard] = field(default_factory=list)
    robots: List[Robot] = field(default_factory=list)
    team_scores: Dict[Team, int] = field(default_factory=lambda: {Team.RED: 0, Team.BLUE: 0})
    round_number: int = 1
    winner: Optional[Team] = None
    game_over: bool = False
    difficulty_level: float = 0.5  # 0.0 to 1.0, 0.0 = easy, 1.0 = hard

    def get_teams(self) -> List[Team]:
        return [Team.RED, Team.BLUE]

    def update(self, dt: float):
        self.current_time += dt

        # Update objectives
        for objective in self.objectives:
            objective.update(self.robots, dt)

        # Update power-ups
        for powerup in self.power_ups:
            collected_by = powerup.update(self.current_time, self.robots)
            if collected_by:
                # Find the robot and update team score
                robot = next((r for r in self.robots if r.id == collected_by), None)
                if robot:
                    self.team_scores[robot.team] += 20  # Bonus for collecting power-up

        # Update hazards
        for hazard in self.hazards:
            hazard.update(self.robots, dt)

        # Update game state
        self.calculate_scores()

        # Check for round end
        if self.current_time >= self.round_duration:
            self.end_round()

        # Adaptive difficulty - based on performance
        self.adaptive_difficulty()

    def calculate_scores(self):
        """Calculate scores based on objectives and teamwork"""
        for team in self.get_teams():
            score = 0

            # Objective points
            for objective in self.objectives:
                if objective.captured_by == team:
                    score += objective.capture_progress * objective.completion_score / 100.0

            # Elimination points
            for robot in self.robots:
                if robot.team == team and not robot.is_alive:
                    # Points for killing opponents
                    # We need to track who killed whom
                    pass  # This would require a kill tracker

            # Teamwork bonus
            for robot in self.robots:
                if robot.team == team:
                    score += robot.team_coordination * 10

            self.score[team] = score

    def end_round(self):
        """End the current round and determine winner"""
        self.game_over = True
        red_score = self.score[Team.RED]
        blue_score = self.score[Team.BLUE]

        if red_score > blue_score:
            self.winner = Team.RED
        elif blue_score > red_score:
            self.winner = Team.BLUE
        else:
            self.winner = None  # Tie

        logger.info(f"Round {self.round_number} ended. Winner: {self.winner.value if self.winner else 'Tie'}")
        logger.info(f"Final Score - Red: {red_score:.1f}, Blue: {blue_score:.1f}")

        # Increase difficulty for next round if one team dominated
        if abs(red_score - blue_score) > 100:
            self.difficulty_level = min(1.0, self.difficulty_level + 0.1)

    def adaptive_difficulty(self):
        """Adjust AI behavior based on performance"""
        # Calculate team performance ratio
        red_score = self.score[Team.RED]
        blue_score = self.score[Team.BLUE]

        # If one team is consistently winning, make the other team's AI smarter
        if red_score > blue_score * 2:
            # Blue team is struggling, make AI more aggressive
            for robot in self.robots:
                if robot.team == Team.BLUE:
                    robot.team_coordination = min(1.0, robot.team_coordination + 0.05)
                    # Increase AI aggression
                    if robot.role == RobotRole.ATTACKER:
                        robot.weapon.damage += 5.0
                    elif robot.role == RobotRole.SUPPORT:
                        robot.speed *= 1.1
        elif blue_score > red_score * 2:
            # Red team is struggling
            for robot in self.robots:
                if robot.team == Team.RED:
                    robot.team_coordination = min(1.0, robot.team_coordination + 0.05)
                    if robot.role == RobotRole.ATTACKER:
                        robot.weapon.damage += 5.0
                    elif robot.role == RobotRole.SUPPORT:
