@dataclass
class AIController:
    game_state: GameState

    def update(self, robot: Robot, dt: float):
        if not robot.is_alive:
            return

        # Get teammates and enemies
        teammates = [r for r in self.game_state.robots if r.team == robot.team and r.is_alive and r.id != robot.id]
        enemies = [r for r in self.game_state.robots if r.team != robot.team and r.is_alive]
        objectives = [o for o in self.game_state.objectives if o.is_active]

        # Determine strategy based on role
        if robot.role == RobotRole.ATTACKER:
            self.attacker_strategy(robot, teammates, enemies, objectives, dt)
        elif robot.role == RobotRole.DEFENDER:
            self.defender_strategy(robot, teammates, enemies, objectives, dt)
        elif robot.role == RobotRole.SUPPORT:
            self.support_strategy(robot, teammates, enemies, objectives, dt)
        elif robot.role == RobotRole.SCOUT:
            self.scout_strategy(robot, teammates, enemies, objectives, dt)
        elif robot.role == RobotRole.CONTROLLER:
            self.controller_strategy(robot, teammates, enemies, objectives, dt)

    def attacker_strategy(self, robot: Robot, teammates: List[Robot], enemies: List[Robot], objectives: List[Objective], dt: float):
        if not enemies:
            # No enemies, move toward objective
            if objectives:
                closest_obj = min(objectives, key=lambda o: robot.position.distance_to(o.position))
                if closest_obj.captured_by != robot.team:
                    robot.move_toward(closest_obj.position, dt)
                    robot.team_coordination = min(1.0, robot.team_coordination + 0.01)
                else:
                    # If objective is captured by team, find enemies
                    if enemies:
                        target = self.find_best_target(robot, enemies)
                        if target:
                            robot.move_toward(target.position, dt)
                            if robot.attack(target, self.game_state.current_time):
                                # Successful attack, improve coordination
                                robot.team_coordination = min(1.0, robot.team_coordination + 0.02)
            else:
                # No objectives, just find enemies
                if enemies:
                    target = self.find_best_target(robot, enemies)
                    if target:
                        robot.move_toward(target.position, dt)
                        if robot.attack(target, self.game_state.current_time):
                            robot.team_coordination = min(1.0, robot.team_coordination + 0.02)
                else:
                    robot.stop()
        else:
            # Find best target
            target = self.find_best_target(robot, enemies)
            if target:
                robot.move_toward(target.position, dt)
                if robot.attack(target, self.game_state.current_time):
                    robot.team_coordination = min(1.0, robot.team_coordination + 0.02)
            else:
                robot.stop()

    def defender_strategy(self, robot: Robot, teammates: List[Robot], enemies: List[Robot], objectives: List[Objective], dt: float):
        # Defend objectives or base
        if objectives:
            # Find objectives that need defending
            defend_targets = [o for o in objectives if o.captured_by == robot.team]
            if defend_targets:
                # Defend the most threatened objective
                most_threatened = min(defend_targets, key=lambda o: o.capture_progress if o.captured_by == robot.team else 0)
                # If objective is being recaptured, defend it
                if most_threatened.capture_progress > 50 and most_threatened.captured_by == robot.team:
                    robot.move_toward(most_threatened.position, dt)

                    # If enemies are near, engage
                    nearby_enemies = [e for e in enemies if robot.position.distance_to(e.position) < 30]
                    if nearby_enemies:
                        target = min(nearby_enemies, key=lambda e: robot.position.distance_to(e.position))
                        if robot.attack(target, self.game_state.current_time):
                            robot.team_coordination = min(1.0, robot.team_coordination + 0.02)
                else:
                    # Move toward the objective to defend
                    robot.move_toward(most_threatened.position, dt)
            else:
                # No objectives captured, defend base position or find enemies
                if enemies:
                    target = self.find_best_target(robot, enemies)
                    if target:
                        robot.move_toward(target.position, dt)
                        if robot.attack(target, self.game_state.current_time):
                            robot.team_coordination = min(1.0, robot.team_coordination + 0.02)
                    else:
                        robot.stop()
        else:
            if enemies:
                target = self.find_best_target(robot, enemies)
                if target:
                    robot.move_toward(target.position, dt)
                    if robot.attack(target, self.game_state.current_time):
                        robot.team_coordination = min(1.0, robot.team_coordination + 0.02)
            else:
                robot.stop()

    def support_strategy(self, robot: Robot, teammates: List[Robot], enemies: List[Robot], objectives: List[Objective], dt: float):
        # Support teammates by healing, providing cover, or power-up distribution
        teammates_in_need = [t for t in teammates if t.health < t.max_health * 0.7]

        if teammates_in_need:
            # Find the most in-need teammate
            most_in_need = min(teammates_in_need, key=lambda t: t.health / t.max_health)
            # Move toward teammate
            robot.move_toward(most_in_need.position, dt)

            # If close enough, provide support
            if robot.position.distance_to(most_in_need.position) < 10.0:
                # Give health or power-up if available
                if PowerUpType.REGEN in robot.power_ups:
                    most_in_need.heal(2.0)

                # Increase coordination
                robot.team_coordination = min(1.0, robot.team_coordination + 0.01)
        elif enemies:
            # No teammates in need, engage enemies
            target = self.find_best_target(robot, enemies)
            if target:
                robot.move_toward(target.position, dt)
                if robot.attack(target, self.game_state.current_time):
                    robot.team_coordination = min(1.0, robot.team_coordination + 0.02)
        else:
            # Look for objectives
            if objectives:
                closest_obj = min(objectives, key=lambda o: robot.position.distance_to(o.position))
                if closest_obj.captured_by == robot.team:
                    robot.move_toward(closest_obj.position, dt)

    def scout_strategy(self, robot: Robot, teammates: List[Robot], enemies: List[Robot], objectives: List[Objective], dt: float):
        # Scout for enemy positions and report back
        # Move to high ground or strategic positions
        if enemies:
            # Find enemy positions and move toward them to get info
            target = self.find_best_target(robot, enemies)
            if target:
                # Move toward enemy but keep distance to avoid combat
                distance_to_target = robot.position.distance_to(target.position)
                if distance_to_target > 40.0:
                    robot.move_toward(target.position, dt)
                elif distance_to_target > 20.0:
                    robot.move_toward(target.position, dt)
                else:
                    # Too close, move away to avoid combat
                    robot.move_away(target.position, dt)

                # Store enemy position
                robot.last_known_enemy_positions.append(target.position.copy())
                if len(robot.last_known_enemy_positions) > 5:
                    robot.last_known_enemy_positions.pop(0)

                # Report to teammates
                for teammate in teammates:
                    teammate.team_coordination = min(1.0, teammate.team_coordination + 0.005)
        else:
            # No enemies detected, explore map
            # Find unexplored objectives
            if objectives:
                unclaimed = [o for o in objectives if o.captured_by is None or o.captured_by != robot.team]
                if unclaimed:
                    closest_unclaimed = min(unclaimed, key=lambda o: robot.position.distance_to(o.position))
                    robot.move_toward(closest_unclaimed.position, dt)
                else:
                    # Move to a random position
                    random_x = random.uniform(-50, 50)
                    random_y = random.uniform(-50, 50)
                    robot.move_toward(Vector2D(random_x, random_y), dt)
            else:
                random_x = random.uniform(-50, 50)
                random_y = random.uniform(-50, 50)
                robot.move_toward(Vector2D(random_x, random_y), dt)

    def controller_strategy(self, robot: Robot, teammates: List[Robot], enemies: List[Robot], objectives: List[Objective], dt: float):
        # Control the battlefield by coordinating team actions
        # Find key objectives and direct teammates
        objectives_to_control = [o for o in objectives if o.captured_by == robot.team]

        if objectives_to_control:
            # Control a key objective
            target_obj = max(objectives_to_control, key=lambda o: o.capture_progress)
            robot.move_toward(target_obj.position, dt)

            # Find teammates who are not near objective
            teammates_far = [t for t in teammates if t.position.distance_to(target_obj.position) > 20]

            # If teammates are far, guide them to the objective
            for teammate in teammates_far:
                # Create a "command" by moving toward the teammate and guiding
                if teammate.position.distance_to(robot.position) < 15.0:
                    # Give verbal guidance (simulated)
                    teammate.team_coordination = min(1.0, teammate.team_coordination + 0.01)

            # If enemies nearby, engage or call for backup
            nearby_enemies = [e for e in enemies if robot.position.distance_to(e.position) < 35]
            if nearby_enemies:
                # Coordinate team defense
                target = min(nearby_enemies, key=lambda e: robot.position.distance_to(e.position))
                if robot.attack(target, self.game_state.current_time):
                    # Alert teammates
                    for teammate in teammates:
                        teammate.team_coordination = min(1.0, teammate.team_coordination + 0.02)

        else:
            # No objectives under control, find and capture
            if objectives:
                target_obj = min(objectives, key=lambda o: robot.position.distance_to(o.position))
                robot.move_toward(target_obj.position, dt)

    def find_best_target(self, robot: Robot, enemies: List[Robot]) -> Optional[Robot]:
        """Find the best target based on threat, health, distance, and role"""
        if not enemies:
            return None

        best_target = None
        best_score = -float('inf')

        for enemy in enemies:
            distance = robot.position.distance_to(enemy.position)
            if distance > robot.weapon.range:
                continue  # Out of range

            # Score based on multiple factors
            score = 0

            # Health factor - target lower health
            health_ratio = enemy.health / enemy.max_health
            score += (1 - health_ratio) * 20

            # Distance factor - closer is better
            if distance > 0:
                score += 10 / distance

            # Role priority - attackers are higher priority
            if enemy.role == RobotRole.ATTACKER:
                score += 30
            elif enemy.role == RobotRole.SUPPORT:
                score += 20
            elif enemy.role == RobotRole.CONTROLLER:
                score += 25

            # Enemy is threatening our objective
            for objective in self.game_state.objectives:
                if objective.captured_by == robot.team:
                    if enemy.position.distance_to(objective.position) < 20:
                        score += 40  # High priority

            # If enemy has power-up, target them
            if enemy.power_ups:
                score += 25

            # Avoid targets that are too far
            if distance > robot.vision_range * 1.5:
                score -= 100

            if score > best_score:
                best_score = score
                best_target = enemy

        return best_target

