        if robot_type == RobotType.ASSAULT:
            return Weapon(WeaponType.RANGED, "Assault Rifle", 20, 0.3, 40, 150)
        elif robot_type == RobotType.SUPPORT:
            return Weapon(WeaponType.RANGED, "Healing Rifle", 10, 0.5, 35, 120)
