        return self.active

@dataclass
class PowerUp:
    type: PowerUpType
    position: Vector2D
    value: float
    duration: float
    collected: bool = False
    spawn_time: float = 0.0
    respawn_time: float = 30.0

    def is_available(self, current_time: float) -> bool:
        return not self.collected and (current_time - self.spawn_time >= self.respawn_time)

@dataclass
class Hazard:
    type: HazardType
    position: Vector2D
    radius: float
    damage_per_second: float
    active: bool = True
    spawn_time: float = 0.0

    def affects_position(self, position: Vector2D) -> bool:
        return self.position.distance_to(position) <= self.radius

@dataclass
class Objective:
    type: ObjectiveType
    position: Vector2D
    team: Team
    progress: float = 0.0
    max_progress: float = 100.0
    captured: bool = False
    defenders: List[str] = field(default_factory=list)
    attackers: List[str] = field(default_factory=list)
    payload_speed: float = 2.0
    payload_path: List[Vector2D] = field(default_factory=list)
    payload_current_target: int = 0

    def update_progress(self, team: Team, amount: float) -> bool:
        if team == self.team and not self.captured:
            self.progress = min(self.progress + amount, self.max_progress)
            if self.progress >= self.max_progress:
                self.captured = True
                return True
        elif team != self.team and self.captured:
            self.progress = max(self.progress - amount, 0)
            if self.progress <= 0:
                self.captured = False
                self.team = team
                return True
        return False

@dataclass
class GameMap:
    width: int = 1000
    height: int = 1000
    spawn_points: Dict[Team, List[Vector2D]] = field(default_factory=dict)
    objectives: List[Objective] = field(default_factory=list)
    power_ups: List[PowerUp] = field(default_factory=list)
    hazards: List[Hazard] = field(default_factory=list)
    walls: List[Tuple[Vector2D, Vector2D]] = field(default_factory=list)

    def __post_init__(self):
        if not self.spawn_points:
            self.spawn_points = {
                Team.RED: [Vector2D(100, 100), Vector2D(150, 150)],
                Team.BLUE: [Vector2D(900, 900), Vector2D(850, 850)]
            }

# ============================
# BEHAVIOR TREE IMPLEMENTATION
# ============================

class BehaviorNode:
    def __init__(self):
        self.children = []

    def execute(self, robot: Robot, game_state: 'GameState') -> bool:
        raise NotImplementedError

class SelectorNode(BehaviorNode):
    def execute(self, robot: Robot, game_state: 'GameState') -> bool:
        for child in self.children:
            if child.execute(robot, game_state):
                return True
        return False

class SequenceNode(BehaviorNode):
    def execute(self, robot: Robot, game_state: 'GameState') -> bool:
        for child in self.children:
            if not child.execute(robot, game_state):
                return False
        return True

class ActionNode(BehaviorNode):
    def __init__(self, action_func):
        super().__init__()
        self.action_func = action_func

    def execute(self, robot: Robot, game_state: 'GameState') -> bool:
        return self.action_func(robot, game_state)

class ConditionNode(BehaviorNode):
    def __init__(self, condition_func):
        super().__init__()
        self.condition_func = condition_func

    def execute(self, robot: Robot, game_state: 'GameState') -> bool:
        return self.condition_func(robot, game_state)

class BehaviorTree:
    def __init__(self, robot: Robot):
        self.robot = robot
        self.root = self.build_behavior_tree()

    def build_behavior_tree(self) -> BehaviorNode:
        # Root selector: try different strategies based on situation
        root = SelectorNode()

        # Priority 1: If health is low, find healing or retreat
        low_health_sequence = SequenceNode()
        low_health_sequence.children.append(
            ConditionNode(lambda r, gs: r.health < 30)
        )
        low_health_sequence.children.append(
            ActionNode(self._seek_healing)
        )

        # Priority 2: If objective is nearby, prioritize objective
        objective_sequence = SequenceNode()
        objective_sequence.children.append(
            ConditionNode(self._has_objective_in_range)
        )
        objective_sequence.children.append(
            ActionNode(self._pursue_objective)
        )

        # Priority 3: If enemy nearby, attack
        attack_sequence = SequenceNode()
        attack_sequence.children.append(
            ConditionNode(self._has_enemy_in_range)
        )
        attack_sequence.children.append(
            ActionNode(self._attack_enemy)
        )

        # Priority 4: Patrol or explore
        patrol_sequence = SequenceNode()
        patrol_sequence.children.append(
            ActionNode(self._patrol)
        )

        root.children.extend([
            low_health_sequence,
            objective_sequence,
            attack_sequence,
            patrol_sequence
        ])

        return root

    def execute(self, game_state: 'GameState') -> bool:
        return self.root.execute(self.robot, game_state)

    def _seek_healing(self, robot: Robot, game_state: 'GameState') -> bool:
        # Find nearby power-ups or ally support
        closest_heal = None
        for powerup in game_state.map.power_ups:
            if (powerup.type == PowerUpType.HEAL and 
                not powerup.collected and 
                robot.position.distance_to(powerup.position) < 20):
                closest_heal = powerup
                break

        if closest_heal:
            # Move toward power-up
            direction = (closest_heal.position - robot.position).normalize()
            robot.position = robot.position + direction * robot.speed * 0.1
            robot.last_action = f"seeking_heal_{closest_heal.type.value}"
            return True
        else:
            # Retreat to spawn if possible
            spawn_points = game_state.map.spawn_points.get(robot.team, [])
            if spawn_points:
                closest_spawn = min(spawn_points, 
                                  key=lambda p: robot.position.distance_to(p))
                direction = (closest_spawn - robot.position).normalize()
                robot.position = robot.position + direction * robot.speed * 0.05
                robot.last_action = "retreating"
            return False

    def _has_objective_in_range(self, robot: Robot, game_state: 'GameState') -> bool:
        for obj in game_state.map.objectives:
            if robot.position.distance_to(obj.position) < robot.vision_range:
                return True
        return False

    def _pursue_objective(self, robot: Robot, game_state: 'GameState') -> bool:
        closest_obj = None
        closest_dist = float('inf')

        for obj in game_state.map.objectives:
            dist = robot.position.distance_to(obj.position)
            if dist < closest_dist and dist < robot.vision_range:
                closest_dist = dist
                closest_obj = obj

        if closest_obj:
            direction = (closest_obj.position - robot.position).normalize()
            robot.position = robot.position + direction * robot.speed * 0.1
            robot.last_action = f"pursuing_{closest_obj.type.value}"

            # Update objective progress if in range
            if closest_dist < 10:
                team_progress = 1.0 if robot.team == closest_obj.team else -0.5
                closest_obj.update_progress(robot.team, team_progress)
                robot.team_objective_progress = min(100, robot.team_objective_progress + 0.1)

            return True
        return False

    def _has_enemy_in_range(self, robot: Robot, game_state: 'GameState') -> bool:
        for other_robot in game_state.robots:
            if (other_robot.team != robot.team and 
                other_robot.is_active and 
                robot.position.distance_to(other_robot.position) < robot.vision_range):
                return True
        return False

    def _attack_enemy(self, robot: Robot, game_state: 'GameState') -> bool:
        target_robot = None
        min_dist = float('inf')

        for other_robot in game_state.robots:
            if (other_robot.team != robot.team and 
                other_robot.is_active):
                dist = robot.position.distance_to(other_robot.position)
                if dist < min_dist and dist < robot.weapon.range:
                    min_dist = dist
                    target_robot = other_robot

        if target_robot:
            # Aim at target
            direction = (target_robot.position - robot.position).normalize()
            robot.last_action = "attacking"

            # Fire weapon if possible
            current_time = time.time()
            if robot.weapon.fire(current_time):
                # Create projectile (simplified)
                game_state.add_projectile(
                    robot.position, direction * robot.weapon.projectile_speed,
                    robot.weapon.damage, robot.team, robot.id
                )
                robot.last_action = f"firing_{robot.weapon.name}"

            # Move toward target if too far
            if min_dist > robot.weapon.range * 0.8:
                robot.position = robot.position + direction * (robot.speed * 0.08)

            return True
        return False

    def _patrol(self, robot: Robot, game_state: 'GameState') -> bool:
        # Simple patrol pattern
        patrol_points = [
            Vector2D(300, 300), Vector2D(300, 700), 
            Vector2D(700, 700), Vector2D(700, 300)
        ]

        if not hasattr(robot, 'current_patrol_index'):
            robot.current_patrol_index = 0

        target = patrol_points[robot.current_patrol_index]
        dist = robot.position.distance_to(target)

        if dist < 10:
            robot.current_patrol_index = (robot.current_patrol_index + 1) % len(patrol_points)
            target = patrol_points[robot.current_patrol_index]

        direction = (target - robot.position).normalize()
        robot.position = robot.position + direction * robot.speed * 0.1
        robot.last_action = "patrolling"

        return True

# ============================
# GAME STATE AND ENGINE
