class GameState:
    def __init__(self, map_config: GameMap):
        self.map = map_config
        self.robots: List[Robot] = []
        self.projectiles: List[Projectile] = []
        self.power_ups: List[PowerUp] = []
        self.hazards: List[Hazard] = []
        self.scores: Dict[Team, float] = {Team.RED: 0, Team.BLUE: 0}
        self.round_time: float = 0
        self.last_update: float = time.time()
        self.game_over: bool = False
        self.winning_team: Optional[Team] = None
        self.team_objectives: Dict[Team, List[Objective]] = {Team.RED: [], Team.BLUE: []}
        self.adaptive_difficulty: float = 0.5  # 0.0 = easy, 1.0 = hard
        self.battle_history: List[Dict] = []
        self.sound_effects: List[str] = []
        self.particle_effects: List[ParticleEffect] = []

        # Initialize objectives based on map
        self._init_objectives()

        # Add some initial power-ups and hazards
        self._spawn_initial_resources()

    def _init_objectives(self):
        # Example: One flag capture objective for each team
        flag_red = Objective(
            type=ObjectiveType.CAPTURE_FLAG,
            position=Vector2D(200, 500),
            team=Team.RED,
            max_progress=100
        )
        flag_blue = Objective(
            type=ObjectiveType.CAPTURE_FLAG,
            position=Vector2D(800, 500),
            team=Team.BLUE,
            max_progress=100
        )

        self.map.objectives.extend([flag_red, flag_blue])
        self.team_objectives[Team.RED].append(flag_red)
        self.team_objectives[Team.BLUE].append(flag_blue)

    def _spawn_initial_resources(self):
        # Generate power-ups
        for _ in range(5):
            power_type = random.choice(list(PowerUpType))
            pos = Vector2D(
                random.randint(100, 900),
                random.randint(100, 900)
            )
            power_up = PowerUp(
                type=power_type,
                position=pos,
                value=20,
                duration=15,
                spawn_time=time.time()
            )
            self.map.power_ups.append(power_up)

        # Generate hazards
        for _ in range(3):
            hazard_type = random.choice(list(HazardType))
            pos = Vector2D(
                random.randint(200, 800),
                random.randint(200, 800)
            )
            hazard = Hazard(
                type=hazard_type,
                position=pos,
                radius=15,
                damage_per_second=5,
                spawn_time=time.time()
            )
            self.map.hazards.append(hazard)

    def add_robot(self, robot: Robot):
        self.robots.append(robot)

    def add_projectile(self, position: Vector2D, velocity: Vector2D, damage: float, team: Team, shooter_id: str):
        projectile = Projectile(position, velocity, damage, team, shooter_id)
        self.projectiles.append(projectile)

    def add_particle_effect(self, position: Vector2D, color: str, particle_type: str, duration: float):
        effect = ParticleEffect(position, color, particle_type, duration)
        self.particle_effects.append(effect)

    def add_sound_effect(self, sound: str):
        self.sound_effects.append(sound)

    def update(self, delta_time: float):
        current_time = time.time()
        self.round_time += delta_time

        # Update robots
        for robot in self.robots:
            if not robot.is_active:
                continue

            # Update cooldowns
            for ability in robot.abilities:
                ability.update(current_time)

            # Update weapon reload
            if robot.weapon.is_reloading:
                robot.weapon.reload(current_time)

            # Execute behavior tree
            self._execute_robot_behavior(robot)

            # Update position if moving
            # Note: In a real game, this would be handled by physics
            # Here we just use the behavior tree to modify position

            # Check for collisions with hazards
            for hazard in self.map.hazards:
                if hazard.active and hazard.affects_position(robot.position):
                    robot.health -= hazard.damage_per_second * delta_time
                    if robot.health <= 0:
                        robot.is_active = False
                        self.add_sound_effect(f"robot_{robot.id}_destroyed")
                        self.add_particle_effect(robot.position, "red", "explosion", 2.0)
                        break

            # Check for power-up collection
            for power_up in self.map.power_ups:
                if (not power_up.collected and 
                    robot.position.distance_to(power_up.position) < 10):
                    self._apply_power_up(robot, power_up)
                    power_up.collected = True
                    self.add_sound_effect(f"powerup_{power_up.type.value}_collected")
                    self.add_particle_effect(power_up.position, "yellow", "collect", 1.0)
                    power_up.spawn_time = current_time  # Reset respawn timer

        # Update projectiles
        projectiles_to_remove = []
        for projectile in self.projectiles:
            projectile.update(delta_time)

            # Check for collisions with robots
            for robot in self.robots:
                if (robot.team != projectile.team and 
                    robot.is_active and 
                    robot.position.distance_to(projectile.position) < 8):

                    robot.health -= projectile.damage
                    self.add_sound_effect(f"hit_{robot.id}")
                    self.add_particle_effect(robot.position, "orange", "impact", 0.5)

                    if robot.health <= 0:
                        robot.is_active = False
                        self.add_sound_effect(f"robot_{robot.id}_destroyed")
                        self.add_particle_effect(robot.position, "red", "explosion", 2.0)

                    projectiles_to_remove.append(projectile)
                    break

            # Check for collisions with walls or boundaries
            if (projectile.position.x < 0 or projectile.position.x > self.map.width or
                projectile.position.y < 0 or projectile.position.y > self.map.height):
                projectiles_to_remove.append(projectile)

        # Remove projectiles that hit targets or went out of bounds
        for projectile in projectiles_to_remove:
            if projectile in self.projectiles:
                self.projectiles.remove(projectile)

        # Update hazards
        for hazard in self.map.hazards:
            if not hazard.active:
                continue
            # Hazards persist for the round

        # Update power-ups respawn
        for power_up in self.map.power_ups:
            if power_up.collected and current_time - power_up.spawn_time >= power_up.respawn_time:
                power_up.collected = False
                power_up.spawn_time = current_time

        # Update objectives
        for obj in self.map.objectives:
            if obj.type == ObjectiveType.ESCORT_PAYLOAD and len(obj.payload_path) > 0:
                # Move payload along path
                target = obj.payload_path[obj.payload_current_target]
                direction = (target - obj.position).normalize()
                obj.position = obj.position + direction * obj.payload_speed * delta_time

                # Check if reached target
                if obj.position.distance_to(target) < 5:
                    obj.payload_current_target = (obj.payload_current_target + 1) % len(obj.payload_path)
                    self.add_sound_effect("payload_reached_checkpoint")

        # Update scoring based on objectives
        self._update_scores()

        # Update adaptive difficulty
        self._update_adaptive_difficulty()

        # Update particle effects
        self.particle_effects = [
            effect for effect in self.particle_effects 
            if effect.duration > 0
        ]
        for effect in self.particle_effects:
            effect.duration -= delta_time

        # Apply score decay for inactivity
        self._apply_score_decay()

    def _execute_robot_behavior(self, robot: Robot):
        # Execute behavior tree
        robot.behavior_tree.execute(self)

    def _apply_power_up(self, robot: Robot, power_up: PowerUp):
        if power_up.type == PowerUpType.HEAL:
            robot.health = min(robot.max_health, robot.health + power_up.value)
        elif power_up.type == PowerUpType.SPEED_BOOST:
            robot.speed *= 1.5
            # Add temporary effect
            timer = threading.Timer(power_up.duration, lambda: setattr(robot, 'speed', robot.speed / 1.5))
            timer.start()
        elif power_up.type == PowerUpType.SHIELD:
            # In a real system, this would implement a shield mechanic
            robot.max_health *= 1.2
            robot.health = robot.max_health
        elif power_up.type == PowerUpType.WEAPON_UPGRADE:
            robot.weapon.damage *= 1.5
            robot.weapon.range *= 1.2
        elif power_up.type == PowerUpType.INVISIBILITY:
            # Invisibility effect (simplified)
            pass

    def _update_scores(self):
        for team in [Team.RED, Team.BLUE]:
            score = 0

            # Points for objectives captured
            for obj in self.team_objectives[team]:
                if obj.captured:
                    score += 50
                    score += obj.progress * 0.5  # Bonus for progress

            # Points for enemy eliminations
            for robot in self.robots:
                if robot.team != team and not robot.is_active:
                    # Check if this robot was killed by a teammate
                    # (simplified: assume any kill gives 10 points to the opposing team)
                    score += 10

            # Points for teamwork (robots near objectives)
            for obj in self.team_objectives[team]:
                if obj.captured:
                    teammates_near = sum(
                        1 for r in self.robots 
                        if r.team == team and r.is_active and 
                        r.position.distance_to(obj.position) < 20
                    )
                    score += teammates_near * 2

            self.scores[team] = score

    def _update_adaptive_difficulty(self):
        # Calculate team performance ratio
        red_score = self.scores[Team.RED]
        blue_score = self.scores[Team.BLUE]

        if red_score + blue_score == 0:
            self.adaptive_difficulty = 0.5
        else:
            # Adjust difficulty based on team imbalance
            ratio = red_score / (red_score + blue_score)
            # Target 50% win rate for balanced gameplay
            if ratio < 0.35:
                # Red team is underperforming, make it easier
                self.adaptive_difficulty = max(0.1, self.adaptive_difficulty - 0.01)
            elif ratio > 0.65:
                # Blue team is underperforming, make it easier
                self.adaptive_difficulty = min(0.9, self.adaptive_difficulty + 0.01)
            else:
                # Balanced, maintain current difficulty
                pass

        # Apply difficulty adjustments to AI behavior
        for robot in self.robots:
            if robot.team == Team.RED:
                # Adjust enemy behavior based on difficulty
                pass
            else:
                # Adjust enemy behavior based on difficulty
                pass

    def _apply_score_decay(self):
        # Apply decay to prevent stalemates
        decay_rate = 0.01
        for team in self.scores:
            if self.scores[team] > 0:
                self.scores[team] -= decay_rate

@dataclass
class Projectile:
    position: Vector2D
    velocity: Vector2D
    damage: float
    team: Team
    shooter_id: str
    lifetime: float = 5.0
    created_time: float = field(default_factory=time.time)

    def update(self, delta_time: float):
        self.position = self.position + self.velocity * delta_time
        self.lifetime -= delta_time

@dataclass
class ParticleEffect:
    position: Vector2D
    color: str
    particle_type: str
    duration: float

# ============================
# MAIN CYBERARENA SYSTEM
# ============================

class CyberArena:
    def __init__(self, map_config: GameMap = None):
        if map_config is None:
            map_config = GameMap()

        self.game_state = GameState(map_config)
        self.is_running = False
        self.paused = False
        self.simulation_speed = 1.0
        self.last_frame_time = time.time()
        self.frame_count = 0

        # Initialize robots
        self._init_robots()

    def _init_robots(self):
        # Create 8 robots: 4 red, 4 blue
        robot_types = [RobotType.ASSAULT, RobotType.SUPPORT, RobotType.SCOUT, RobotType.TANK]

        # Red team robots
        for i in range(4):
            spawn_point = self.game_state.map.spawn_points[Team.RED][i % len(self.game_state.map.spawn_points[Team.RED])]
            robot_type = robot_types[i % len(robot_types)]

            robot = Robot(
                id=f"red_{i}",
                team=Team.RED,
                robot_type=robot_type,
                position=spawn_point,
                weapon=self._create_default_weapon(robot_type),
                abilities=self._create_abilities(robot_type),
                role=self._get_role_for_type(robot_type)
            )
            self.game_state.add_robot(robot)

        # Blue team robots
        for i in range(4):
            spawn_point = self.game_state.map.spawn_points[Team.BLUE][i % len(self.game_state.map.spawn_points[Team.BLUE])]
            robot_type = robot_types[i % len(robot_types)]

            robot = Robot(
                id=f"blue_{i}",
                team=Team.BLUE,
                robot_type=robot_type,
                position=spawn_point,
                weapon=self._create_default_weapon(robot_type),
                abilities=self._create_abilities(robot_type),
                role=self._get_role_for_type(robot_type)
            )
            self.game_state.add_robot(robot)

    def _create_default_weapon(self, robot_type: RobotType) -> Weapon:
        if robot_type == RobotType.ASSAULT:
            return Weapon(WeaponType.RANGED, "Assault Rifle", 20, 0.3, 40, 150)
        elif robot_type == RobotType.SUPPORT:
            return Weapon(WeaponType.RANGED, "Healing Rifle", 10, 0.5, 35, 120)
        elif robot_type == RobotType.SCOUT:
            return Weapon(WeaponType.RANGED, "Sniper Rifle", 40, 1.5, 80, 60)
        elif robot_type == RobotType.TANK:
            return Weapon(WeaponType.MELEE, "Heavy Cannon", 30, 2.0, 20, 80)

    def _create_abilities(self, robot_type: RobotType) -> List[Ability]:
        abilities = []
        if robot_type == RobotType.ASSAULT:
            abilities.append(Ability("Rapid Fire", "Increase fire rate", 30, 10, "speed_boost", 1.5))
        elif robot_type == RobotType.SUPPORT:
            abilities.append(Ability("Heal Aura", "Heal nearby allies", 20, 8, "heal", 15))
        elif robot_type == RobotType.SCOUT:
            abilities.append(Ability("Cloak", "Become invisible", 45, 15, "invisibility", 1.0))
        elif robot_type == RobotType.TANK:
            abilities.append(Ability("Shield", "Deploy protective barrier", 60, 20, "shield", 50))
        return abilities

    def _get_role_for_type(self, robot_type: RobotType) -> str:
        role_map = {
            RobotType.ASSAULT: "offense",
            RobotType.SUPPORT: "support",
            RobotType.SCOUT: "recon",
            RobotType.TANK: "defense"
        }
        return role_map.get(robot_type, "default")

    def start(self):
        self.is_running = True
        self.last_frame_time = time.time()
        print("CyberArena started!")

        # Game loop
        while self.is_running:
            if not self.paused:
                current_time = time.time()
                delta_time = (current_time - self.last_frame_time) * self.simulation_speed
                self.last_frame_time = current_time

                # Update game state
                self.game_state.update(delta_time)

                # Check for game over conditions
                self._check_game_over()

                # Increment frame counter
                self.frame_count += 1

            # Small delay to prevent excessive CPU usage
            time.sleep(0.016)  # ~60 FPS target

    def pause(self):
        self.paused = not self.paused
        print(f"CyberArena {'paused' if self.paused else 'resumed'}")

    def stop(self):
