@dataclass
class Weapon:
    type: WeaponType
    name: str
    damage: float
    fire_rate: float  # seconds between shots
    range: float
    ammo: int = 100
    max_ammo: int = 100
    projectile_speed: float = 15.0
    reload_time: float = 3.0
    is_reloading: bool = False
    last_fired: float = 0.0

    def can_fire(self, current_time: float) -> bool:
        return (current_time - self.last_fired >= self.fire_rate and 
                self.ammo > 0 and not self.is_reloading)

    def fire(self, current_time: float) -> bool:
        if self.can_fire(current_time):
            self.ammo -= 1
            self.last_fired = current_time
            return True
        return False

    def reload(self, current_time: float) -> bool:
        if self.is_reloading:
            if current_time - self.last_fired >= self.reload_time:
                self.ammo = self.max_ammo
                self.is_reloading = False
                return True
        elif self.ammo < self.max_ammo:
            self.is_reloading = True
            self.last_fired = current_time
        return False

@dataclass
class Ability:
    name: str
    description: str
    cooldown: float
    duration: float
    effect: str  # e.g., "heal", "speed_boost", "shield"
    magnitude: float  # e.g., heal amount, speed multiplier
    active: bool = False
    activation_time: float = 0.0

    def is_ready(self, current_time: float) -> bool:
        if not self.active:
            return True
        return current_time - self.activation_time >= self.cooldown

    def activate(self, current_time: float) -> bool:
        if self.is_ready(current_time):
            self.active = True
            self.activation_time = current_time
            return True
        return False

    def update(self, current_time: float) -> bool:
        if self.active and current_time - self.activation_time >= self.duration:
            self.active = False
            return False
        return self.active

