    payload_current_target: int = 0

    def update_progress(self, team: Team, amount: float) -> bool:
        if team == self.team and not self.captured:
            self.progress = min(self.progress + amount, self.max_progress)
            if self.progress >= self.max_progress:
                self.captured = True
                return True
        elif team != self.team and self.captured:
            self.progress = max(self.progress - amount, 0)
            if self.progress <= 0:
                self.captured = False
                self.team = team
                return True
        return False

