@dataclass
class Position:
    x: float
    y: float

    def distance_to(self, other: 'Position') -> float:
        return math.sqrt((self.x - other.x)**2 + (self.y - other.y)**2)

    def normalize(self) -> 'Position':
        mag = math.sqrt(self.x**2 + self.y**2)
        if mag == 0:
            return Position(0, 0)
        return Position(self.x / mag, self.y / mag)

    def __add__(self, other):
        return Position(self.x + other.x, self.y + other.y)

    def __sub__(self, other):
        return Position(self.x - other.x, self.y - other.y)

    def __mul__(self, scalar):
        return Position(self.x * scalar, self.y * scalar)

    def __repr__(self):
        return f"Position({self.x:.1f}, {self.y:.1f})"

@dataclass
class Velocity:
    vx: float = 0
    vy: float = 0

    def update(self, ax: float, ay: float, dt: float):
        self.vx += ax * dt
        self.vy += ay * dt

    def apply_friction(self, friction: float = 0.95):
        self.vx *= friction
        self.vy *= friction

    def magnitude(self) -> float:
        return math.sqrt(self.vx**2 + self.vy**2)

    def clamp(self, max_speed: float):
        mag = self.magnitude()
        if mag > max_speed:
            ratio = max_speed / mag
            self.vx *= ratio
            self.vy *= ratio

