    radius: float
    damage: float = 0
    effect: str = ""
    spawn_time: float = 0
    active: bool = True
    color: str = "gray"

@dataclass
class Objective:
    type: ObjectiveType
    position: Position
    team: int = -1  # which team owns it
    progress: float = 0.0  # 0.0 to 1.0
    completed: bool = False
    required_robots: int = 1
    captured_by: List[int] = field(default_factory=list)
    capture_radius: float = 50.0
    respawn_time: float = 0  # for objectives that respawn

    def update_progress(self, robots_in_range: List[int], dt: float) -> bool:
        """Update progress based on robots in range."""
        if self.completed:
            return True

        # Only progress if robots from the team are in range
        if self.team == -1 or len(robots_in_range) >= self.required_robots:
            self.progress += dt * 0.5 / len(robots_in_range) if robots_in_range else 0
            if self.progress >= 1.0:
                self.completed = True
                return True
        return False

@dataclass
class GameStateManager:
    state: GameState = GameState.PREPARING
    time_elapsed: float = 0.0
    match_duration: float = 300.0  # 5 minutes
    current_objective: Optional[Objective] = None
    objectives: List[Objective] = field(default_factory=list)
    score: Dict[int, int] = field(default_factory=lambda: {0: 0, 1: 0})
    team_objectives_completed: Dict[int, int] = field(default_factory=lambda: {0: 0, 1: 0})
    win_condition: str = "first_to_3"
    last_update: float = 0.0

    def update(self, dt: float) -> bool:
        """Update game state and check win conditions."""
        self.time_elapsed += dt

        # Check if match is over
        if self.time_elapsed >= self.match_duration:
            self.state = GameState.ENDED
            return True

        # Update objectives
        for obj in self.objectives:
            # If objective is not completed, update progress
            if not obj.completed:
                obj.update_progress([], dt)  # This would be updated with actual robots in range
                if obj.completed:
                    self.team_objectives_completed[obj.team] += 1
                    self.score[obj.team] += 100  # Reward for objective completion
                    # Reset objective after some time
                    if obj.respawn_time > 0:
                        obj.completed = False
                        obj.progress = 0.0
                        obj.captured_by = []
                        threading.Timer(obj.respawn_time, lambda: None).start()

        # Check win condition
        if self.win_condition == "first_to_3":
            if self.team_objectives_completed[0] >= 3:
                self.state = GameState.ENDED
                return True
            if self.team_objectives_completed[1] >= 3:
                self.state = GameState.ENDED
                return True

        return False

