class RobotAI:
    def __init__(self, robot: Robot, game_state: GameStateManager, all_robots: List[Robot]):
        self.robot = robot
        self.game_state = game_state
        self.all_robots = all_robots
        self.team_robots = [r for r in all_robots if r.team == robot.team and not r.is_dead]
        self.enemy_robots = [r for r in all_robots if r.team != robot.team and not r.is_dead]
        self.adaptive_difficulty = 1.0  # 1.0 is normal, higher = harder
        self.strategy_history = deque(maxlen=20)  # Keep last 20 decisions

    def update(self, dt: float) -> Dict:
        """Update AI behavior and return action commands."""
        if self.robot.is_dead:
            return {"action": "dead", "target": None}

        # Update team and enemy lists
        self.team_robots = [r for r in self.all_robots if r.team == self.robot.team and not r.is_dead]
        self.enemy_robots = [r for r in self.all_robots if r.team != self.robot.team and not r.is_dead]

        # Update power-ups and weapons
        self.robot.update_power_ups(dt)
        self.robot.update_weapon_cooldowns(dt)

        # Adaptive difficulty: adjust AI behavior based on team performance
        self._update_adaptive_difficulty()

        # Determine current state
        state = self.robot.get_behavior_state()

        if state == "dead":
            return {"action": "dead", "target": None}

        # Get current objective
        if self.game_state.current_objective:
            target_pos = self.game_state.current_objective.position
        else:
            # Default to enemy base
            target_pos = Position(GAME_WIDTH * 0.8 if self.robot.team == 0 else GAME_WIDTH * 0.2, GAME_HEIGHT * 0.5)

        # Decide on action based on state and strategy
        action = self._choose_action(state, target_pos)

        # Record decision for learning
        self.strategy_history.append({
            "state": state,
            "action": action,
            "time": time.time(),
            "team_health": sum(r.health for r in self.team_robots) / len(self.team_robots) if self.team_robots else 0,
            "enemy_count": len(self.enemy_robots)
        })

        return action

    def _update_adaptive_difficulty(self):
        """Adjust AI difficulty based on team performance."""
        # Calculate team win rate (simplified)
        team_health_ratio = sum(r.health for r in self.team_robots) / (len(self.team_robots) * self.robot.max_health) if self.team_robots else 0
        enemy_health_ratio = sum(r.health for r in self.enemy_robots) / (len(self.enemy_robots) * self.robot.max_health) if self.enemy_robots else 0

        # If team is doing well, make AI more aggressive
        if team_health_ratio > 0.7 and enemy_health_ratio < 0.3:
            self.adaptive_difficulty = 1.2  # Make AI smarter and more aggressive
        # If team is struggling, make AI more defensive
        elif team_health_ratio < 0.3 and enemy_health_ratio > 0.7:
            self.adaptive_difficulty = 0.8  # Make AI more cautious
        else:
            self.adaptive_difficulty = 1.0  # Normal difficulty

    def _choose_action(self, state: str, target_pos: Position) -> Dict:
        """Choose the best action based on current state."""
        # Get closest enemy
        closest_enemy = self.robot.get_closest_enemy(self.enemy_robots)

        # If no enemies visible, move toward objective
        if not closest_enemy:
            return self._move_to_objective(target_pos)

        # If enemy is very close, consider melee attack
        distance_to_enemy = self.robot.position.distance_to(closest_enemy.position)

        # Check if we can attack enemy with current weapon
        if distance_to_enemy <= self.robot.weapon.range and self.robot.weapon.can_fire():
            # Decide whether to attack or use strategy
            attack_prob = 0.8 + (0.2 * self.adaptive_difficulty)  # Higher difficulty = more aggressive

            if random.random() < attack_prob:
                return self._attack_enemy(closest_enemy)

        # If we're low on health, retreat
        if self.robot.health < self.robot.max_health * 0.3:
            return self._retreat()

        # If we're supporting, try to heal or buff teammates
        if self.robot.role == RobotRole.SUPPORT and self._can_heal_teammate():
            return self._heal_teammate()

        # If we're a defender, position near objective
        if self.robot.role == RobotRole.DEFENDER and self._is_near_objective(target_pos):
            return self._defend_objective(target_pos)

        # Scout: move to perimeter
        if self.robot.role == RobotRole.SCOUT:
            return self._explore_perimeter()

        # Default: chase enemy
        if closest_enemy:
            return self._chase_enemy(closest_enemy)

        # Fallback: move to objective
        return self._move_to_objective(target_pos)

    def _move_to_objective(self, target_pos: Position) -> Dict:
        """Move robot toward objective."""
        # Calculate direction to target
        direction = target_pos - self.robot.position
        if direction.magnitude() > 0:
            direction = direction.normalize()

        # Calculate desired velocity
        speed = self.robot.get_effective_speed()
        desired_velocity = direction * speed

        # Smooth movement toward target
        vx = desired_velocity.x - self.robot.velocity.vx
        vy = desired_velocity.y - self.robot.velocity.vy

        # Return movement command
        return {
            "action": "move",
            "target": target_pos,
            "vx": vx,
            "vy": vy,
            "rotate_to": math.atan2(direction.y, direction.x)
        }

    def _attack_enemy(self, enemy: Robot) -> Dict:
        """Attack the specified enemy."""
        # Switch to best weapon for this enemy
        best_weapon = self.robot.get_best_weapon_for_target(enemy)
        if best_weapon != self.robot.weapon:
            self.robot.weapon = best_weapon

        # Calculate direction to enemy
        direction = enemy.position - self.robot.position

        if direction.magnitude() > 0:
            direction = direction.normalize()

        # Aim at enemy
        target_angle = math.atan2(direction.y, direction.x)

        # Fire if possible
        fire = False
        if self.robot.weapon.can_fire():
            # Add some randomness to make AI less predictable
            if random.random() < 0.9:  # 90% chance to fire when possible
                fire = True
                self.robot.weapon.fire()

        return {
            "action": "attack",
            "target": enemy,
            "vx": 0,
            "vy": 0,
            "rotate_to": target_angle,
            "fire": fire,
            "weapon": self.robot.weapon.name
        }

    def _chase_enemy(self, enemy: Robot) -> Dict:
        """Chase an enemy."""
        direction = enemy.position - self.robot.position
        if direction.magnitude() > 0:
            direction = direction.normalize()

        speed = self.robot.get_effective_speed()
        desired_velocity = direction * speed

        vx = desired_velocity.x - self.robot.velocity.vx
        vy = desired_velocity.y - self.robot.velocity.vy

        return {
            "action": "chase",
            "target": enemy,
            "vx": vx,
            "vy": vy,
            "rotate_to": math.atan2(direction.y, direction.x)
        }

    def _retreat(self) -> Dict:
        """Retreat to safety (move away from enemies)."""
        # Find the direction away from the nearest enemy
        if not self.enemy_robots:
            return self._move_to_objective(Position(GAME_WIDTH * 0.5, GAME_HEIGHT * 0.5))

        closest_enemy = self.robot.get_closest_enemy(self.enemy_robots)
        if not closest_enemy:
            return self._move_to_objective(Position(GAME_WIDTH * 0.5, GAME_HEIGHT * 0.5))

        # Move away from enemy
        direction = self.robot.position - closest_enemy.position
        if direction.magnitude() > 0:
            direction = direction.normalize()

        # Reduce speed when retreating
        speed = self.robot.get_effective_speed() * 0.7
        desired_velocity = direction * speed

        vx = desired_velocity.x - self.robot.velocity.vx
        vy = desired_velocity.y - self.robot.velocity.vy

        return {
            "action": "retreat",
            "target": closest_enemy,
            "vx": vx,
            "vy": vy,
            "rotate_to": math.atan2(direction.y, direction.x)
        }

    def _heal_teammate(self) -> Dict:
        """Find a teammate to heal and move toward them."""
        teammates = [r for r in self.team_robots if r != self.robot and r.health < r.max_health]

        if not teammates:
            return self._move_to_objective(self.robot.get_target_position(ObjectiveType.DEFEND_BASE, self.game_state))

        # Find the teammate with lowest health
        target_teammate = min(teammates, key=lambda r: r.health)

        # Move toward teammate
        direction = target_teammate.position - self.robot.position
        if direction.magnitude() > 0:
            direction = direction.normalize()

        speed = self.robot.get_effective_speed()
        desired_velocity = direction * speed

        vx = desired_velocity.x - self.robot.velocity.vx
        vy = desired_velocity.y - self.robot.velocity.vy

        return {
            "action": "heal",
            "target": target_teammate,
            "vx": vx,
            "vy": vy,
            "rotate_to": math.atan2(direction.y, direction.x)
        }

    def _defend_objective(self, objective_pos: Position) -> Dict:
        """Defend a specific objective."""
        # Move to a position near the objective
        # Add some randomness to avoid clustering
        offset = Position(
            random.uniform(-30, 30),
            random.uniform(-30, 30)
        )

        defense_pos = objective_pos + offset

        # Calculate direction
        direction = defense_pos - self.robot.position
        if direction.magnitude() > 0:
            direction = direction.normalize()

        speed = self.robot.get_effective_speed() * 0.8  # Move slower when defending
        desired_velocity = direction * speed

        vx = desired_velocity.x - self.robot.velocity.vx
        vy = desired_velocity.y - self.robot.velocity.vy

        return {
            "action": "defend",
            "target": objective_pos,
            "vx": vx,
            "vy": vy,
            "rotate_to": math.atan2(direction.y, direction.x)
        }

    def _explore_perimeter(self) -> Dict:
        """Scout the perimeter of the map."""
        # Define perimeter positions
        if self.robot.team == 0:
            # Red team: explore right side
            perimeter_pos = Position(GAME_WIDTH * 0.8, random.uniform(100, GAME_HEIGHT - 100))
        else:
            # Blue team: explore left side
            perimeter_pos = Position(GAME_WIDTH * 0.2, random.uniform(100, GAME_HEIGHT - 100))

        direction = perimeter_pos - self.robot.position
        if direction.magnitude() > 0:
            direction = direction.normalize()

        speed = self.robot.get_effective_speed() * 1.2  # Scouts move faster
        desired_velocity = direction * speed

        vx = desired_velocity.x - self.robot.velocity.vx
        vy = desired_velocity.y - self.robot.velocity.vy

        return {
            "action": "explore",
            "target": perimeter_pos,
            "vx": vx,
            "vy": vy,
            "rotate_to": math.atan2(direction.y, direction.x)
        }

    def _can_heal_teammate(self) -> bool:
        """Check if there's a teammate that needs healing."""
        for teammate in self.team_robots:
            if teammate != self.robot and teammate.health < teammate.max_health * 0.7:
                return True
        return False

    def _is_near_objective(self, objective_pos: Position) -> bool:
        """Check if robot is near the objective."""
        return self.robot.position.distance_to(objective_pos) < 100

