    def update(self, delta_time: float, game_state: 'GameState') -> None:
        """Update robot state based on environment and strategy."""
        self.last_updated = time.time()

        # Handle shield regeneration
        if self.shield_active:
            self.shield_duration -= delta_time
            if self.shield_duration <= 0:
                self.shield_active = False

        # Update cooldowns
        for ability, cooldown in list(self.cooldowns.items()):
            self.cooldowns[ability] = max(0, cooldown - delta_time)

        # Update weapon reload
        if self.weapon.ammo < self.weapon.max_ammo:
            if time.time() - self.weapon.last_fired > self.weapon.reload_time:
                self.weapon.ammo = min(self.weapon.max_ammo, self.weapon.ammo + 1)

        # Process strategy and state transitions
        self._execute_strategy(game_state)

        # Update experience based on actions
        self._update_experience(delta_time)

    def _update_experience(self, delta_time: float) -> None:
        """Update robot experience based on actions."""
        if self.state == RobotState.ATTACKING:
            self.experience += delta_time * 0.5
        elif self.state == RobotState.CAPTURING:
            self.experience += delta_time * 0.8
        elif self.state == RobotState.DEFENDING:
            self.experience += delta_time * 0.6
        elif self.state == RobotState.ESCORTING:
            self.experience += delta_time * 0.7
        elif self.is_alive and self.state == RobotState.IDLE:
