        if "attacker" in self.roles:
            if closest_enemy and self._can_attack(closest_enemy):
                self.state = RobotState.ATTACKING
                self._attack_target(closest_enemy)
            elif target_objective:
                self.state = RobotState.MOVING
                self._move_to_target(target_objective)
