    def _assign_role(self, game_state: 'GameState') -> None:
        """Assign dynamic roles based on team composition and game state."""
        team_robots = [r for r in game_state.robots if r.team == self.team and r.is_alive]

        # Count roles
        roles_count = defaultdict(int)
        for robot in team_robots:
            for role in robot.roles:
                roles_count[role] += 1

        # Balance roles if needed
        if len(team_robots) == 0:
