            if obj.type == EntityType.POWERUP and obj.powerup_type == PowerUpType.REGEN:
                if self.position.distance_to(obj.position) < 15.0:
                    return True
        return False

    def _has_healing_item(self) -> bool:
        """Check if robot has healing item in inventory."""
        return any(pu.type == PowerUpType.REGEN for pu in self.inventory)

    def _use_healing_item(self) -> None:
        """Use a healing item from inventory."""
        for i, item in enumerate(self.inventory):
            if item.powerup_type == PowerUpType.REGEN:
                heal_amount = 30.0
                self.health = min(self.max_health, self.health + heal_amount)
                self.inventory.pop(i)
                self.last_heal_time = time.time()
                break

    def _move_to_target(self, target: Entity) -> None:
        """Move toward target using pathfinding."""
        if not target:
            return

        direction = (target.position - self.position).normalize()
        move_distance = self.speed * self.speed_multiplier

        # Simple pathfinding: avoid obstacles and other robots
        new_position = self.position + direction * move_distance

        # Check for collisions (simplified)
        collision = False
        for robot in [r for r in game_state.robots if r != self]:
            if new_position.distance_to(robot.position) < 5.0:
                collision = True
                break

        if not collision:
            self.position = new_position

    def _capture_target(self, target: Entity) -> None:
        """Attempt to capture a flag or objective."""
        dist = self.position.distance_to(target.position)
        if dist < 5.0:  # In capture range
            capture_progress = 0.1  # Progress per second
            target.capture_progress += capture_progress
            if target.capture_progress >= 100:
                target.captured_by = self.team.id
                target.capture_progress = 0
                game_state.log(f"Robot {self.id} captured {target.id}!")
        else:
            self._move_to_target(target)

    def _defend_base(self, base: Entity, game_state: 'GameState') -> None:
        """Defend base by patrolling around it or engaging enemies."""
        # Patrol around base in a circular pattern
        angle = (time.time() * 0.5) % (2 * math.pi)
        patrol_distance = 15.0
        patrol_x = base.position.x + patrol_distance * math.cos(angle)
        patrol_y = base.position.y + patrol_distance * math.sin(angle)
        patrol_pos = Vector2D(patrol_x, patrol_y)

        # If enemy is near base, engage
        closest_enemy = self._find_closest_enemy(game_state)
        if closest_enemy and self.position.distance_to(closest_enemy.position) < 40.0:
            self.state = RobotState.ATTACKING
            self._attack_target(closest_enemy)
        else:
            self._move_to_target(Entity("patrol_point", EntityType.HAZARD, patrol_pos, Team.NEUTRAL))

    def take_damage(self, damage: float, attacker: Optional['Robot'] = None) -> None:
        """Apply damage to robot, considering armor and shields."""
        if not self.is_alive:
            return

        # Apply shield reduction first
        if self.shield_active:
            shield_damage = min(damage, self.shield_regen)
            self.shield_regen -= shield_damage
            damage -= shield_damage
            if self.shield_regen <= 0:
                self.shield_active = False

        # Apply armor reduction
        damage_reduction = min(self.armor * 0.5, 50)  # Max 50% damage reduction
        final_damage = damage * (1 - damage_reduction / 100)

        self.health -= final_damage

        # Add to memory for learning
        if attacker:
            self.memory.append({
                'event': 'damage_taken',
                'source': attacker.id,
                'damage': final_damage,
                'time': time.time(),
                'health': self.health
            })

        # Log damage
        game_state.log(f"Robot {self.id} took {final_damage:.1f} damage from {attacker.id if attacker else 'unknown'}. Health: {self.health:.1f}")

        # Check if dead
        if self.health <= 0:
            self.is_alive = False
            self.state = RobotState.DEAD
            game_state.log(f"Robot {self.id} has been eliminated!")
            game_state.add_kill(attacker.id if attacker else "environment", self.team)

    def heal(self, amount: float) -> None:
        """Heal robot by specified amount."""
        if not self.is_alive:
            return
        self.health = min(self.max_health, self.health + amount)
        self.last_heal_time = time.time()

    def apply_powerup(self, powerup: 'PowerUp') -> None:
        """Apply power-up effects to robot."""
        if powerup.powerup_type == PowerUpType.SPEED_BOOST:
            self.speed_multiplier = 1.5
            self.cooldowns["speed_boost"] = 10.0
        elif powerup.powerup_type == PowerUpType.DAMAGE_BOOST:
            self.damage_multiplier = 1.5
            self.cooldowns["damage_boost"] = 10.0
        elif powerup.powerup_type == PowerUpType.SHIELD:
            self.shield_active = True
            self.shield_regen = 50.0
            self.shield_duration = 15.0
        elif powerup.powerup_type == PowerUpType.REGEN:
            self.health = min(self.max_health, self.health + 25.0)
        elif powerup.powerup_type == PowerUpType.TELEPORT:
            # Teleport to random location
            x = random.uniform(0, game_state.arena_size[0])
            y = random.uniform(0, game_state.arena_size[1])
            self.position = Vector2D(x, y)
        elif powerup.powerup_type == PowerUpType.INVINCIBILITY:
            self.invulnerable = True
            self.cooldowns["invincibility"] = 8.0

        self.inventory.append(powerup)
        game_state.log(f"Robot {self.id} picked up {powerup.powerup_type.value}")


@dataclass
class Entity:
    """Base class for all entities in the arena."""
    id: str
    type: EntityType
    position: Vector2D
    team: Team = Team.NEUTRAL
    active: bool = True
    health: float = 100.0
    max_health: float = 100.0
    capture_progress: float = 0.0
    captured_by: Optional[str] = None
    is_payload: bool = False
    speed: float = 0.0
    direction: Vector2D = field(default_factory=lambda: Vector2D(1, 0))
    radius: float = 10.0

    def update(self, delta_time: float) -> None:
        """Update entity state (used for moving objectives like payloads)."""
        if self.is_payload:
            self.position = self.position + self.direction * self.speed * delta_time
            # Keep within arena bounds
            self._constrain_to_arena()


@dataclass
class PowerUp(Entity):
    """Represents a power-up item in the arena."""
    powerup_type: PowerUpType = PowerUpType.SPEED_BOOST
    duration: float = 10.0  # Duration of effect (seconds)
    spawn_time: float = field(default_factory=time.time)


@dataclass
class Projectile(Entity):
    """Represents a projectile fired from a weapon."""
    owner_id: str = ""
    weapon_type: WeaponType = WeaponType.PISTOL
    damage: float = 10.0
    speed: float = 15.0
    lifetime: float = 5.0  # seconds
    spawn_time: float = field(default_factory=time.time)

    def update(self, delta_time: float) -> None:
        """Update projectile position and check lifetime."""
        super().update(delta_time)
        self.lifetime -= delta_time
        if self.lifetime <= 0:
            self.active = False


@dataclass
class GameState:
    """Manages the overall state of the game."""
    arena_size: Tuple[float, float] = (1000, 1000)
    game_mode: GameMode = GameMode.FLAG_CAPTURE
    robots: List[Robot] = field(default_factory=list)
    objectives: List[Entity] = field(default_factory=list)
    projectiles: List[Projectile] = field(default_factory=list)
    powerups: List[PowerUp] = field(default_factory=list)
    hazards: List[Entity] = field(default_factory=list)
    team_scores: Dict[Team, int] = field(default_factory=lambda: {Team.RED: 0, Team.BLUE: 0})
    kills: Dict[str, int] = field(default_factory=lambda: defaultdict(int))
    deaths: Dict[str, int] = field(default_factory=lambda: defaultdict(int))
    game_time: float = 0.0
    last_update: float = 0.0
    is_running: bool = False
    difficulty: float = 0.5  # 0.0 to 1.0, 0.5 is medium
    logs: List[str] = field(default_factory=list)
    max_logs: int = 100
    learning_data: Dict[str, List] = field(default_factory=dict)  # For AI learning

    def __post_init__(self):
        self.last_update = time.time()
        self.learning_data = {
            "team_red": [],
            "team_blue": [],
            "global": []
        }

    def log(self, message: str) -> None:
        """Add a log message with timestamp."""
        timestamp = time.strftime("%H:%M:%S", time.localtime())
        log_entry = f"[{timestamp}] {message}"
        self.logs.append(log_entry)
        if len(self.logs) > self.max_logs:
            self.logs.pop(0)

    def add_kill(self, killer_id: str, victim_team: Team) -> None:
        """Record a kill and update scores."""
        self.kills[killer_id] += 1
        self.deaths[victim_team.id] += 1

        # Score for team
        if killer_id in [r.id for r in self.robots if r.team == Team.RED]:
            self.team_scores[Team.RED] += 10
        elif killer_id in [r.id for r in self.robots if r.team == Team.BLUE]:
            self.team_scores[Team.BLUE] += 10

    def spawn_robot(self, team: Team, position: Vector2D = None) -> Robot:
        """Spawn a new robot with randomized attributes."""
        if position is None:
            # Spawn near the team's base
            base = next((obj for obj in self.objectives if obj.type == EntityType.BASE and obj.team == team), None)
            if base:
                position = base.position + Vector2D(random.uniform(-20, 20), random.uniform(-20, 20))
            else:
                # Default spawn point
                if team == Team.RED:
                    position = Vector2D(100, 100)
                else:
                    position = Vector2D(self.arena_size[0] - 100, self.arena_size[1] - 100)

        robot_id = f"robot_{len(self.robots)}_{team.value}"
        weapon_type = random.choice(list(WeaponType))

        # Adjust weapon based on difficulty
        if self.difficulty > 0.7:
            weapon_type = random.choice([WeaponType.RIFLE, WeaponType.SHOTGUN, WeaponType.ROCKET_LAUNCHER])
        elif self.difficulty < 0.3:
            weapon_type = random.choice([WeaponType.PISTOL, WeaponType.MELEE])

        weapon = Weapon(
            type=weapon_type,
            damage=random.uniform(8, 20),
            range=random.uniform(40, 80),
            fire_rate=random.uniform(0.3, 0.8),
            ammo=random.randint(10, 20),
            max_ammo=random.randint(15, 30),
            reload_time=random.uniform(1.5, 3.0)
        )

        robot = Robot(
            id=robot_id,
            team=team,
            position=position,
            health=random.uniform(80, 120),
            max_health=random.uniform(80, 120),
            speed=random.uniform(4.0, 6.0),
            weapon=weapon
        )

        self.robots.append(robot)
        self.log(f"Spawned robot {robot_id} on team {team.value}")
        return robot

    def spawn_objective(self, type_: EntityType, team: Team, position: Vector2D) -> Entity:
        """Spawn an objective (flag, base, payload, etc.)."""
        obj_id = f"{type_.value}_{len(self.objectives)}"
        obj = Entity(obj_id, type_, position, team)

        if type_ == EntityType.FLAG:
            obj.captured_by = None
            obj.capture_progress = 0.0
        elif type_ == EntityType.HAZARD:
            # Payload
            obj.is_payload = True
            obj.speed = 1.0
            obj.direction = Vector2D(1, 0)

        self.objectives.append(obj)
        self.log(f"Spawned objective {obj_id} of type {type_.value}")
        return obj

    def spawn_powerup(self, powerup_type: PowerUpType, position: Vector2D) -> PowerUp:
        """Spawn a power-up item."""
        powerup_id = f"powerup_{len(self.powerups)}_{powerup_type.value}"
        powerup = PowerUp(
            id=powerup_id,
            type=EntityType.POWERUP,
            position=position,
            powerup_type=powerup_type,
            duration=10.0
        )
        self.powerups.append(powerup)
        self.log(f"Spawned power-up {powerup_id} at position {position.to_tuple()}")
        return powerup

    def spawn_hazard(self, position: Vector2D, hazard_type: str = "lava") -> Entity:
        """Spawn a hazardous area."""
        hazard_id = f"hazard_{len(self.hazards)}"
        hazard = Entity(
            id=hazard_id,
            type=EntityType.HAZARD,
            position=position,
            team=Team.NEUTRAL,
            health=1000,
            radius=25.0
        )
        self.hazards.append(hazard)
        self.log(f"Spawned hazard {hazard_id} at position {position.to_tuple()}")
        return hazard

    def update(self, delta_time: float) -> None:
        """Update the entire game state."""
        current_time = time.time()
        self.game_time += delta_time

        # Update robots
        for robot in self.robots:
            if robot.is_alive:
                robot.update(delta_time, self)

        # Update projectiles
        for projectile in self.projectiles[:]:
            projectile.update(delta_time)
            if not projectile.active:
                self.projectiles.remove(projectile)
                continue

            # Check for collisions with robots
            for robot in self.robots:
                if robot.is_alive and robot.team != self._get_team_by_id(projectile.owner_id):
                    if projectile.position.distance_to(robot.position) < 15.0:
                        robot.take_damage(projectile.damage, self._get_robot_by_id(projectile.owner_id))
                        projectile.active = False
                        break

        # Update objectives
        for obj in self.objectives:
            obj.update(delta_time)
            # Check for flag capture completion
            if obj.type == EntityType.FLAG and obj.capture_progress >= 100 and obj.captured_by is None:
                # Capture by nearest robot of opposing team
                nearest_robot = self._find_nearest_robot(obj.position)
                if nearest_robot and nearest_robot.team != obj.team:
                    obj.captured_by = nearest_robot.team.id
                    obj.capture_progress = 0
                    self.log(f"Flag {obj.id} captured by {nearest_robot.team.value}!")
                    self.team_scores[nearest_robot.team] += 25
                    self._apply_flag_capture_bonus(nearest_robot)

        # Update power-ups
        for powerup in self.powerups[:]:
            # Power-ups despawn after a certain time if not picked up
            if time.time() - powerup.spawn_time > 30.0:
                self.powerups.remove(powerup)
                continue

            # Check for pickup
            for robot in self.robots:
                if robot.is_alive and powerup.position.distance_to(robot.position) < 20.0:
                    robot.apply_powerup(powerup)
                    self.powerups.remove(powerup)
                    break

        # Update hazards
        for hazard in self.hazards:
            # Hazards damage robots that enter them
            for robot in self.robots:
                if robot.is_alive and hazard.position.distance_to(robot.position) < hazard.radius:
                    robot.take_damage(1.0)  # Slow damage over time
                    # Add visual effect (would be handled by rendering system)

        # Adaptive difficulty: adjust based on team performance
        self._adjust_difficulty()

        # Update learning data
        self._update_learning_data()

        # Check win conditions
        self._check_win_conditions()

        # Update last update time
        self.last_update = current_time

    def _get_team_by_id(self, robot_id: str) -> Optional[Team]:
        """Get the team of a robot by ID."""
        for robot in self.robots:
            if robot.id == robot_id:
                return robot.team
        return None

    def _get_robot_by_id(self, robot_id: str) -> Optional[Robot]:
        """Get a robot by ID."""
        for robot in self.robots:
            if robot.id == robot_id:
                return robot
        return None

    def _find_nearest_robot(self, position: Vector2D) -> Optional[Robot]:
        """Find the nearest robot to a position."""
        nearest = None
        min_dist = float('inf')

        for robot in self.robots:
            if robot.is_alive:
                dist = position.distance_to(robot.position)
                if dist < min_dist:
                    min_dist = dist
                    nearest = robot

        return nearest

    def _apply_flag_capture_bonus(self, robot: Robot) -> None:
        """Apply bonus to robot who captured the flag."""
        # Increase experience and give temporary boost
        robot.experience += 50
        robot.speed_multiplier = 1.2
        robot.damage_multiplier = 1.2
        robot.cooldowns["capture_bonus"] = 20.0  # 20 second bonus

    def _adjust_difficulty(self) -> None:
