            # For flag capture, prioritize enemy flag if own flag is safe
            own_flag = next((obj for obj in objectives if obj.type == EntityType.FLAG and obj.team == self.team), None)
            enemy_flag = next((obj for obj in objectives if obj.type == EntityType.FLAG and obj.team != self.team), None)

            if enemy_flag and (not own_flag or own_flag.captured_by != self.team.id):
                return enemy_flag
            elif own_flag and own_flag.captured_by == self.team.id:
                return own_flag  # Defend own flag if captured
            else:
