        """Spawn a new robot with randomized attributes."""
        if position is None:
            # Spawn near the team's base
            base = next((obj for obj in self.objectives if obj.type == EntityType.BASE and obj.team == team), None)
            if base:
                position = base.position + Vector2D(random.uniform(-20, 20), random.uniform(-20, 20))
            else:
                # Default spawn point
                if team == Team.RED:
                    position = Vector2D(100, 100)
                else:
                    position = Vector2D(self.arena_size[0] - 100, self.arena_size[1] - 100)

        robot_id = f"robot_{len(self.robots)}_{team.value}"
        weapon_type = random.choice(list(WeaponType))

        # Adjust weapon based on difficulty
        if self.difficulty > 0.7:
            weapon_type = random.choice([WeaponType.RIFLE, WeaponType.SHOTGUN, WeaponType.ROCKET_LAUNCHER])
        elif self.difficulty < 0.3:
            weapon_type = random.choice([WeaponType.PISTOL, WeaponType.MELEE])

        weapon = Weapon(
            type=weapon_type,
            damage=random.uniform(8, 20),
            range=random.uniform(40, 80),
            fire_rate=random.uniform(0.3, 0.8),
            ammo=random.randint(10, 20),
            max_ammo=random.randint(15, 30),
            reload_time=random.uniform(1.5, 3.0)
        )

        robot = Robot(
            id=robot_id,
            team=team,
            position=position,
            health=random.uniform(80, 120),
            max_health=random.uniform(80, 120),
            speed=random.uniform(4.0, 6.0),
            weapon=weapon
        )

