@dataclass
class Entity:
    """Base class for all entities in the arena."""
    id: str
    type: EntityType
    position: Vector2D
    team: Team = Team.NEUTRAL
    active: bool = True
    health: float = 100.0
    max_health: float = 100.0
    capture_progress: float = 0.0
    captured_by: Optional[str] = None
    is_payload: bool = False
    speed: float = 0.0
    direction: Vector2D = field(default_factory=lambda: Vector2D(1, 0))
    radius: float = 10.0

    def update(self, delta_time: float) -> None:
        """Update entity state (used for moving objectives like payloads)."""
        if self.is_payload:
            self.position = self.position + self.direction * self.speed * delta_time
            # Keep within arena bounds
            self._constrain_to_arena()


@dataclass
class PowerUp(Entity):
    """Represents a power-up item in the arena."""
    powerup_type: PowerUpType = PowerUpType.SPEED_BOOST
    duration: float = 10.0  # Duration of effect (seconds)
    spawn_time: float = field(default_factory=time.time)


@dataclass
class Projectile(Entity):
    """Represents a projectile fired from a weapon."""
    owner_id: str = ""
    weapon_type: WeaponType = WeaponType.PISTOL
    damage: float = 10.0
    speed: float = 15.0
    lifetime: float = 5.0  # seconds
    spawn_time: float = field(default_factory=time.time)

    def update(self, delta_time: float) -> None:
        """Update projectile position and check lifetime."""
        super().update(delta_time)
        self.lifetime -= delta_time
        if self.lifetime <= 0:
            self.active = False


