        """Spawn an objective (flag, base, payload, etc.)."""
        obj_id = f"{type_.value}_{len(self.objectives)}"
        obj = Entity(obj_id, type_, position, team)

        if type_ == EntityType.FLAG:
            obj.captured_by = None
            obj.capture_progress = 0.0
        elif type_ == EntityType.HAZARD:
