    MELEE = "melee"
    EXPLOSIVE = "explosive"
    SUPPORT = "support"

class ObjectiveType(Enum):
    CAPTURE_FLAG = "capture_flag"
    DEFEND_BASE = "defend_base"
    ESCORT_PAYLOAD = "escort_payload"
    DESTROY_TARGET = "destroy_target"

class PowerUpType(Enum):
    HEAL = "heal"
    SPEED_BOOST = "speed_boost"
    SHIELD = "shield"
    DAMAGE_BOOST = "damage_boost"
    CLONE = "clone"
    SILENCE = "silence"

class EnvironmentHazard(Enum):
    LAVA = "lava"
    ELECTRIC_FIELD = "electric_field"
    TOXIC_GAS = "toxic_gas"
    GRAVITY_WELL = "gravity_well"

@dataclass
class Position:
    x: float = 0.0
    y: float = 0.0
    z: float = 0.0

    def distance_to(self, other: 'Position') -> float:
        return math.sqrt((self.x - other.x)**2 + (self.y - other.y)**2 + (self.z - other.z)**2)

    def __add__(self, other: 'Position') -> 'Position':
        return Position(self.x + other.x, self.y + other.y, self.z + other.z)

    def __sub__(self, other: 'Position') -> 'Position':
        return Position(self.x - other.x, self.y - other.y, self.z - other.z)

@dataclass
class Vector3:
    x: float = 0.0
    y: float = 0.0
    z: float = 0.0

    def normalize(self) -> 'Vector3':
        mag = math.sqrt(self.x**2 + self.y**2 + self.z**2)
        if mag == 0:
            return Vector3(0, 0, 0)
        return Vector3(self.x/mag, self.y/mag, self.z/mag)

    def dot(self, other: 'Vector3') -> float:
        return self.x * other.x + self.y * other.y + self.z * other.z

    def __mul__(self, scalar: float) -> 'Vector3':
        return Vector3(self.x * scalar, self.y * scalar, self.z * scalar)

@dataclass
class Weapon:
    type: WeaponType
    damage: float
    range: float
    cooldown: float
    ammo: int = -1  # -1 means infinite ammo
    max_ammo: int = -1
    fire_mode: str = "single"  # single, burst, auto
    name: str = "Weapon"

    def can_fire(self, last_fired: float, current_time: float) -> bool:
        return current_time - last_fired >= self.cooldown

    def use_ammo(self) -> bool:
        if self.ammo == -1:
            return True
        if self.ammo > 0:
            self.ammo -= 1
            return True
        return False

@dataclass
class Robot:
    id: str
    team: Team
    robot_type: RobotType
    position: Position
    velocity: Vector3 = field(default_factory=lambda: Vector3(0, 0, 0))
    health: float = 100.0
    max_health: float = 100.0
    shield: float = 0.0
    max_shield: float = 50.0
    energy: float = 100.0
    max_energy: float = 100.0
    weapon: Weapon = field(default_factory=lambda: Weapon(WeaponType.RANGED, 25.0, 50.0, 0.5, 30, 30, "auto", "Plasma Rifle"))
    last_fired: float = 0.0
    last_healed: float = 0.0
    objective: Optional[ObjectiveType] = None
    role: str = "default"
    perception_radius: float = 30.0
    last_updated: float = 0.0
    ai_state: str = "idle"
    strategy_memory: List[Dict] = field(default_factory=list)
    cooldowns: Dict[str, float] = field(default_factory=dict)
    inventory: List[PowerUpType] = field(default_factory=list)
    kills: int = 0
    assists: int = 0
    objectives_completed: int = 0
    team_contributions: float = 0.0

    def __post_init__(self):
        self.cooldowns = {
            "heal": 0,
            "ultimate": 0,
            "dash": 0,
            "cloak": 0
        }

    def take_damage(self, damage: float) -> float:
        # Apply shield first
        if self.shield > 0:
            shield_absorbed = min(damage, self.shield)
            self.shield -= shield_absorbed
            damage -= shield_absorbed

        # Apply remaining damage to health
        damage_taken = min(damage, self.health)
        self.health -= damage_taken

        # If health goes below 0, robot is eliminated
        if self.health <= 0:
            self.health = 0
            self.ai_state = "eliminated"

        return damage_taken

    def heal(self, amount: float) -> float:
        if self.health >= self.max_health:
            return 0

        heal_amount = min(amount, self.max_health - self.health)
        self.health += heal_amount
        return heal_amount

    def recharge_shield(self, amount: float) -> float:
        if self.shield >= self.max_shield:
            return 0

        recharge_amount = min(amount, self.max_shield - self.shield)
        self.shield += recharge_amount
        return recharge_amount

    def add_powerup(self, powerup: PowerUpType):
        self.inventory.append(powerup)
        logger.info(f"Robot {self.id} picked up {powerup.value}")

    def use_powerup(self, powerup: PowerUpType) -> bool:
        if powerup in self.inventory:
            self.inventory.remove(powerup)
            logger.info(f"Robot {self.id} used {powerup.value}")
            return True
        return False

    def has_powerup(self, powerup: PowerUpType) -> bool:
        return powerup in self.inventory

    def update_cooldowns(self, delta_time: float):
        for key in self.cooldowns:
            if self.cooldowns[key] > 0:
                self.cooldowns[key] -= delta_time
                if self.cooldowns[key] < 0:
                    self.cooldowns[key] = 0

    def is_alive(self) -> bool:
        return self.health > 0 and self.ai_state != "eliminated"

    def get_team_score(self, team: Team) -> int:
        """Helper method to get team score based on robot's performance"""
        return self.kills + self.assists + self.objectives_completed

@dataclass
class Objective:
    type: ObjectiveType
    position: Position
    team: Team
    captured: bool = False
    capture_progress: float = 0.0
    capture_time: float = 0.0
    capture_required: float = 10.0  # seconds to capture
    defender_count: int = 0
    attacker_count: int = 0
    is_active: bool = True
    description: str = ""

    def update_capture_progress(self, capturing_team: Team, delta_time: float) -> bool:
        if self.captured:
            return True

        if self.team == capturing_team:
            # Friendly team is defending
            self.capture_progress = max(0, self.capture_progress - delta_time * 0.5)
            return False

        if self.capture_progress >= self.capture_required:
            self.captured = True
            self.team = capturing_team
            logger.info(f"Objective {self.type.value} captured by {capturing_team.value} team!")
            return True

        # If enemies are near, progress increases
        if self.attacker_count > 0:
            self.capture_progress += delta_time * (1 + self.attacker_count * 0.2)

        # If defenders are near, progress slows
        if self.defender_count > 0:
            self.capture_progress -= delta_time * 0.3

        self.capture_progress = max(0, min(self.capture_progress, self.capture_required))
        return False

@dataclass
class PowerUp:
    type: PowerUpType
    position: Position
    active: bool = True
    spawn_time: float = 0.0
    duration: float = 30.0  # seconds before despawning
    effect_value: float = 25.0  # how much it affects the robot

    def update(self, current_time: float) -> bool:
        if self.active and current_time - self.spawn_time > self.duration:
            self.active = False
            return False
        return True

@dataclass
class EnvironmentHazardInstance:
    type: EnvironmentHazard
    position: Position
    radius: float = 5.0
    damage_per_second: float = 5.0
    active: bool = True
    spawn_time: float = 0.0

    def affects_position(self, pos: Position) -> bool:
        return self.position.distance_to(pos) <= self.radius

@dataclass
class GameStats:
    total_battles: int = 0
    avg_battle_duration: float = 0.0
    team_wins: Dict[Team, int] = field(default_factory=lambda: {Team.RED: 0, Team.BLUE: 0})
    avg_robot_kills: float = 0.0
    avg_objectives_completed: float = 0.0
    adaptive_difficulty: float = 1.0  # 0.5 to 2.0, where 1.0 is normal

    def update_stats(self, battle_duration: float, winner_team: Team, robots: List[Robot]):
        self.total_battles += 1
        self.team_wins[winner_team] += 1

        # Update average battle duration
        if self.total_battles == 1:
            self.avg_battle_duration = battle_duration
        else:
            self.avg_battle_duration = (self.avg_battle_duration * (self.total_battles - 1) + battle_duration) / self.total_battles

        # Calculate average kills and objectives
        total_kills = sum(robot.kills for robot in robots)
        total_objectives = sum(robot.objectives_completed for robot in robots)
        self.avg_robot_kills = total_kills / len(robots) if robots else 0
        self.avg_objectives_completed = total_objectives / len(robots) if robots else 0

        # Adjust difficulty based on win rates and performance
        red_win_rate = self.team_wins[Team.RED] / max(1, self.total_battles)
        blue_win_rate = self.team_wins[Team.BLUE] / max(1, self.total_battles)

        # If one team is dominating, increase difficulty for them
        if abs(red_win_rate - blue_win_rate) > 0.3:
            if red_win_rate > blue_win_rate:
                self.adaptive_difficulty = min(2.0, self.adaptive_difficulty + 0.05)
            else:
                self.adaptive_difficulty = max(0.5, self.adaptive_difficulty - 0.05)
        else:
            # Normalize if balanced
            self.adaptive_difficulty = max(0.5, min(2.0, self.adaptive_difficulty + (0.5 - red_win_rate) * 0.2))

