class TankAIController(AIController):
    def __init__(self, robot: Robot):
        super().__init__(robot)
        self.behavior_tree = ["find_target", "engage", "tank_mode", "defend", "reposition"]

    def perceive_environment(self, game_state: 'CyberArena') -> Dict:
        perception = {
            "enemies": [],
            "allies": [],
            "powerups": [],
            "hazards": [],
            "objectives": [],
            "closest_enemy": None,
            "closest_ally": None,
            "closest_powerup": None,
            "closest_objective": None,
            "distance_to_enemy": float('inf'),
            "distance_to_ally": float('inf'),
            "distance_to_powerup": float('inf'),
            "distance_to_objective": float('inf'),
            "has_line_of_sight": False,
            "is_under_attack": False,
            "low_health": False
        }

        for robot in game_state.robots:
            if robot.id == self.robot.id:
                continue

            distance = self.robot.position.distance_to(robot.position)

            if distance <= self.robot.perception_radius:
                if robot.team != self.robot.team and robot.is_alive():
                    perception["enemies"].append((robot, distance))
                    if distance < perception["distance_to_enemy"]:
                        perception["distance_to_enemy"] = distance
                        perception["closest_enemy"] = robot

                elif robot.team == self.robot.team and robot.is_alive():
                    perception["allies"].append((robot, distance))
                    if distance < perception["distance_to_ally"]:
                        perception["distance_to_ally"] = distance
                        perception["closest_ally"] = robot

        # Find power-ups
        for powerup in game_state.powerups:
            if powerup.active:
                distance = self.robot.position.distance_to(powerup.position)
                if distance <= self.robot.perception_radius:
                    perception["powerups"].append((powerup, distance))
                    if distance < perception["distance_to_powerup"]:
                        perception["distance_to_powerup"] = distance
                        perception["closest_powerup"] = powerup

        # Find hazards
        for hazard in game_state.hazards:
            if hazard.active and hazard.affects_position(self.robot.position):
                perception["hazards"].append(hazard)

        # Find objectives
        for objective in game_state.objectives:
            if objective.is_active:
                distance = self.robot.position.distance_to(objective.position)
                if distance <= self.robot.perception_radius:
                    perception["objectives"].append((objective, distance))
                    if distance < perception["distance_to_objective"]:
                        perception["distance_to_objective"] = distance
                        perception["closest_objective"] = objective

        # Check if under attack
        if perception["closest_enemy"] and perception["distance_to_enemy"] < 30:
            perception["is_under_attack"] = True
            perception["has_line_of_sight"] = True

        # Check if low on health
        if self.robot.health < 30:
            perception["low_health"] = True

        return perception

    def decide_action(self, game_state: 'CyberArena', delta_time: float) -> str:
        perception = self.perceive_environment(game_state)
        current_time = time.time()

        if not self.robot.is_alive():
            return "dead"

        # If low health, retreat to safety
        if perception["low_health"]:
            return "retreat"

        # If power-up is beneficial, go for it
        if perception["closest_powerup"] and perception["distance_to_powerup"] < 10:
            if perception["closest_powerup"].type == PowerUpType.SHIELD and self.robot.shield < 30:
                return "go_for_powerup"
            elif perception["closest_powerup"].type == PowerUpType.HEAL and self.robot.health < 60:
                return "go_for_powerup"

        # If enemy is close and we can attack
        if perception["closest_enemy"] and perception["distance_to_enemy"] < self.robot.weapon.range:
            if self.robot.weapon.can_fire(self.robot.last_fired, current_time):
                self.robot.last_fired = current_time
                self.robot.weapon.use_ammo()
                return "attack"

        # If objective is nearby and enemy is present, defend
        if perception["closest_objective"]:
            closest_obj = perception["closest_objective"]
            if closest_obj.team != self.robot.team and not closest_obj.captured:
                return "capture_objective"
            elif closest_obj.team == self.robot.team and not closest_obj.captured:
                return "defend_objective"

        # If no target, find nearest ally and hold position
        if perception["allies"]:
            return "hold_position"

        return "patrol"

