    fire_mode: str = "single"  # single, burst, auto
    name: str = "Weapon"

    def can_fire(self, last_fired: float, current_time: float) -> bool:
        return current_time - last_fired >= self.cooldown

    def use_ammo(self) -> bool:
        if self.ammo == -1:
