                        perception["closest_powerup"] = powerup

        # Find hazards
        for hazard in game_state.hazards:
            if hazard.active and hazard.affects_position(self.robot.position):
                perception["hazards"].append(hazard)

        # Find objectives
        for objective in game_state.objectives:
            if objective.is_active:
                distance = self.robot.position.distance_to(objective.position)
                if distance <= self.robot.perception_radius:
                    perception["objectives"].append((objective, distance))
                    if distance < perception["distance_to_objective"]:
                        perception["distance_to_objective"] = distance
                        perception["closest_objective"] = objective

        # Check if robot is under attack
        if perception["closest_enemy"]:
            # Simple line of sight check (no raycasting for simplicity)
            perception["has_line_of_sight"] = True
            if perception["distance_to_enemy"] < 30:
                perception["is_under_attack"] = True

        return perception

    def decide_action(self, game_state: 'CyberArena', delta_time: float) -> str:
        """Main AI decision logic for ranged robots"""
        perception = self.perceive_environment(game_state)
        current_time = time.time()

        # Update robot's state based on perception
        if perception["closest_enemy"] and perception["distance_to_enemy"] < 20:
            self.robot.ai_state = "combat"
        elif perception["closest_powerup"] and perception["distance_to_powerup"] < 15:
            self.robot.ai_state = "powerup_hunt"
        elif perception["closest_objective"] and perception["distance_to_objective"] < 25:
            self.robot.ai_state = "objective_hunt"
        else:
            self.robot.ai_state = "patrol"

        # Decision tree logic
        if not self.robot.is_alive():
            return "dead"

        # If under heavy attack, retreat
        if perception["is_under_attack"] and self.robot.health < 40:
            return "retreat"

        # If power-up is close and beneficial, go for it
        if perception["closest_powerup"] and perception["distance_to_powerup"] < 10:
            if perception["closest_powerup"].type == PowerUpType.HEAL and self.robot.health < 70:
                return "go_for_powerup"
            elif perception["closest_powerup"].type == PowerUpType.SPEED_BOOST:
                return "go_for_powerup"
            elif perception["closest_powerup"].type == PowerUpType.SHIELD and self.robot.shield < 30:
                return "go_for_powerup"

        # If objective is important and close, try to capture/defend
        if perception["closest_objective"]:
            closest_obj = perception["closest_objective"]
            # If objective belongs to team and needs defending
            if closest_obj.team == self.robot.team and not closest_obj.captured:
                if closest_obj.defender_count < 1:  # Not enough defenders
                    return "defend_objective"
                elif closest_obj.captured:
                    return "defend_objective"
            # If objective is enemy's and we can capture
            elif closest_obj.team != self.robot.team and not closest_obj.captured:
                return "capture_objective"

        # If enemies are nearby and we can attack
        if perception["closest_enemy"] and perception["distance_to_enemy"] < self.robot.weapon.range:
            # Check if weapon is ready to fire
            if self.robot.weapon.can_fire(self.robot.last_fired, current_time):
                self.robot.last_fired = current_time
                self.robot.weapon.use_ammo()
                return "attack"

        # If we're low on ammo, try to find a respawn point or reload
        if self.robot.weapon.ammo != -1 and self.robot.weapon.ammo < 5:
            return "find_ammo"

        # Default behavior: patrol around objective or move to ally
        if perception["closest_ally"] and perception["distance_to_ally"] > 15:
            return "follow_ally"

        # If no clear target, patrol
        return "patrol"

