        }

        for robot in game_state.robots:
            if robot.id == self.robot.id:
                continue

            distance = self.robot.position.distance_to(robot.position)

            if distance <= self.robot.perception_radius:
                if robot.team == self.robot.team and robot.is_alive():
                    perception["allies"].append((robot, distance))
                    # Check if ally is needy (low health, low shield)
                    if robot.health < 50 or robot.shield < 20:
                        perception["needy_allies"].append((robot, distance))
                        if distance < perception["distance_to_needy_ally"]:
                            perception["distance_to_needy_ally"] = distance
                            perception["closest_needy_ally"] = robot

                elif robot.team != self.robot.team and robot.is_alive():
                    perception["enemies"].append((robot, distance))
                    if distance < perception["distance_to_enemy"]:
                        perception["distance_to_enemy"] = distance
                        perception["closest_enemy"] = robot

        # Find power-ups
        for powerup in game_state.powerups:
            if powerup.active:
                distance = self.robot.position.distance_to(powerup.position)
                if distance <= self.robot.perception_radius:
                    perception["powerups"].append((powerup, distance))
                    if distance < perception["distance_to_powerup"]:
                        perception["distance_to_powerup"] = distance
                        perception["closest_powerup"] = powerup

        # Find hazards
        for hazard in game_state.hazards:
            if hazard.active and hazard.affects_position(self.robot.position):
                perception["hazards"].append(hazard)

        # Find objectives
        for objective in game_state.objectives:
            if objective.is_active:
                distance = self.robot.position.distance_to(objective.position)
                if distance <= self.robot.perception_radius:
                    perception["objectives"].append((objective, distance))
                    if distance < perception["distance_to_objective"]:
                        perception["distance_to_objective"] = distance
                        perception["closest_objective"] = objective

        # Check if under attack
        if perception["closest_enemy"] and perception["distance_to_enemy"] < 25:
            perception["is_under_attack"] = True
            perception["has_line_of_sight"] = True

        return perception

    def decide_action(self, game_state: 'CyberArena', delta_time: float) -> str:
        perception = self.perceive_environment(game_state)
        current_time = time.time()

        if not self.robot.is_alive():
            return "dead"

        # If we're low on health, retreat or heal
        if self.robot.health < 40:
            return "retreat"

        # If we have a healing power-up and allies need it
        if self.robot.has_powerup(PowerUpType.HEAL) and perception["needy_allies"]:
            return "use_heal_powerup"

        # If there's a needy ally nearby
        if perception["closest_needy_ally"] and perception["distance_to_needy_ally"] < 15:
            # Check if we can heal (cooldown)
            if current_time - self.robot.last_healed > 5:  # 5 second cooldown
                self.robot.last_healed = current_time
                return "heal_ally"

        # If enemy is too close, defend or retreat
        if perception["closest_enemy"] and perception["distance_to_enemy"] < 10:
            return "defend"

        # If we have a buff power-up and allies are in range
        if self.robot.has_powerup(PowerUpType.DAMAGE_BOOST) or self.robot.has_powerup(PowerUpType.SPEED_BOOST):
            for ally, dist in perception["allies"]:
                if dist < 20:
                    return "use_buff_powerup"

        # If objective is nearby, help defend
        if perception["closest_objective"] and perception["distance_to_objective"] < 20:
            closest_obj = perception["closest_objective"]
            if closest_obj.team == self.robot.team and not closest_obj.captured:
                return "defend_objective"

        # Default: find nearest ally and stay close
        if perception["allies"]:
            return "follow_ally"

        return "patrol"

