class ActivationRequirement(Enum):
    ONE_NEIGHBOR = 1
    TWO_NEIGHBORS = 2
    THREE_NEIGHBORS = 3
    ALL_NEIGHBORS = 4

@dataclass
class Node:
    id: int
    position: Tuple[int, int]
    node_type: NodeType = NodeType.STANDARD
    activated: bool = False
    activation_requirement: ActivationRequirement = ActivationRequirement.ONE_NEIGHBOR
    neighbors: List[Tuple[int, int]] = field(default_factory=list)
    player_role: Optional[PlayerRole] = None
    dependent_nodes: Set[int] = field(default_factory=set)  # Nodes that must be activated before this one

    def is_ready_to_activate(self, active_nodes: Set[int]) -> bool:
        if self.activated:
            return False
        if not self.dependent_nodes:
            return True
        return self.dependent_nodes.issubset(active_nodes)

    def can_activate(self, active_nodes: Set[int]) -> bool:
        if not self.is_ready_to_activate(active_nodes):
            return False
        if self.node_type == NodeType.BARRIER:
            return False
        if self.node_type == NodeType.LOCKED:
            return False
        neighbor_count = sum(1 for nb in self.neighbors if nb in active_nodes)
        return neighbor_count >= self.activation_requirement.value

@dataclass
class Player:
    role: PlayerRole
    controlled_nodes: Set[int] = field(default_factory=set)
    last_action_time: float = 0.0
    can_act: bool = True

@dataclass
class Level:
