    solution_sequence: List[int] = field(default_factory=list)
    time_limit: int = 60
    hint_count: int = 3

@dataclass
class GameStateManager:
    current_level: Optional[Level] = None
    state: GameState = GameState.PREPARE
    timer_start: Optional[float] = None
    elapsed_time: float = 0.0
    active_nodes: Set[int] = field(default_factory=set)
    players: Dict[PlayerRole, Player] = field(default_factory=dict)
    hints_used: int = 0
    saved_progress: Optional[Dict] = None

    def start_timer(self):
        self.timer_start = time.time()
        self.state = GameState.PLAYING

    def stop_timer(self):
        if self.timer_start:
            self.elapsed_time = time.time() - self.timer_start

    def get_elapsed_time(self) -> float:
        if self.timer_start and self.state == GameState.PLAYING:
            return time.time() - self.timer_start
        return self.elapsed_time

    def is_level_solved(self) -> bool:
        if not self.current_level:
            return False
        return len(self.active_nodes) == len(self.current_level.nodes)

    def reset_level(self):
        self.active_nodes.clear()
        self.hints_used = 0
        self.elapsed_time = 0.0
        self.timer_start = None
        self.state = GameState.PREPARE
        for node in self.current_level.nodes.values():
