            "hints_used": self.hints_used,
            "level_id": getattr(self.current_level, 'id', 0),
            "state": self.state.value
        }
        return self.saved_progress

    def load_progress(self, progress_data: Dict):
        self.active_nodes = set(progress_data["active_nodes"])
        self.elapsed_time = progress_data["elapsed_time"]
        self.hints_used = progress_data["hints_used"]
        self.state = GameState(progress_data["state"])
        self.timer_start = time.time() - self.elapsed_time if self.state == GameState.PLAYING else None
        # Re-activate nodes in grid
        if self.current_level:
            for node_id in self.active_nodes:
                if node_id in self.current_level.nodes:
                    self.current_level.nodes[node_id].activated = True

# ========================
