        """Find a random safe location to teleport to"""
        # For simplicity, find a random point away from enemies
        # In a real implementation, this would use pathfinding
        return Vector2D(
            random.uniform(50, 1950),
            random.uniform(50, 1950)
        )

    def check_hazards(self, environment: 'Environment'):
        """Check if robot is in a hazard area and take damage"""
        for hazard in environment.hazards:
            if (self.position - hazard.position).magnitude() < hazard.radius:
                if hazard.type == HazardType.ELECTRIC_FLOOR:
                    self.take_damage(1.5)
                elif hazard.type == HazardType.FIRE_FIELD:
                    self.take_damage(2.0)
                elif hazard.type == HazardType.GRAVITY_WELL:
                    # Pull robot toward center
                    direction = (hazard.position - self.position).normalize()
                    self.velocity = self.velocity + (direction * 20)
                elif hazard.type == HazardType.MINEFIELD:
                    if random.random() < 0.1:  # 10% chance to trigger
                        self.take_damage(15)
                        environment.add_particle_effect(self.position, "explosion")

    def check_power_ups(self, environment: 'Environment'):
        """Check if robot is near a power-up and collect it"""
        for power_up in list(environment.power_ups):
            if (self.position - power_up.position).magnitude() < 30:
                self.power_ups[power_up.type] = power_up.duration
                self.apply_power_up_effect(power_up.type)
                environment.power_ups.remove(power_up)
                environment.add_particle_effect(power_up.position, "powerup")
                environment.play_sound("powerup_collected")

    def take_damage(self, damage: float):
        """Apply damage to robot, considering armor"""
        if not self.is_alive:
            return

        damage_after_armor = max(0, damage - (self.armor * 0.5))
        self.health -= damage_after_armor

        if self.health <= 0:
            self.is_alive = False
            self.health = 0
            # Create death effect
            self.team.environment.add_particle_effect(self.position, "death")
            self.team.environment.play_sound("robot_death")

    def heal(self, amount: float):
        """Heal robot"""
        if not self.is_alive:
            return

        self.health = min(self.max_health, self.health + amount)
        self.last_healed = time.time()

    def shoot(self, target: Vector2D, environment: 'Environment') -> bool:
        """Fire weapon at target if possible"""
        if not self.is_alive or not self.weapon.can_fire(self.last_fired):
            return False

        # Check if target is within range
        if (self.position - target).magnitude() > self.weapon.range:
            return False

        # Calculate damage based on weapon type
        damage = self.weapon.damage

        # Check for critical hit (10% chance)
        if random.random() < 0.1:
            damage *= 1.5
            environment.play_sound("critical_hit")

        # Find robots in line of sight
        for robot in environment.robots:
            if (robot.team != self.team and 
                robot.is_alive and 
                (robot.position - target).magnitude() < 10):

                # Apply damage
                robot.take_damage(damage)

                # Create visual effect
                environment.add_particle_effect(robot.position, "hit")
                self.last_fired = time.time()
                environment.play_sound("weapon_fire")
                return True

        return False

    def ai_decision(self, environment: 'Environment'):
        """AI decision-making system - uses strategy, memory, and current situation"""
        if not self.is_alive:
            return

        # Find closest enemy
        closest_enemy = None
        min_distance = float('inf')

        for robot in environment.robots:
            if robot.team != self.team and robot.is_alive:
                distance = (self.position - robot.position).magnitude()
                if distance < min_distance:
                    min_distance = distance
                    closest_enemy = robot

        # Determine current objective based on team strategy
        primary_objective = self.get_primary_objective(environment)

        # Different behaviors based on role
        if self.role == RobotRole.ATTACKER:
            if closest_enemy and min_distance < 300:
                # Engage enemy
                self.target = closest_enemy.position
                if min_distance < self.weapon.range and (self.position - closest_enemy.position).magnitude() < 50:
                    self.shoot(closest_enemy.position, environment)
            elif primary_objective == ObjectiveType.CAPTURE_FLAG:
                self.target = environment.flag_positions[self.team]
            elif primary_objective == ObjectiveType.ESCAPE_PAYLOAD:
                self.target = environment.payload_position
            else:
                # Move toward enemy base
                self.target = environment.enemy_bases[self.team]

        elif self.role == RobotRole.DEFENDER:
            if closest_enemy and min_distance < 200:
                # Intercept enemy
                self.target = closest_enemy.position
                self.shoot(closest_enemy.position, environment)
            else:
                # Defend base or objective
                if primary_objective == ObjectiveType.DEFEND_BASE:
                    self.target = environment.my_bases[self.team]
                elif primary_objective == ObjectiveType.CAPTURE_FLAG:
                    self.target = environment.flag_positions[self.team]
                else:
                    # Default to base defense
                    self.target = environment.my_bases[self.team]

        elif self.role == RobotRole.SUPPORT:
            # Heal allies or provide cover
            nearest_ally = None
            min_ally_distance = float('inf')

            for robot in environment.robots:
                if robot.team == self.team and robot.is_alive and robot != self:
                    distance = (self.position - robot.position).magnitude()
                    if distance < min_ally_distance and robot.health < robot.max_health * 0.7:
                        min_ally_distance = distance
                        nearest_ally = robot

            if nearest_ally and min_ally_distance < 150:
                self.target = nearest_ally.position
                # Try to heal
                if time.time() - self.last_healed > 3.0 and random.random() < 0.3:
                    nearest_ally.heal(10)
                    self.last_healed = time.time()
            else:
                # Support objective
                if primary_objective == ObjectiveType.CAPTURE_FLAG:
                    self.target = environment.flag_positions[self.team]
                else:
                    self.target = environment.my_bases[self.team]

        elif self.role == RobotRole.SCOUT:
            # Explore and gather intel
            if closest_enemy:
                # Track enemy
                self.target = closest_enemy.position
                if min_distance < 100:
                    # Report enemy position to team
                    environment.add_team_message(f"SCOUT: Enemy spotted at {closest_enemy.position.x:.1f}, {closest_enemy.position.y:.1f}")
            else:
                # Patrol patrol points
                if len(environment.scout_patrol_points) > 0:
                    patrol_index = int(time.time() * 0.1) % len(environment.scout_patrol_points)
                    self.target = environment.scout_patrol_points[patrol_index]

        # Adaptive strategy based on team performance
        self.adapt_strategy(environment)

    def get_primary_objective(self, environment: 'Environment') -> ObjectiveType:
        """Get the current primary objective for this team"""
        if len(self.objectives) > 0:
            return self.objectives[0]

        # Default objective based on environment
        if environment.current_objective:
            return environment.current_objective

        # Default to capture flag if available
        if environment.flag_positions:
            return ObjectiveType.CAPTURE_FLAG

        return ObjectiveType.DEFEND_BASE

    def adapt_strategy(self, environment: 'Environment'):
        """Adapt strategy based on team performance and learning"""
        if not self.team.team_stats:
            return

        # Calculate team performance metrics
        team_win_rate = self.team.team_stats.get('wins', 0) / max(1, self.team.team_stats.get('games', 1))
        team_objective_success = self.team.team_stats.get('objectives_completed', 0) / max(1, self.team.team_stats.get('objectives_attempted', 1))

        # Adjust aggression based on performance
        if team_win_rate < 0.4:
            # Underperforming - be more aggressive
            if self.role == RobotRole.DEFENDER and random.random() < 0.3:
                self.role = RobotRole.ATTACKER
                environment.add_team_message(f"{self.id} switched to ATTACKER for better pressure")
        elif team_win_rate > 0.7:
            # Overperforming - be more strategic
            if self.role == RobotRole.ATTACKER and random.random() < 0.2:
                self.role = RobotRole.SUPPORT
                environment.add_team_message(f"{self.id} switched to SUPPORT to enhance team cohesion")

        # Remember successful strategies
        if random.random() < 0.05:  # 5% chance to record strategy
            strategy_record = {
                'timestamp': time.time(),
                'team_performance': team_win_rate,
                'role': self.role.value,
                'objective': self.get_primary_objective(environment).value,
                'position': (self.position.x, self.position.y)
            }
            self.strategy_memory.append(strategy_record)

            # Keep only last 20 records
            if len(self.strategy_memory) > 20:
                self.strategy_memory.pop(0)

        # Learn from team's past strategies
        if len(self.team.team_strategy_memory) > 0:
            # Use the most recent successful strategy
            recent_strategy = self.team.team_strategy_memory[-1]
            if 'preferred_role' in recent_strategy and recent_strategy['success']:
                if self.role.value != recent_strategy['preferred_role']:
                    if random.random() < 0.3:
                        self.role = RobotRole(recent_strategy['preferred_role'])
                        environment.add_team_message(f"{self.id} adopted team's successful role: {recent_strategy['preferred_role']}")

@dataclass
class PowerUp:
    type: PowerUpType
    position: Vector2D
    duration: float = 15.0  # seconds
    spawn_time: float = field(default_factory=time.time)

@dataclass
class Hazard:
    type: HazardType
    position: Vector2D
    radius: float = 50.0
    damage_per_second: float = 1.0
    spawn_time: float = field(default_factory=time.time)

@dataclass
class TeamStats:
    wins: int = 0
    losses: int = 0
    games: int = 0
    objectives_completed: int = 0
    objectives_attempted: int = 0
    total_damage_dealt: float = 0
    total_damage_taken: float = 0
    team_strategy_memory: List[Dict] = field(default_factory=list)

@dataclass
class Environment:
    width: int = 2000
    height: int = 2000
    robots: List[Robot] = field(default_factory=list)
    power_ups: List[PowerUp] = field(default_factory=list)
    hazards: List[Hazard] = field(default_factory=list)
    flag_positions: Dict[Team, Vector2D] = field(default_factory=dict)
    my_bases: Dict[Team, Vector2D] = field(default_factory=dict)
    enemy_bases: Dict[Team, Vector2D] = field(default_factory=dict)
    payload_position: Optional[Vector2D] = None
    payload_destination: Optional[Vector2D] = None
    current_objective: Optional[ObjectiveType] = None
    scout_patrol_points: List[Vector2D] = field(default_factory=list)
    teams: Dict[Team, TeamStats] = field(default_factory=dict)
    game_time: float = 0.0
    last_spawn_time: float = 0.0
    particle_effects: List[Dict] = field(default_factory=list)
    team_messages: deque = field(default_factory=lambda: deque(maxlen=5))
    audio_queue: queue.Queue = field(default_factory=queue.Queue)

    def __post_init__(self):
        # Initialize teams
        self.teams[Team.RED] = TeamStats()
        self.teams[Team.BLUE] = TeamStats()

        # Set up base positions
        self.my_bases[Team.RED] = Vector2D(200, 1000)
        self.my_bases[Team.BLUE] = Vector2D(1800, 1000)
        self.enemy_bases[Team.RED] = Vector2D(1800, 1000)
        self.enemy_bases[Team.BLUE] = Vector2D(200, 1000)

        # Set up flag positions
        self.flag_positions[Team.RED] = Vector2D(1000, 400)
        self.flag_positions[Team.BLUE] = Vector2D(1000, 1600)

        # Set up payload
        self.payload_position = Vector2D(1000, 1000)
        self.payload_destination = Vector2D(200, 1000)  # Red base

        # Set up scout patrol points
        self.scout_patrol_points = [
            Vector2D(500, 300),
            Vector2D(1500, 300),
            Vector2D(1500, 1700),
            Vector2D(500, 1700),
        ]

        # Set initial objective
        self.current_objective = ObjectiveType.CAPTURE_FLAG

        # Spawn initial power-ups
        self.spawn_power_ups()

        # Spawn initial hazards
        self.spawn_hazards()

    def spawn_power_ups(self):
        """Spawn new power-ups at random locations"""
        power_up_types = [
            PowerUpType.SPEED_BOOST,
            PowerUpType.HEALTH_PACK,
            PowerUpType.SHIELD,
            PowerUpType.WEAPON_UPGRADE,
            PowerUpType.TELEPORT
        ]

        for _ in range(3):  # Spawn 3 power-ups
            power_up_type = random.choice(power_up_types)
            position = Vector2D(
                random.uniform(100, self.width - 100),
                random.uniform(100, self.height - 100)
            )
            # Ensure it's not too close to bases or flags
            too_close = False
            for base in self.my_bases.values():
                if (position - base).magnitude() < 150:
                    too_close = True
                    break
            if not too_close:
                self.power_ups.append(PowerUp(power_up_type, position))

    def spawn_hazards(self):
        """Spawn environmental hazards"""
        hazard_types = [
            HazardType.ELECTRIC_FLOOR,
            HazardType.FIRE_FIELD,
            HazardType.GRAVITY_WELL,
            HazardType.MINEFIELD
        ]

        for _ in range(4):  # Spawn 4 hazards
            hazard_type = random.choice(hazard_types)
            position = Vector2D(
                random.uniform(200, self.width - 200),
                random.uniform(200, self.height - 200)
            )
            # Ensure not too close to bases or flags
            too_close = False
            for base in list(self.my_bases.values()) + list(self.flag_positions.values()):
                if (position - base).magnitude() < 150:
                    too_close = True
                    break
            if not too_close:
                self.hazards.append(Hazard(hazard_type, position))

    def add_particle_effect(self, position: Vector2D, effect_type: str):
        """Add a visual particle effect"""
        particle = {
            'position': position,
            'type': effect_type,
            'lifetime': 1.0,  # seconds
            'creation_time': time.time(),
            'color': self.get_particle_color(effect_type),
            'size': random.uniform(5, 15),
            'velocity': Vector2D(
                random.uniform(-5, 5),
                random.uniform(-5, 5)
            )
        }
        self.particle_effects.append(particle)

    def get_particle_color(self, effect_type: str) -> Tuple[int, int, int]:
        """Get RGB color for different particle effects"""
        colors = {
            "explosion": (255, 165, 0),     # Orange
            "hit": (255, 0, 0),             # Red
            "powerup": (0, 255, 255),       # Cyan
            "death": (128, 0, 128),         # Purple
            "shield": (0, 100, 255),        # Blue
            "heal": (0, 255, 0),            # Green
            "teleport": (128, 0, 255)       # Violet
        }
        return colors.get(effect_type, (255, 255, 255))

    def add_team_message(self, message: str):
        """Add a message to the team message queue"""
        self.team_messages.append({
            'text': message,
            'timestamp': time.time(),
            'duration': 5.0  # 5 seconds display time
        })

    def play_sound(self, sound_name: str):
        """Add sound effect to queue (in a real implementation, this would trigger audio)"""
        self.audio_queue.put(sound_name)

    def update(self, dt: float):
        """Update the entire environment"""
        self.game_time += dt

        # Update robots
        for robot in self.robots:
            robot.update(dt, self)

        # Update particle effects
        for particle in list(self.particle_effects):
            particle['lifetime'] -= dt
            particle['position'] = particle['position'] + (particle['velocity'] * dt)
            if particle['lifetime'] <= 0:
                self.particle_effects.remove(particle)

        # Update team messages
        for msg in list(self.team_messages):
            if time.time() - msg['timestamp'] > msg['duration']:
                self.team_messages.remove(msg)

        # Spawn new power-ups periodically
        if time.time() - self.last_spawn_time > 30:  # Every 30 seconds
            self.spawn_power_ups()
            self.last_spawn_time = time.time()

        # Check objective completion
        self.check_objectives()

        # Adaptive difficulty adjustment
        self.adaptive_difficulty()

    def check_objectives(self):
        """Check if objectives have been completed"""
        if self.current_objective == ObjectiveType.CAPTURE_FLAG:
            # Check if any robot has captured the flag
            for robot in self.robots:
                if robot.is_alive:
                    # Check if robot is at enemy flag position
                    if (robot.position - self.flag_positions[robot.team]).magnitude() < 50:
                        # Robot has captured the enemy flag
                        # In a real implementation, this would trigger a capture sequence
                        self.teams[robot.team].objectives_completed += 1
                        self.teams[robot.team].objectives_attempted += 1
                        self.add_team_message(f"{robot.team.value.upper()} captured the flag!")
                        self.current_objective = ObjectiveType.DEFEND_BASE
                        self.respawn_flag()

        elif self.current_objective == ObjectiveType.ESCAPE_PAYLOAD:
            # Check if payload reached destination
            if self.payload_position and self.payload_destination:
                if (self.payload_position - self.payload_destination).magnitude() < 50:
                    # Payload reached destination
                    # Find which team is escorting (closest robot)
                    closest_robot = None
                    min_distance = float('inf')
                    for robot in self.robots:
                        if robot.is_alive and (robot.position - self.payload_position).magnitude() < 100:
                            distance = (robot.position - self.payload_destination).magnitude()
                            if distance < min_distance:
                                min_distance = distance
                                closest_robot = robot

                    if closest_robot:
                        self.teams[closest_robot.team].objectives_completed += 1
                        self.teams[closest_robot.team].objectives_attempted += 1
                        self.add_team_message(f"{closest_robot.team.value.upper()} successfully escorted the payload!")
                        self.current_objective = ObjectiveType.CAPTURE_FLAG
                        self.respawn_payload()

        elif self.current_objective == ObjectiveType.DEFEND_BASE:
            # Check if enemy has entered base
            for robot in self.robots:
                if robot.is_alive and robot.team != Team.RED:
                    if (robot.position - self.my_bases[Team.RED]).magnitude() < 80:
                        # Enemy entered base
                        self.teams[Team.BLUE].objectives_attempted += 1
                        self.add_team_message("BLUE team breached RED base!")

                if robot.is_alive and robot.team != Team.BLUE:
                    if (robot.position - self.my_bases[Team.BLUE]).magnitude() < 80:
                        # Enemy entered base
                        self.teams[Team.RED].objectives_attempted += 1
                        self.add_team_message("RED team breached BLUE base!")

    def respawn_flag(self):
        """Respawn flag at a random location"""
        # Move flag to new position
        self.flag_positions[Team.RED] = Vector2D(
            random.uniform(100, self.width - 100),
            random.uniform(100, self.height - 100)
        )
        self.flag_positions[Team.BLUE] = Vector2D(
            random.uniform(100, self.width - 100),
            random.uniform(100, self.height - 100)
        )

    def respawn_payload(self):
        """Respawn payload at a new location"""
        self.payload_position = Vector2D(
            random.uniform(100, self.width - 100),
            random.uniform(100, self.height - 100)
        )
        # Set new destination (opposite base)
        if self.payload_destination == self.my_bases[Team.RED]:
            self.payload_destination = self.my_bases[Team.BLUE]
        else:
            self.payload_destination = self.my_bases[Team.RED]

    def adaptive_difficulty(self):
        """Adjust difficulty based on team performance"""
        red_win_rate = self.teams[Team.RED].wins / max(1, self.teams[Team.RED].games)
        blue_win_rate = self.teams[Team.BLUE].wins / max(1, self.teams[Team.BLUE].games)

        # If one team is consistently winning, make it harder for them
        # and easier for the other team
        if red_win_rate > 0.7:
            # Make it harder for RED team
            for robot in self.robots:
                if robot.team == Team.RED:
                    robot.weapon.damage *= 0.9
                    robot.movement_speed *= 0.95
                    robot.vision_range *= 0.9
        elif red_win_rate < 0.3:
            # Make it easier for RED team
            for robot in self.robots:
                if robot.team == Team.RED:
                    robot.weapon.damage *= 1.1
                    robot.movement_speed *= 1.05
                    robot.vision_range *= 1.1

        if blue_win_rate > 0.7:
            # Make it harder for BLUE team
            for robot in self.robots:
                if robot.team == Team.BLUE:
                    robot.weapon.damage *= 0.9
                    robot.movement_speed *= 0.95
                    robot.vision_range *= 0.9
        elif blue_win_rate < 0.3:
            # Make it easier for BLUE team
            for robot in self.robots:
                if robot.team == Team.BLUE:
                    robot.weapon.damage *= 1.1
                    robot.movement_speed *= 1.05
                    robot.vision_range *= 1.1

        # Adjust AI behavior complexity based on win rates
        # Higher win rate = more complex AI decisions
        if red_win_rate > 0.6:
            # Increase RED team AI complexity
            for robot in self.robots:
                if robot.team == Team.RED:
                    robot.team_strategy['complexity'] = 'high'
        elif red_win_rate < 0.4:
            # Decrease RED team AI complexity
            for robot in self.robots:
                if robot.team == Team.RED:
                    robot.team_strategy['complexity'] = 'low'

        if blue_win_rate > 0.6:
            # Increase BLUE team AI complexity
            for robot in self.robots:
                if robot.team == Team.BLUE:
                    robot.team_strategy['complexity'] = 'high'
        elif blue_win_rate < 0.4:
            # Decrease BLUE team AI complexity
            for robot in self.robots:
                if robot.team == Team.BLUE:
                    robot.team_strategy['complexity'] = 'low'

    def get_team_score(self, team: Team) -> int:
        """Calculate and return the score for a team"""
        stats = self.teams[team]
        base_score = stats.wins * 100
        objective_score = stats.objectives_completed * 50
        damage_score = int(stats.total_damage_dealt / 10)
        return base_score + objective_score + damage_score

