class CyberArena:
    def __init__(self):
        self.environment = Environment()
        self.screen = pygame.display.set_mode((1200, 800))
        pygame.display.set_caption("CyberArena - Futuristic Robot Battle Arena")
        self.clock = pygame.time.Clock()
        self.running = True
        self.font = pygame.font.SysFont('Arial', 18)
        self.small_font = pygame.font.SysFont('Arial', 14)

        # Initialize robots
        self.initialize_robots()

        # Create threads for audio and AI processing
        self.ai_thread = threading.Thread(target=self.ai_update_loop, daemon=True)
        self.audio_thread = threading.Thread(target=self.audio_update_loop, daemon=True)
        self.ai_thread.start()
        self.audio_thread.start()

        # Game state
        self.paused = False
        self.game_start_time = time.time()

        # Color mapping for teams
        self.team_colors = {
            Team.RED: (255, 50, 50),
            Team.BLUE: (50, 50, 255)
        }

    def initialize_robots(self):
        """Initialize robots for the arena"""
        # Create 4 robots per team (8 total)
        for i in range(2):
            # RED team
            role = random.choice(list(RobotRole))
            position = Vector2D(
                self.environment.my_bases[Team.RED].x + random.uniform(-50, 50),
                self.environment.my_bases[Team.RED].y + random.uniform(-50, 50)
            )

            robot = Robot(
                id=f"RED{i+1}",
                team=Team.RED,
                role=role,
                position=position,
                weapon=Weapon(WeaponType.RANGED, 25, 300, 1.0, name=f"Pulse Rifle {i+1}")
            )
            self.environment.robots.append(robot)

            # BLUE team
            role = random.choice(list(RobotRole))
            position = Vector2D(
                self.environment.my_bases[Team.BLUE].x + random.uniform(-50, 50),
                self.environment.my_bases[Team.BLUE].y + random.uniform(-50, 50)
            )

            robot = Robot(
                id=f"BLUE{i+1}",
                team=Team.BLUE,
                role=role,
                position=position,
                weapon=Weapon(WeaponType.RANGED, 25, 300, 1.0, name=f"Pulse Rifle {i+1}")
            )
            self.environment.robots.append(robot)

    def ai_update_loop(self):
        """Background thread for AI updates"""
        while self.running:
            if not self.paused:
                # Update AI decisions in a separate thread
                for robot in self.environment.robots:
                    if robot.is_alive:
                        robot.ai_decision(self.environment)
            time.sleep(0.1)  # Update AI every 100ms

    def audio_update_loop(self):
        """Background thread for audio processing"""
        while self.running:
            try:
