    def update(self, dt: float, environment: 'Environment'):
        """Update robot state based on physics and AI decisions"""
        if not self.is_alive:
            return

        # Update power-up durations
        for power_type, duration in list(self.power_ups.items()):
            self.power_ups[power_type] = duration - dt
            if self.power_ups[power_type] <= 0:
                self.apply_power_up_effect(power_type, remove=True)
                del self.power_ups[power_type]

        # Update cooldowns
        for cooldown_name, duration in list(self.cooldowns.items()):
            self.cooldowns[cooldown_name] = duration - dt
            if self.cooldowns[cooldown_name] <= 0:
                del self.cooldowns[cooldown_name]

        # Apply movement
        if self.target:
            direction = (self.target - self.position).normalize()
            self.velocity = direction * self.movement_speed

            # Stop if close enough to target
            if (self.target - self.position).magnitude() < 10:
                self.velocity = Vector2D(0, 0)
                self.target = None
        else:
