    def get_nearest_teammate(self, team: Team) -> Optional[Robot]:
        """Find nearest teammate"""
        teammates = [r for r in self.game_state.robots 
                    if r.team == team and r.id != self.robot.id and r.is_alive]
        if not teammates:
            return None

        return min(teammates, key=lambda r: self.robot.position.distance_to(r.position))

    def get_nearest_enemy(self, team: Team) -> Optional[Robot]:
        """Find nearest enemy"""
        enemies = [r for r in self.game_state.robots 
                  if r.team != team and r.is_alive]
        if not enemies:
            return None

        return min(enemies, key=lambda r: self.robot.position.distance_to(r.position))

    def get_nearest_objective(self, objective_type: ObjectiveType) -> Optional[Objective]:
        """Find nearest objective of specified type"""
        objectives = [obj for obj in self.game_state.objectives 
                     if obj.type == objective_type and obj.active]
        if not objectives:
            return None

        return min(objectives, key=lambda o: self.robot.position.distance_to(o.position))

    def get_nearest_power_up(self) -> Optional[PowerUp]:
        """Find nearest active power-up"""
        power_ups = [pu for pu in self.game_state.power_ups if pu.active]
        if not power_ups:
            return None

        return min(power_ups, key=lambda pu: self.robot.position.distance_to(pu.position))

    def get_nearest_hazard(self) -> Optional[Hazard]:
        """Find nearest active hazard"""
        hazards = [h for h in self.game_state.hazards if h.active]
        if not hazards:
            return None

        return min(hazards, key=lambda h: self.robot.position.distance_to(h.position))

    def should_use_ability(self, ability_type: str, current_time: float) -> bool:
        """Check if robot should use a specific ability"""
        if ability_type not in self.robot.cooldowns:
            return False

        # Check if cooldown is ready
        if current_time - self.robot.cooldowns[ability_type] < 0:
            return False

        # Check if ability is beneficial
        if ability_type == "ultimate":
            # Use ultimate if many enemies nearby or low health
            enemies = self.get_nearby_enemies(150)
            if len(enemies) >= 3 or self.robot.health < self.robot.max_health * 0.3:
                return True
        elif ability_type == "ability_1":
            # Use ability 1 when near enemy or low ammo
            enemy = self.get_nearest_enemy(self.robot.team)
            if enemy and self.robot.position.distance_to(enemy.position) < 100:
                return True
            if self.robot.weapon.ammo_left < 5:
                return True
        elif ability_type == "ability_2":
            # Use ability 2 for healing or defense
            if self.robot.health < self.robot.max_health * 0.6:
                return True
            if self.get_nearest_hazard():
                return True

        return False

    def get_nearby_enemies(self, radius: float) -> List[Robot]:
        """Get all enemies within radius"""
        return [r for r in self.game_state.robots 
                if r.team != self.robot.team and r.is_alive 
                and self.robot.position.distance_to(r.position) < radius]

class AssaultAI(AIController):
    """AI for Assault robots - aggressive frontline fighters"""

    def decide_action(self, current_time: float) -> Dict[str, Any]:
        if current_time - self.last_decision_time < self.decision_cooldown:
            return {"action": "idle", "target": None}

        self.last_decision_time = current_time

        # Target the nearest enemy
        nearest_enemy = self.get_nearest_enemy(self.robot.team)
        nearest_objective = self.get_nearest_objective(ObjectiveType.FLAG_CAPTURE)
        nearest_power_up = self.get_nearest_power_up()
        nearest_hazard = self.get_nearest_hazard()

        # Check if we need to reload
        if self.robot.weapon.ammo_left < 5 and self.robot.weapon.can_fire(current_time):
            return {"action": "reload"}

        # Check if we should use ability
        if self.should_use_ability("ultimate", current_time):
            return {"action": "use_ability", "type": "ultimate", "target": nearest_enemy.position if nearest_enemy else None}

        if nearest_hazard and self.robot.position.distance_to(nearest_hazard.position) < 80:
            # Avoid hazard
            direction = (self.robot.position - nearest_hazard.position).normalize()
            return {"action": "move", "target": self.robot.position + direction * 100}

        # If power-up is nearby and beneficial, go for it
        if nearest_power_up and nearest_power_up.position.distance_to(self.robot.position) < 120:
            return {"action": "move", "target": nearest_power_up.position}

        # If objective is nearby, move to capture it
        if nearest_objective and nearest_objective.position.distance_to(self.robot.position) < 200:
            # If we're not controlling it, try to capture
            if nearest_objective.captured_by != self.robot.team:
                return {"action": "move", "target": nearest_objective.position}
            else:
                # Defend objective
                enemy = self.get_nearest_enemy(self.robot.team)
                if enemy:
                    return {"action": "attack", "target": enemy.position}

        # Attack nearest enemy if in range
        if nearest_enemy and self.robot.position.distance_to(nearest_enemy.position) < self.robot.weapon.range:
            return {"action": "attack", "target": nearest_enemy.position}

        # Move toward nearest objective if no immediate threat
        if nearest_objective:
            return {"action": "move", "target": nearest_objective.position}

        # If no clear target, patrol a random point
        return {"action": "patrol", "target": self.robot.position + Vector2D(random.uniform(-50, 50), random.uniform(-50, 50))}

class SupportAI(AIController):
