@dataclass
class Vector2D:
    x: float = 0.0
    y: float = 0.0

    def __add__(self, other):
        return Vector2D(self.x + other.x, self.y + other.y)

    def __sub__(self, other):
        return Vector2D(self.x - other.x, self.y - other.y)

    def __mul__(self, scalar):
        return Vector2D(self.x * scalar, self.y * scalar)

    def __truediv__(self, scalar):
        if scalar == 0:
            return Vector2D(0, 0)
        return Vector2D(self.x / scalar, self.y / scalar)

    def magnitude(self):
        return math.sqrt(self.x**2 + self.y**2)

    def normalize(self):
        mag = self.magnitude()
        if mag == 0:
            return Vector2D(0, 0)
        return self / mag

    def distance_to(self, other):
        return (self - other).magnitude()

    def to_tuple(self):
        return (self.x, self.y)

@dataclass
class Weapon:
    type: WeaponType
    name: str
    damage: float
    range: float
    fire_rate: float  # seconds between shots
    ammo: int
    max_ammo: int
    reload_time: float = 3.0
    splash_radius: float = 0.0  # for explosive weapons
    is_melee: bool = False

    def __post_init__(self):
        self.ammo_left = self.ammo
        self.last_fired = 0.0

    def can_fire(self, current_time: float) -> bool:
        return (current_time - self.last_fired >= self.fire_rate) and self.ammo_left > 0

    def fire(self, current_time: float) -> bool:
        if self.can_fire(current_time):
            self.ammo_left -= 1
            self.last_fired = current_time
            return True
        return False

    def reload(self):
        self.ammo_left = self.max_ammo

