                damage=25.0,
                range=500.0,
                fire_rate=0.5,
                ammo=30,
                max_ammo=30
            )

        # Initialize cooldowns for abilities
        self.cooldowns = {
            "ability_1": 0.0,
            "ability_2": 0.0,
            "ultimate": 0.0
        }

        # Initialize robot-specific knowledge
        self.knowledge = {
            "battle_history": [],
            "team_performance": 0.0,
            "enemy_patterns": {},
            "preferred_positions": {},
            "strategy_success_rate": 0.5
        }

@dataclass
class Objective:
    type: ObjectiveType
    position: Vector2D
    team_required: Team
    captured_by: Optional[Team] = None
    progress: float = 0.0
    max_progress: float = 100.0
    capture_radius: float = 50.0
    defenders: List[int] = field(default_factory=list)
    attackers: List[int] = field(default_factory=list)

    def update_progress(self, team: Team, delta: float):
        if team == self.team_required:
            # Team is trying to capture/defend
            self.progress = min(self.max_progress, self.progress + delta)
        else:
            # Opposing team is trying to capture
            self.progress = max(0, self.progress - delta)

        # Update who controls it
        if self.progress >= self.max_progress:
            self.captured_by = self.team_required
        elif self.progress <= 0:
            # Flip control if enough progress lost
            self.captured_by = Team.RED if self.team_required == Team.BLUE else Team.BLUE

@dataclass
class PowerUp:
    type: PowerUpType
    position: Vector2D
    active: bool = True
    duration: float = 10.0
    value: float = 0.0
    spawn_time: float = 0.0
    effect: str = ""

    def __post_init__(self):
        # Define effects based on type
        effect_map = {
            PowerUpType.HEALTH_PACK: ("health", 30),
            PowerUpType.AMMO_RELOAD: ("ammo", 20),
            PowerUpType.SPEED_BOOST: ("speed", 1.5),
            PowerUpType.SHIELD: ("shield", 50),
            PowerUpType.TELEPORT: ("teleport", 0),
            PowerUpType.EMP: ("emp", 0)
        }
        self.effect, self.value = effect_map.get(self.type, ("health", 30))

@dataclass
class Hazard:
    type: HazardType
    position: Vector2D
    radius: float
    damage_per_second: float
    active: bool = True
    spawn_time: float = 0.0

@dataclass
class GameState:
    time_elapsed: float = 0.0
    round_start_time: float = 0.0
    current_map: str = "Arena_01"
    objectives: List[Objective] = field(default_factory=list)
    power_ups: List[PowerUp] = field(default_factory=list)
    hazards: List[Hazard] = field(default_factory=list)
    robots: List[Robot] = field(default_factory=list)
    team_scores: Dict[Team, int] = field(default_factory=lambda: {Team.RED: 0, Team.BLUE: 0})
    winner: Optional[Team] = None
    game_over: bool = False
    difficulty_level: float = 0.5  # 0.0 to 1.0
    adaptive_system: Optional['AdaptiveSystem'] = None

    def __post_init__(self):
        if self.adaptive_system is None:
            self.adaptive_system = AdaptiveSystem(self)

class AdaptiveSystem:
    """Manages adaptive difficulty based on robot performance"""

    def __init__(self, game_state: GameState):
        self.game_state = game_state
        self.performance_history: List[float] = []  # Average team performance
        self.adjustment_cooldown: float = 10.0  # Seconds between adjustments
        self.last_adjustment: float = 0.0
        self.difficulty_thresholds = [0.3, 0.5, 0.7]  # Levels for difficulty changes

    def update(self, current_time: float):
        """Update adaptive difficulty based on team performance"""
        if current_time - self.last_adjustment < self.adjustment_cooldown:
            return

        # Calculate average team performance
        total_performance = 0.0
        robot_count = 0

        for robot in self.game_state.robots:
            if robot.is_alive:
                # Performance based on score, objectives completed, and survival
                performance = robot.score / 10.0 + (1.0 if robot.objective else 0.0)
                total_performance += performance
                robot_count += 1

        if robot_count > 0:
            avg_performance = total_performance / robot_count
            self.performance_history.append(avg_performance)

            # Keep only recent history (last 10 evaluations)
            if len(self.performance_history) > 10:
                self.performance_history.pop(0)

            # Calculate trend
            if len(self.performance_history) >= 5:
                trend = sum(self.performance_history[-5:]) / 5.0

                # Adjust difficulty based on performance trend
                if trend > 0.8 and self.game_state.difficulty_level < 1.0:
                    self.game_state.difficulty_level = min(1.0, self.game_state.difficulty_level + 0.1)
                    logger.info(f"Difficulty increased to {self.game_state.difficulty_level}")
                elif trend < 0.3 and self.game_state.difficulty_level > 0.1:
                    self.game_state.difficulty_level = max(0.1, self.game_state.difficulty_level - 0.1)
                    logger.info(f"Difficulty decreased to {self.game_state.difficulty_level}")

                self.last_adjustment = current_time

class AIController(ABC):
    """Abstract base class for AI controllers"""

    def __init__(self, robot: Robot, game_state: GameState):
        self.robot = robot
        self.game_state = game_state
        self.last_decision_time = 0.0
        self.decision_cooldown = 0.5  # seconds between decisions

    @abstractmethod
    def decide_action(self, current_time: float) -> Dict[str, Any]:
        """Decide next action based on current state"""
        pass

    def get_nearest_teammate(self, team: Team) -> Optional[Robot]:
        """Find nearest teammate"""
        teammates = [r for r in self.game_state.robots 
                    if r.team == team and r.id != self.robot.id and r.is_alive]
        if not teammates:
            return None

        return min(teammates, key=lambda r: self.robot.position.distance_to(r.position))

    def get_nearest_enemy(self, team: Team) -> Optional[Robot]:
        """Find nearest enemy"""
        enemies = [r for r in self.game_state.robots 
                  if r.team != team and r.is_alive]
        if not enemies:
            return None

        return min(enemies, key=lambda r: self.robot.position.distance_to(r.position))

    def get_nearest_objective(self, objective_type: ObjectiveType) -> Optional[Objective]:
        """Find nearest objective of specified type"""
        objectives = [obj for obj in self.game_state.objectives 
                     if obj.type == objective_type and obj.active]
        if not objectives:
            return None

        return min(objectives, key=lambda o: self.robot.position.distance_to(o.position))

    def get_nearest_power_up(self) -> Optional[PowerUp]:
        """Find nearest active power-up"""
        power_ups = [pu for pu in self.game_state.power_ups if pu.active]
        if not power_ups:
            return None

        return min(power_ups, key=lambda pu: self.robot.position.distance_to(pu.position))

    def get_nearest_hazard(self) -> Optional[Hazard]:
        """Find nearest active hazard"""
        hazards = [h for h in self.game_state.hazards if h.active]
        if not hazards:
            return None

        return min(hazards, key=lambda h: self.robot.position.distance_to(h.position))

    def should_use_ability(self, ability_type: str, current_time: float) -> bool:
        """Check if robot should use a specific ability"""
        if ability_type not in self.robot.cooldowns:
            return False

        # Check if cooldown is ready
        if current_time - self.robot.cooldowns[ability_type] < 0:
            return False

        # Check if ability is beneficial
        if ability_type == "ultimate":
            # Use ultimate if many enemies nearby or low health
            enemies = self.get_nearby_enemies(150)
            if len(enemies) >= 3 or self.robot.health < self.robot.max_health * 0.3:
                return True
        elif ability_type == "ability_1":
            # Use ability 1 when near enemy or low ammo
            enemy = self.get_nearest_enemy(self.robot.team)
            if enemy and self.robot.position.distance_to(enemy.position) < 100:
                return True
            if self.robot.weapon.ammo_left < 5:
                return True
        elif ability_type == "ability_2":
            # Use ability 2 for healing or defense
            if self.robot.health < self.robot.max_health * 0.6:
                return True
            if self.get_nearest_hazard():
                return True

        return False

    def get_nearby_enemies(self, radius: float) -> List[Robot]:
        """Get all enemies within radius"""
        return [r for r in self.game_state.robots 
                if r.team != self.robot.team and r.is_alive 
                and self.robot.position.distance_to(r.position) < radius]

class AssaultAI(AIController):
    """AI for Assault robots - aggressive frontline fighters"""

    def decide_action(self, current_time: float) -> Dict[str, Any]:
        if current_time - self.last_decision_time < self.decision_cooldown:
            return {"action": "idle", "target": None}

        self.last_decision_time = current_time

        # Target the nearest enemy
        nearest_enemy = self.get_nearest_enemy(self.robot.team)
        nearest_objective = self.get_nearest_objective(ObjectiveType.FLAG_CAPTURE)
        nearest_power_up = self.get_nearest_power_up()
        nearest_hazard = self.get_nearest_hazard()

        # Check if we need to reload
        if self.robot.weapon.ammo_left < 5 and self.robot.weapon.can_fire(current_time):
            return {"action": "reload"}

        # Check if we should use ability
        if self.should_use_ability("ultimate", current_time):
            return {"action": "use_ability", "type": "ultimate", "target": nearest_enemy.position if nearest_enemy else None}

        if nearest_hazard and self.robot.position.distance_to(nearest_hazard.position) < 80:
            # Avoid hazard
            direction = (self.robot.position - nearest_hazard.position).normalize()
            return {"action": "move", "target": self.robot.position + direction * 100}

        # If power-up is nearby and beneficial, go for it
        if nearest_power_up and nearest_power_up.position.distance_to(self.robot.position) < 120:
            return {"action": "move", "target": nearest_power_up.position}

        # If objective is nearby, move to capture it
        if nearest_objective and nearest_objective.position.distance_to(self.robot.position) < 200:
            # If we're not controlling it, try to capture
            if nearest_objective.captured_by != self.robot.team:
                return {"action": "move", "target": nearest_objective.position}
            else:
                # Defend objective
                enemy = self.get_nearest_enemy(self.robot.team)
                if enemy:
                    return {"action": "attack", "target": enemy.position}

        # Attack nearest enemy if in range
        if nearest_enemy and self.robot.position.distance_to(nearest_enemy.position) < self.robot.weapon.range:
            return {"action": "attack", "target": nearest_enemy.position}

        # Move toward nearest objective if no immediate threat
        if nearest_objective:
            return {"action": "move", "target": nearest_objective.position}

        # If no clear target, patrol a random point
        return {"action": "patrol", "target": self.robot.position + Vector2D(random.uniform(-50, 50), random.uniform(-50, 50))}

class SupportAI(AIController):
    """AI for Support robots - healers and team enhancers"""

    def decide_action(self, current_time: float) -> Dict[str, Any]:
        if current_time - self.last_decision_time < self.decision_cooldown:
            return {"action": "idle", "target": None}

        self.last_decision_time = current_time

        # Check if we need to reload
        if self.robot.weapon.ammo_left < 10 and self.robot.weapon.can_fire(current_time):
            return {"action": "reload"}

        # Find teammates in need
        teammates_in_need = [
            r for r in self.game_state.robots 
            if r.team == self.robot.team and r.is_alive and r.health < r.max_health * 0.7
        ]

        # Find nearest teammate for healing
        if teammates_in_need:
            nearest_teammate = min(teammates_in_need, key=lambda r: self.robot.position.distance_to(r.position))

            # Use healing ability if available
            if self.should_use_ability("ability_2", current_time):
                return {"action": "use_ability", "type": "ability_2", "target": nearest_teammate.position}

            # If we're close enough, stay near
            if self.robot.position.distance_to(nearest_teammate.position) < 100:
                return {"action": "support", "target": nearest_teammate.position}
            else:
                # Move toward teammate
                return {"action": "move", "target": nearest_teammate.position}

        # Get nearest objective
        nearest_objective = self.get_nearest_objective(ObjectiveType.BASE_DEFENSE)
        if nearest_objective and nearest_objective.captured_by == self.robot.team:
            # Defend objective
            enemy = self.get_nearest_enemy(self.robot.team)
            if enemy and self.robot.position.distance_to(enemy.position) < 200:
                return {"action": "attack", "target": enemy.position}

        # If power-up is nearby, go for it
        nearest_power_up = self.get_nearest_power_up()
        if nearest_power_up and nearest_power_up.position.distance_to(self.robot.position) < 150:
            return {"action": "move", "target": nearest_power_up.position}

        # Stay near base or objective
        if nearest_objective:
            return {"action": "patrol", "target": nearest_objective.position}

        # Default: move toward nearest teammate
        nearest_teammate = self.get_nearest_teammate(self.robot.team)
        if nearest_teammate:
            return {"action": "move", "target": nearest_teammate.position}

        return {"action": "idle", "target": None}

class ReconAI(AIController):
    """AI for Recon robots - scouts and information gatherers"""

    def decide_action(self, current_time: float) -> Dict[str, Any]:
        if current_time - self.last_decision_time < self.decision_cooldown:
            return {"action": "idle", "target": None}

        self.last_decision_time = current_time

        # Check if we need to reload
        if self.robot.weapon.ammo_left < 5 and self.robot.weapon.can_fire(current_time):
            return {"action": "reload"}

        # Use ultimate to reveal enemies
        if self.should_use_ability("ultimate", current_time):
            return {"action": "use_ability", "type": "ultimate", "target": None}

        # Find enemies within vision range
        visible_enemies = [
            r for r in self.game_state.robots 
            if r.team != self.robot.team and r.is_alive 
            and self.robot.position.distance_to(r.position) < self.robot.vision_range
        ]

        # If we see enemies, report and flank
        if visible_enemies:
            # Update knowledge about enemy positions
            for enemy in visible_enemies:
                self.robot.knowledge["enemy_patterns"][enemy.id] = enemy.position.to_tuple()

            # Find the closest enemy
            nearest_enemy = min(visible_enemies, key=lambda e: self.robot.position.distance_to(e.position))

            # Use ability to distract enemy
            if self.should_use_ability("ability_1", current_time):
                return {"action": "use_ability", "type": "ability_1", "target": nearest_enemy.position}

            # Move to flank enemy
            if self.robot.position.distance_to(nearest_enemy.position) < 100:
                # Flank by moving perpendicular to enemy
                direction = (nearest_enemy.position - self.robot.position).normalize()
                perpendicular = Vector2D(-direction.y, direction.x)  # 90 degree rotation
                flank_target = nearest_enemy.position + perpendicular * 80
                return {"action": "move", "target": flank_target}
            else:
                # Move toward enemy
                return {"action": "move", "target": nearest_enemy.position}

        # Find objectives to scout
        objectives = [obj for obj in self.game_state.objectives if obj.captured_by != self.robot.team]
        if objectives:
            nearest_objective = min(objectives, key=lambda o: self.robot.position.distance_to(o.position))
            # Move to scout objective
            return {"action": "move", "target": nearest_objective.position}

        # Find power-ups
        nearest_power_up = self.get_nearest_power_up()
        if nearest_power_up and nearest_power_up.position.distance_to(self.robot.position) < 200:
            return {"action": "move", "target": nearest_power_up.position}

        # Patrol a perimeter around the base
        if self.robot.team == Team.RED:
            patrol_point = Vector2D(100, 100)
        else:
            patrol_point = Vector2D(700, 700)

        return {"action": "patrol", "target": patrol_point}

class TankAI(AIController):
    """AI for Tank robots - heavy defense and frontline protectors"""

    def decide_action(self, current_time: float) -> Dict[str, Any]:
        if current_time - self.last_decision_time < self.decision_cooldown:
            return {"action": "idle", "target": None}

        self.last_decision_time = current_time

        # Check if we need to reload
        if self.robot.weapon.ammo_left < 3 and self.robot.weapon.can_fire(current_time):
            return {"action": "reload"}

        # Use ultimate ability to shield teammates
        if self.should_use_ability("ultimate", current_time):
            return {"action": "use_ability", "type": "ultimate", "target": None}

        # Find nearest enemy
        nearest_enemy = self.get_nearest_enemy(self.robot.team)
        nearest_hazard = self.get_nearest_hazard()

        # If we're below 50% health, move toward base or power-up
        if self.robot.health < self.robot.max_health * 0.5:
            nearest_power_up = self.get_nearest_power_up()
            if nearest_power_up and nearest_power_up.position.distance_to(self.robot.position) < 200:
                return {"action": "move", "target": nearest_power_up.position}
            else:
                # Return to base
                base_pos = Vector2D(150, 150) if self.robot.team == Team.RED else Vector2D(650, 650)
                return {"action": "move", "target": base_pos}

        # If there's a hazard nearby, we're tough enough to handle it
        if nearest_hazard and nearest_hazard.position.distance_to(self.robot.position) < 100:
            # We're a tank, we can take the damage
            # But still try to move away slightly if possible
            direction = (self.robot.position - nearest_hazard.position).normalize()
            return {"action": "move", "target": self.robot.position + direction * 60}

        # Find objectives to defend
        objectives = [obj for obj in self.game_state.objectives if obj.captured_by == self.robot.team]
        if objectives:
            nearest_objective = min(objectives, key=lambda o: self.robot.position.distance_to(o.position))

            # If enemy is near objective, defend it
            if nearest_enemy and nearest_enemy.position.distance_to(nearest_objective.position) < 150:
                # Position between objective and enemy to block
                direction = (nearest_enemy.position - nearest_objective.position).normalize()
                defense_pos = nearest_objective.position + direction * 80
                return {"action": "move", "target": defense_pos}

            # Otherwise, patrol objective
            return {"action": "patrol", "target": nearest_objective.position}

        # If no objective nearby, find and attack nearest enemy
        if nearest_enemy:
            # Move to intercept
            return {"action": "attack", "target": nearest_enemy.position}

        # Patrol a fixed area
        patrol_center = Vector2D(150, 150) if self.robot.team == Team.RED else Vector2D(650, 650)
        return {"action": "patrol", "target": patrol_center}

class RobotManager:
    """Manages all robots and their behaviors"""

    def __init__(self, game_state: GameState):
        self.game_state = game_state
        self.ai_controllers: Dict[int, AIController] = {}
        self.initialize_ai_controllers()

    def initialize_ai_controllers(self):
        """Initialize AI controllers for each robot"""
        for robot in self.game_state.robots:
            if robot.robot_type == RobotType.ASSAULT:
                self.ai_controllers[robot.id] = AssaultAI(robot, self.game_state)
            elif robot.robot_type == RobotType.SUPPORT:
                self.ai_controllers[robot.id] = SupportAI(robot, self.game_state)
            elif robot.robot_type == RobotType.RECON:
                self.ai_controllers[robot.id] = ReconAI(robot, self.game_state)
            elif robot.robot_type == RobotType.TANK:
                self.ai_controllers[robot.id] = TankAI(robot, self.game_state)

    def update_robots(self, current_time: float):
        """Update all robots' behaviors"""
        for robot in self.game_state.robots:
            if not robot.is_alive:
                continue

            controller = self.ai_controllers.get(robot.id)
            if controller is None:
                continue

            action = controller.decide_action(current_time)
            self.execute_robot_action(robot, action, current_time)

    def execute_robot_action(self, robot: Robot, action: Dict[str, Any], current_time: float):
        """Execute robot action"""
        if action["action"] == "attack":
            # Check if weapon can fire
            if robot.weapon.can_fire(current_time):
                target_pos = action["target"]
                if target_pos:
                    # Calculate direction toward target
                    direction = (target_pos - robot.position).normalize()
                    # Apply damage to enemy if in range
                    for enemy in self.game_state.robots:
                        if enemy.team != robot.team and enemy.is_alive:
                            distance = robot.position.distance_to(enemy.position)
                            if distance <= robot.weapon.range:
                                # Apply damage
                                damage = robot.weapon.damage
                                if robot.weapon.splash_radius > 0:
                                    # Splash damage
                                    if distance <= robot.weapon.splash_radius:
                                        damage *= 0.7  # Reduced damage at splash edge
                                    else:
                                        continue  # Out of splash range

                                # Apply damage with armor reduction
                                effective_damage = damage * (1 - min(0.75, enemy.armor / 100))
                                enemy.health -= effective_damage
                                robot.knowledge["battle_history"].append({
                                    "action": "attack",
                                    "target": enemy.id,
                                    "damage": effective_damage,
                                    "time": current_time
                                })

                                # Play sound effect
                                self.play_sound_effect("weapon_fire")

                                # Check if enemy is dead
                                if enemy.health <= 0:
                                    enemy.is_alive = False
                                    robot.score += 10
                                    self.game_state.team_scores[robot.team] += 10
                                    logger.info(f"Robot {robot.id} eliminated Robot {enemy.id}")
                                    self.play_sound_effect("enemy_down")

                                # Reduce ammo
                                robot.weapon.fire(current_time)
                                break

        elif action["action"] == "move":
            # Move toward target position
            if action["target"]:
                target = action["target"]
                direction = (target - robot.position).normalize()
                # Apply speed with difficulty multiplier
                speed = robot.speed * (1.0 + self.game_state.difficulty_level * 0.2)
                robot.velocity = direction * speed

                # Update position
                robot.position = robot.position + robot.velocity * (1/60)  # Assuming 60 FPS

                # Ensure robot stays within arena bounds
                robot.position.x = max(0, min(robot.position.x, 800))
                robot.position.y = max(0, min(robot.position.y, 800))

        elif action["action"] == "reload":
            # Reload weapon
            robot.weapon.reload()
            self.play_sound_effect("reload")

        elif action["action"] == "use_ability":
            ability_type = action["type"]
            if ability_type == "ultimate":
                # Ultimate ability: AoE damage or shield
                if robot.robot_type == RobotType.RECON:
                    # Recon ultimate: reveal all enemies
                    for enemy in self.game_state.robots:
                        if enemy.team != robot.team:
                            enemy.knowledge["revealed_by"] = robot.id
                    self.play_sound_effect("recon_ultimate")
                elif robot.robot_type == RobotType.TANK:
                    # Tank ultimate: deploy shield around self
                    for teammate in self.game_state.robots:
                        if teammate.team == robot.team and teammate.is_alive:
                            distance = robot.position.distance_to(teammate.position)
                            if distance < 150:
                                teammate.armor += 30  # Temporary armor boost
                    self.play_sound_effect("tank_ultimate")
                robot.cooldowns["ultimate"] = current_time + 20.0  # 20 second cooldown

            elif ability_type == "ability_1":
                # Ability 1: Speed boost or distraction
                if robot.robot_type == RobotType.RECON:
                    robot.speed *= 2.0
                    robot.cooldowns["ability_1"] = current_time + 8.0
                    self.play_sound_effect("recon_ability")
                elif robot.robot_type == RobotType.ASSAULT:
                    # Create distraction (small explosion)
                    self.game_state.hazards.append(
                        Hazard(
                            type=HazardType.MINE_FIELD,
                            position=robot.position,
                            radius=40,
                            damage_per_second=10.0,
                            spawn_time=current_time
                        )
                    )
                    robot.cooldowns["ability_1"] = current_time + 12.0
                    self.play_sound_effect("assault_ability")

            elif ability_type == "ability_2":
                # Ability 2: Heal or shield
                if robot.robot_type == RobotType.SUPPORT:
                    # Heal nearest teammate
                    teammates = [r for r in self.game_state.robots 
                                if r.team == robot.team and r.is_alive]
                    if teammates:
                        nearest_teammate = min(teammates, 
