        self.health -= damage
        if self.health <= 0:
            self.is_alive = False
            self.health = 0
            return 0  # full damage applied, robot dead
        return damage

    def heal(self, amount: float):
        """Heal robot up to max health."""
        self.health = min(self.health + amount, DEFAULT_HEALTH)

    def can_see(self, target_position: Vector2D, obstacles: List[Tuple[Vector2D, Vector2D]]) -> bool:
        """Simple line-of-sight check (ignores complex geometry for performance)."""
        # For simplicity, assume no obstacles in this implementation
        # In a real system, we'd use ray-tracing or pathfinding
        distance = self.position.distance_to(target_position)
        return distance <= self.vision_range

    def get_available_actions(self, game_state: 'CyberArena') -> List[str]:
        """Return list of possible actions based on current state."""
        actions = []

        # Movement
        actions.append("move")

        # Combat
        if self.weapon.can_fire():
            actions.append("fire")

        # Reload
        if self.weapon.ammo < self.weapon.max_ammo:
            actions.append("reload")

        # Use power-up
        if any(self.power_ups.values()):
            actions.append("use_powerup")

        # Objectives
        if self.objectives:
            actions.append("complete_objective")

        # Team communication
        actions.append("communicate")

        return actions

    def decide_action(self, game_state: 'CyberArena') -> Dict:
        """
        AI decision-making using a simple state machine with memory and adaptive learning.
        This is the core of the adaptive difficulty system.
        """
        current_time = time.time()

        # Update strategy memory based on recent performance
        if current_time - self.last_update_time > 2.0:
            self.update_strategy_memory(game_state)
            self.last_update_time = current_time

        # Check for immediate threats
        enemies = game_state.get_enemies_in_range(self.position, self.vision_range)

        if enemies:
            closest_enemy = min(enemies, key=lambda e: self.position.distance_to(e['position']))
            distance = self.position.distance_to(closest_enemy['position'])

            # Adaptive behavior based on difficulty and team performance
            difficulty_multiplier = game_state.get_difficulty_multiplier()

            # If low on health, prioritize retreat or healing
            if self.health < 30 and distance < 10:
                return {"action": "retreat", "target": self.position + Vector2D(random.uniform(-5,5), random.uniform(-5,5))}

            # If high damage and close, melee
            if distance <= MELEE_RANGE and self.weapon.type == WeaponType.MELEE:
                return {"action": "melee_attack", "target": closest_enemy['id']}

            # If ranged weapon and in range, shoot
            if distance <= self.weapon.range and self.weapon.can_fire():
                return {"action": "fire", "target": closest_enemy['id']}

            # Otherwise, move toward enemy
            if distance > self.weapon.range:
                return {"action": "move", "target": closest_enemy['position']}

        # Check if objectives are within range
        objectives = game_state.get_active_objectives()
        for obj in objectives:
            if self.position.distance_to(obj['position']) < 8.0:
                if obj['type'] == ObjectiveType.CAPTURE_THE_FLAG and obj['team'] != self.team:
                    return {"action": "capture", "target": obj['id']}

        # Check for power-ups
        powerups = game_state.get_powerups_in_range(self.position, 10.0)
        if powerups:
            closest_powerup = min(powerups, key=lambda p: self.position.distance_to(p['position']))
            return {"action": "move", "target": closest_powerup['position']}

        # Default behavior: patrol or explore
        if random.random() < 0.3:
            # Random movement pattern based on role
            if self.role == RobotRole.SCATTER:
                target = self.position + Vector2D(random.uniform(-10,10), random.uniform(-10,10))
            elif self.role == RobotRole.DEFENDER:
                target = game_state.teams[self.team]['base']
            elif self.role == RobotRole.SUPPORT:
                # Find teammate with low health
                teammates = game_state.get_teammates_in_range(self.position, 15.0)
                if teammates:
                    weakest = min(teammates, key=lambda t: t['health'])
                    target = weakest['position']
                else:
                    target = game_state.teams[self.team]['base']
            else:
                target = self.position + Vector2D(random.uniform(-5,5), random.uniform(-5,5))
            return {"action": "move", "target": target}

        # Default: stay and reload if needed
        if self.weapon.ammo < 10 and self.weapon.ammo < self.weapon.max_ammo:
            return {"action": "reload"}

        return {"action": "idle"}

    def update_strategy_memory(self, game_state: 'CyberArena'):
        """Update memory with recent performance data for learning."""
        # Track recent actions and outcomes
        if 'action_history' not in self.strategy_memory:
            self.strategy_memory['action_history'] = deque(maxlen=20)

        # Record the last action and its success
        recent_outcome = {
            'time': time.time(),
            'action': self.last_action,
            'team_performance': game_state.get_team_performance(self.team),
            'survival_time': time.time() - self.last_update_time
        }
        self.strategy_memory['action_history'].append(recent_outcome)

        # Adjust behavior based on success rate
        if len(self.strategy_memory['action_history']) >= 5:
            successful_actions = sum(1 for a in self.strategy_memory['action_history'] 
                                   if a['team_performance'] > 0.5)
            if successful_actions / len(self.strategy_memory['action_history']) < 0.3:
                # Poor performance: try more defensive behavior
                self.role = RobotRole.DEFENDER
            elif successful_actions / len(self.strategy_memory['action_history']) > 0.7:
                # Good performance: become more aggressive
                self.role = RobotRole.ATTACKER

@dataclass
class PowerUp:
    type: PowerUpType
    position: Vector2D
    duration: float = POWER_UP_DURATION
    spawn_time: float = field(default_factory=lambda: time.time())
    active: bool = True

@dataclass
class Hazard:
    type: HazardType
    position: Vector2D
    radius: float
    damage_per_tick: float
    active: bool = True
    spawn_time: float = field(default_factory=lambda: time.time())

@dataclass
class Objective:
    id: str
    type: ObjectiveType
    position: Vector2D
    team: Optional[int] = None  # which team controls it
    progress: float = 0.0  # 0.0 to 1.0
    required_robots: int = 1
    capture_radius: float = 5.0
    completed: bool = False
    last_updated: float = field(default_factory=lambda: time.time())

@dataclass
class Team:
    id: int
    name: str
    base: Vector2D
    score: int = 0
    robots: List[Robot] = field(default_factory=list)
    objectives: List[Objective] = field(default_factory=list)
    last_capture_time: float = 0.0

@dataclass
class GameState:
    map_size: Tuple[int, int]
    teams: Dict[int, Team]
    robots: List[Robot]
    powerups: List[PowerUp]
    hazards: List[Hazard]
    objectives: List[Objective]
    game_time: float = 0.0
    state: GameState = GameState.PREPARING
    winner: Optional[int] = None
    difficulty_level: int = 1  # 1-5 scale
    team_performance: Dict[int, float] = field(default_factory=dict)  # team_id -> performance score (0.0-1.0)
    last_ai_update: float = 0.0
    visual_effects: List[Dict] = field(default_factory=list)  # for rendering
    audio_queue: List[str] = field(default_factory=list)  # for audio feedback

    def __post_init__(self):
        if not self.team_performance:
            for team_id in self.teams:
                self.team_performance[team_id] = 0.5  # neutral starting performance

    def get_team_performance(self, team_id: int) -> float:
        return self.team_performance.get(team_id, 0.5)

    def get_difficulty_multiplier(self) -> float:
        """Adjust AI difficulty based on average team performance."""
        if len(self.team_performance) == 0:
            return 1.0
        avg_performance = sum(self.team_performance.values()) / len(self.team_performance)
        # Higher performance -> harder AI
        # Normalize to 0.5-1.5 range
        return max(0.5, min(1.5, 1.0 + (avg_performance - 0.5) * 1.0))

    def get_enemies_in_range(self, position: Vector2D, range_radius: float) -> List[Dict]:
        """Return list of enemy robots within range."""
        enemies = []
        for robot in self.robots:
            if robot.team != self.get_team_by_robot_id(robot.id) and robot.is_alive:
                distance = position.distance_to(robot.position)
                if distance <= range_radius:
                    enemies.append({
                        'id': robot.id,
                        'position': robot.position,
                        'health': robot.health,
                        'armor': robot.armor,
                        'role': robot.role,
                        'team': robot.team
                    })
        return enemies

    def get_teammates_in_range(self, position: Vector2D, range_radius: float) -> List[Dict]:
        """Return list of teammate robots within range."""
        teammates = []
        robot_team = self.get_team_by_robot_id(self.get_robot_by_position(position).id)
        for robot in self.robots:
            if robot.team == robot_team and robot.is_alive:
                distance = position.distance_to(robot.position)
                if distance <= range_radius:
                    teammates.append({
                        'id': robot.id,
                        'position': robot.position,
                        'health': robot.health,
                        'armor': robot.armor,
                        'role': robot.role
                    })
        return teammates

    def get_powerups_in_range(self, position: Vector2D, range_radius: float) -> List[Dict]:
        """Return list of active power-ups within range."""
        powerups = []
        for pu in self.powerups:
            if pu.active:
                distance = position.distance_to(pu.position)
                if distance <= range_radius:
                    powerups.append({
                        'type': pu.type,
                        'position': pu.position,
                        'id': pu.spawn_time  # unique identifier
                    })
        return powerups

    def get_active_objectives(self) -> List[Dict]:
        """Return list of active objectives."""
        return [
            {
                'id': obj.id,
                'type': obj.type,
                'position': obj.position,
                'team': obj.team,
                'progress': obj.progress,
                'completed': obj.completed
            }
            for obj in self.objectives if not obj.completed
        ]

    def get_robot_by_id(self, robot_id: str) -> Optional[Robot]:
        """Find robot by ID."""
        for robot in self.robots:
            if robot.id == robot_id:
                return robot
        return None

    def get_robot_by_position(self, position: Vector2D) -> Optional[Robot]:
        """Find robot by position (approximate)."""
        for robot in self.robots:
            if robot.is_alive and robot.position.distance_to(position) < 1.0:
                return robot
        return None

    def get_team_by_robot_id(self, robot_id: str) -> int:
        """Determine team by robot ID."""
        robot = self.get_robot_by_id(robot_id)
        return robot.team if robot else -1

    def add_visual_effect(self, effect_type: str, position: Vector2D, duration: float = VISUAL_EFFECT_DURATION):
        """Add a visual effect (e.g., explosion, glow)."""
        self.visual_effects.append({
            'type': effect_type,
            'position': position,
            'start_time': time.time(),
            'duration': duration
        })

    def add_audio_effect(self, effect_name: str):
        """Add audio effect to queue."""
        self.audio_queue.append(effect_name)

    def update_game_state(self, dt: float):
        """Update the entire game state."""
        self.game_time += dt

        # Update robots
        for robot in self.robots:
            if not robot.is_alive:
                continue

            # Update power-ups
            robot.update_power_ups()

            # Regenerate health
            if robot.health < DEFAULT_HEALTH:
                robot.health += REGEN_RATE * dt
                robot.health = min(robot.health, DEFAULT_HEALTH)

            # Check for environmental hazards
            for hazard in self.hazards:
                if hazard.active and hazard.position.distance_to(robot.position) <= hazard.radius:
                    damage = hazard.damage_per_tick * dt
                    robot.take_damage(damage)
                    if robot.audio_feedback:
                        self.add_audio_effect(AUDIO_EFFECTS['hit'])
                    if robot.health <= 0:
                        robot.is_alive = False
                        self.add_visual_effect('explosion', robot.position)
                        self.add_audio_effect(AUDIO_EFFECTS['death'])
                        # Log death for scoring
                        self.team_performance[robot.team] = max(0, self.team_performance[robot.team] - 0.05)
                        break

            # Update weapon cooldowns
            if robot.weapon.cooldown > 0:
                robot.weapon.cooldown -= dt

            # AI decision-making
            if self.state == GameState.RUNNING:
                action = robot.decide_action(self)
                self.execute_action(robot, action)

        # Update objectives
        for objective in self.objectives:
            if objective.completed:
                continue

            # Check for capture progress
            if objective.type == ObjectiveType.CAPTURE_THE_FLAG:
                robots_in_range = 0
                for robot in self.robots:
                    if (robot.is_alive and 
                        robot.team == objective.team and
                        robot.position.distance_to(objective.position) <= objective.capture_radius):
                        robots_in_range += 1

                if robots_in_range >= objective.required_robots:
                    objective.progress = min(1.0, objective.progress + dt / 20.0)  # slower capture
                    if objective.progress >= 1.0:
                        objective.completed = True
                        objective.team = self.get_team_by_robot_id(self.robots[0].id)  # placeholder
                        self.add_audio_effect(AUDIO_EFFECTS['capture'])
                        self.add_visual_effect('capture', objective.position)
                        self.team_performance[objective.team] = min(1.0, self.team_performance[objective.team] + 0.1)
                        self.teams[objective.team].score += 10
                        self.add_audio_effect(AUDIO_EFFECTS['team_score'])

                        # Create new objective
                        new_obj = Objective(
                            id=f"flag_{len(self.objectives)}",
                            type=ObjectiveType.CAPTURE_THE_FLAG,
                            position=Vector2D(random.uniform(10, MAP_SIZE[0]-10), random.uniform(10, MAP_SIZE[1]-10)),
                            team=None,
                            progress=0.0
                        )
                        self.objectives.append(new_obj)

            # Update objective timer
            objective.last_updated = self.game_time

        # Update power-ups
        current_time = time.time()
        for pu in self.powerups[:]:
            if not pu.active:
                continue
            if current_time - pu.spawn_time > pu.duration:
                pu.active = False
                continue

            # Check if robot is in range to collect
            for robot in self.robots:
                if robot.is_alive and robot.position.distance_to(pu.position) <= 1.5:
                    robot.add_power_up(pu.type, pu.duration)
                    pu.active = False
                    self.add_audio_effect(AUDIO_EFFECTS['powerup'])
                    self.add_visual_effect('powerup', pu.position)
                    break

        # Update visual effects
        self.visual_effects = [
            effect for effect in self.visual_effects
            if time.time() - effect['start_time'] < effect['duration']
        ]

        # Update difficulty based on team performance
        self.update_difficulty()

        # Check win conditions
        self.check_win_conditions()

    def update_difficulty(self):
        """Adjust difficulty based on team performance."""
        if len(self.team_performance) == 0:
            return

        avg_performance = sum(self.team_performance.values()) / len(self.team_performance)

        # Difficulty scales with average performance
        if avg_performance > 0.7 and self.difficulty_level < 5:
            self.difficulty_level += 1
        elif avg_performance < 0.3 and self.difficulty_level > 1:
            self.difficulty_level -= 1

        # Apply difficulty multiplier to AI behavior
        # Higher difficulty makes AI more aggressive and accurate
        pass

    def execute_action(self, robot: Robot, action: Dict):
        """Execute the action decided by the AI."""
        action_type = action.get('action', 'idle')
        robot.last_action = action_type
        robot.last_action_time = time.time()

        if action_type == "fire":
            if robot.weapon.can_fire():
                weapon_data = robot.weapon.fire()
                weapon_data['source'] = robot.id
                # Simulate hit detection (simplified)
                for target_robot in self.robots:
                    if (target_robot.team != robot.team and 
                        target_robot.is_alive and 
                        target_robot.position.distance_to(robot.position) <= weapon_data['range']):
                        damage = weapon_data['damage']
                        # Apply splash damage if applicable
                        if weapon_data.get('splash', 0) > 0:
                            if target_robot.position.distance_to(robot.position) <= weapon_data['splash']:
                                damage *= 0.5  # reduced splash damage
                        target_robot.take_damage(damage)
                        self.add_audio_effect(AUDIO_EFFECTS['shoot'])
                        self.add_visual_effect('bullet_impact', target_robot.position)
                        if not target_robot.is_alive:
                            self.add_audio_effect(AUDIO_EFFECTS['death'])
                            self.add_visual_effect('explosion', target_robot.position)
                            self.team_performance[robot.team] = min(1.0, self.team_performance[robot.team] + 0.02)
                            self.team_performance[target_robot.team] = max(0, self.team_performance[target_robot.team] - 0.03)
                        break
                # Reload if needed
                if robot.weapon.ammo <= 5:
                    robot.weapon.reload()

        elif action_type == "reload":
            robot.weapon.reload()

        elif action_type == "move":
            if 'target' in action:
                target = action['target']
                if isinstance(target, Vector2D):
                    direction = (target - robot.position).normalize()
                    move_amount = robot.speed * 0.1  # adjusted for 60fps
                    robot.position = robot.position + direction * move_amount
                    # Keep robot within bounds
                    robot.position.x = max(0, min(robot.position.x, MAP_SIZE[0]))
                    robot.position.y = max(0, min(robot.position.y, MAP_SIZE[1]))

        elif action_type == "melee_attack":
            target_id = action.get('target')
            target_robot = self.get_robot_by_id(target_id)
            if target_robot and target_robot.team != robot.team and target_robot.is_alive:
                distance = robot.position.distance_to(target_robot.position)
                if distance <= MELEE_RANGE:
                    damage = robot.weapon.damage * 1.5  # melee bonus
                    target_robot.take_damage(damage)
                    self.add_audio_effect(AUDIO_EFFECTS['hit'])
                    self.add_visual_effect('melee_impact', target_robot.position)
                    if not target_robot.is_alive:
                        self.add_audio_effect(AUDIO_EFFECTS['death'])
                        self.add_visual_effect('explosion', target_robot.position)
                        self.team_performance[robot.team] = min(1.0, self.team_performance[robot.team] + 0.02)
                        self.team_performance[target_robot.team] = max(0, self.team_performance[target_robot.team] - 0.03)

        elif action_type == "capture":
            obj_id = action.get('target')
            objective = next((obj for obj in self.objectives if obj.id == obj_id), None)
            if objective and objective.team != robot.team:
                # This is handled in update_game_state via proximity
                pass

        elif action_type == "retreat":
            if 'target' in action:
                robot.position = action['target']
                # Keep within bounds
                robot.position.x = max(0, min(robot.position.x, MAP_SIZE[0]))
                robot.position.y = max(0, min(robot.position.y, MAP_SIZE[1]))

        elif action_type == "use_powerup":
            # Find the first active power-up to use
            for power_type, expiry in robot.power_ups.items():
                if time.time() < expiry:
                    # Already applied on pickup, no need to reapply
                    break

        elif action_type == "communicate":
            # Simulate team communication - could be expanded for complex coordination
            pass

    def check_win_conditions(self):
        """Check if the game has been won."""
        if self.state != GameState.RUNNING:
            return

        alive_teams = set()
        for robot in self.robots:
            if robot.is_alive:
                alive_teams.add(robot.team)

        if len(alive_teams) <= 1:
            # Game ended
            self.state = GameState.ENDED
            if len(alive_teams) == 1:
                self.winner = list(alive_teams)[0]
            return

        # Check time-based win condition
        if self.game_time >= 300:  # 5 minutes
            self.state = GameState.ENDED
            # Winner is team with highest score
            max_score = -1
            for team_id, team in self.teams.items():
                if team.score > max_score:
                    max_score = team.score
                    self.winner = team_id

class CyberArena:
    """Main CyberArena class that orchestrates the entire simulation."""

    def __init__(self, num_teams: int = 2, robots_per_team: int = 3, objective_type: ObjectiveType = ObjectiveType.CAPTURE_THE_FLAG):
        self.num_teams = min(num_teams, MAX_TEAMS)
        self.robots_per_team = min(robots_per_team, MAX_ROBOTS_PER_TEAM)
        self.objective_type = objective_type

        # Initialize game state
        self.state = GameState(
            map_size=MAP_SIZE,
            teams={},
            robots=[],
            powerups=[],
            hazards=[],
            objectives=[],
            game_time=0.0,
            state=GameState.PREPARING,
            team_performance={}
        )

        # Create teams
        for i in range(self.num_teams):
            team_name = f"Team {chr(65 + i)}"
            base_x = random.uniform(10, MAP_SIZE[0] - 10)
            base_y = random.uniform(10, MAP_SIZE[1] - 10)
            team = Team(
                id=i,
                name=team_name,
                base=Vector2D(base_x, base_y),
                score=0,
                robots=[]
            )
            self.state.teams[i] = team

        # Create robots
        robot_id = 0
        for team_id, team in self.state.teams.items():
            for _ in range(self.robots_per_team):
                # Random position near base
                offset_x = random.uniform(-5, 5)
                offset_y = random.uniform(-5, 5)
                position = Vector2D(
                    team.base.x + offset_x,
                    team.base.y + offset_y
                )

                # Random role assignment
                role = random.choice(list(RobotRole))

                # Random weapon
                weapon_choices = [
                    Weapon("Pulse Rifle", WeaponType.RANGED, 15, 20, 0.5, 30, 60),
                    Weapon("Plasma Cannon", WeaponType.HEAVY, 40, 15, 1.5, 8, 16, 3.0, 4.0),
                    Weapon("Sword", WeaponType.MELEE, 25, 2, 1.0, 0, 0),
                    Weapon("Healing Beam", WeaponType.SUPPORT, 0, 15, 0.8, 20, 40, 2.0)
                ]
                weapon = random.choice(weapon_choices)

                robot = Robot(
                    id=f"robot_{robot_id}",
                    team=team_id,
                    position=position,
                    role=role,
                    weapon=weapon,
                    audio_feedback=True
                )
                team.robots.append(robot)
                self.state.robots.append(robot)
                robot_id += 1

        # Create objectives based on type
        self.create_objectives()

        # Create power-ups
        self.create_powerups()

        # Create hazards
        self.create_hazards()

        # Initialize AI learning system
        self.last_ai_update = time.time()
        self.state.state = GameState.PREPARING

    def create_objectives(self):
        """Create objectives based on type."""
        if self.objective_type == ObjectiveType.CAPTURE_THE_FLAG:
            # Create two flags, one for each team
            for team_id in self.state.teams.keys():
                # Place flag near base but not exactly on it
                base = self.state.teams[team_id].base
                flag_pos = Vector2D(base.x + random.uniform(5, 10), base.y + random.uniform(5, 10))
                objective = Objective(
                    id=f"flag_{team_id}",
                    type=ObjectiveType.CAPTURE_THE_FLAG,
                    position=flag_pos,
                    team=team_id,
                    required_robots=1,
                    capture_radius=5.0
                )
                self.state.objectives.append(objective)

        elif self.objective_type == ObjectiveType.ESCAPE_PAYLOAD:
            # Create a payload to escort
            payload_pos = Vector2D(MAP_SIZE[0] / 2, MAP_SIZE[1] / 2)
            objective = Objective(
                id="payload_0",
                type=ObjectiveType.ESCAPE_PAYLOAD,
                position=payload_pos,
                team=None,
                required_robots=2
            )
            self.state.objectives.append(objective)

        elif self.objective_type == ObjectiveType.CONTROL_POINTS:
            # Create 3 control points around the map
            for i in range(3):
                x = random.uniform(15, MAP_SIZE[0] - 15)
                y = random.uniform(15, MAP_SIZE[1] - 15)
                objective = Objective(
                    id=f"control_{i}",
                    type=ObjectiveType.CONTROL_POINTS,
                    position=Vector2D(x, y),
                    team=None,
                    required_robots=1,
                    capture_radius=7.0
