    def add_power_up(self, power_type: PowerUpType, duration: float = POWER_UP_DURATION):
        """Apply a power-up effect with specified duration."""
        self.power_ups[power_type] = time.time() + duration
        if power_type == PowerUpType.SPEED_BOOST:
            self.speed *= 1.5
        elif power_type == PowerUpType.DAMAGE_BOOST:
            self.weapon.damage *= 1.5
        elif power_type == PowerUpType.SHIELD:
