@dataclass
class Vector2D:
    x: float = 0.0
    y: float = 0.0

    def __add__(self, other):
        return Vector2D(self.x + other.x, self.y + other.y)

    def __sub__(self, other):
        return Vector2D(self.x - other.x, self.y - other.y)

    def __mul__(self, scalar):
        return Vector2D(self.x * scalar, self.y * scalar)

    def __truediv__(self, scalar):
        return Vector2D(self.x / scalar, self.y / scalar)

    def length(self) -> float:
        return math.sqrt(self.x**2 + self.y**2)

    def normalize(self):
        length = self.length()
        if length == 0:
            return Vector2D(0, 0)
        return self / length

    def distance_to(self, other):
        return (self - other).length()

    def to_tuple(self):
        return (self.x, self.y)

@dataclass
class Weapon:
    name: str
    type: WeaponType
    damage: float
    range: float
    fire_rate: float  # seconds between shots
    ammo: int
    max_ammo: int
    reload_time: float = 2.0
    splash_radius: float = 0.0  # for explosive weapons
    cooldown: float = 0.0

    def can_fire(self) -> bool:
        return self.cooldown <= 0 and self.ammo > 0

    def fire(self) -> Dict:
        if not self.can_fire():
            return {}
        self.ammo -= 1
        self.cooldown = self.fire_rate
        return {
            'damage': self.damage,
            'range': self.range,
            'type': self.type,
            'splash': self.splash_radius,
            'source': None  # to be set by robot
        }

    def reload(self):
        self.ammo = min(self.ammo + 5, self.max_ammo)
        return self.ammo

@dataclass
class Robot:
    id: str
    team: int
    position: Vector2D
    health: float = DEFAULT_HEALTH
    armor: float = DEFAULT_ARMOR
    speed: float = DEFAULT_SPEED
    role: RobotRole = RobotRole.ATTACKER
    weapon: Weapon = None
    inventory: List[Weapon] = field(default_factory=list)
    objectives: List[str] = field(default_factory=list)
    last_seen_enemies: List[Dict] = field(default_factory=list)
    last_action: str = ""
    last_action_time: float = 0.0
    power_ups: Dict[PowerUpType, float] = field(default_factory=dict)  # type -> expiry_time
    is_alive: bool = True
    last_update_time: float = 0.0
    vision_range: float = 15.0
    audio_feedback: bool = True
    strategy_memory: Dict = field(default_factory=dict)

    def __post_init__(self):
        if not self.weapon:
            self.weapon = Weapon(
                name="Pulse Rifle",
                type=WeaponType.RANGED,
                damage=15.0,
                range=20.0,
                fire_rate=0.5,
                ammo=30,
                max_ammo=60
            )
        self.inventory.append(self.weapon)

    def add_power_up(self, power_type: PowerUpType, duration: float = POWER_UP_DURATION):
        """Apply a power-up effect with specified duration."""
        self.power_ups[power_type] = time.time() + duration
        if power_type == PowerUpType.SPEED_BOOST:
            self.speed *= 1.5
        elif power_type == PowerUpType.DAMAGE_BOOST:
            self.weapon.damage *= 1.5
        elif power_type == PowerUpType.SHIELD:
            self.armor += 50
        elif power_type == PowerUpType.REGEN:
            global REGEN_RATE
            REGEN_RATE += 0.2
        elif power_type == PowerUpType.SILENCE:
            # Silence enemy communication (simulated in AI)
            pass
        elif power_type == PowerUpType.TELEPORT:
            # Teleport to random safe location (implementation in update)
            pass

    def is_power_up_active(self, power_type: PowerUpType) -> bool:
        if power_type not in self.power_ups:
            return False
        return time.time() < self.power_ups[power_type]

    def update_power_ups(self):
        """Remove expired power-ups and revert effects."""
        current_time = time.time()
        expired = []
        for power_type, expiry_time in self.power_ups.items():
            if current_time > expiry_time:
                expired.append(power_type)
                # Revert effects
                if power_type == PowerUpType.SPEED_BOOST:
                    self.speed /= 1.5
                elif power_type == PowerUpType.DAMAGE_BOOST:
                    self.weapon.damage /= 1.5
                elif power_type == PowerUpType.SHIELD:
                    self.armor -= 50
                    self.armor = max(0, self.armor)
                elif power_type == PowerUpType.REGEN:
                    global REGEN_RATE
                    REGEN_RATE -= 0.2
                    REGEN_RATE = max(0.1, REGEN_RATE)

        for p in expired:
            del self.power_ups[p]

    def take_damage(self, damage: float) -> float:
        """Apply damage with armor reduction."""
        if self.armor > 0:
            armor_absorbed = min(damage, self.armor)
            self.armor -= armor_absorbed
            damage -= armor_absorbed

        self.health -= damage
        if self.health <= 0:
            self.is_alive = False
            self.health = 0
            return 0  # full damage applied, robot dead
        return damage

    def heal(self, amount: float):
        """Heal robot up to max health."""
        self.health = min(self.health + amount, DEFAULT_HEALTH)

    def can_see(self, target_position: Vector2D, obstacles: List[Tuple[Vector2D, Vector2D]]) -> bool:
        """Simple line-of-sight check (ignores complex geometry for performance)."""
        # For simplicity, assume no obstacles in this implementation
        # In a real system, we'd use ray-tracing or pathfinding
        distance = self.position.distance_to(target_position)
        return distance <= self.vision_range

    def get_available_actions(self, game_state: 'CyberArena') -> List[str]:
        """Return list of possible actions based on current state."""
        actions = []

        # Movement
        actions.append("move")

        # Combat
        if self.weapon.can_fire():
            actions.append("fire")

        # Reload
        if self.weapon.ammo < self.weapon.max_ammo:
            actions.append("reload")

        # Use power-up
        if any(self.power_ups.values()):
            actions.append("use_powerup")

        # Objectives
        if self.objectives:
            actions.append("complete_objective")

        # Team communication
        actions.append("communicate")

        return actions

    def decide_action(self, game_state: 'CyberArena') -> Dict:
        """
        AI decision-making using a simple state machine with memory and adaptive learning.
        This is the core of the adaptive difficulty system.
        """
        current_time = time.time()

        # Update strategy memory based on recent performance
        if current_time - self.last_update_time > 2.0:
            self.update_strategy_memory(game_state)
            self.last_update_time = current_time

        # Check for immediate threats
        enemies = game_state.get_enemies_in_range(self.position, self.vision_range)

        if enemies:
            closest_enemy = min(enemies, key=lambda e: self.position.distance_to(e['position']))
            distance = self.position.distance_to(closest_enemy['position'])

            # Adaptive behavior based on difficulty and team performance
            difficulty_multiplier = game_state.get_difficulty_multiplier()

            # If low on health, prioritize retreat or healing
            if self.health < 30 and distance < 10:
                return {"action": "retreat", "target": self.position + Vector2D(random.uniform(-5,5), random.uniform(-5,5))}

            # If high damage and close, melee
            if distance <= MELEE_RANGE and self.weapon.type == WeaponType.MELEE:
                return {"action": "melee_attack", "target": closest_enemy['id']}

            # If ranged weapon and in range, shoot
            if distance <= self.weapon.range and self.weapon.can_fire():
                return {"action": "fire", "target": closest_enemy['id']}

            # Otherwise, move toward enemy
            if distance > self.weapon.range:
                return {"action": "move", "target": closest_enemy['position']}

        # Check if objectives are within range
        objectives = game_state.get_active_objectives()
        for obj in objectives:
            if self.position.distance_to(obj['position']) < 8.0:
                if obj['type'] == ObjectiveType.CAPTURE_THE_FLAG and obj['team'] != self.team:
                    return {"action": "capture", "target": obj['id']}

        # Check for power-ups
        powerups = game_state.get_powerups_in_range(self.position, 10.0)
        if powerups:
            closest_powerup = min(powerups, key=lambda p: self.position.distance_to(p['position']))
            return {"action": "move", "target": closest_powerup['position']}

        # Default behavior: patrol or explore
        if random.random() < 0.3:
            # Random movement pattern based on role
            if self.role == RobotRole.SCATTER:
                target = self.position + Vector2D(random.uniform(-10,10), random.uniform(-10,10))
            elif self.role == RobotRole.DEFENDER:
                target = game_state.teams[self.team]['base']
            elif self.role == RobotRole.SUPPORT:
                # Find teammate with low health
                teammates = game_state.get_teammates_in_range(self.position, 15.0)
                if teammates:
                    weakest = min(teammates, key=lambda t: t['health'])
                    target = weakest['position']
                else:
                    target = game_state.teams[self.team]['base']
            else:
                target = self.position + Vector2D(random.uniform(-5,5), random.uniform(-5,5))
            return {"action": "move", "target": target}

        # Default: stay and reload if needed
        if self.weapon.ammo < 10 and self.weapon.ammo < self.weapon.max_ammo:
            return {"action": "reload"}

        return {"action": "idle"}

    def update_strategy_memory(self, game_state: 'CyberArena'):
        """Update memory with recent performance data for learning."""
        # Track recent actions and outcomes
        if 'action_history' not in self.strategy_memory:
            self.strategy_memory['action_history'] = deque(maxlen=20)

        # Record the last action and its success
        recent_outcome = {
            'time': time.time(),
            'action': self.last_action,
            'team_performance': game_state.get_team_performance(self.team),
            'survival_time': time.time() - self.last_update_time
        }
        self.strategy_memory['action_history'].append(recent_outcome)

        # Adjust behavior based on success rate
        if len(self.strategy_memory['action_history']) >= 5:
            successful_actions = sum(1 for a in self.strategy_memory['action_history'] 
                                   if a['team_performance'] > 0.5)
            if successful_actions / len(self.strategy_memory['action_history']) < 0.3:
