@dataclass
class GameState:
    map_size: Tuple[int, int]
    teams: Dict[int, Team]
    robots: List[Robot]
    powerups: List[PowerUp]
    hazards: List[Hazard]
    objectives: List[Objective]
    game_time: float = 0.0
    state: GameState = GameState.PREPARING
    winner: Optional[int] = None
    difficulty_level: int = 1  # 1-5 scale
    team_performance: Dict[int, float] = field(default_factory=dict)  # team_id -> performance score (0.0-1.0)
    last_ai_update: float = 0.0
    visual_effects: List[Dict] = field(default_factory=list)  # for rendering
    audio_queue: List[str] = field(default_factory=list)  # for audio feedback

    def __post_init__(self):
        if not self.team_performance:
            for team_id in self.teams:
                self.team_performance[team_id] = 0.5  # neutral starting performance

    def get_team_performance(self, team_id: int) -> float:
        return self.team_performance.get(team_id, 0.5)

    def get_difficulty_multiplier(self) -> float:
        """Adjust AI difficulty based on average team performance."""
        if len(self.team_performance) == 0:
            return 1.0
        avg_performance = sum(self.team_performance.values()) / len(self.team_performance)
        # Higher performance -> harder AI
        # Normalize to 0.5-1.5 range
        return max(0.5, min(1.5, 1.0 + (avg_performance - 0.5) * 1.0))

    def get_enemies_in_range(self, position: Vector2D, range_radius: float) -> List[Dict]:
        """Return list of enemy robots within range."""
        enemies = []
        for robot in self.robots:
            if robot.team != self.get_team_by_robot_id(robot.id) and robot.is_alive:
                distance = position.distance_to(robot.position)
                if distance <= range_radius:
                    enemies.append({
                        'id': robot.id,
                        'position': robot.position,
                        'health': robot.health,
                        'armor': robot.armor,
                        'role': robot.role,
                        'team': robot.team
                    })
        return enemies

    def get_teammates_in_range(self, position: Vector2D, range_radius: float) -> List[Dict]:
        """Return list of teammate robots within range."""
        teammates = []
        robot_team = self.get_team_by_robot_id(self.get_robot_by_position(position).id)
        for robot in self.robots:
            if robot.team == robot_team and robot.is_alive:
                distance = position.distance_to(robot.position)
                if distance <= range_radius:
                    teammates.append({
                        'id': robot.id,
                        'position': robot.position,
                        'health': robot.health,
                        'armor': robot.armor,
                        'role': robot.role
                    })
        return teammates

    def get_powerups_in_range(self, position: Vector2D, range_radius: float) -> List[Dict]:
        """Return list of active power-ups within range."""
        powerups = []
        for pu in self.powerups:
            if pu.active:
                distance = position.distance_to(pu.position)
                if distance <= range_radius:
                    powerups.append({
                        'type': pu.type,
                        'position': pu.position,
                        'id': pu.spawn_time  # unique identifier
                    })
        return powerups

    def get_active_objectives(self) -> List[Dict]:
        """Return list of active objectives."""
        return [
            {
                'id': obj.id,
                'type': obj.type,
                'position': obj.position,
                'team': obj.team,
                'progress': obj.progress,
                'completed': obj.completed
            }
            for obj in self.objectives if not obj.completed
        ]

    def get_robot_by_id(self, robot_id: str) -> Optional[Robot]:
        """Find robot by ID."""
        for robot in self.robots:
            if robot.id == robot_id:
                return robot
        return None

    def get_robot_by_position(self, position: Vector2D) -> Optional[Robot]:
        """Find robot by position (approximate)."""
        for robot in self.robots:
            if robot.is_alive and robot.position.distance_to(position) < 1.0:
                return robot
        return None

    def get_team_by_robot_id(self, robot_id: str) -> int:
        """Determine team by robot ID."""
        robot = self.get_robot_by_id(robot_id)
        return robot.team if robot else -1

    def add_visual_effect(self, effect_type: str, position: Vector2D, duration: float = VISUAL_EFFECT_DURATION):
        """Add a visual effect (e.g., explosion, glow)."""
        self.visual_effects.append({
            'type': effect_type,
            'position': position,
            'start_time': time.time(),
            'duration': duration
        })

    def add_audio_effect(self, effect_name: str):
        """Add audio effect to queue."""
        self.audio_queue.append(effect_name)

    def update_game_state(self, dt: float):
        """Update the entire game state."""
        self.game_time += dt

        # Update robots
        for robot in self.robots:
            if not robot.is_alive:
                continue

            # Update power-ups
            robot.update_power_ups()

            # Regenerate health
            if robot.health < DEFAULT_HEALTH:
                robot.health += REGEN_RATE * dt
                robot.health = min(robot.health, DEFAULT_HEALTH)

            # Check for environmental hazards
            for hazard in self.hazards:
                if hazard.active and hazard.position.distance_to(robot.position) <= hazard.radius:
                    damage = hazard.damage_per_tick * dt
                    robot.take_damage(damage)
                    if robot.audio_feedback:
                        self.add_audio_effect(AUDIO_EFFECTS['hit'])
                    if robot.health <= 0:
                        robot.is_alive = False
                        self.add_visual_effect('explosion', robot.position)
                        self.add_audio_effect(AUDIO_EFFECTS['death'])
                        # Log death for scoring
                        self.team_performance[robot.team] = max(0, self.team_performance[robot.team] - 0.05)
                        break

            # Update weapon cooldowns
            if robot.weapon.cooldown > 0:
                robot.weapon.cooldown -= dt

            # AI decision-making
            if self.state == GameState.RUNNING:
                action = robot.decide_action(self)
                self.execute_action(robot, action)

        # Update objectives
        for objective in self.objectives:
            if objective.completed:
