import threading
import time
from datetime import datetime, timedelta
from enum import Enum
from typing import List, Dict, Optional, Set, Tuple, Any
from collections import defaultdict, deque
import heapq

# ===============================
# CONFIGURATION AND GLOBAL SETTINGS
# ===============================

NOTIFICATION_DELAY_MINUTES = 30  # Notify 30 minutes before task start if dependent tasks are done

# ===============================
# ENUMS
# ===============================

class TaskStatus(Enum):
    NOT_STARTED = "not started"
    IN_PROGRESS = "in progress"
    COMPLETED = "completed"
    DELAYED = "delayed"
    AT_RISK = "at risk"

class Priority(Enum):
    LOW = "low"
    MEDIUM = "medium"
    HIGH = "high"

# ===============================
# DATA CLASSES
# ===============================

@dataclass
class Task:
    id: str
    title: str
    description: str = ""
    status: TaskStatus = TaskStatus.NOT_STARTED
    start_time: Optional[datetime] = None
    end_time: Optional[datetime] = None
    due_date: Optional[datetime] = None
    priority: Priority = Priority.MEDIUM
    assigned_to: List[str] = field(default_factory=list)
    comments: List[Dict[str, Any]] = field(default_factory=list)
    dependencies: Set[str] = field(default_factory=set)  # task_ids that must be completed before this one
    dependents: Set[str] = field(default_factory=set)   # task_ids that depend on this one

    def add_comment(self, user: str, text: str):
        self.comments.append({
            "user": user,
            "text": text,
            "timestamp": datetime.now().isoformat()
        })

    def update_status(self, status: TaskStatus, user: str):
        self.status = status
        if status == TaskStatus.IN_PROGRESS and not self.start_time:
            self.start_time = datetime.now()
        elif status == TaskStatus.COMPLETED and not self.end_time:
            self.end_time = datetime.now()
        # Add comment for status change
        self.add_comment(user, f"Status changed to {status.value}")

    def is_ready_to_start(self, completed_tasks: Set[str]) -> bool:
        return all(dep in completed_tasks for dep in self.dependencies)

    def to_dict(self):
        return {
            "id": self.id,
            "title": self.title,
            "description": self.description,
            "status": self.status.value,
            "start_time": self.start_time.isoformat() if self.start_time else None,
            "end_time": self.end_time.isoformat() if self.end_time else None,
            "due_date": self.due_date.isoformat() if self.due_date else None,
            "priority": self.priority.value,
            "assigned_to": self.assigned_to,
            "comments": self.comments,
            "dependencies": list(self.dependencies),
            "dependents": list(self.dependents)
        }

    @classmethod
    def from_dict(cls, data):
        task = cls(
            id=data["id"],
            title=data["title"],
            description=data.get("description", ""),
            status=TaskStatus(data["status"]),
            start_time=datetime.fromisoformat(data["start_time"]) if data["start_time"] else None,
            end_time=datetime.fromisoformat(data["end_time"]) if data["end_time"] else None,
            due_date=datetime.fromisoformat(data["due_date"]) if data["due_date"] else None,
            priority=Priority(data["priority"]),
            assigned_to=data.get("assigned_to", []),
            comments=data.get("comments", []),
            dependencies=set(data.get("dependencies", [])),
            dependents=set(data.get("dependents", []))
        )
        return task

# ===============================
# CORE SYSTEM CLASSES
# ===============================

class DependencyManager:
    def __init__(self):
        self.tasks: Dict[str, Task] = {}
        self.dependency_graph: Dict[str, Set[str]] = defaultdict(set)  # task -> prerequisites
        self.reverse_graph: Dict[str, Set[str]] = defaultdict(set)     # task -> dependents
        self.completed_tasks: Set[str] = set()
        self.ready_tasks: Set[str] = set()  # tasks ready to start
        self.lock = threading.RLock()

    def add_task(self, task: Task):
        with self.lock:
            self.tasks[task.id] = task
            for dep_id in task.dependencies:
                self.dependency_graph[task.id].add(dep_id)
                self.reverse_graph[dep_id].add(task.id)
                if dep_id not in self.tasks:
                    raise ValueError(f"Dependency task {dep_id} does not exist.")
            # Update dependents of dependencies
            for dep_id in task.dependencies:
                self.tasks[dep_id].dependents.add(task.id)

            # Check if task is ready to start
            if task.is_ready_to_start(self.completed_tasks):
                self.ready_tasks.add(task.id)

    def remove_task(self, task_id: str):
        with self.lock:
            if task_id not in self.tasks:
                return
            # Remove from dependency graph
            for dep_id in self.dependency_graph[task_id]:
                self.reverse_graph[dep_id].discard(task_id)
            for dep_id in self.reverse_graph[task_id]:
                self.dependency_graph[dep_id].discard(task_id)
                self.tasks[dep_id].dependencies.discard(task_id)
            # Remove task
            del self.tasks[task_id]
            self.completed_tasks.discard(task_id)
            self.ready_tasks.discard(task_id)

    def complete_task(self, task_id: str, user: str):
        with self.lock:
            if task_id not in self.tasks:
                return False
            if task_id in self.completed_tasks:
                return False
            self.completed_tasks.add(task_id)
            self.ready_tasks.discard(task_id)
            self.tasks[task_id].update_status(TaskStatus.COMPLETED, user)

            # Check if any dependent tasks are now ready
            for dependent_id in self.reverse_graph[task_id]:
                if dependent_id not in self.completed_tasks:
                    if self.tasks[dependent_id].is_ready_to_start(self.completed_tasks):
                        self.ready_tasks.add(dependent_id)
                        self.tasks[dependent_id].update_status(TaskStatus.NOT_STARTED, user)  # Reset to not started if not yet started
            return True

    def get_ready_tasks(self) -> List[Task]:
        with self.lock:
            return [self.tasks[tid] for tid in self.ready_tasks if tid in self.tasks]

    def get_blocked_tasks(self) -> List[Task]:
        with self.lock:
            blocked = []
            for task_id, task in self.tasks.items():
                if task.status != TaskStatus.COMPLETED and not task.is_ready_to_start(self.completed_tasks):
                    blocked.append(task)
            return blocked

    def get_project_dependencies(self) -> Dict[str, List[str]]:
        with self.lock:
            return {tid: list(deps) for tid, deps in self.dependency_graph.items()}

    def get_task_by_id(self, task_id: str) -> Optional[Task]:
        with self.lock:
            return self.tasks.get(task_id)

    def get_all_tasks(self) -> List[Task]:
