    def update(self, dt: float):
        """Update environment state"""
        self.game_time += dt
        self.last_update = time.time()

        # Update robots
        for robot in self.robots:
            if robot.is_alive:
                robot.update(dt, self)

        # Update powerups
        for powerup in self.powerups[:]:
            powerup.update(dt)
            if not powerup.active:
                self.powerups.remove(powerup)

        # Update hazards
        for hazard in self.hazards[:]:
            hazard.update(dt)
            # Check if robot is in hazard zone
            for robot in self.robots:
                if robot.is_alive and robot.position.distance_to(hazard.position) < hazard.radius:
                    robot.take_damage(hazard.damage_per_second * dt, -1)  # Damage from environment

