        # Check for game end conditions
        self._check_game_end()

        # Update adaptive difficulty based on performance
        self._update_adaptive_difficulty()

    def _update_objectives(self):
        """Update objective progress based on robot positions and actions"""
        if self.current_objective == ObjectiveType.CAPTURE_FLAG:
            # Flag is at center; robots can capture it
            flag_pos = self.get_objective_position()
            for robot in self.robots:
                if robot.position.distance_to(flag_pos) < 60:
                    # Robot is at flag
                    if robot.team == 0:
                        self.objective_progress['flag_captured'] = True
                        self.team_scores[0] += 1
                    else:
                        self.objective_progress['flag_captured'] = True
                        self.team_scores[1] += 1

        elif self.current_objective == ObjectiveType.DEFEND_BASE:
            # Base at spawn points; if enemy is near, defend it
            for team_id in [0, 1]:
                base_pos = self.spawn_points[team_id]
                enemy_nearby = False
                for robot in self.robots:
                    if robot.team != team_id and robot.is_alive:
                        if robot.position.distance_to(base_pos) < 100:
                            enemy_nearby = True
                            break

                if not enemy_nearby:
                    self.team_objectives[team_id]['defended_bases'] = self.team_objectives[team_id].get('defended_bases', 0) + 0.1 * dt
                    if self.team_objectives[team_id]['defended_bases'] >= 1:
                        self.team_scores[team_id] += 1
                        self.team_objectives[team_id]['defended_bases'] = 0

        elif self.current_objective == ObjectiveType.ESCAPE_PAYLOAD:
            # Payload moves toward enemy base
            payload_pos = self.get_objective_position()
            payload_distance = min(self.width, self.height)  # Max distance
            self.objective_progress['payload_distance'] = payload_distance

            # Check if payload reached enemy base
            for team_id in [0, 1]:
                enemy_base = self.spawn_points[1 - team_id]
                if payload_pos.distance_to(enemy_base) < 50:
                    self.team_scores[team_id] += 10
                    self.objective_progress['payload_distance'] = 0

        elif self.current_objective == ObjectiveType.DOMINATION:
            # Control points capture
            control_pos = self.get_control_point()
            for robot in self.robots:
                if robot.position.distance_to(control_pos) < 80:
