                for robot in self.robots:
                    if robot.team == 0:
                        robot.ai_difficulty = min(1.0, self.adaptive_difficulty)
                    else:
                        robot.ai_difficulty = max(0.3, self.adaptive_difficulty - 0.4)
            else:
                self.adaptive_difficulty = 0.7 + (score_diff - 5) * 0.05
                for robot in self.robots:
                    if robot.team == 1:
                        robot.ai_difficulty = min(1.0, self.adaptive_difficulty)
                    else:
                        robot.ai_difficulty = max(0.3, self.adaptive_difficulty - 0.4)
        else:
            # Balanced difficulty
            self.adaptive_difficulty = 0.5
            for robot in self.robots:
                robot.ai_difficulty = 0.5


