                'cooldown': 2.5, 
                'type': 'ranged',
                'sound': 'sniper_shot'
            },
            WeaponType.ROCKET_LAUNCHER: {
                'range': 300, 
                'damage': 80, 
                'cooldown': 3.0, 
                'type': 'ranged',
                'sound': 'rocket_launch'
            },
            WeaponType.SHIELD_GENERATOR: {
                'range': 150, 
                'damage': 0, 
                'cooldown': 1.0, 
                'type': 'support',
                'sound': 'shield_activate'
            }
        }
        return weapons.get(self.weapon, weapons[WeaponType.RANGED_PLASMA])

    def can_attack(self) -> bool:
        return self.cooldown <= 0 and self.is_alive

    def attack(self, target_robot: Optional['Robot'], environment: 'Environment') -> bool:
        """Attempt to attack a target robot"""
        if not self.can_attack() or not target_robot or not target_robot.is_alive:
            return False

        weapon_stats = self.get_weapon_stats()

        # Check if target is within range
        distance = self.position.distance_to(target_robot.position)
        if distance > weapon_stats['range']:
            return False

        # For melee, need to be very close
        if weapon_stats['type'] == 'melee' and distance > weapon_stats['range'] * 0.8:
            return False

        # Apply damage
        damage = weapon_stats['damage']
        if weapon_stats['type'] == 'melee':
            # Melee attacks deal full damage
            target_robot.take_damage(damage, self.team)
        else:
            # Ranged attacks may have armor/shield reduction
            if target_robot.shield > 0:
                shield_absorbed = min(damage, target_robot.shield)
                target_robot.shield -= shield_absorbed
                damage -= shield_absorbed

            if damage > 0:
                target_robot.take_damage(damage, self.team)

        # Apply cooldown
        self.cooldown = weapon_stats['cooldown']

        # Reduce battery for energy weapons
        self.battery = max(0, self.battery - 10)

        # Add experience for successful attack
        self.experience += 5
        return True

    def take_damage(self, damage: float, attacker_team: int):
        """Apply damage to the robot"""
        if not self.is_alive:
            return

        # Shield absorbs damage first
        if self.shield > 0:
            shield_absorbed = min(damage, self.shield)
            self.shield -= shield_absorbed
            damage -= shield_absorbed

        # Apply remaining damage to health
        if damage > 0:
            self.health = max(0, self.health - damage)

        # Check if robot is dead
        if self.health <= 0:
            self.is_alive = False
            self.health = 0
            # Add experience to attacker
            # This would be handled in the environment for fairness

    def heal(self, amount: float):
        """Heal the robot"""
        if not self.is_alive:
            return

        self.health = min(self.max_health, self.health + amount)
        self.battery = min(self.max_battery, self.battery + 5)

    def use_powerup(self, powerup: PowerUpType):
        """Apply the effect of a powerup"""
        if not self.is_alive:
            return

        if powerup == PowerUpType.HEALTH_PACK:
            self.heal(30)
        elif powerup == PowerUpType.SPEED_BOOST:
            self.speed *= 1.5
            # Add a timer for speed boost (5 seconds)
            threading.Timer(5.0, lambda: setattr(self, 'speed', self.speed / 1.5)).start()
        elif powerup == PowerUpType.DAMAGE_BOOST:
            # Increase damage of weapon by 50% temporarily
            self.battery = min(self.max_battery, self.battery + 20)
        elif powerup == PowerUpType.SHIELD_BOOST:
            self.shield = min(self.max_shield, self.shield + 30)
        elif powerup == PowerUpType.REGEN_AURA:
            # Temporary health regeneration
            threading.Timer(10.0, lambda: None).start()
        elif powerup == PowerUpType.TELEPORT:
            # Teleport to a random safe location
            self.position = Vector2D(
                random.randint(50, SCREEN_WIDTH-50),
                random.randint(50, SCREEN_HEIGHT-50)
            )

        # Remove from inventory
        if powerup in self.inventory:
            self.inventory.remove(powerup)

    def get_ai_decision(self, environment: 'Environment') -> Dict:
        """
        AI decision-making system
        Uses reinforcement learning principles and behavior trees
        """
        if not self.is_alive:
            return {'action': 'idle', 'target': None}

        weapon_stats = self.get_weapon_stats()

        # Get nearby enemies and allies
        nearby_enemies = []
        nearby_allies = []

        for robot in environment.robots:
            if robot.id == self.id:
                continue
            if not robot.is_alive:
                continue

            distance = self.position.distance_to(robot.position)
            if distance <= self.vision_radius:
                if robot.team == self.team:
                    nearby_allies.append((robot, distance))
                else:
                    nearby_enemies.append((robot, distance))

        # Sort by distance
        nearby_enemies.sort(key=lambda x: x[1])
        nearby_allies.sort(key=lambda x: x[1])

        # Determine role-based behavior
        if self.role == TeamRole.ATTACKER:
            if nearby_enemies:
                # Target closest enemy
                target_robot, _ = nearby_enemies[0]
                if self.can_attack() and self.position.distance_to(target_robot.position) <= weapon_stats['range']:
                    return {'action': 'attack', 'target': target_robot}
                else:
                    return {'action': 'move', 'target': target_robot.position}
            else:
                # Move toward objective
                return {'action': 'move', 'target': environment.get_objective_position()}

        elif self.role == TeamRole.DEFENDER:
            if nearby_enemies:
                # Defend base/flag
                target_robot, _ = nearby_enemies[0]
                if self.can_attack() and self.position.distance_to(target_robot.position) <= weapon_stats['range']:
                    return {'action': 'attack', 'target': target_robot}
                else:
                    return {'action': 'move', 'target': environment.get_objective_position()}
            else:
                # Patrol defensive position
                return {'action': 'patrol', 'target': environment.get_defensive_position(self.team)}

        elif self.role == TeamRole.SUPPORTER:
            # Find low-health allies
            low_health_allies = [(a, d) for a, d in nearby_allies if a.health < a.max_health * 0.4]
            if low_health_allies:
                # Heal or shield the lowest health ally
                closest_allied_robot, _ = min(low_health_allies, key=lambda x: x[0].health)
                if self.weapon == WeaponType.SHIELD_GENERATOR and self.can_attack():
                    return {'action': 'support', 'target': closest_allied_robot}
                else:
                    return {'action': 'move', 'target': closest_allied_robot.position}
            elif nearby_enemies:
                # If no allies need help, attack enemies from range
                target_robot, _ = nearby_enemies[0]
                if self.can_attack() and self.position.distance_to(target_robot.position) <= weapon_stats['range']:
                    return {'action': 'attack', 'target': target_robot}
                else:
                    return {'action': 'move', 'target': target_robot.position}
            else:
                # Move toward objective
                return {'action': 'move', 'target': environment.get_objective_position()}

        elif self.role == TeamRole.CONTROLLER:
            # Control key areas
            if nearby_enemies:
                # Target high-priority enemy (e.g., enemy supporter)
                enemy_priorities = []
                for enemy, dist in nearby_enemies:
                    priority = 1
                    if enemy.role == TeamRole.SUPPORTER:
                        priority = 3
                    elif enemy.role == TeamRole.DEFENDER:
                        priority = 2
                    enemy_priorities.append((enemy, dist, priority))

                if enemy_priorities:
                    best_enemy = max(enemy_priorities, key=lambda x: x[2])
                    target_robot = best_enemy[0]
                    if self.can_attack() and self.position.distance_to(target_robot.position) <= weapon_stats['range']:
                        return {'action': 'attack', 'target': target_robot}
                    else:
                        return {'action': 'move', 'target': target_robot.position}
            else:
                # Move to control point
                return {'action': 'move', 'target': environment.get_control_point()}

        # Default: move toward objective if nothing else
        return {'action': 'move', 'target': environment.get_objective_position()}

@dataclass
class PowerUp:
    position: Vector2D
    powerup_type: PowerUpType
    active: bool = True
    spawn_time: float = field(default_factory=lambda: time.time())
    duration: float = 30.0  # How long it stays before despawning

    def update(self, dt: float):
        if self.active:
            if time.time() - self.spawn_time > self.duration:
                self.active = False

@dataclass
class Hazard:
    position: Vector2D
    hazard_type: HazardType
    radius: float = 40.0
    damage_per_second: float = 5.0
    active: bool = True
    spawn_time: float = field(default_factory=lambda: time.time())

    def update(self, dt: float):
        # Hazards are always active unless removed
        pass

@dataclass
class Team:
