    def update(self, dt: float, environment: 'Environment'):
        """Update robot state based on time delta and environment"""
        if not self.is_alive:
            return

        # Update cooldown
        if self.cooldown > 0:
            self.cooldown = max(0, self.cooldown - dt)

        # Update battery consumption based on movement and abilities
        self.battery = max(0, self.battery - dt * 0.5)  # Slow drain

        # Apply shield regeneration
        if self.shield < self.max_shield and self.battery > 10:
            self.shield = min(self.max_shield, self.shield + dt * 0.5)
            self.battery -= dt * 0.1

        # Update memory: store recent observations
        self._update_memory(environment)

