        if powerup in self.inventory:
            self.inventory.remove(powerup)

    def get_ai_decision(self, environment: 'Environment') -> Dict:
        """
        AI decision-making system
        Uses reinforcement learning principles and behavior trees
        """
        if not self.is_alive:
            return {'action': 'idle', 'target': None}

        weapon_stats = self.get_weapon_stats()

        # Get nearby enemies and allies
        nearby_enemies = []
        nearby_allies = []

        for robot in environment.robots:
            if robot.id == self.id:
                continue
            if not robot.is_alive:
                continue

            distance = self.position.distance_to(robot.position)
            if distance <= self.vision_radius:
                if robot.team == self.team:
                    nearby_allies.append((robot, distance))
                else:
                    nearby_enemies.append((robot, distance))

        # Sort by distance
        nearby_enemies.sort(key=lambda x: x[1])
        nearby_allies.sort(key=lambda x: x[1])

        # Determine role-based behavior
        if self.role == TeamRole.ATTACKER:
            if nearby_enemies:
                # Target closest enemy
                target_robot, _ = nearby_enemies[0]
                if self.can_attack() and self.position.distance_to(target_robot.position) <= weapon_stats['range']:
                    return {'action': 'attack', 'target': target_robot}
                else:
                    return {'action': 'move', 'target': target_robot.position}
            else:
                # Move toward objective
                return {'action': 'move', 'target': environment.get_objective_position()}

        elif self.role == TeamRole.DEFENDER:
            if nearby_enemies:
                # Defend base/flag
                target_robot, _ = nearby_enemies[0]
                if self.can_attack() and self.position.distance_to(target_robot.position) <= weapon_stats['range']:
                    return {'action': 'attack', 'target': target_robot}
                else:
                    return {'action': 'move', 'target': environment.get_objective_position()}
            else:
                # Patrol defensive position
                return {'action': 'patrol', 'target': environment.get_defensive_position(self.team)}

        elif self.role == TeamRole.SUPPORTER:
            # Find low-health allies
            low_health_allies = [(a, d) for a, d in nearby_allies if a.health < a.max_health * 0.4]
            if low_health_allies:
                # Heal or shield the lowest health ally
                closest_allied_robot, _ = min(low_health_allies, key=lambda x: x[0].health)
                if self.weapon == WeaponType.SHIELD_GENERATOR and self.can_attack():
                    return {'action': 'support', 'target': closest_allied_robot}
                else:
                    return {'action': 'move', 'target': closest_allied_robot.position}
            elif nearby_enemies:
                # If no allies need help, attack enemies from range
                target_robot, _ = nearby_enemies[0]
                if self.can_attack() and self.position.distance_to(target_robot.position) <= weapon_stats['range']:
                    return {'action': 'attack', 'target': target_robot}
                else:
                    return {'action': 'move', 'target': target_robot.position}
            else:
                # Move toward objective
                return {'action': 'move', 'target': environment.get_objective_position()}

        elif self.role == TeamRole.CONTROLLER:
            # Control key areas
            if nearby_enemies:
                # Target high-priority enemy (e.g., enemy supporter)
                enemy_priorities = []
                for enemy, dist in nearby_enemies:
                    priority = 1
                    if enemy.role == TeamRole.SUPPORTER:
                        priority = 3
                    elif enemy.role == TeamRole.DEFENDER:
                        priority = 2
                    enemy_priorities.append((enemy, dist, priority))

                if enemy_priorities:
                    best_enemy = max(enemy_priorities, key=lambda x: x[2])
                    target_robot = best_enemy[0]
                    if self.can_attack() and self.position.distance_to(target_robot.position) <= weapon_stats['range']:
                        return {'action': 'attack', 'target': target_robot}
                    else:
                        return {'action': 'move', 'target': target_robot.position}
            else:
                # Move to control point
                return {'action': 'move', 'target': environment.get_control_point()}

        # Default: move toward objective if nothing else
        return {'action': 'move', 'target': environment.get_objective_position()}

@dataclass
class PowerUp:
    position: Vector2D
    powerup_type: PowerUpType
    active: bool = True
    spawn_time: float = field(default_factory=lambda: time.time())
    duration: float = 30.0  # How long it stays before despawning

    def update(self, dt: float):
        if self.active:
            if time.time() - self.spawn_time > self.duration:
                self.active = False

@dataclass
class Hazard:
    position: Vector2D
    hazard_type: HazardType
    radius: float = 40.0
    damage_per_second: float = 5.0
    active: bool = True
    spawn_time: float = field(default_factory=lambda: time.time())

    def update(self, dt: float):
        # Hazards are always active unless removed
        pass

@dataclass
class Team:
    id: int
    name: str
    score: int = 0
    robots: List[Robot] = field(default_factory=list)
    objectives: Dict = field(default_factory=dict)
    ai_difficulty: float = 0.7  # 0.0 - 1.0, affects AI aggression and accuracy

    def __post_init__(self):
        self.objectives = {
            'captured_flags': 0,
            'defended_bases': 0,
            'payload_distance': 0,
            'domination_points': 0
        }

@dataclass
class Environment:
    # Arena
    width: int = SCREEN_WIDTH
    height: int = SCREEN_HEIGHT
    grid_size: int = GRID_SIZE

    # Game objects
    robots: List[Robot] = field(default_factory=list)
    powerups: List[PowerUp] = field(default_factory=list)
    hazards: List[Hazard] = field(default_factory=list)

    # Game state
    game_state: GameState = GameState.LOBBY
    current_objective: Optional[ObjectiveType] = None
    objective_progress: Dict = field(default_factory=dict)
    team_scores: Dict[int, int] = field(default_factory=dict)
    team_objectives: Dict[int, Dict] = field(default_factory=dict)

    # Spawn points
    spawn_points: List[Vector2D] = field(default_factory=list)

    # Time
    game_time: float = 0.0
    last_update: float = 0.0

    # AI difficulty
    adaptive_difficulty: float = 0.5

    def __post_init__(self):    def get_objective_position(self) -> Vector2D:
        """Return position of current objective"""
        if self.current_objective == ObjectiveType.CAPTURE_FLAG:
            # Flag is placed in the center
            return Vector2D(self.width / 2, self.height / 2)
        elif self.current_objective == ObjectiveType.DEFEND_BASE:
            # Base is at the team's spawn point
            return self.spawn_points[0] if self.team_scores[0] > self.team_scores[1] else self.spawn_points[1]
        elif self.current_objective == ObjectiveType.ESCORT_PAYLOAD:
            # Return current payload position if set, otherwise center
            if 'payload_position' in self.objective_progress:
                return self.objective_progress['payload_position']
            else:
                return Vector2D(self.width / 2, self.height / 2)
        else:
            return Vector2D(self.width / 2, self.height / 2)
    def __post_init__(self):
        # Initialize team objectives for both teams
        for team_id in range(MAX_TEAMS):
            self.team_objectives[team_id] = {
                'captured_flags': 0,
                'defended_bases': 0,
                'payload_distance': 0,
                'domination_points': 0
            }

        # Initialize team scores
        for team_id in range(MAX_TEAMS):
            self.team_scores[team_id] = 0

        # Initialize spawn points at opposite corners
        self.spawn_points = [
            Vector2D(100, 100),
            Vector2D(self.width - 100, self.height - 100)
        ]    def get_defensive_position(self, team_id: int) -> Vector2D:
        """Return position to defend for a team"""
        if team_id == 0:
            return self.spawn_points[0]
        else:
            return self.spawn_points[1]

    def get_control_point(self) -> Vector2D:
        """Return the central control point"""
        return Vector2D(self.width / 2, self.height / 2)

    def update(self, dt: float):
        """Update environment state"""
        self.game_time += dt
        self.last_update = time.time()

        # Update robots
        for robot in self.robots:
            if robot.is_alive:
                robot.update(dt, self)

        # Update powerups
        for powerup in self.powerups[:]:
            powerup.update(dt)
            if not powerup.active:
                self.powerups.remove(powerup)

        # Update hazards
        for hazard in self.hazards[:]:
            hazard.update(dt)
            # Check if robot is in hazard zone
            for robot in self.robots:
                if robot.is_alive and robot.position.distance_to(hazard.position) < hazard.radius:
                    robot.take_damage(hazard.damage_per_second * dt, -1)  # Damage from environment

        # Spawn powerups randomly
        if random.random() < 0.001 and len(self.powerups) < 5:
            self.spawn_powerup()

        # Spawn hazards randomly
        if random.random() < 0.0005 and len(self.hazards) < 3:
            self.spawn_hazard()

        # Update objective progress
        self._update_objectives()

        # Check for game end conditions
        self._check_game_end()

        # Update adaptive difficulty based on performance
        self._update_adaptive_difficulty()

    def _update_objectives(self):
        """Update objective progress based on robot positions and actions"""
        if self.current_objective == ObjectiveType.CAPTURE_FLAG:
            # Flag is at center; robots can capture it
            flag_pos = self.get_objective_position()
            for robot in self.robots:
                if robot.position.distance_to(flag_pos) < 60:
                    # Robot is at flag
                    if robot.team == 0:
                        self.objective_progress['flag_captured'] = True
                        self.team_scores[0] += 1
                    else:
                        self.objective_progress['flag_captured'] = True
                        self.team_scores[1] += 1

        elif self.current_objective == ObjectiveType.DEFEND_BASE:
            # Base at spawn points; if enemy is near, defend it
            for team_id in [0, 1]:
                base_pos = self.spawn_points[team_id]
                enemy_nearby = False        elif self.current_objective == ObjectiveType.ESCORT_PAYLOAD:            # Payload moves toward enemy base
            payload_pos = self.get_objective_position()
            payload_distance = min(self.width, self.height)  # Max distance
            self.objective_progress['payload_distance'] = payload_distance

            # Check if payload reached enemy base
            for team_id in [0, 1]:
                enemy_base = self.spawn_points[1 - team_id]
                if payload_pos.distance_to(enemy_base) < 50:
                    self.team_scores[team_id] += 10
                    self.objective_progress['payload_distance'] = 0

        elif self.current_objective == ObjectiveType.DOMINATION:
            # Control points capture
            control_pos = self.get_control_point()
            for robot in self.robots:
                if robot.position.distance_to(control_pos) < 80:
                    # Capture point for team
                    self.team_objectives[robot.team]['domination_points'] = self.team_objectives[robot.team].get('domination_points', 0) + dt * 0.1
                    if self.team_objectives[robot.team]['domination_points'] >= 1:
                        self.team_scores[robot.team] += 1
                        self.team_objectives[robot.team]['domination_points'] = 0

    def _check_game_end(self):
        """Check if game should end"""
        if max(self.team_scores.values()) >= 15:
            self.game_state = GameState.GAME_OVER

    def _update_adaptive_difficulty(self):
        """Adjust AI difficulty based on team performance"""
        score_diff = abs(self.team_scores[0] - self.team_scores[1])

        # If one team is dominating, make AI harder for them and easier for the other
        if score_diff > 5:
            # For the leading team, make AI more aggressive
            if self.team_scores[0] > self.team_scores[1]:
                self.adaptive_difficulty = 0.7 + (score_diff - 5) * 0.05
                for robot in self.robots:
                    if robot.team == 0:
                        robot.ai_difficulty = min(1.0, self.adaptive_difficulty)
                    else:
                        robot.ai_difficulty = max(0.3, self.adaptive_difficulty - 0.4)
            else:
                self.adaptive_difficulty = 0.7 + (score_diff - 5) * 0.05
                for robot in self.robots:
                    if robot.team == 1:
                        robot.ai_difficulty = min(1.0, self.adaptive_difficulty)
                    else:
                        robot.ai_difficulty = max(0.3, self.adaptive_difficulty - 0.4)
        else:
            # Balanced difficulty
            self.adaptive_difficulty = 0.5
            for robot in self.robots:
                robot.ai_difficulty = 0.5


