@dataclass
class Vector2D:
    """2D Vector for position, velocity, and direction"""
    x: float = 0.0
    y: float = 0.0

    def __add__(self, other):
        return Vector2D(self.x + other.x, self.y + other.y)

    def __sub__(self, other):
        return Vector2D(self.x - other.x, self.y - other.y)

    def __mul__(self, scalar):
        return Vector2D(self.x * scalar, self.y * scalar)

    def __truediv__(self, scalar):
        if scalar == 0:
            return Vector2D(0, 0)
        return Vector2D(self.x / scalar, self.y / scalar)

    def magnitude(self):
        return math.sqrt(self.x**2 + self.y**2)

    def normalize(self):
        mag = self.magnitude()
        if mag == 0:
            return Vector2D(0, 0)
        return self / mag

    def distance_to(self, other):
        return (self - other).magnitude()

    def dot(self, other):
        return self.x * other.x + self.y * other.y

    def as_tuple(self):
        return (self.x, self.y)

@dataclass
class Weapon:
    """Weapon configuration for robots"""
    name: str
    type: WeaponType
    damage: float
    range: float
    fire_rate: float  # seconds between shots
    ammo: int
    reload_time: float
    effect: Optional[str] = None  # e.g., "explosion", "poison", "stun"

    def can_fire(self, last_fired: float) -> bool:
        return time.time() - last_fired >= self.fire_rate

@dataclass
class Robot:
    """Represents a single AI-controlled robot in the arena"""
    id: str
    team: Team
    role: RobotRole
    position: Vector2D
    velocity: Vector2D = field(default_factory=lambda: Vector2D(0, 0))
    health: float = 100.0
    max_health: float = 100.0
    armor: float = 0.0
    weapon: Optional[Weapon] = None
    secondary_weapon: Optional[Weapon] = None
    active_power_up: Optional[PowerUpType] = None
    power_up_timer: float = 0.0
    cooldowns: Dict[str, float] = field(default_factory=dict)  # ability_name -> end_time
    vision_range: float = 30.0
    movement_speed: float = 2.0
    last_action_time: float = 0.0
    last_target: Optional[str] = None
    target_objective: Optional[ObjectiveType] = None
    knowledge_base: Dict[str, Any] = field(default_factory=dict)  # Learning data
    decision_tree: List[Dict] = field(default_factory=list)  # Strategy rules

    def __post_init__(self):
        if not self.weapon:
            self.weapon = Weapon("Plasma Rifle", WeaponType.RANGED, 25.0, 50.0, 0.8, 30, 2.5)
        if not self.secondary_weapon:
            self.secondary_weapon = Weapon("Energy Blade", WeaponType.MELEE, 40.0, 5.0, 1.5, 1, 0.0)
        if not self.cooldowns:
            self.cooldowns = {
                "dash": 0.0,
                "shield": 0.0,
                "teleport": 0.0
            }

    def take_damage(self, damage: float) -> float:
        """Apply damage to robot, considering armor"""
        actual_damage = damage * (1 - min(self.armor / 100.0, 0.8))  # Max 80% reduction
        self.health -= actual_damage
        return actual_damage

    def heal(self, amount: float) -> float:
        """Heal robot, not exceeding max health"""
        heal_amount = min(amount, self.max_health - self.health)
        self.health += heal_amount
        return heal_amount

    def is_alive(self) -> bool:
        return self.health > 0

    def get_distance_to(self, other_position: Vector2D) -> float:
        return self.position.distance_to(other_position)

    def set_target(self, target_id: str):
        self.last_target = target_id

    def has_active_power_up(self) -> bool:
        return self.active_power_up is not None and self.power_up_timer > time.time()

    def update_power_up(self):
        """Decrease power-up timer and remove if expired"""
        if self.has_active_power_up():
            self.power_up_timer -= 0.1
            if self.power_up_timer <= time.time():
                self.active_power_up = None
                logger.info(f"Robot {self.id} power-up expired")

    def add_knowledge(self, key: str, value: Any):
        """Store learned information for adaptive behavior"""
        self.knowledge_base[key] = value

    def get_knowledge(self, key: str, default=None) -> Any:
        return self.knowledge_base.get(key, default)

    def get_role_priority(self) -> int:
        """Returns priority for role assignment (lower number = higher priority)"""
        role_priorities = {
            RobotRole.ATTACKER: 1,
            RobotRole.DEFENDER: 2,
            RobotRole.SUPPORT: 3,
            RobotRole.SCOUT: 4,
            RobotRole.CONTROLLER: 5
        }
        return role_priorities.get(self.role, 5)

@dataclass
class Objective:
    """Represents a team-based objective"""
    id: str
    type: ObjectiveType
    position: Vector2D
    team: Team
    capture_progress: float = 0.0
    is_active: bool = True
    defenders: Set[str] = field(default_factory=set)  # Robot IDs defending
    attackers: Set[str] = field(default_factory=set)  # Robot IDs attacking
    capture_threshold: float = 100.0
    spawn_points: List[Vector2D] = field(default_factory=list)

    def update_capture_progress(self, robot_count: int, team: Team) -> bool:
        """Update capture progress based on robots near objective"""
        if team != self.team:
            # Enemy team capturing
            self.capture_progress = min(self.capture_progress + robot_count * 0.5, self.capture_threshold)
        else:
            # Friendly team defending
            self.capture_progress = max(self.capture_progress - robot_count * 0.3, 0)

        return self.capture_progress >= self.capture_threshold

@dataclass
class PowerUp:
    """Power-up item in the arena"""
    id: str
    type: PowerUpType
    position: Vector2D
    spawn_time: float
    duration: float = 15.0
    active: bool = True
    radius: float = 3.0

    def is_collected(self, robot_position: Vector2D) -> bool:
        """Check if robot is within power-up radius"""
        return self.position.distance_to(robot_position) <= self.radius

@dataclass
class Hazard:
    """Environmental hazard in the arena"""
    id: str
    type: HazardType
    position: Vector2D
    radius: float
    damage_per_second: float
    active: bool = True
    spawn_time: float = 0.0
    duration: float = 30.0

    def affects_robot(self, robot_position: Vector2D) -> bool:
        """Check if robot is in hazard zone"""
        return self.position.distance_to(robot_position) <= self.radius

@dataclass
class GameState:
    """Current state of the entire game"""
    round_time: float = 0.0
    team_scores: Dict[Team, int] = field(default_factory=lambda: {Team.RED: 0, Team.BLUE: 0})
    objectives: Dict[str, Objective] = field(default_factory=dict)
    power_ups: Dict[str, PowerUp] = field(default_factory=dict)
    hazards: Dict[str, Hazard] = field(default_factory=dict)
    robots: Dict[str, Robot] = field(default_factory=dict)
    last_update: float = 0.0
    round_count: int = 0
    winner: Optional[Team] = None
    game_over: bool = False
    match_history: List[Dict] = field(default_factory=list)

    def get_team_robots(self, team: Team) -> List[Robot]:
        return [robot for robot in self.robots.values() if robot.team == team]

    def get_active_objectives(self) -> List[Objective]:
        return [obj for obj in self.objectives.values() if obj.is_active]

    def get_alive_robots(self) -> List[Robot]:
        return [robot for robot in self.robots.values() if robot.is_alive()]

    def get_team_winning(self) -> Optional[Team]:
        if not self.team_scores:
            return None
        return max(self.team_scores.keys(), key=lambda k: self.team_scores[k])

    def get_robot_by_id(self, robot_id: str) -> Optional[Robot]:
        return self.robots.get(robot_id)

    def get_closest_objective(self, robot: Robot) -> Optional[Objective]:
        """Find the closest active objective to robot"""
        active_objectives = self.get_active_objectives()
        if not active_objectives:
            return None

        closest = min(active_objectives, key=lambda obj: robot.position.distance_to(obj.position))
        return closest if robot.get_distance_to(closest.position) <= robot.vision_range else None

    def get_closest_enemy(self, robot: Robot) -> Optional[Robot]:
        """Find closest enemy robot within vision range"""
        enemies = [r for r in self.robots.values() 
                  if r.team != robot.team and r.is_alive() and r.get_distance_to(robot.position) <= robot.vision_range]
        if not enemies:
            return None
        return min(enemies, key=lambda e: robot.position.distance_to(e.position))

    def get_closest_power_up(self, robot: Robot) -> Optional[PowerUp]:
        """Find closest power-up within vision range"""
        power_ups = [pu for pu in self.power_ups.values() if pu.active and robot.get_distance_to(pu.position) <= robot.vision_range]
        if not power_ups:
            return None
        return min(power_ups, key=lambda pu: robot.position.distance_to(pu.position))

    def get_closest_hazard(self, robot: Robot) -> Optional[Hazard]:
        """Find closest hazard within vision range"""
        hazards = [h for h in self.hazards.values() if h.active and robot.get_distance_to(h.position) <= robot.vision_range]
        if not hazards:
            return None
        return min(hazards, key=lambda h: robot.position.distance_to(h.position))

# =====================
# AUDIO VISUAL SYSTEM
# =====================

class AudioVisualSystem:
    """Manages immersive audiovisual effects"""

    def __init__(self):
        self.particle_effects = []
        self.sound_queue = queue.Queue()
        self.lighting_effects = []
        self.is_muted = False
        self.volume = 1.0

    def play_sound(self, sound_type: str, position: Vector2D = None, volume: float = 1.0):
        """Queue a sound effect"""
        if self.is_muted:
            return

        sound_data = {
            "type": sound_type,
            "position": position.as_tuple() if position else None,
            "volume": volume * self.volume,
            "timestamp": time.time()
        }
        self.sound_queue.put(sound_data)

    def create_particle_effect(self, effect_type: str, position: Vector2D, color: str = "white", duration: float = 2.0):
        """Create a visual particle effect"""
        particle = {
            "type": effect_type,
            "position": position.as_tuple(),
            "color": color,
            "duration": duration,
            "start_time": time.time(),
            "alive": True
        }
        self.particle_effects.append(particle)

    def create_lighting_effect(self, position: Vector2D, color: Tuple[int, int, int], radius: float, intensity: float):
        """Create a dynamic lighting effect"""
        lighting = {
            "position": position.as_tuple(),
            "color": color,
            "radius": radius,
            "intensity": intensity,
            "start_time": time.time(),
            "duration": 3.0,
            "alive": True
        }
        self.lighting_effects.append(lighting)

    def update_effects(self):
        """Update all visual and audio effects"""
        # Update particles
        for particle in self.particle_effects[:]:
            if time.time() - particle["start_time"] > particle["duration"]:
                particle["alive"] = False

        self.particle_effects = [p for p in self.particle_effects if p["alive"]]

        # Update lighting
        for light in self.lighting_effects[:]:
            if time.time() - light["start_time"] > light["duration"]:
                light["alive"] = False

        self.lighting_effects = [l for l in self.lighting_effects if l["alive"]]

    def get_audio_feedback(self) -> List[Dict]:
        """Get all queued audio events"""
        sounds = []
        while not self.sound_queue.empty():
            sounds.append(self.sound_queue.get())
        return sounds

    def get_visual_feedback(self) -> Dict:
        """Get current visual effects state"""
        return {
            "particles": self.particle_effects,
            "lighting": self.lighting_effects
        }

# =====================
# AI DECISION MAKER
# =====================

class AIDecisionMaker:
    """Handles AI decision-making for robots using machine learning principles"""

    def __init__(self, game_state: GameState, av_system: AudioVisualSystem):
        self.game_state = game_state
        self.av_system = av_system
        self.learning_rate = 0.1
        self.exploration_rate = 0.3  # Chance to explore new strategies
        self.decision_history = deque(maxlen=100)

        # Define common decision rules
        self.strategy_patterns = {
            RobotRole.ATTACKER: [
                {"priority": 10, "condition": lambda r, gs: gs.get_closest_enemy(r) is not None, "action": "attack"},
                {"priority": 8, "condition": lambda r, gs: gs.get_closest_objective(r) is not None and gs.get_closest_objective(r).team != r.team, "action": "capture_objective"},
                {"priority": 5, "condition": lambda r, gs: gs.get_closest_power_up(r) is not None, "action": "collect_powerup"},
                {"priority": 2, "condition": lambda r, gs: True, "action": "patrol"}
            ],
            RobotRole.DEFENDER: [
                {"priority": 10, "condition": lambda r, gs: gs.get_closest_objective(r) is not None and gs.get_closest_objective(r).team == r.team, "action": "defend_objective"},
                {"priority": 8, "condition": lambda r, gs: gs.get_closest_enemy(r) is not None, "action": "counter_attack"},
                {"priority": 6, "condition": lambda r, gs: gs.get_closest_power_up(r) is not None, "action": "collect_powerup"},
                {"priority": 4, "condition": lambda r, gs: True, "action": "patrol_base"}
            ],
            RobotRole.SUPPORT: [
                {"priority": 10, "condition": lambda r, gs: self._has_low_health_teammate(gs, r.team), "action": "heal_teammate"},
                {"priority": 8, "condition": lambda r, gs: gs.get_closest_power_up(r) is not None, "action": "collect_powerup"},
                {"priority": 6, "condition": lambda r, gs: gs.get_closest_objective(r) is not None and gs.get_closest_objective(r).team == r.team, "action": "support_defense"},
                {"priority": 4, "condition": lambda r, gs: True, "action": "patrol"}
            ],
            RobotRole.SCOUT: [
                {"priority": 10, "condition": lambda r, gs: gs.get_closest_enemy(r) is not None, "action": "recon_and_report"},
                {"priority": 8, "condition": lambda r, gs: gs.get_closest_objective(r) is not None, "action": "scout_objective"},
                {"priority": 5, "condition": lambda r, gs: gs.get_closest_power_up(r) is not None, "action": "collect_powerup"},
                {"priority": 2, "condition": lambda r, gs: True, "action": "patrol"}
            ],
            RobotRole.CONTROLLER: [
                {"priority": 10, "condition": lambda r, gs: self._has_low_health_teammate(gs, r.team), "action": "provide_support"},
                {"priority": 9, "condition": lambda r, gs: gs.get_closest_hazard(r) is not None, "action": "avoid_hazard"},
                {"priority": 8, "condition": lambda r, gs: gs.get_closest_objective(r) is not None and gs.get_closest_objective(r).team == r.team, "action": "control_objective"},
                {"priority": 7, "condition": lambda r, gs: gs.get_closest_power_up(r) is not None, "action": "collect_powerup"},
                {"priority": 5, "condition": lambda r, gs: True, "action": "patrol"}
            ]
        }

    def _has_low_health_teammate(self, game_state: GameState, team: Team) -> bool:
        """Check if any teammate has low health"""
        teammates = [r for r in game_state.robots.values() if r.team == team and r.is_alive()]
        return any(r.health < r.max_health * 0.3 for r in teammates)

    def get_best_action(self, robot: Robot) -> str:
        """Determine the best action for a robot using decision tree and learning"""
        if not robot.is_alive():
            return "idle"

        # Get strategy pattern for robot's role
        patterns = self.strategy_patterns.get(robot.role, [])

        # Apply learning-based adjustment
        if random.random() < self.exploration_rate:
            # Exploration: try a random action
            return random.choice([p["action"] for p in patterns])

        # Exploitation: use learned best action
        best_action = None
        best_priority = -1

        for pattern in patterns:
            if pattern["condition"](robot, self.game_state):
                # Check if this action has been successful in the past
                action_key = f"{robot.role.value}_{pattern['action']}_success"
                success_rate = robot.get_knowledge(action_key, 0.5)  # Default 50% success

                # Weight priority by success rate
                weighted_priority = pattern["priority"] * success_rate

                if weighted_priority > best_priority:
                    best_priority = weighted_priority
                    best_action = pattern["action"]

        # If no pattern matches, use default
        if best_action is None:
            best_action = patterns[0]["action"] if patterns else "patrol"

        # Update decision history
        self.decision_history.append({
            "robot_id": robot.id,
            "role": robot.role.value,
            "action": best_action,
            "timestamp": time.time()
        })

        return best_action

    def learn_from_outcome(self, robot: Robot, action: str, outcome: str):
        """Update knowledge based on action outcome"""
        # outcome: "success", "failure", "partial"

        action_key = f"{robot.role.value}_{action}_success"
        current_success_rate = robot.get_knowledge(action_key, 0.5)

        if outcome == "success":
            new_rate = min(current_success_rate + self.learning_rate, 1.0)
        elif outcome == "failure":
            new_rate = max(current_success_rate - self.learning_rate, 0.1)
        else:  # partial
            new_rate = current_success_rate

        robot.add_knowledge(action_key, new_rate)
        logger.debug(f"Robot {robot.id} learned: {action_key} -> {new_rate:.2f}")

    def adjust_difficulty(self):
        """Adaptive difficulty system based on team performance"""
        red_score = self.game_state.team_scores[Team.RED]
        blue_score = self.game_state.team_scores[Team.BLUE]

        # Calculate performance difference
        score_diff = abs(red_score - blue_score)
        avg_score = (red_score + blue_score) / 2 if (red_score + blue_score) > 0 else 0

        # Adjust AI behavior based on performance imbalance
        if score_diff > 15 and avg_score > 10:
            # Game is unbalanced, adjust difficulty
            if red_score > blue_score:
                # Blue team is losing, make blue AI more aggressive
                for robot in self.game_state.get_team_robots(Team.BLUE):
                    if robot.role == RobotRole.DEFENDER:
                        robot.role = RobotRole.ATTACKER
                        robot.vision_range = min(robot.vision_range * 1.2, 50.0)
                        robot.movement_speed = min(robot.movement_speed * 1.1, 3.5)
            else:
                # Red team is losing, make red AI more aggressive
                for robot in self.game_state.get_team_robots(Team.RED):
                    if robot.role == RobotRole.DEFENDER:
                        robot.role = RobotRole.ATTACKER
                        robot.vision_range = min(robot.vision_range * 1.2, 50.0)
                        robot.movement_speed = min(robot.movement_speed * 1.1, 3.5)

        # Adjust exploration rate based on game progression
        if avg_score > 20:
            self.exploration_rate = 0.1  # Less exploration, more refined strategies
        else:
            self.exploration_rate = 0.3  # More exploration early on

# =====================
# GAME LOGIC SYSTEM
# =====================

class CyberArena:
    """Main game system for CyberArena"""

    def __init__(self):
        self.game_state = GameState()
        self.av_system = AudioVisualSystem()
        self.ai_decision_maker = AIDecisionMaker(self.game_state, self.av_system)
        self.game_running = False
        self.game_thread = None
        self.last_tick_time = 0
        self.tick_rate = 1/60  # 60 FPS

        # Initialize default game configuration
        self.setup_default_arena()

        # Control scheme
        self.control_scheme = "standard"  # Options: "standard", "keyboard", "joystick"

    def setup_default_arena(self):
        """Initialize the game with default robots, objectives, and environment"""
        # Create robots
        robot_ids = [f"R{chr(65 + i)}" for i in range(10)]

        # Assign teams and roles
        team_assignments = [
            (Team.RED, RobotRole.ATTACKER),
            (Team.RED, RobotRole.DEFENDER),
            (Team.RED, RobotRole.SUPPORT),
            (Team.RED, RobotRole.SCOUT),
            (Team.RED, RobotRole.CONTROLLER),
            (Team.BLUE, RobotRole.ATTACKER),
            (Team.BLUE, RobotRole.DEFENDER),
            (Team.BLUE, RobotRole.SUPPORT),
            (Team.BLUE, RobotRole.SCOUT),
            (Team.BLUE, RobotRole.CONTROLLER)
        ]

        # Create robots with initial positions
        red_spawn = Vector2D(20, 20)
        blue_spawn = Vector2D(180, 180)

        for i, (team, role) in enumerate(team_assignments):
            base_pos = red_spawn if team == Team.RED else blue_spawn
            offset = Vector2D(random.uniform(-8, 8), random.uniform(-8, 8))
            position = base_pos + offset

            robot = Robot(
                id=robot_ids[i],
                team=team,
                role=role,
                position=position
            )

            # Add special weapons based on role
            if role == RobotRole.ATTACKER:
                robot.weapon = Weapon("Heavy Plasma Cannon", WeaponType.RANGED, 35.0, 60.0, 1.2, 20, 3.0)
                robot.secondary_weapon = Weapon("Laser Sword", WeaponType.MELEE, 50.0, 6.0, 1.0, 1, 0.0)
            elif role == RobotRole.DEFENDER:
                robot.weapon = Weapon("Railgun", WeaponType.RANGED, 30.0, 70.0, 1.5, 15, 3.5)
                robot.armor = 40.0
                robot.max_health = 150.0
                robot.health = 150.0
            elif role == RobotRole.SUPPORT:
                robot.weapon = Weapon("Medi-Gun", WeaponType.RANGED, 10.0, 40.0, 0.5, 50, 1.0)
                robot.secondary_weapon = Weapon("Shield Generator", WeaponType.SPECIAL, 0.0, 20.0, 5.0, 1, 8.0)
            elif role == RobotRole.SCOUT:
                robot.movement_speed = 4.0
                robot.vision_range = 45.0
                robot.weapon = Weapon("Sniper Rifle", WeaponType.RANGED, 45.0, 100.0, 2.0, 8, 4.0)
            elif role == RobotRole.CONTROLLER:
                robot.weapon = Weapon("EMP Pulse", WeaponType.SPECIAL, 0.0, 25.0, 8.0, 1, 10.0)
                robot.secondary_weapon = Weapon("Hack Device", WeaponType.SPECIAL, 0.0, 15.0, 6.0, 1, 7.0)

            self.game_state.robots[robot.id] = robot

        # Create objectives
        # Flag Capture objective
        flag_position = Vector2D(100, 100)
        flag_obj = Objective(
            id="flag_1",
            type=ObjectiveType.CAPTURE_FLAG,
            position=flag_position,
            team=Team.NEUTRAL,
            spawn_points=[Vector2D(30, 30), Vector2D(170, 170)],
            capture_threshold=150.0
        )
        self.game_state.objectives[flag_obj.id] = flag_obj

        # Control point 1
        cp1 = Objective(
            id="cp_1",
            type=ObjectiveType.CONTROL_POINT,
            position=Vector2D(60, 60),
            team=Team.RED,
            spawn_points=[Vector2D(40, 40), Vector2D(80, 80)],
            capture_threshold=120.0
        )
        self.game_state.objectives[cp1.id] = cp1

        # Control point 2
        cp2 = Objective(
            id="cp_2",
            type=ObjectiveType.CONTROL_POINT,
            position=Vector2D(140, 140),
            team=Team.BLUE,
            spawn_points=[Vector2D(120, 120), Vector2D(160, 160)],
            capture_threshold=120.0
        )
        self.game_state.objectives[cp2.id] = cp2

        # Create power-ups
        power_ups = [
            (PowerUpType.SPEED_BOOST, Vector2D(40, 160)),
            (PowerUpType.DAMAGE_BOOST, Vector2D(160, 40)),
            (PowerUpType.SHIELD, Vector2D(40, 40)),
            (PowerUpType.REGENERATION, Vector2D(160, 160)),
            (PowerUpType.TELEPORT, Vector2D(100, 20)),
            (PowerUpType.SILENCE, Vector2D(100, 180))
        ]

        for i, (ptype, pos) in enumerate(power_ups):
            power_up = PowerUp(
                id=f"pu_{i}",
                type=ptype,
                position=pos,
                spawn_time=time.time(),
                duration=15.0
            )
            self.game_state.power_ups[power_up.id] = power_up

        # Create hazards
        hazards = [
            (HazardType.ELECTRIC_FIELD, Vector2D(90, 90), 8.0, 2.0),
            (HazardType.FIRE_ZONE, Vector2D(110, 110), 6.0, 1.5),
            (HazardType.MINE_FIELD, Vector2D(80, 120), 7.0, 1.0),
            (HazardType.SMOKE_SCREEN, Vector2D(120, 80), 10.0, 0.0)
        ]

        for i, (htype, pos, radius, damage) in enumerate(hazards):
            hazard = Hazard(
                id=f"h_{i}",
                type=htype,
                position=pos,
                radius=radius,
                damage_per_second=damage,
                duration=45.0,
                spawn_time=time.time()
            )
            self.game_state.hazards[hazard.id] = hazard

        self.game_state.last_update = time.time()
        logger.info("Default arena setup complete")

    def spawn_new_robot(self, team: Team, role: RobotRole):
        """Spawn a new robot if one dies"""
        if len(self.game_state.get_team_robots(team)) >= 5:
            return  # Max robots per team

        # Find spawn point
        spawn_points = []
        for obj in self.game_state.objectives.values():
            if obj.team == team:
                spawn_points.extend(obj.spawn_points)

        if not spawn_points:
            # Default spawn
