class AudioVisualSystem:
    """Manages immersive audiovisual effects"""

    def __init__(self):
        self.particle_effects = []
        self.sound_queue = queue.Queue()
        self.lighting_effects = []
        self.is_muted = False
        self.volume = 1.0

    def play_sound(self, sound_type: str, position: Vector2D = None, volume: float = 1.0):
        """Queue a sound effect"""
        if self.is_muted:
            return

        sound_data = {
            "type": sound_type,
            "position": position.as_tuple() if position else None,
            "volume": volume * self.volume,
            "timestamp": time.time()
        }
        self.sound_queue.put(sound_data)

    def create_particle_effect(self, effect_type: str, position: Vector2D, color: str = "white", duration: float = 2.0):
        """Create a visual particle effect"""
        particle = {
            "type": effect_type,
            "position": position.as_tuple(),
            "color": color,
            "duration": duration,
            "start_time": time.time(),
            "alive": True
        }
        self.particle_effects.append(particle)

    def create_lighting_effect(self, position: Vector2D, color: Tuple[int, int, int], radius: float, intensity: float):
        """Create a dynamic lighting effect"""
        lighting = {
            "position": position.as_tuple(),
            "color": color,
            "radius": radius,
            "intensity": intensity,
            "start_time": time.time(),
            "duration": 3.0,
            "alive": True
        }
        self.lighting_effects.append(lighting)

    def update_effects(self):
        """Update all visual and audio effects"""
        # Update particles
        for particle in self.particle_effects[:]:
            if time.time() - particle["start_time"] > particle["duration"]:
                particle["alive"] = False

        self.particle_effects = [p for p in self.particle_effects if p["alive"]]

        # Update lighting
        for light in self.lighting_effects[:]:
            if time.time() - light["start_time"] > light["duration"]:
                light["alive"] = False

        self.lighting_effects = [l for l in self.lighting_effects if l["alive"]]

    def get_audio_feedback(self) -> List[Dict]:
        """Get all queued audio events"""
        sounds = []
        while not self.sound_queue.empty():
            sounds.append(self.sound_queue.get())
        return sounds

    def get_visual_feedback(self) -> Dict:
        """Get current visual effects state"""
        return {
            "particles": self.particle_effects,
            "lighting": self.lighting_effects
        }

