    def _has_low_health_teammate(self, game_state: GameState, team: Team) -> bool:
        """Check if any teammate has low health"""
        teammates = [r for r in game_state.robots.values() if r.team == team and r.is_alive()]
        return any(r.health < r.max_health * 0.3 for r in teammates)

    def get_best_action(self, robot: Robot) -> str:
        """Determine the best action for a robot using decision tree and learning"""
        if not robot.is_alive():
            return "idle"

        # Get strategy pattern for robot's role
        patterns = self.strategy_patterns.get(robot.role, [])

        # Apply learning-based adjustment
        if random.random() < self.exploration_rate:
            # Exploration: try a random action
            return random.choice([p["action"] for p in patterns])

        # Exploitation: use learned best action
        best_action = None
        best_priority = -1

        for pattern in patterns:
            if pattern["condition"](robot, self.game_state):
                # Check if this action has been successful in the past
                action_key = f"{robot.role.value}_{pattern['action']}_success"
                success_rate = robot.get_knowledge(action_key, 0.5)  # Default 50% success

                # Weight priority by success rate
                weighted_priority = pattern["priority"] * success_rate

                if weighted_priority > best_priority:
                    best_priority = weighted_priority
                    best_action = pattern["action"]

        # If no pattern matches, use default
        if best_action is None:
            best_action = patterns[0]["action"] if patterns else "patrol"

        # Update decision history
        self.decision_history.append({
            "robot_id": robot.id,
            "role": robot.role.value,
            "action": best_action,
            "timestamp": time.time()
        })

        return best_action

    def learn_from_outcome(self, robot: Robot, action: str, outcome: str):
        """Update knowledge based on action outcome"""
        # outcome: "success", "failure", "partial"

        action_key = f"{robot.role.value}_{action}_success"
        current_success_rate = robot.get_knowledge(action_key, 0.5)

        if outcome == "success":
            new_rate = min(current_success_rate + self.learning_rate, 1.0)
        elif outcome == "failure":
            new_rate = max(current_success_rate - self.learning_rate, 0.1)
        else:  # partial
            new_rate = current_success_rate

        robot.add_knowledge(action_key, new_rate)
        logger.debug(f"Robot {robot.id} learned: {action_key} -> {new_rate:.2f}")

    def adjust_difficulty(self):
        """Adaptive difficulty system based on team performance"""
        red_score = self.game_state.team_scores[Team.RED]
        blue_score = self.game_state.team_scores[Team.BLUE]

        # Calculate performance difference
        score_diff = abs(red_score - blue_score)
        avg_score = (red_score + blue_score) / 2 if (red_score + blue_score) > 0 else 0

        # Adjust AI behavior based on performance imbalance
        if score_diff > 15 and avg_score > 10:
            # Game is unbalanced, adjust difficulty
            if red_score > blue_score:
                # Blue team is losing, make blue AI more aggressive
                for robot in self.game_state.get_team_robots(Team.BLUE):
                    if robot.role == RobotRole.DEFENDER:
                        robot.role = RobotRole.ATTACKER
                        robot.vision_range = min(robot.vision_range * 1.2, 50.0)
                        robot.movement_speed = min(robot.movement_speed * 1.1, 3.5)
            else:
                # Red team is losing, make red AI more aggressive
                for robot in self.game_state.get_team_robots(Team.RED):
                    if robot.role == RobotRole.DEFENDER:
                        robot.role = RobotRole.ATTACKER
                        robot.vision_range = min(robot.vision_range * 1.2, 50.0)
                        robot.movement_speed = min(robot.movement_speed * 1.1, 3.5)

        # Adjust exploration rate based on game progression
        if avg_score > 20:
            self.exploration_rate = 0.1  # Less exploration, more refined strategies
        else:
            self.exploration_rate = 0.3  # More exploration early on

