@dataclass
class Vector2D:
    """2D Vector for position, velocity, and direction"""
    x: float = 0.0
    y: float = 0.0

    def __add__(self, other):
        return Vector2D(self.x + other.x, self.y + other.y)

    def __sub__(self, other):
        return Vector2D(self.x - other.x, self.y - other.y)

    def __mul__(self, scalar):
        return Vector2D(self.x * scalar, self.y * scalar)

    def __truediv__(self, scalar):
        if scalar == 0:
            return Vector2D(0, 0)
        return Vector2D(self.x / scalar, self.y / scalar)

    def magnitude(self):
        return math.sqrt(self.x**2 + self.y**2)

    def normalize(self):
        mag = self.magnitude()
        if mag == 0:
            return Vector2D(0, 0)
        return self / mag

    def distance_to(self, other):
        return (self - other).magnitude()

    def dot(self, other):
        return self.x * other.x + self.y * other.y

    def as_tuple(self):
        return (self.x, self.y)

@dataclass
class Weapon:
    """Weapon configuration for robots"""
    name: str
    type: WeaponType
    damage: float
    range: float
    fire_rate: float  # seconds between shots
    ammo: int
    reload_time: float
    effect: Optional[str] = None  # e.g., "explosion", "poison", "stun"

    def can_fire(self, last_fired: float) -> bool:
        return time.time() - last_fired >= self.fire_rate

@dataclass
class Robot:
    """Represents a single AI-controlled robot in the arena"""
    id: str
    team: Team
    role: RobotRole
    position: Vector2D
    velocity: Vector2D = field(default_factory=lambda: Vector2D(0, 0))
    health: float = 100.0
    max_health: float = 100.0
    armor: float = 0.0
    weapon: Optional[Weapon] = None
    secondary_weapon: Optional[Weapon] = None
    active_power_up: Optional[PowerUpType] = None
    power_up_timer: float = 0.0
    cooldowns: Dict[str, float] = field(default_factory=dict)  # ability_name -> end_time
    vision_range: float = 30.0
    movement_speed: float = 2.0
    last_action_time: float = 0.0
    last_target: Optional[str] = None
    target_objective: Optional[ObjectiveType] = None
    knowledge_base: Dict[str, Any] = field(default_factory=dict)  # Learning data
    decision_tree: List[Dict] = field(default_factory=list)  # Strategy rules

    def __post_init__(self):
        if not self.weapon:
            self.weapon = Weapon("Plasma Rifle", WeaponType.RANGED, 25.0, 50.0, 0.8, 30, 2.5)
        if not self.secondary_weapon:
            self.secondary_weapon = Weapon("Energy Blade", WeaponType.MELEE, 40.0, 5.0, 1.5, 1, 0.0)
        if not self.cooldowns:
            self.cooldowns = {
                "dash": 0.0,
                "shield": 0.0,
                "teleport": 0.0
            }

    def take_damage(self, damage: float) -> float:
        """Apply damage to robot, considering armor"""
        actual_damage = damage * (1 - min(self.armor / 100.0, 0.8))  # Max 80% reduction
        self.health -= actual_damage
        return actual_damage

    def heal(self, amount: float) -> float:
        """Heal robot, not exceeding max health"""
        heal_amount = min(amount, self.max_health - self.health)
        self.health += heal_amount
        return heal_amount

    def is_alive(self) -> bool:
        return self.health > 0

    def get_distance_to(self, other_position: Vector2D) -> float:
        return self.position.distance_to(other_position)

    def set_target(self, target_id: str):
        self.last_target = target_id

    def has_active_power_up(self) -> bool:
        return self.active_power_up is not None and self.power_up_timer > time.time()

    def update_power_up(self):
        """Decrease power-up timer and remove if expired"""
        if self.has_active_power_up():
            self.power_up_timer -= 0.1
            if self.power_up_timer <= time.time():
                self.active_power_up = None
                logger.info(f"Robot {self.id} power-up expired")

    def add_knowledge(self, key: str, value: Any):
        """Store learned information for adaptive behavior"""
        self.knowledge_base[key] = value

    def get_knowledge(self, key: str, default=None) -> Any:
        return self.knowledge_base.get(key, default)

    def get_role_priority(self) -> int:
        """Returns priority for role assignment (lower number = higher priority)"""
        role_priorities = {
            RobotRole.ATTACKER: 1,
            RobotRole.DEFENDER: 2,
            RobotRole.SUPPORT: 3,
            RobotRole.SCOUT: 4,
            RobotRole.CONTROLLER: 5
        }
        return role_priorities.get(self.role, 5)

@dataclass
class Objective:
    """Represents a team-based objective"""
    id: str
    type: ObjectiveType
    position: Vector2D
    team: Team
    capture_progress: float = 0.0
    is_active: bool = True
    defenders: Set[str] = field(default_factory=set)  # Robot IDs defending
    attackers: Set[str] = field(default_factory=set)  # Robot IDs attacking
    capture_threshold: float = 100.0
    spawn_points: List[Vector2D] = field(default_factory=list)

    def update_capture_progress(self, robot_count: int, team: Team) -> bool:
        """Update capture progress based on robots near objective"""
        if team != self.team:
            # Enemy team capturing
            self.capture_progress = min(self.capture_progress + robot_count * 0.5, self.capture_threshold)
        else:
            # Friendly team defending
            self.capture_progress = max(self.capture_progress - robot_count * 0.3, 0)

        return self.capture_progress >= self.capture_threshold

@dataclass
class PowerUp:
    """Power-up item in the arena"""
    id: str
    type: PowerUpType
    position: Vector2D
    spawn_time: float
    duration: float = 15.0
    active: bool = True
    radius: float = 3.0

    def is_collected(self, robot_position: Vector2D) -> bool:
        """Check if robot is within power-up radius"""
        return self.position.distance_to(robot_position) <= self.radius

@dataclass
class Hazard:
    """Environmental hazard in the arena"""
    id: str
    type: HazardType
    position: Vector2D
    radius: float
    damage_per_second: float
    active: bool = True
    spawn_time: float = 0.0
    duration: float = 30.0

    def affects_robot(self, robot_position: Vector2D) -> bool:
        """Check if robot is in hazard zone"""
        return self.position.distance_to(robot_position) <= self.radius

@dataclass
class GameState:
    """Current state of the entire game"""
    round_time: float = 0.0
    team_scores: Dict[Team, int] = field(default_factory=lambda: {Team.RED: 0, Team.BLUE: 0})
    objectives: Dict[str, Objective] = field(default_factory=dict)
    power_ups: Dict[str, PowerUp] = field(default_factory=dict)
    hazards: Dict[str, Hazard] = field(default_factory=dict)
    robots: Dict[str, Robot] = field(default_factory=dict)
    last_update: float = 0.0
    round_count: int = 0
    winner: Optional[Team] = None
    game_over: bool = False
    match_history: List[Dict] = field(default_factory=list)

    def get_team_robots(self, team: Team) -> List[Robot]:
        return [robot for robot in self.robots.values() if robot.team == team]

    def get_active_objectives(self) -> List[Objective]:
        return [obj for obj in self.objectives.values() if obj.is_active]

    def get_alive_robots(self) -> List[Robot]:
        return [robot for robot in self.robots.values() if robot.is_alive()]

    def get_team_winning(self) -> Optional[Team]:
        if not self.team_scores:
            return None
        return max(self.team_scores.keys(), key=lambda k: self.team_scores[k])

    def get_robot_by_id(self, robot_id: str) -> Optional[Robot]:
        return self.robots.get(robot_id)

    def get_closest_objective(self, robot: Robot) -> Optional[Objective]:
        """Find the closest active objective to robot"""
        active_objectives = self.get_active_objectives()
        if not active_objectives:
            return None

        closest = min(active_objectives, key=lambda obj: robot.position.distance_to(obj.position))
        return closest if robot.get_distance_to(closest.position) <= robot.vision_range else None

    def get_closest_enemy(self, robot: Robot) -> Optional[Robot]:
        """Find closest enemy robot within vision range"""
        enemies = [r for r in self.robots.values() 
                  if r.team != robot.team and r.is_alive() and r.get_distance_to(robot.position) <= robot.vision_range]
        if not enemies:
            return None
        return min(enemies, key=lambda e: robot.position.distance_to(e.position))

    def get_closest_power_up(self, robot: Robot) -> Optional[PowerUp]:
        """Find closest power-up within vision range"""
        power_ups = [pu for pu in self.power_ups.values() if pu.active and robot.get_distance_to(pu.position) <= robot.vision_range]
        if not power_ups:
            return None
        return min(power_ups, key=lambda pu: robot.position.distance_to(pu.position))

    def get_closest_hazard(self, robot: Robot) -> Optional[Hazard]:
        """Find closest hazard within vision range"""
        hazards = [h for h in self.hazards.values() if h.active and robot.get_distance_to(h.position) <= robot.vision_range]
        if not hazards:
            return None
        return min(hazards, key=lambda h: robot.position.distance_to(h.position))

