class ParticleManager:
    """Manages visual particle effects"""

    @dataclass
    class Particle:
        position: Vector2D
        velocity: Vector2D
        color: Tuple[int, int, int]
        life: float
        size: float
        type: str

    particles: List[Particle] = []

    @staticmethod
    def create_hit_effect(position: Vector2D):
        """Create hit particle effect"""
        for _ in range(8):
            angle = random.uniform(0, 2 * math.pi)
            speed = random.uniform(2, 5)
            velocity = Vector2D(
                math.cos(angle) * speed,
                math.sin(angle) * speed
            )
            ParticleManager.particles.append(
                ParticleManager.Particle(
                    position=position,
                    velocity=velocity,
                    color=(255, 50, 50),
                    life=1.0,
                    size=3,
                    type="hit"
                )
            )

    @staticmethod
    def create_explosion(position: Vector2D, particle_count: int, max_radius: float):
        """Create explosion effect"""
        for _ in range(particle_count):
            angle = random.uniform(0, 2 * math.pi)
            speed = random.uniform(1, 5)
            velocity = Vector2D(
                math.cos(angle) * speed,
                math.sin(angle) * speed
            )
            ParticleManager.particles.append(
                ParticleManager.Particle(
                    position=position,
                    velocity=velocity,
                    color=(255, 200, 50),
                    life=1.5,
                    size=random.uniform(4, 8),
                    type="explosion"
                )
            )

    @staticmethod
    def create_powerup_effect(position: Vector2D, power_up_type: PowerUpType):
        """Create power-up collection effect"""
        colors = {
            PowerUpType.SPEED_BOOST: (50, 255, 255),
            PowerUpType.SHIELD: (100, 150, 255),
            PowerUpType.DAMAGE_BOOST: (255, 50, 50),
            PowerUpType.REGEN: (50, 255, 100),
            PowerUpType.TELEPORT: (150, 50, 255)
        }
        color = colors.get(power_up_type, (255, 255, 255))

        for _ in range(12):
            angle = random.uniform(0, 2 * math.pi)
            speed = random.uniform(1, 3)
            velocity = Vector2D(
                math.cos(angle) * speed,
                math.sin(angle) * speed
            )
            ParticleManager.particles.append(
                ParticleManager.Particle(
                    position=position,
                    velocity=velocity,
                    color=color,
                    life=2.0,
                    size=random.uniform(2, 5),
                    type="powerup"
                )
            )

    @staticmethod
    def update_particles(dt: float):
        """Update all particles"""
        for particle in ParticleManager.particles[:]:
            particle.position = particle.position + (particle.velocity * dt)
            particle.life -= dt
            particle.size = max(0, particle.size - dt * 2)

            if particle.life <= 0:
                ParticleManager.particles.remove(particle)

class AdaptiveDifficultySystem:
    """Adapts game difficulty based on team performance"""

    def __init__(self):
        self.team_performance = {
            Team.RED: {'wins': 0, 'losses': 0, 'avg_progress': 0.0, 'avg_damage': 0.0},
            Team.BLUE: {'wins': 0, 'losses': 0, 'avg_progress': 0.0, 'avg_damage': 0.0}
        }
        self.difficulty_level = 1.0  # 1.0 is normal, >1.0 harder, <1.0 easier
        self.history = deque(maxlen=10)

    def update_performance(self, team: Team, win: bool, progress: float, damage_dealt: float):
        """Update team performance metrics"""
        if win:
            self.team_performance[team]['wins'] += 1
        else:
            self.team_performance[team]['losses'] += 1

        self.team_performance[team]['avg_progress'] = (
            self.team_performance[team]['avg_progress'] * 0.9 + progress * 0.1
        )
        self.team_performance[team]['avg_damage'] = (
            self.team_performance[team]['avg_damage'] * 0.9 + damage_dealt * 0.1
        )

        # Add to history for trend analysis
        self.history.append({
            'team': team,
            'win': win,
            'progress': progress,
            'damage': damage_dealt,
            'timestamp': time.time()
        })

        # Adjust difficulty based on performance imbalance
        self._adjust_difficulty()

    def _adjust_difficulty(self):
        """Adjust difficulty based on team performance imbalance"""
        if len(self.history) < 3:
            return

        red_avg = self.team_performance[Team.RED]['avg_progress'] + \
                  self.team_performance[Team.RED]['avg_damage']
        blue_avg = self.team_performance[Team.BLUE]['avg_progress'] + \
                   self.team_performance[Team.BLUE]['avg_damage']

        # If one team is significantly outperforming, adjust difficulty
        if red_avg > blue_avg * 1.5:
            # Make it harder for red team
