@dataclass
class PowerUp:
    type: PowerUpType
    position: Vector2D
    duration: float = 15.0  # seconds
    active: bool = True

    def collect(self, robot: Robot):
        """Collect power-up and apply to robot"""
        if self.active:
            robot.power_ups[self.type] = self.duration
            self.active = False
            ParticleManager.create_powerup_effect(self.position, self.type)
            SoundManager.play_sound("powerup_collect")

@dataclass
class EnvironmentalHazard:
    type: EnvironmentalHazard
    position: Vector2D
    radius: float = 30.0
    intensity: float = 1.0  # 0-1 scale
    active: bool = True

@dataclass
class Objective:
    type: ObjectiveType
    team: Team
    position: Vector2D
    progress: float = 0.0  # 0.0 to 1.0
    captured_by: Optional[Team] = None
    required_team_members: int = 2  # Number of team members needed to complete
    completion_threshold: float = 1.0  # Progress threshold to complete

    def get_target_position(self) -> Vector2D:
        """Get target position for objective"""
        if self.type == ObjectiveType.FLAG_CAPTURE:
            return self.position
        elif self.type == ObjectiveType.BASE_DEFENSE:
            return self.position
        elif self.type == ObjectiveType.PAYLOAD_ESCORT:
            # Payload moves toward destination
            return self.position

    def get_defense_position(self) -> Vector2D:
        """Get position that needs to be defended"""
        return self.position

    def update_progress(self, robots: List[Robot], dt: float):
        """Update objective progress based on team members near objective"""
        if self.captured_by:
            # Objective already captured
            return

        team_robots_near = [r for r in robots if r.team == self.team and 
                           r.position.distance_to(self.position) < 80]

        if len(team_robots_near) >= self.required_team_members:
            # Progress increases when team members are near
            self.progress = min(1.0, self.progress + dt * 0.1)
        else:
            # Progress decreases if not enough team members
            self.progress = max(0.0, self.progress - dt * 0.02)

        # Capture objective if progress reaches threshold
        if self.progress >= self.completion_threshold:
            self.captured_by = self.team
            self.progress = 1.0

@dataclass
class Environment:
    width: float = 1200
    height: float = 800
    robots: List[Robot] = field(default_factory=list)
    power_ups: List[PowerUp] = field(default_factory=list)
    hazards: List[EnvironmentalHazard] = field(default_factory=list)
    objectives: List[Objective] = field(default_factory=list)
    lighting: Dict = field(default_factory=dict)
    time_of_day: float = 0.5  # 0.0 to 1.0 (day to night)

    def __post_init__(self):
        self.lighting = {
            'ambient': 0.4,
            'directional': 0.6,
            'color': (200, 200, 255)  # Default blueish day light
        }
        # Initialize with some power-ups and hazards
        self._generate_initial_map()

    def _generate_initial_map(self):
        """Generate initial map with power-ups and hazards"""
        # Add power-ups randomly
        power_up_types = list(PowerUpType)
        for _ in range(5):
            x = random.uniform(100, self.width - 100)
            y = random.uniform(100, self.height - 100)
            power_up_type = random.choice(power_up_types)
            self.power_ups.append(PowerUp(power_up_type, Vector2D(x, y)))

        # Add hazards
        hazard_types = list(EnvironmentalHazard)
        for _ in range(3):
            x = random.uniform(150, self.width - 150)
            y = random.uniform(150, self.height - 150)
            hazard_type = random.choice(hazard_types)
            self.hazards.append(EnvironmentalHazard(hazard_type, Vector2D(x, y)))

    def update(self, dt: float):
        """Update environment state"""
        # Update time of day (slowly cycles)
        self.time_of_day = (self.time_of_day + dt * 0.0001) % 1.0

        # Update lighting based on time of day
        if self.time_of_day < 0.3:  # Night
            self.lighting['ambient'] = 0.1
            self.lighting['directional'] = 0.2
            self.lighting['color'] = (50, 50, 100)
        elif self.time_of_day < 0.5:  # Dawn
            self.lighting['ambient'] = 0.2
            self.lighting['directional'] = 0.4
            self.lighting['color'] = (150, 100, 180)
        elif self.time_of_day < 0.7:  # Day
            self.lighting['ambient'] = 0.4
            self.lighting['directional'] = 0.6
            self.lighting['color'] = (200, 200, 255)
        else:  # Dusk
            self.lighting['ambient'] = 0.3
            self.lighting['directional'] = 0.5
            self.lighting['color'] = (220, 150, 100)

        # Update objectives
        for objective in self.objectives:
            objective.update_progress(self.robots, dt)

        # Check for power-up collection
        for power_up in list(self.power_ups):
            if not power_up.active:
                self.power_ups.remove(power_up)
                continue

            for robot in self.robots:
                if robot.position.distance_to(power_up.position) < 40:
                    power_up.collect(robot)
                    break

