class AdaptiveDifficultySystem:
    """Adapts game difficulty based on team performance"""

    def __init__(self):
        self.team_performance = {
            Team.RED: {'wins': 0, 'losses': 0, 'avg_progress': 0.0, 'avg_damage': 0.0},
            Team.BLUE: {'wins': 0, 'losses': 0, 'avg_progress': 0.0, 'avg_damage': 0.0}
        }
        self.difficulty_level = 1.0  # 1.0 is normal, >1.0 harder, <1.0 easier
        self.history = deque(maxlen=10)

    def update_performance(self, team: Team, win: bool, progress: float, damage_dealt: float):
        """Update team performance metrics"""
        if win:
            self.team_performance[team]['wins'] += 1
        else:
            self.team_performance[team]['losses'] += 1

        self.team_performance[team]['avg_progress'] = (
            self.team_performance[team]['avg_progress'] * 0.9 + progress * 0.1
        )
        self.team_performance[team]['avg_damage'] = (
            self.team_performance[team]['avg_damage'] * 0.9 + damage_dealt * 0.1
        )

        # Add to history for trend analysis
        self.history.append({
            'team': team,
            'win': win,
            'progress': progress,
            'damage': damage_dealt,
            'timestamp': time.time()
        })

        # Adjust difficulty based on performance imbalance
        self._adjust_difficulty()

    def _adjust_difficulty(self):
        """Adjust difficulty based on team performance imbalance"""
        if len(self.history) < 3:
            return

        red_avg = self.team_performance[Team.RED]['avg_progress'] + \
                  self.team_performance[Team.RED]['avg_damage']
        blue_avg = self.team_performance[Team.BLUE]['avg_progress'] + \
                   self.team_performance[Team.BLUE]['avg_damage']

        # If one team is significantly outperforming, adjust difficulty
        if red_avg > blue_avg * 1.5:
            # Make it harder for red team
            self.difficulty_level = min(1.5, self.difficulty_level + 0.05)
        elif blue_avg > red_avg * 1.5:
            # Make it harder for blue team
            self.difficulty_level = min(1.5, self.difficulty_level + 0.05)
        else:
            # Normalize difficulty if balanced
            self.difficulty_level = max(0.7, self.difficulty_level - 0.02)

    def get_ai_intensity(self, team: Team) -> float:
        """Get AI intensity factor for team based on difficulty"""
        # Higher difficulty means more aggressive AI
        base_intensity = 1.0
        # Adjust based on team performance
        if self.team_performance[team]['wins'] > self.team_performance[team]['losses'] * 2:
            # Team is winning too much, make AI more challenging
            return base_intensity * self.difficulty_level * 1.3
        elif self.team_performance[team]['losses'] > self.team_performance[team]['wins'] * 2:
            # Team is losing too much, make AI easier
            return base_intensity * self.difficulty_level * 0.7
        else:
            return base_intensity * self.difficulty_level

