    SPEED_BOOST = "speed_boost"
    SHIELD = "shield"
    DAMAGE_BOOST = "damage_boost"
    REGEN = "regen"
    TELEPORT = "teleport"

class EnvironmentalHazard(Enum):
    LAVA = "lava"
    ELECTRIC_FIELD = "electric_field"
    GRAVITY_WELL = "gravity_well"
    SLOW_FIELD = "slow_field"

@dataclass
class Vector2D:
    x: float = 0.0
    y: float = 0.0

    def __add__(self, other):
        return Vector2D(self.x + other.x, self.y + other.y)

    def __sub__(self, other):
        return Vector2D(self.x - other.x, self.y - other.y)

    def __mul__(self, scalar):
        return Vector2D(self.x * scalar, self.y * scalar)

    def magnitude(self):
        return math.sqrt(self.x**2 + self.y**2)

    def normalize(self):
        mag = self.magnitude()
        if mag == 0:
            return Vector2D(0, 0)
        return Vector2D(self.x / mag, self.y / mag)

    def distance_to(self, other):
        return (self - other).magnitude()

@dataclass
class Robot:
    id: str
    team: Team
    role: RobotRole
    position: Vector2D
    velocity: Vector2D = field(default_factory=lambda: Vector2D(0, 0))
    health: float = 100.0
    max_health: float = 100.0
    speed: float = 5.0
    weapon: WeaponType = WeaponType.RANGED
    cooldown: float = 0.0
    shield: float = 0.0
    power_ups: Dict[PowerUpType, float] = field(default_factory=dict)
    last_action: str = ""
    memory: List[Dict] = field(default_factory=list)  # For learning
    strategy: Dict = field(default_factory=dict)  # Adaptive strategy

    def __post_init__(self):
        self.strategy = {
            "aggression": 0.5,  # 0-1 scale
            "caution": 0.5,     # 0-1 scale  
            "teamwork": 0.5,    # 0-1 scale
            "adaptability": 0.5 # 0-1 scale
        }
        self.power_ups = {power_up: 0.0 for power_up in PowerUpType}

    def update(self, dt: float, environment: 'Environment', objective: 'Objective'):
        """Update robot state based on time delta and environment"""
        # Update cooldowns
        if self.cooldown > 0:
            self.cooldown -= dt

        # Update power-ups
        for power_up, duration in list(self.power_ups.items()):
            if duration > 0:
                self.power_ups[power_up] = max(0, duration - dt)
                if self.power_ups[power_up] == 0:
                    self.apply_power_up_effect(power_up, remove=True)

        # Apply speed boost if active
        if self.power_ups[PowerUpType.SPEED_BOOST] > 0:
            self.speed = 8.0  # 60% faster
        else:
            self.speed = 5.0

        # Apply damage boost if active
        if self.power_ups[PowerUpType.DAMAGE_BOOST] > 0:
            # This will affect damage calculation in attack
            pass

        # Apply regen if active
        if self.power_ups[PowerUpType.REGEN] > 0 and self.health < self.max_health:
            self.health = min(self.max_health, self.health + 0.5 * dt)

        # Update position based on velocity
        self.position = self.position + (self.velocity * dt)

        # Apply environmental effects
        for hazard in environment.hazards:
            if self.is_in_hazard(hazard):
                self.apply_hazard_effect(hazard, dt)

        # Ensure robot stays within bounds
        self.position.x = max(0, min(environment.width, self.position.x))
        self.position.y = max(0, min(environment.height, self.position.y))

        # Update memory with current state for learning
        self.memory.append({
            'timestamp': time.time(),
            'health': self.health,
            'position': (self.position.x, self.position.y),
            'role': self.role,
            'objective_progress': objective.progress,
            'enemy_nearby': len(self.get_nearby_enemies(environment.robots)),
            'team_mates_nearby': len(self.get_nearby_teammates(environment.robots))
        })

        # Limit memory size to prevent memory leaks
        if len(self.memory) > 100:
            self.memory.pop(0)

    def get_nearby_enemies(self, robots: List['Robot']) -> List['Robot']:
        """Get enemies within sensing range (100 units)"""
        enemies = []
        for robot in robots:
            if robot.team != self.team:
                distance = self.position.distance_to(robot.position)
                if distance < 100:
                    enemies.append(robot)
        return enemies

    def get_nearby_teammates(self, robots: List['Robot']) -> List['Robot']:
        """Get teammates within sensing range (150 units)"""
        teammates = []
        for robot in robots:
            if robot.team == self.team:
                distance = self.position.distance_to(robot.position)
                if distance < 150:
                    teammates.append(robot)
        return teammates

    def is_in_hazard(self, hazard: 'EnvironmentalHazard') -> bool:
        """Check if robot is within hazard area"""
        distance = self.position.distance_to(hazard.position)
        return distance < hazard.radius

    def apply_hazard_effect(self, hazard: 'EnvironmentalHazard', dt: float):
        """Apply effect of environmental hazard to robot"""
        if hazard.type == EnvironmentalHazard.LAVA:
            self.health -= 2 * dt
        elif hazard.type == EnvironmentalHazard.ELECTRIC_FIELD:
            self.velocity = self.velocity * 0.5  # Slow down
            self.health -= 0.5 * dt
        elif hazard.type == EnvironmentalHazard.GRAVITY_WELL:
            # Pull robot toward hazard
            direction = (hazard.position - self.position).normalize()
            self.velocity = self.velocity + (direction * 2 * dt)
        elif hazard.type == EnvironmentalHazard.SLOW_FIELD:
            self.speed = max(1.0, self.speed * 0.7)

    def apply_power_up_effect(self, power_up: PowerUpType, remove: bool = False):
        """Apply or remove power-up effect"""
        if power_up == PowerUpType.SPEED_BOOST:
            if remove:
                self.speed = 5.0
            else:
                self.speed = 8.0
        elif power_up == PowerUpType.SHIELD:
            if remove:
                self.shield = 0.0
            else:
                self.shield = 50.0
        elif power_up == PowerUpType.DAMAGE_BOOST:
            if remove:
                # Remove any damage multiplier effect
                pass
        elif power_up == PowerUpType.REGEN:
            if remove:
                pass
        elif power_up == PowerUpType.TELEPORT:
            # Teleport to random location (on activation)
            pass

    def attack(self, target: 'Robot', environment: 'Environment') -> float:
        """Perform attack on target and return damage dealt"""
        if self.cooldown > 0:
            return 0.0

        distance = self.position.distance_to(target.position)
        damage = 0.0

        # Weapon-specific damage and range
        if self.weapon == WeaponType.RANGED:
            if distance < 300:  # Ranged weapon effective range
                damage = 25.0
                # Apply damage boost if active
                if self.power_ups[PowerUpType.DAMAGE_BOOST] > 0:
                    damage *= 1.5
                # Apply team synergy bonus
                nearby_teammates = self.get_nearby_teammates(environment.robots)
                if len(nearby_teammates) > 1:
                    damage *= 1.1

                self.cooldown = 1.0  # 1 second cooldown for ranged
                # Play sound effect
                SoundManager.play_sound("ranged_shot")
            else:
                return 0.0  # Out of range

        elif self.weapon == WeaponType.MELEE:
            if distance < 50:  # Melee range
                damage = 40.0
                if self.power_ups[PowerUpType.DAMAGE_BOOST] > 0:
                    damage *= 1.5
                self.cooldown = 1.5  # Longer cooldown for melee
                SoundManager.play_sound("melee_strike")
            else:
                return 0.0  # Too far

        elif self.weapon == WeaponType.SPECIAL:
            if distance < 200:
                damage = 50.0
                self.cooldown = 5.0  # Long cooldown for special
                SoundManager.play_sound("special_ability")
                # Create particle effect
                ParticleManager.create_explosion(self.position, 50, 10)

        # Apply shield reduction if target has shield
        if target.shield > 0:
            shield_absorbed = min(damage, target.shield)
            target.shield -= shield_absorbed
            damage -= shield_absorbed

        # Apply damage to health
        target.health = max(0, target.health - damage)

        # Create hit particle effect
        if damage > 0:
            ParticleManager.create_hit_effect(target.position)
            SoundManager.play_sound("hit")

        return damage

    def choose_action(self, environment: 'Environment', objective: 'Objective') -> str:
        """AI decision-making for robot actions using adaptive strategy"""
        # Get nearby enemies and teammates
        enemies = self.get_nearby_enemies(environment.robots)
        teammates = self.get_nearby_teammates(environment.robots)def choose_action(self, environment: 'Environment', objective: 'Objective') -> str:
        """AI decision-making for robot actions using adaptive strategy"""
        # Get nearby enemies and teammates
        enemies = self.get_nearby_enemies(environment.robots)
        teammates = self.get_nearby_teammates(environment.robots)

        # Filter out dead enemies
        alive_enemies = [e for e in enemies if e.health > 0]

        # Determine priority based on role
        if self.role == RobotRole.ATTACKER:
            if alive_enemies:
                # Focus on closest alive enemy
                closest_enemy = min(alive_enemies, key=lambda e: self.position.distance_to(e.position))
                # Check if we can attack
                distance = self.position.distance_to(closest_enemy.position)
                if distance <= 300 and self.cooldown <= 0:
                    self.last_action = f"attack_{closest_enemy.id}"
                    return "attack"
                else:
                    # Move toward enemy
                    direction = (closest_enemy.position - self.position).normalize()
                    self.velocity = direction * self.speed
                    self.last_action = f"move_toward_{closest_enemy.id}"
                    return "move"
            else:
                # No alive enemies, move toward objective as fallback
                return self._move_toward_objective(objective)

        elif self.role == RobotRole.DEFENDER:
            if alive_enemies:
                # Defend base or objective
                base_pos = objective.get_defense_position() if objective else self.position
                if self.position.distance_to(base_pos) > 50:
                    # Move toward base
                    direction = (base_pos - self.position).normalize()
                    self.velocity = direction * self.speed
                    self.last_action = "move_to_base"
                    return "move"
                else:
                    # Stay and defend
                    self.velocity = Vector2D(0, 0)
                    # Attack if alive enemy is nearby
                    closest_enemy = min(alive_enemies, key=lambda e: self.position.distance_to(e.position))
                    if self.position.distance_to(closest_enemy.position) < 100 and self.cooldown <= 0:
                        self.last_action = f"defend_attack_{closest_enemy.id}"
                        return "attack"
            else:
                # No alive enemies, patrol objective as fallback
                return self._patrol_objective(objective)

        elif self.role == RobotRole.SUPPORT:
            # Heal or buff teammates
            low_health_teammates = [t for t in teammates if t.health < t.max_health * 0.6]
            if low_health_teammates:
                target = min(low_health_teammates, key=lambda t: t.health)
                # Move to support
                direction = (target.position - self.position).normalize()
                self.velocity = direction * self.speed
                self.last_action = f"support_{target.id}"
                return "move"
            else:
                # Look for power-ups
                return self._seek_power_up(environment)

        elif self.role == RobotRole.SCOUT:
            if alive_enemies:
                # Report enemy positions
                self.last_action = f"scout_report_{len(alive_enemies)}_enemies"
                # Move to flank enemy
                closest_enemy = min(alive_enemies, key=lambda e: self.position.distance_to(e.position))
                # Move to side of enemy position
                direction = (closest_enemy.position - self.position).normalize()
                # Move perpendicular to direct path
                perpendicular = Vector2D(-direction.y, direction.x)
                target_pos = closest_enemy.position + (perpendicular * 40)
                direction_to_target = (target_pos - self.position).normalize()
                self.velocity = direction_to_target * self.speed
                return "move"
            else:
                # No alive enemies, explore map as fallback
                return self._explore_map(environment)

        # Default action: move toward objective (guaranteed fallback)
        return self._move_toward_objective(objective)    def _move_toward_objective(self, objective: 'Objective') -> str:
        """Move toward the current objective"""
        if not objective:
            return "idle"

        target_pos = objective.get_target_position()
        if target_pos:
            direction = (target_pos - self.position).normalize()
            self.velocity = direction * self.speed
            self.last_action = f"move_to_objective_{objective.type.value}"
            return "move"
        return "idle"

    def _patrol_objective(self, objective: 'Objective') -> str:
        """Patrol around objective"""
        if not objective:
            return "idle"

        base_pos = objective.get_defense_position()
        if not base_pos:
            return "idle"

        # Define patrol points around objective
        patrol_points = [
            base_pos + Vector2D(50, 50),
            base_pos + Vector2D(-50, 50),
            base_pos + Vector2D(-50, -50),
            base_pos + Vector2D(50, -50)
        ]

        # Find closest patrol point
        closest_point = min(patrol_points, key=lambda p: self.position.distance_to(p))
        direction = (closest_point - self.position).normalize()
        self.velocity = direction * self.speed
        self.last_action = "patrol_objective"
        return "move"

    def _seek_power_up(self, environment: 'Environment') -> str:
        """Seek available power-ups"""
        if not environment.power_ups:
            return "idle"

        closest_powerup = min(environment.power_ups, key=lambda p: self.position.distance_to(p.position))
        direction = (closest_powerup.position - self.position).normalize()
        self.velocity = direction * self.speed
        self.last_action = f"seek_{closest_powerup.type.value}"
        return "move"

    def _explore_map(self, environment: 'Environment') -> str:
        """Explore unvisited areas of the map"""
        # Simple exploration: move toward edge of known area
        # For simplicity, move toward map center if far from center
        center = Vector2D(environment.width/2, environment.height/2)
        direction = (center - self.position).normalize()
        self.velocity = direction * self.speed
        self.last_action = "explore"
        return "move"

    def adapt_strategy(self, battle_result: Dict):
        """Update strategy based on battle outcomes (learning)"""
        # Simple learning: adjust strategy parameters based on performance
        # This is a simplified reinforcement learning model

        # Win/loss ratio affects aggression and caution
        if battle_result.get('win', False):
            # Increase aggression and teamwork if won
            self.strategy['aggression'] = min(1.0, self.strategy['aggression'] + 0.05)
            self.strategy['teamwork'] = min(1.0, self.strategy['teamwork'] + 0.03)
        else:
            # Increase caution if lost
            self.strategy['caution'] = min(1.0, self.strategy['caution'] + 0.05)

        # Teamwork improvement based on success of coordinated actions
        if battle_result.get('teamwork_success', 0) > 0.7:
            self.strategy['teamwork'] = min(1.0, self.strategy['teamwork'] + 0.04)

        # Adaptability based on changing conditions
        if battle_result.get('adaptable_actions', 0) > 3:
            self.strategy['adaptability'] = min(1.0, self.strategy['adaptability'] + 0.03)

        # Apply learning to role behavior
        if self.role == RobotRole.ATTACKER:
            self.strategy['aggression'] = max(0.3, self.strategy['aggression'])
        elif self.role == RobotRole.DEFENDER:
            self.strategy['caution'] = max(0.4, self.strategy['caution'])
        elif self.role == RobotRole.SUPPORT:
            self.strategy['teamwork'] = max(0.5, self.strategy['teamwork'])

@dataclass
class PowerUp:
    type: PowerUpType
    position: Vector2D
    duration: float = 15.0  # seconds
    active: bool = True

    def collect(self, robot: Robot):
        """Collect power-up and apply to robot"""
        if self.active:
            robot.power_ups[self.type] = self.duration
            self.active = False
            ParticleManager.create_powerup_effect(self.position, self.type)
            SoundManager.play_sound("powerup_collect")

@dataclass
class EnvironmentalHazard:
    type: EnvironmentalHazard
    position: Vector2D
    radius: float = 30.0
    intensity: float = 1.0  # 0-1 scale
    active: bool = True

@dataclass
class Objective:
    type: ObjectiveType
    team: Team
    position: Vector2D
    progress: float = 0.0  # 0.0 to 1.0
    captured_by: Optional[Team] = None
    required_team_members: int = 2  # Number of team members needed to complete
    completion_threshold: float = 1.0  # Progress threshold to complete

    def get_target_position(self) -> Vector2D:
        """Get target position for objective"""
        if self.type == ObjectiveType.FLAG_CAPTURE:
            return self.position
        elif self.type == ObjectiveType.BASE_DEFENSE:
            return self.position
        elif self.type == ObjectiveType.PAYLOAD_ESCORT:
            # Payload moves toward destination
            return self.position

    def get_defense_position(self) -> Vector2D:
        """Get position that needs to be defended"""
        return self.position

    def update_progress(self, robots: List[Robot], dt: float):
        """Update objective progress based on team members near objective"""
        if self.captured_by:
            # Objective already captured
            return

        team_robots_near = [r for r in robots if r.team == self.team and 
                           r.position.distance_to(self.position) < 80]

        if len(team_robots_near) >= self.required_team_members:
            # Progress increases when team members are near
            self.progress = min(1.0, self.progress + dt * 0.1)
        else:
            # Progress decreases if not enough team members
            self.progress = max(0.0, self.progress - dt * 0.02)

        # Capture objective if progress reaches threshold
        if self.progress >= self.completion_threshold:
            self.captured_by = self.team
            self.progress = 1.0

@dataclass
class Environment:
    width: float = 1200
    height: float = 800
    robots: List[Robot] = field(default_factory=list)
    power_ups: List[PowerUp] = field(default_factory=list)
    hazards: List[EnvironmentalHazard] = field(default_factory=list)
    objectives: List[Objective] = field(default_factory=list)
    lighting: Dict = field(default_factory=dict)
    time_of_day: float = 0.5  # 0.0 to 1.0 (day to night)

    def __post_init__(self):
        self.lighting = {
            'ambient': 0.4,
            'directional': 0.6,
            'color': (200, 200, 255)  # Default blueish day light
        }
        # Initialize with some power-ups and hazards
        self._generate_initial_map()

    def _generate_initial_map(self):
        """Generate initial map with power-ups and hazards"""
        # Add power-ups randomly
        power_up_types = list(PowerUpType)
        for _ in range(5):
            x = random.uniform(100, self.width - 100)
            y = random.uniform(100, self.height - 100)
            power_up_type = random.choice(power_up_types)
            self.power_ups.append(PowerUp(power_up_type, Vector2D(x, y)))

        # Add hazards
        hazard_types = list(EnvironmentalHazard)
        for _ in range(3):
            x = random.uniform(150, self.width - 150)
            y = random.uniform(150, self.height - 150)
            hazard_type = random.choice(hazard_types)
            self.hazards.append(EnvironmentalHazard(hazard_type, Vector2D(x, y)))

    def update(self, dt: float):
        """Update environment state"""
        # Update time of day (slowly cycles)
        self.time_of_day = (self.time_of_day + dt * 0.0001) % 1.0

        # Update lighting based on time of day
        if self.time_of_day < 0.3:  # Night
            self.lighting['ambient'] = 0.1
            self.lighting['directional'] = 0.2
            self.lighting['color'] = (50, 50, 100)
        elif self.time_of_day < 0.5:  # Dawn
            self.lighting['ambient'] = 0.2
            self.lighting['directional'] = 0.4
            self.lighting['color'] = (150, 100, 180)
        elif self.time_of_day < 0.7:  # Day
            self.lighting['ambient'] = 0.4
            self.lighting['directional'] = 0.6
            self.lighting['color'] = (200, 200, 255)
        else:  # Dusk
            self.lighting['ambient'] = 0.3
            self.lighting['directional'] = 0.5
            self.lighting['color'] = (220, 150, 100)

        # Update objectives
        for objective in self.objectives:
            objective.update_progress(self.robots, dt)

        # Check for power-up collection
        for power_up in list(self.power_ups):
            if not power_up.active:
                self.power_ups.remove(power_up)
                continue

            for robot in self.robots:
                if robot.position.distance_to(power_up.position) < 40:
                    power_up.collect(robot)
                    break

