    RIFLE = "rifle"
    SHOTGUN = "shotgun"
    PLASMA = "plasma"
    MELEE = "melee"
    MISSILE = "missile"

class AbilityType(Enum):
    HEAL = "heal"
    SLOW = "slow"
    BOOST = "boost"
    INVISIBILITY = "invisibility"
    BARRICADE = "barricade"
    EXPLOSION = "explosion"

class MapFeature(Enum):
