@dataclass
class Position:
    x: float
    y: float

    def distance_to(self, other: 'Position') -> float:
        return math.sqrt((self.x - other.x)**2 + (self.y - other.y)**2)

    def clamp(self, min_x, max_x, min_y, max_y) -> 'Position':
        return Position(
            max(min_x, min(max_x, self.x)),
            max(min_y, min(max_y, self.y))
        )

@dataclass
class Character:
    id: str
    team: Team
    robot_type: RobotType
    position: Position
    health: float = 100.0
    max_health: float = 100.0
    speed: float = 5.0
    weapon: WeaponType = WeaponType.PISTOL
    abilities: List[AbilityType] = field(default_factory=list)
    is_alive: bool = True
    cooldowns: Dict[AbilityType, float] = field(default_factory=dict)
    score: int = 0

    def use_ability(self, ability: AbilityType, game_state: 'GameState') -> bool:
        if ability not in self.abilities:
            return False
        if self.cooldowns.get(ability, 0) > 0:
            return False

        # Apply ability effect
        if ability == AbilityType.HEAL:
            self.health = min(self.max_health, self.health + 25)
        elif ability == AbilityType.SLOW:
            for char in game_state.characters:
                if char.team != self.team and char.position.distance_to(self.position) < 15:
                    char.speed *= 0.5
                    char.cooldowns[AbilityType.SLOW] = 5.0  # Apply slow effect duration
        elif ability == AbilityType.BOOST:
            self.speed *= 1.5
            self.cooldowns[AbilityType.BOOST] = 8.0
        elif ability == AbilityType.INVISIBILITY:
            self.is_invisible = True
            self.cooldowns[AbilityType.INVISIBILITY] = 10.0
        elif ability == AbilityType.BARRICADE:
            game_state.map_features.append(MapFeature.BARRICADE)
        elif ability == AbilityType.EXPLOSION:
            for char in game_state.characters:
                if char.position.distance_to(self.position) < 10:
                    char.health -= 30

        # Set cooldown
        self.cooldowns[ability] = 15.0  # Base cooldown in seconds
        return True

    def take_damage(self, damage: float):
        self.health = max(0, self.health - damage)
        if self.health <= 0:
            self.is_alive = False

@dataclass
class MapPoint:
    position: Position
    team: Optional[Team] = None  # Which team currently holds it
    capture_progress: float = 0.0  # 0.0 to 1.0
    capture_rate: float = 0.01  # per tick
    is_active: bool = True

@dataclass
class PowerUp:
    position: Position
    type: str  # e.g., "health", "speed", "damage"
    duration: int = 10  # seconds
    is_active: bool = True

@dataclass
class GameState:
    characters: List[Character] = field(default_factory=list)
    map_points: List[MapPoint] = field(default_factory=list)
    power_ups: List[PowerUp] = field(default_factory=list)
    map_features: List[MapFeature] = field(default_factory=list)
    team_scores: Dict[Team, int] = field(default_factory=lambda: {Team.RED: 0, Team.BLUE: 0})
    time_elapsed: float = 0.0
    game_running: bool = False
    match_duration: int = 600  # 10 minutes in seconds

    def get_team_characters(self, team: Team) -> List[Character]:
        return [char for char in self.characters if char.team == team]

    def get_nearest_key_point(self, position: Position) -> Optional[MapPoint]:
        if not self.map_points:
            return None
        return min(self.map_points, key=lambda p: p.position.distance_to(position))

    def update_capture_points(self):
        for point in self.map_points:
            if not point.is_active:
                continue

            red_count = sum(1 for c in self.get_team_characters(Team.RED) if c.position.distance_to(point.position) < 8)
            blue_count = sum(1 for c in self.get_team_characters(Team.BLUE) if c.position.distance_to(point.position) < 8)

            if red_count > blue_count:
                point.capture_progress = max(0, point.capture_progress - point.capture_rate)
                if point.capture_progress <= 0:
                    point.team = Team.RED
            elif blue_count > red_count:
                point.capture_progress = min(1, point.capture_progress + point.capture_rate)
                if point.capture_progress >= 1:
                    point.team = Team.BLUE
            else:
                # Neutral
                if point.capture_progress > 0.5:
                    point.capture_progress = max(0.5, point.capture_progress - point.capture_rate)
                else:
                    point.capture_progress = min(0.5, point.capture_progress + point.capture_rate)
                point.team = None

    def update_power_ups(self):
        for power in self.power_ups:
            if not power.is_active:
                continue
            power.duration -= 1
            if power.duration <= 0:
                power.is_active = False

    def update_cooldowns(self):
        for char in self.characters:
            for ability in list(char.cooldowns.keys()):
                if char.cooldowns[ability] > 0:
                    char.cooldowns[ability] -= 1/60  # Assuming 60 FPS

    def update(self, delta_time: float):
        self.time_elapsed += delta_time
        self.update_capture_points()
        self.update_power_ups()
        self.update_cooldowns()

        if self.time_elapsed >= self.match_duration:
            self.game_running = False

