    def apply_ability(self, ability: AbilityType, target: Optional['Character'] = None):
        if ability not in self.abilities:
            return False

        if ability in self.cooldowns and self.cooldowns[ability] > 0:
            return False

        # Apply ability effect
        if ability == AbilityType.BOOST:
            self.speed *= 1.5
            self.cooldowns[ability] = 5.0
        elif ability == AbilityType.SHIELD:
            self.health = min(self.max_health, self.health + 30)
            self.cooldowns[ability] = 10.0
        elif ability == AbilityType.TELEPORT:
            # Teleport to random position within 50 units
            angle = random.uniform(0, 2 * math.pi)
            dist = random.uniform(10, 50)
            self.position.x += dist * math.cos(angle)
            self.position.y += dist * math.sin(angle)
