            target.speed *= 0.5
            target.cooldowns[AbilityType.SLOW] = 4.0  # Apply slow on target
            self.cooldowns[ability] = 8.0
        elif ability == AbilityType.HEAL and target:
            target.health = min(target.max_health, target.health + 25)
            self.cooldowns[ability] = 6.0
        elif ability == AbilityType.STUN and target:
            target.speed = 0.0
            target.cooldowns[AbilityType.STUN] = 3.0
            self.cooldowns[ability] = 12.0

        return True

    def update_cooldowns(self, dt: float):
        for ability in list(self.cooldowns.keys()):
            self.cooldowns[ability] = max(0, self.cooldowns[ability] - dt)

