    def capture_by(self, team: Team, dt: float):
        if not self.is_active:
            return

        if self.team == team:
            self.capture_progress = min(100.0, self.capture_progress + self.capture_rate * dt)
        else:
            delta = self.capture_rate * dt
            if self.team is None:
                self.capture_progress += delta
                self.team = team
            else:
                # Competing capture
                if self.team != team:
                    self.capture_progress -= delta
                    if self.capture_progress <= 0:
                        self.team = team
                        self.capture_progress = 0
                else:
                    self.capture_progress += delta

        if self.capture_progress >= 100.0:
            self.team = team
            self.capture_progress = 100.0

