    position: Position
    velocity: Velocity = field(default_factory=Velocity)
    health: float = 100.0
    max_health: float = 100.0
    armor: float = 0.0
    energy: float = 100.0
    max_energy: float = 100.0
    weapons: List[Weapon] = field(default_factory=list)
    active_weapon_index: int = 0
    is_alive: bool = True
    last_updated: float = 0.0
    strategy_memory: List[Dict] = field(default_factory=list)  # History of actions and outcomes
    learning_rate: float = 0.1  # How quickly the robot learns from experience
    decision_tree: Dict = field(default_factory=dict)  # AI decision tree for strategy

    def __post_init__(self):
        if not self.weapons:
            # Default weapons based on role
            if self.role == RobotRole.ATTACKER:
                self.weapons = [
                    Weapon("Plasma Rifle", WeaponType.RANGED, 25.0, 50.0, 5.0, 30, 2.0, 30.0),
                    Weapon("Plasma Blade", WeaponType.MELEE, 40.0, 5.0, 1.0, 1, 0.5)
                ]
            elif self.role == RobotRole.DEFENDER:
                self.weapons = [
                    Weapon("Heavy Cannon", WeaponType.RANGED, 30.0, 40.0, 2.0, 15, 3.5, 20.0, 8.0),
                    Weapon("Shield Generator", WeaponType.SPECIAL, 0.0, 10.0, 0.0, 1, 5.0)
                ]
            elif self.role == RobotRole.SUPPORT:
                self.weapons = [
                    Weapon("Medi-Gun", WeaponType.SPECIAL, 0.0, 30.0, 0.0, 1, 0.0),
                    Weapon("Pulse Pistol", WeaponType.RANGED, 15.0, 35.0, 6.0, 20, 1.5, 25.0)
                ]
            elif self.role == RobotRole.SCOUT:
                self.weapons = [
                    Weapon("Sniper Rifle", WeaponType.RANGED, 50.0, 100.0, 1.5, 10, 4.0, 50.0),
                    Weapon("Nano-Knife", WeaponType.MELEE, 30.0, 3.0, 1.5, 1, 0.3)
                ]
            else:  # CONTROLLER
                self.weapons = [
                    Weapon("EMP Pulse", WeaponType.SPECIAL, 0.0, 25.0, 0.0, 1, 10.0),
                    Weapon("Stun Baton", WeaponType.MELEE, 20.0, 4.0, 2.0, 1, 1.0)
                ]
            self.active_weapon_index = 0

    def take_damage(self, damage: float, source: Optional[str] = None) -> float:
        if not self.is_alive:
            return 0.0

        # Apply armor reduction
        actual_damage = max(0, damage - self.armor)
        self.health = max(0, self.health - actual_damage)

        if self.health <= 0:
            self.is_alive = False
            logger.info(f"Robot {self.id} ({self.team.value}) has been eliminated by {source if source else 'unknown'}")

        return actual_damage

    def heal(self, amount: float) -> None:
        if self.is_alive:
            self.health = min(self.max_health, self.health + amount)

    def recharge_energy(self, amount: float) -> None:
        if self.is_alive:
            self.energy = min(self.max_energy, self.energy + amount)

    def use_weapon(self, target_position: Position, current_time: float) -> Optional[Dict]:
        """Fire the active weapon and return weapon effect data if successful"""
        if not self.is_alive:
            return None

        weapon = self.weapons[self.active_weapon_index]

        if not weapon.can_fire():
            return None

        # Calculate distance to target
        distance = self.position.distance_to(target_position)

        # Check if target is within range
        if distance > weapon.range:
            return None

        # Fire weapon
        weapon.fire()

        # Create effect data
        effect = {
            'weapon': weapon.name,
            'weapon_type': weapon.weapon_type,
            'damage': weapon.damage,
            'range': weapon.range,
            'target_position': target_position,
            'source': self.id,
            'timestamp': current_time,
            'projectile_speed': weapon.projectile_speed,
            'area_effect': weapon.area_effect
        }

        # Apply special effects based on weapon type
        if weapon.weapon_type == WeaponType.SPECIAL:
            if weapon.name == "Medi-Gun":
                # Heal nearby allies
                effect['heal_amount'] = 15
            elif weapon.name == "Shield Generator":
                # Apply shield to self
                self.armor = min(50.0, self.armor + 25.0)
                effect['shield_amount'] = 25.0
            elif weapon.name == "EMP Pulse":
                # Disable enemy systems
                effect['disables_systems'] = True
            elif weapon.name == "Stun Baton":
                # Stun target
                effect['stun_duration'] = 2.0

        return effect

    def update(self, dt: float, environment: 'Environment') -> None:
        """Update robot state"""
        if not self.is_alive:
            return

        # Update weapon cooldowns
        for weapon in self.weapons:
            weapon.update_cooldown(dt)

        # Update position based on velocity
        self.position.x += self.velocity.x * dt
        self.position.y += self.velocity.y * dt
        self.position.z += self.velocity.z * dt

        # Apply environmental effects (e.g., gravity, hazards)
        self._apply_environmental_effects(dt, environment)

        # Update strategy based on learning
        self._update_strategy(dt, environment)

        self.last_updated = time.time()

    def _apply_environmental_effects(self, dt: float, environment: 'Environment') -> None:
        """Apply environmental effects to the robot"""
        # Check for hazards
        for hazard in environment.hazards:
            if hazard.position.distance_to(self.position) < hazard.radius:
                if hazard.hazard_type == HazardType.ELECTRIC_FLOOR:
                    self.take_damage(5 * dt, "electric_floor")
                    self.velocity.x *= 0.8
                    self.velocity.y *= 0.8
                elif hazard.hazard_type == HazardType.LAVA_POOL:
                    self.take_damage(10 * dt, "lava_pool")
                    self.velocity.x *= 0.5
                    self.velocity.y *= 0.5
                elif hazard.hazard_type == HazardType.GRAVITY_WELL:
                    # Pull toward center of gravity well
                    direction = hazard.position - self.position
                    if direction.x != 0 or direction.y != 0:
                        normalized = direction
                        norm = math.sqrt(normalized.x**2 + normalized.y**2)
                        if norm > 0:
                            normalized.x /= norm
                            normalized.y /= norm
                        self.velocity.x += normalized.x * 15 * dt
                        self.velocity.y += normalized.y * 15 * dt
                elif hazard.hazard_type == HazardType.SILENCE_FIELD:
                    # Reduce weapon effectiveness
                    self.energy = max(0, self.energy - 2 * dt)

        # Apply gravity
        self.velocity.z -= 9.8 * dt

        # Apply friction
        friction = 0.95
        self.velocity.x *= friction
        self.velocity.y *= friction
        self.velocity.z *= friction

    def _update_strategy(self, dt: float, environment: 'Environment') -> None:
        """Update AI strategy based on learning and environment"""
        # Simple learning mechanism: reinforce successful actions
        if len(self.strategy_memory) > 10:  # Learn from last 10 actions
            # Calculate success rate of recent actions
            recent_actions = self.strategy_memory[-10:]
            success_rate = sum(1 for action in recent_actions if action.get('success', False)) / len(recent_actions)

            # Adjust learning rate based on success rate
            if success_rate > 0.7:
                self.learning_rate = min(0.3, self.learning_rate + 0.01)
            elif success_rate < 0.3:
                self.learning_rate = max(0.05, self.learning_rate - 0.01)

            # Update decision tree based on successful patterns
            self._update_decision_tree(recent_actions)

    def _update_decision_tree(self, recent_actions: List[Dict]) -> None:
        """Update the decision tree with new patterns"""
        # This is a simplified version - in a real system, this would be a complex machine learning model
        for action in recent_actions:
            if 'context' in action and 'action' in action:
                context = tuple(action['context'])
                action_type = action['action']

                # Create a simple decision tree structure
                if context not in self.decision_tree:
                    self.decision_tree[context] = {}

                if action_type not in self.decision_tree[context]:
                    self.decision_tree[context][action_type] = 0

                # Reward successful actions
                if action.get('success', False):
                    self.decision_tree[context][action_type] += 1 * self.learning_rate
                else:
                    self.decision_tree[context][action_type] = max(0, self.decision_tree[context][action_type] - 0.1 * self.learning_rate)

    def get_best_action(self, environment: 'Environment', team_members: List['Robot']) -> Dict:
        """Determine the best action based on current state and decision tree"""
        # Extract context for decision making
        context = self._extract_context(environment, team_members)

        # Look for patterns in decision tree
        if context in self.decision_tree:
            # Choose action with highest score
            actions = self.decision_tree[context]
            if actions:
                best_action = max(actions.keys(), key=lambda x: actions[x])
                return {
                    'action': best_action,
                    'confidence': actions[best_action],
                    'context': context
                }

        # Fallback to simple behavior based on role
        return self._default_behavior(environment, team_members)

    def _extract_context(self, environment: 'Environment', team_members: List['Robot']) -> Tuple:
        """Extract current state context for decision making"""
        # Find nearest enemy and ally
        nearest_enemy = None
        nearest_ally = None
        min_enemy_dist = float('inf')
        min_ally_dist = float('inf')

        for robot in environment.robots:
            if robot.team != self.team and robot.is_alive:
                dist = self.position.distance_to(robot.position)
                if dist < min_enemy_dist:
                    min_enemy_dist = dist
                    nearest_enemy = robot

            elif robot.team == self.team and robot.is_alive and robot.id != self.id:
                dist = self.position.distance_to(robot.position)
                if dist < min_ally_dist:
                    min_ally_dist = dist
                    nearest_ally = robot

        # Extract relevant context
        enemy_distance = min_enemy_dist if nearest_enemy else -1
        ally_distance = min_ally_dist if nearest_ally else -1
        health_ratio = self.health / self.max_health
        energy_ratio = self.energy / self.max_energy
        objective_distance = self._get_objective_distance(environment)

        return (
            int(self.role.value),
            int(enemy_distance < 20),
            int(ally_distance < 15),
            int(health_ratio < 0.3),
            int(energy_ratio < 0.2),
            int(objective_distance < 10)
        )

    def _get_objective_distance(self, environment: 'Environment') -> float:
        """Calculate distance to current objective"""
        if not environment.current_objective:
            return float('inf')

        if environment.current_objective.objective_type == ObjectiveType.CAPTURE_FLAG:
            return self.position.distance_to(environment.current_objective.position)
        elif environment.current_objective.objective_type == ObjectiveType.DEFEND_BASE:
            return self.position.distance_to(environment.current_objective.position)
        elif environment.current_objective.objective_type == ObjectiveType.ESCAPE_PAYLOAD:
            return self.position.distance_to(environment.current_objective.position)
        elif environment.current_objective.objective_type == ObjectiveType.DOMINATE_ZONE:
            return self.position.distance_to(environment.current_objective.position)

        return float('inf')

    def _default_behavior(self, environment: 'Environment', team_members: List['Robot']) -> Dict:
        """Default behavior based on role and environment"""
        # Find objectives and enemies
        nearest_enemy = self._find_nearest_enemy(environment)
        nearest_objective = self._find_nearest_objective(environment)

        # Base behavior based on role
        if self.role == RobotRole.ATTACKER:
            if nearest_enemy and self.position.distance_to(nearest_enemy.position) < 30:
                return {'action': 'attack', 'target': nearest_enemy.id}
            elif nearest_objective:
                return {'action': 'move_to', 'target': 'objective'}
            else:
                return {'action': 'patrol'}

        elif self.role == RobotRole.DEFENDER:
            if nearest_enemy and self.position.distance_to(nearest_enemy.position) < 25:
                return {'action': 'attack', 'target': nearest_enemy.id}
            elif nearest_objective:
                return {'action': 'defend', 'target': 'objective'}
            else:
                return {'action': 'patrol', 'target': 'base'}

        elif self.role == RobotRole.SUPPORT:
            wounded_ally = self._find_nearest_wounded_ally(team_members)
            if wounded_ally:
                return {'action': 'heal', 'target': wounded_ally.id}
            elif nearest_enemy and self.position.distance_to(nearest_enemy.position) < 20:
                return {'action': 'attack', 'target': nearest_enemy.id}
            else:
                return {'action': 'patrol', 'target': 'team_center'}

        elif self.role == RobotRole.SCOUT:
            if nearest_enemy and self.position.distance_to(nearest_enemy.position) < 40:
                return {'action': 'recon', 'target': nearest_enemy.id}
            elif nearest_objective:
                return {'action': 'capture', 'target': 'objective'}
            else:
                return {'action': 'explore'}

        elif self.role == RobotRole.CONTROLLER:
            if nearest_enemy and self.position.distance_to(nearest_enemy.position) < 25:
                return {'action': 'disable', 'target': nearest_enemy.id}
            elif nearest_objective:
                return {'action': 'control', 'target': 'objective'}
            else:
                return {'action': 'patrol'}

        return {'action': 'patrol'}

    def _find_nearest_enemy(self, environment: 'Environment') -> Optional['Robot']:
        """Find the nearest enemy robot"""
        nearest = None
        min_dist = float('inf')

        for robot in environment.robots:
            if robot.team != self.team and robot.is_alive:
                dist = self.position.distance_to(robot.position)
                if dist < min_dist:
                    min_dist = dist
                    nearest = robot

        return nearest

    def _find_nearest_wounded_ally(self, team_members: List['Robot']) -> Optional['Robot']:
        """Find the nearest wounded ally"""
        nearest = None
        min_dist = float('inf')

        for ally in team_members:
            if ally.id != self.id and ally.is_alive and ally.health < ally.max_health * 0.5:
                dist = self.position.distance_to(ally.position)
                if dist < min_dist:
                    min_dist = dist
                    nearest = ally

        return nearest

    def _find_nearest_objective(self, environment: 'Environment') -> Optional['Objective']:
        """Find the nearest objective"""
        if not environment.current_objective:
            return None

        return environment.current_objective

@dataclass
class Objective:
    objective_type: ObjectiveType
    position: Position
    team: Team
    captured_by: Optional[Team] = None
    progress: float = 0.0  # For objectives with progress (e.g., escort)
    required_score: int = 100  # Score needed to complete objective
    completion_reward: int = 100  # Points awarded for completion

    def update_progress(self, amount: float, team: Team) -> bool:
        """Update objective progress and return True if completed"""
        if team != self.team:
            return False

        self.progress = min(1.0, self.progress + amount)
        if self.progress >= 1.0:
            self.captured_by = team
            return True
        return False

    def reset(self) -> None:
        """Reset objective for next round"""
        self.progress = 0.0
        self.captured_by = None

@dataclass
class PowerUp:
    power_up_type: PowerUpType
    position: Position
    radius: float = 3.0
    duration: float = 10.0  # Duration in seconds
    active: bool = True
    spawn_time: float = 0.0
    collected_by: Optional[str] = None

    def collect(self, robot_id: str) -> Dict:
        """Collect the power-up and return its effect"""
        if not self.active:
            return {}

        self.active = False
        self.collected_by = robot_id

        effect = {
            'type': self.power_up_type,
            'robot_id': robot_id,
            'duration': self.duration
        }

        if self.power_up_type == PowerUpType.HEALTH_PACK:
            effect['health_amount'] = 30
        elif self.power_up_type == PowerUpType.AMMO_RELOAD:
            effect['ammo_amount'] = 20
        elif self.power_up_type == PowerUpType.SPEED_BOOST:
            effect['speed_multiplier'] = 1.5
        elif self.power_up_type == PowerUpType.SHIELD:
            effect['shield_amount'] = 25
        elif self.power_up_type == PowerUpType.TELEPORT:
            effect['teleport'] = True
        elif self.power_up_type == PowerUpType.INVINCIBILITY:
            effect['invincibility_time'] = 5.0

        return effect

@dataclass
class Hazard:
    hazard_type: HazardType
    position: Position
    radius: float = 5.0
    damage_per_second: float = 5.0
    active: bool = True

@dataclass
class ParticleEffect:
    position: Position
    color: Tuple[int, int, int]
    lifetime: float
    velocity: Velocity
    size: float
    type: str  # "explosion", "trail", "spark", etc.
    created_at: float = field(default_factory=time.time)

    def update(self, dt: float) -> bool:
        """Update particle effect and return True if still active"""
        self.position += self.velocity * dt
        self.lifetime -= dt
        self.size = max(0, self.size - dt * 0.5)

        return self.lifetime > 0

@dataclass
class TeamScore:
    team: Team
    score: int = 0
    objectives_completed: int = 0
    kills: int = 0
    assists: int = 0
    deaths: int = 0
    last_update: float = 0.0

@dataclass
class Environment:
    width: float = 200.0
    height: float = 200.0
    depth: float = 50.0
    gravity: float = 9.8
    time: float = 0.0
    robots: List[Robot] = field(default_factory=list)
    power_ups: List[PowerUp] = field(default_factory=list)
    hazards: List[Hazard] = field(default_factory=list)
    particles: List[ParticleEffect] = field(default_factory=list)
    current_objective: Optional[Objective] = None
    objectives: List[Objective] = field(default_factory=list)
    team_scores: Dict[Team, TeamScore] = field(default_factory=dict)
    audio_manager: Any = None
    visual_manager: Any = None
    difficulty: float = 0.5  # 0.0 to 1.0, where 0.5 is medium

    def __post_init__(self):
        # Initialize team scores
        for team in Team:
            if team != Team.NEUTRAL:
                self.team_scores[team] = TeamScore(team)

        # Initialize default objective
        self._generate_objective()

    def _generate_objective(self) -> None:
        """Generate a random objective based on difficulty"""
        objective_types = [
            ObjectiveType.CAPTURE_FLAG,
            ObjectiveType.DEFEND_BASE,
            ObjectiveType.ESCAPE_PAYLOAD,
            ObjectiveType.DOMINATE_ZONE
        ]

        # Adjust objective frequency based on difficulty
        if self.difficulty < 0.3:
            objective_types = [ObjectiveType.CAPTURE_FLAG, ObjectiveType.DEFEND_BASE]
        elif self.difficulty > 0.7:
            objective_types = [ObjectiveType.ESCAPE_PAYLOAD, ObjectiveType.DOMINATE_ZONE]

        objective_type = random.choice(objective_types)
        position = Position(
            random.uniform(20, self.width - 20),
            random.uniform(20, self.height - 20),
            0
        )

        # Assign team based on objective type
        # For simplicity, assign objectives randomly but balance over time
        team = random.choice([Team.RED, Team.BLUE])

        objective = Objective(
            objective_type=objective_type,
            position=position,
            team=team,
            required_score=100,
            completion_reward=100
        )

        self.current_objective = objective
        self.objectives.append(objective)

        logger.info(f"New objective spawned: {objective_type.value} at {position.x:.1f}, {position.y:.1f}")

    def spawn_power_up(self, power_up_type: PowerUpType) -> None:
        """Spawn a power-up at a random location"""
        position = Position(
            random.uniform(10, self.width - 10),
            random.uniform(10, self.height - 10),
            0
        )

        power_up = PowerUp(
            power_up_type=power_up_type,
            position=position,
            spawn_time=self.time
        )

        self.power_ups.append(power_up)
        logger.info(f"Power-up {power_up_type.value} spawned at {position.x:.1f}, {position.y:.1f}")

    def spawn_hazard(self, hazard_type: HazardType) -> None:
        """Spawn a hazard at a random location"""
        position = Position(
            random.uniform(10, self.width - 10),
            random.uniform(10, self.height - 10),
            0
        )

        # Adjust hazard properties based on difficulty
        radius = 5.0 + self.difficulty * 10.0
        damage_per_second = 5.0 + self.difficulty * 5.0

        hazard = Hazard(
            hazard_type=hazard_type,
            position=position,
            radius=radius,
            damage_per_second=damage_per_second
        )

        self.hazards.append(hazard)
        logger.info(f"Hazard {hazard_type.value} spawned at {position.x:.1f}, {position.y:.1f}")

    def spawn_random_power_up(self) -> None:
        """Spawn a random power-up"""
        power_up_types = list(PowerUpType)
        if self.difficulty < 0.3:
            power_up_types = [PowerUpType.HEALTH_PACK, PowerUpType.AMMO_RELOAD]
        elif self.difficulty > 0.7:
            power_up_types = [PowerUpType.SPEED_BOOST, PowerUpType.SHIELD, PowerUpType.INVINCIBILITY]

        selected_type = random.choice(power_up_types)
        self.spawn_power_up(selected_type)

    def spawn_random_hazard(self) -> None:
        """Spawn a random hazard"""
        hazard_types = list(HazardType)
        if self.difficulty < 0.3:
            hazard_types = [HazardType.ELECTRIC_FLOOR, HazardType.LAVA_POOL]
        elif self.difficulty > 0.7:
            hazard_types = [HazardType.GRAVITY_WELL, HazardType.SILENCE_FIELD]

        selected_type = random.choice(hazard_types)
        self.spawn_hazard(selected_type)

    def update(self, dt: float) -> None:
        """Update the entire environment"""
        self.time += dt

        # Update robots
        for robot in self.robots:
            robot.update(dt, self)

        # Update power-ups
        for power_up in self.power_ups[:]:  # Copy list to avoid modification during iteration
            if not power_up.active:
                self.power_ups.remove(power_up)

        # Update hazards - don't remove them for now (persistent)

        # Update particles
        for particle in self.particles[:]:  # Copy list to avoid modification during iteration
            if not particle.update(dt):
                self.particles.remove(particle)

        # Check for power-up collection
        self._check_power_up_collection(dt)

        # Check for objective completion
        self._check_objective_completion(dt)

        # Spawn new power-ups and hazards based on time and difficulty
        self._spawn_dynamic_elements(dt)

        # Update difficulty based on team performance
        self._adjust_difficulty()

    def _check_power_up_collection(self, dt: float) -> None:
        """Check if any robot has collected a power-up"""
        for power_up in self.power_ups[:]:
            if not power_up.active:
                continue

            for robot in self.robots:
                if robot.is_alive and robot.position.distance_to(power_up.position) < power_up.radius:
                    effect = power_up.collect(robot.id)

                    # Apply effect to robot
                    if effect['type'] == PowerUpType.HEALTH_PACK:
                        robot.heal(effect.get('health_amount', 30))
                    elif effect['type'] == PowerUpType.AMMO_RELOAD:
                        for weapon in robot.weapons:
                            weapon.ammo_capacity = min(weapon.ammo_capacity + effect.get('ammo_amount', 20), weapon.ammo_capacity + 20)
                    elif effect['type'] == PowerUpType.SPEED_BOOST:
                        robot.velocity.x *= effect.get('speed_multiplier', 1.5)
                        robot.velocity.y *= effect.get('speed_multiplier', 1.5)
                    elif effect['type'] == PowerUpType.SHIELD:
                        robot.armor = min(robot.armor + effect.get('shield_amount', 25), 50)
                    elif effect['type'] == PowerUpType.INVINCIBILITY:
                        robot.max_health *= 1.5
                        robot.health = robot.max_health

                    # Create particle effect for collection
                    self._create_particle_effect(
                        power_up.position,
                        (255, 215, 0),  # Gold color
                        2.0,
                        Velocity(0, 0, 0),
                        5.0,
                        "spark"
                    )

                    # Play audio cue
                    if self.audio_manager:
                        self.audio_manager.play_sound("powerup_collected", robot.position)

                    break  # Only one robot can collect a power-up

    def _check_objective_completion(self, dt: float) -> None:
        """Check if any objective has been completed"""
        if not self.current_objective:
            return

        # Calculate distance-based progress for capture objectives
        if self.current_objective.objective_type == ObjectiveType.CAPTURE_FLAG:
            red_proximity = 0
            blue_proximity = 0

            for robot in self.robots:
                if robot.is_alive:
                    distance = robot.position.distance_to(self.current_objective.position)
                    proximity = max(0, 1 - distance / 30)  # Max 30m distance for proximity

                    if robot.team == Team.RED:
                        red_proximity += proximity
                    elif robot.team == Team.BLUE:
                        blue_proximity += proximity

