@dataclass
class Position:
    x: float
    y: float
    z: float = 0.0

    def distance_to(self, other: 'Position') -> float:
        return math.sqrt((self.x - other.x)**2 + (self.y - other.y)**2 + (self.z - other.z)**2)

    def __add__(self, other: 'Position') -> 'Position':
        return Position(self.x + other.x, self.y + other.y, self.z + other.z)

    def __sub__(self, other: 'Position') -> 'Position':
        return Position(self.x - other.x, self.y - other.y, self.z - other.z)

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, Position):
            return False
        return abs(self.x - other.x) < 0.001 and abs(self.y - other.y) < 0.001 and abs(self.z - other.z) < 0.001

@dataclass
class Velocity:
    x: float = 0.0
    y: float = 0.0
    z: float = 0.0

    def apply_force(self, force: 'Velocity', mass: float, dt: float) -> None:
        self.x += force.x / mass * dt
        self.y += force.y / mass * dt
        self.z += force.z / mass * dt

