            closest_point = min(control_points, key=lambda cp: self.position.distance_to(cp.position))
            distance = self.position.distance_to(closest_point.position)

            if closest_point.owner == self.team:
                self.ai_state = "defend_point"
            elif closest_point.owner == -1:  # Neutral
                if distance < 50:
                    self.ai_state = "capture_point"
