    def can_interact_with_objective(self, game_state: 'GameState') -> bool:
        """Check if robot can interact with objective."""
        if not self.is_alive:
            return False

        if game_state.mode == GameMode.CAPTURE_THE_FLAG:
            if self.team == 0:
                flag_pos = game_state.flag_positions[1]  # Enemy flag
                base_pos = game_state.base_positions[0]  # Our base
            else:
                flag_pos = game_state.flag_positions[0]  # Enemy flag
                base_pos = game_state.base_positions[1]  # Our base

            # Can pick up enemy flag
            if game_state.flag_carrier_id is None and self.position.distance_to(flag_pos) < 50:
                return True
            # Can return flag to base
            elif game_state.flag_carrier_id == self.id and self.position.distance_to(base_pos) < 50:
                return True

        elif game_state.mode == GameMode.ESCORT_PAYLOAD:
            if self.position.distance_to(game_state.payload_position) < 50:
                return True

        elif game_state.mode == GameMode.DOMINATION:
            for point in game_state.control_points:
                if self.position.distance_to(point.position) < 50:
                    return True

        return False

    def interact_with_objective(self, game_state: 'GameState') -> bool:
        """Interact with objective based on game mode."""
        if not self.is_alive:
            return False

        if game_state.mode == GameMode.CAPTURE_THE_FLAG:
            if self.team == 0:
                enemy_flag = game_state.flag_positions[1]
                our_base = game_state.base_positions[0]
            else:
                enemy_flag = game_state.flag_positions[0]
                our_base = game_state.base_positions[1]

            # Pick up enemy flag
            if game_state.flag_carrier_id is None and self.position.distance_to(enemy_flag) < 50:
                game_state.flag_carrier_id = self.id
                game_state.flag_position = self.position
                game_state.flag_pickup_time = time.time()
                SOUND_EFFECTS['capture'].play()
                return True

            # Return flag to base
            elif game_state.flag_carrier_id == self.id and self.position.distance_to(our_base) < 50:
                game_state.flag_carrier_id = -1  # Flag returned
                game_state.flag_position = our_base
                game_state.team_scores[self.team] += 10
                game_state.objective_completed = True
                SOUND_EFFECTS['capture'].play()
                return True

        elif game_state.mode == GameMode.ESCORT_PAYLOAD:
            if self.position.distance_to(game_state.payload_position) < 50:
                # Take control of payload
                game_state.payload_carrier_id = self.id
                game_state.payload_position = self.position
                game_state.payload_progress = 0.0
                return True

        elif game_state.mode == GameMode.DOMINATION:
            for point in game_state.control_points:
                if self.position.distance_to(point.position) < 50:
                    if point.owner == -1:  # Neutral
                        point.owner = self.team
                        point.capture_progress = 0
                        game_state.team_scores[self.team] += 5
                        SOUND_EFFECTS['capture'].play()
                    elif point.owner == self.team:
                        point.capture_progress += 0.02
                        if point.capture_progress >= 1.0:
                            # Point captured
                            game_state.team_scores[self.team] += 10
                            point.owner = self.team
                            point.capture_progress = 0
                            SOUND_EFFECTS['capture'].play()
                    else:  # Enemy point
                        point.capture_progress -= 0.01
                        if point.capture_progress <= 0:
                            point.owner = self.team
                            point.capture_progress = 0
                            game_state.team_scores[self.team] += 10
                            SOUND_EFFECTS['capture'].play()
                    return True

        return False

@dataclass
class Projectile:
    owner_id: int
    team: int
    position: Vector2D
    velocity: Vector2D
    damage: float
    weapon_type: WeaponType
    spread: float = 0.0
    lifetime: float = 3.0
    created_time: float = field(default_factory=time.time)

    def update(self, dt: float) -> bool:
        """Update projectile position and check if it should expire."""
        self.position += self.velocity * dt
        self.lifetime -= dt
        return self.lifetime > 0

@dataclass
class PowerUp:
    type: PowerUpType
    position: Vector2D
    duration: float = 10.0
    spawn_time: float = field(default_factory=time.time)
    active: bool = True

    def collect(self) -> bool:
        """Mark power-up as collected."""
        self.active = False
        return True

@dataclass
class Hazard:
    type: HazardType
    position: Vector2D
    radius: float = 30
    damage_per_second: float = 5.0
    active: bool = True

    def affect_robot(self, robot: Robot, dt: float) -> bool:
        """Apply hazard effect to robot if within range."""
        if not robot.is_alive:
            return False

        distance = robot.position.distance_to(self.position)
        if distance < self.radius:
            # Apply damage
            robot.take_damage(self.damage_per_second * dt)
            return True
        return False

@dataclass
class ControlPoint:
    position: Vector2D
    owner: int = -1  # -1 = neutral, 0/1 = team
    capture_progress: float = 0.0
    capture_rate: float = 0.005  # per second

@dataclass
class GameState:
    mode: GameMode
    time: float = 0.0
    team_scores: Dict[int, int] = field(default_factory=lambda: {0: 0, 1: 0})
    flag_positions: List[Vector2D] = field(default_factory=list)
    flag_carrier_id: int = None  # robot id of carrier, -1 = in base, None = not in play
    flag_position: Vector2D = field(default_factory=lambda: Vector2D(0, 0))
    flag_pickup_time: float = 0.0
    payload_position: Vector2D = field(default_factory=lambda: Vector2D(0, 0))
    payload_destination: Vector2D = field(default_factory=lambda: Vector2D(0, 0))
    payload_carrier_id: int = None
    payload_progress: float = 0.0
    control_points: List[ControlPoint] = field(default_factory=list)
    power_ups: List[PowerUp] = field(default_factory=list)
    hazards: List[Hazard] = field(default_factory=list)
    projectiles: List[Projectile] = field(default_factory=list)
