    'explosion': pygame.mixer.Sound(buffer=bytearray([0] * 2000)),
    'capture': pygame.mixer.Sound(buffer=bytearray([0] * 1000)),
    'powerup': pygame.mixer.Sound(buffer=bytearray([0] * 1000)),
    'team_win': pygame.mixer.Sound(buffer=bytearray([0] * 3000)),
}

# Game Modes
class GameMode(Enum):
    CAPTURE_THE_FLAG = "capture_the_flag"
    ESCORT_PAYLOAD = "escort_payload"
    DOMINATION = "domination"

# Weapon Types
class WeaponType(Enum):
    PISTOL = "pistol"
    RIFLE = "rifle"
    SHOTGUN = "shotgun"
    SNIPER = "sniper"
    MELEE = "melee"
    ROCKET_LAUNCHER = "rocket_launcher"

# Robot Roles
class Role(Enum):
    ATTACKER = "attacker"
    DEFENDER = "defender"
    SUPPORT = "support"
    SCOUT = "scout"
    CARRIER = "carrier"

# Power-up Types
class PowerUpType(Enum):
    SPEED_BOOST = "speed_boost"
    SHIELD = "shield"
    REGEN = "regen"
    WEAPON_UPGRADE = "weapon_upgrade"
    INVISIBILITY = "invisibility"
    EMP = "emp"

# Environmental Hazards
class HazardType(Enum):
    ELECTRIC_FIELD = "electric_field"
    FLAME_SPOT = "flame_spot"
    TOXIC_GAS = "toxic_gas"
    GRAVITY_WELL = "gravity_well"

@dataclass
class Vector2D:
    x: float = 0.0
    y: float = 0.0

    def __add__(self, other):
        return Vector2D(self.x + other.x, self.y + other.y)

    def __sub__(self, other):
        return Vector2D(self.x - other.x, self.y - other.y)

    def __mul__(self, scalar):
        return Vector2D(self.x * scalar, self.y * scalar)

    def __truediv__(self, scalar):
        return Vector2D(self.x / scalar, self.y / scalar)

    def length(self):
        return math.sqrt(self.x**2 + self.y**2)

    def normalize(self):
        length = self.length()
        if length == 0:
            return Vector2D(0, 0)
        return self / length

    def distance_to(self, other):
        return (self - other).length()

    def to_tuple(self):
        return (int(self.x), int(self.y))

@dataclass
class Weapon:
    type: WeaponType
    damage: float
    range: float
    fire_rate: float  # seconds between shots
    ammo: int
    max_ammo: int
    reload_time: float = 2.0
    spread: float = 0.0  # for shotguns, etc.
    projectile_speed: float = 10.0
    is_melee: bool = False

    def __post_init__(self):
        self.cooldown = 0.0
        self.is_reloading = False
        self.ammo_left = self.ammo

@dataclass
class Robot:
    id: int
    team: int  # 0 or 1
    position: Vector2D
    velocity: Vector2D = field(default_factory=lambda: Vector2D(0, 0))
    health: float = 100.0
    max_health: float = 100.0
    speed: float = 3.0
    role: Role = Role.ATTACKER
    weapon: Weapon = field(default_factory=lambda: Weapon(WeaponType.PISTOL, 15, 300, 0.5, 15, 45))
    inventory: List[Weapon] = field(default_factory=list)
    power_ups: Dict[PowerUpType, float] = field(default_factory=dict)  # type -> duration
    is_alive: bool = True
    last_action_time: float = 0.0
    strategy_memory: List[Dict] = field(default_factory=list)  # for learning
    vision_range: float = 250.0
    cooldowns: Dict[str, float] = field(default_factory=dict)  # e.g., 'dash', 'ability'
    team_objective_progress: float = 0.0  # for objectives
    last_seen_enemies: List[Dict] = field(default_factory=list)  # [ {id, position, time} ]
    ai_state: str = "patrol"  # patrol, attack, defend, retreat, capture
    ai_behavior_model: Dict = field(default_factory=dict)  # learned model for AI decisions
    score: int = 0

    def __post_init__(self):
        self.inventory = [self.weapon]
        self.power_ups = {}
        self.cooldowns = {}
        self.last_seen_enemies = []
        self.strategy_memory = []
        self.ai_behavior_model = {
            'attack_weight': 0.5,
            'defend_weight': 0.3,
            'support_weight': 0.2,
            'recent_success': 0.5,
            'team_cooperation': 0.5
        }

    def update_cooldowns(self, dt: float):
        """Update all cooldown timers."""
        for key in list(self.cooldowns.keys()):
            self.cooldowns[key] = max(0, self.cooldowns[key] - dt)

    def add_power_up(self, power_up_type: PowerUpType, duration: float):
        """Apply a power-up effect."""
        self.power_ups[power_up_type] = duration
        if power_up_type == PowerUpType.SPEED_BOOST:
            self.speed *= 1.5
        elif power_up_type == PowerUpType.SHIELD:
            self.max_health = self.max_health * 1.5
            self.health = self.max_health
        elif power_up_type == PowerUpType.WEAPON_UPGRADE:
            # Upgrade current weapon
            self.weapon.damage += 10
            self.weapon.range += 50
            self.weapon.fire_rate *= 0.8
        elif power_up_type == PowerUpType.INVISIBILITY:
            # Invisible for duration
            pass
        elif power_up_type == PowerUpType.EMP:
            # Disable enemy systems
            pass

    def apply_power_up_effects(self, dt: float):
        """Apply and decay power-up effects."""
        to_remove = []
        for power_up, duration in self.power_ups.items():
            self.power_ups[power_up] = duration - dt
            if self.power_ups[power_up] <= 0:
                to_remove.append(power_up)

        for power_up in to_remove:
            del self.power_ups[power_up]
            if power_up == PowerUpType.SPEED_BOOST:
                self.speed /= 1.5
            elif power_up == PowerUpType.SHIELD:
                self.max_health /= 1.5
                if self.health > self.max_health:
                    self.health = self.max_health
            elif power_up == PowerUpType.WEAPON_UPGRADE:
                # Revert weapon stats
                self.weapon.damage -= 10
                self.weapon.range -= 50
                self.weapon.fire_rate /= 0.8

    def take_damage(self, damage: float, source: Optional['Robot'] = None) -> bool:
        """Apply damage to robot, return True if killed."""
        if not self.is_alive:
            return False

        # Apply shield if active
        if PowerUpType.SHIELD in self.power_ups:
            damage *= 0.5

        self.health -= damage
        if self.health <= 0:
            self.health = 0
            self.is_alive = False
            return True
        return False

    def heal(self, amount: float):
        """Heal robot."""
        self.health = min(self.max_health, self.health + amount)

    def can_see(self, target_position: Vector2D, obstacles: List) -> bool:
        """Check line of sight to target position (simplified)."""
        # In a real implementation, this would use raycasting with map collision
        # For now, just check if distance is within vision range
        distance = self.position.distance_to(target_position)
        return distance <= self.vision_range

    def get_best_enemy_target(self, enemies: List['Robot']) -> Optional['Robot']:
        """Select best enemy target based on strategy, range, and health."""
        if not enemies:
            return None

        # Filter alive enemies within vision range
        visible_enemies = [
            e for e in enemies 
            if e.is_alive and self.can_see(e.position, []) and self.position.distance_to(e.position) <= self.vision_range
        ]

        if not visible_enemies:
            return None

        # Strategy-based target selection
        if self.role == Role.ATTACKER:
            # Target weakest enemy
            return min(visible_enemies, key=lambda e: e.health)
        elif self.role == Role.DEFENDER:
            # Target closest enemy to base or objective
            return min(visible_enemies, key=lambda e: e.position.distance_to(self.position))
        elif self.role == Role.SUPPORT:
            # Target enemy threatening teammates
            threats = []
            for e in visible_enemies:
                for teammate in [r for r in robot_manager.robots if r.team == self.team and r.is_alive]:
                    if teammate.position.distance_to(e.position) < 150:
                        threats.append(e)
                        break
            if threats:
                return min(threats, key=lambda e: e.position.distance_to(self.position))
            return min(visible_enemies, key=lambda e: e.health)
        else:
            # Default: target closest
            return min(visible_enemies, key=lambda e: self.position.distance_to(e.position))

    def update_behavior(self, game_state: 'GameState', dt: float):
        """Update AI behavior based on current state and learning."""
        # Update memory with current state
        current_state = {
            'time': game_state.time,
            'role': self.role,
            'health': self.health,
            'team_objective_progress': self.team_objective_progress,
            'enemy_count': len([r for r in robot_manager.robots if r.team != self.team and r.is_alive]),
            'teammate_positions': [r.position for r in robot_manager.robots if r.team == self.team and r.is_alive],
            'objective_position': game_state.objective_position,
            'power_up_positions': [pu.position for pu in game_state.power_ups],
            'hazard_positions': [h.position for h in game_state.hazards],
            'ai_state': self.ai_state
        }

        if len(self.strategy_memory) > 100:  # Limit memory
            self.strategy_memory.pop(0)
        self.strategy_memory.append(current_state)

        # Adjust AI weights based on performance feedback
        if game_state.time > 10:
            recent_successes = sum(1 for m in self.strategy_memory[-10:] if m['team_objective_progress'] > 0.7)
            if recent_successes > 5:
                self.ai_behavior_model['recent_success'] = min(1.0, self.ai_behavior_model['recent_success'] + 0.05)
            else:
                self.ai_behavior_model['recent_success'] = max(0.1, self.ai_behavior_model['recent_success'] - 0.02)

        # Update AI state based on current conditions
        self._update_ai_state(game_state, dt)

    def _update_ai_state(self, game_state: 'GameState', dt: float):
        """Internal method to update AI state machine."""
        enemies = [r for r in robot_manager.robots if r.team != self.team and r.is_alive]
        teammates = [r for r in robot_manager.robots if r.team == self.team and r.is_alive]

        # Update cooldowns
        self.update_cooldowns(dt)

        # Determine current objective
        if game_state.mode == GameMode.CAPTURE_THE_FLAG:
            # Flag capture objective
            if self.team == 0:
                objective_pos = game_state.flag_positions[1]  # Enemy flag
                base_pos = game_state.base_positions[0]  # Our base
            else:
                objective_pos = game_state.flag_positions[0]  # Enemy flag
                base_pos = game_state.base_positions[1]  # Our base

            # Check if we have the flag
            if game_state.flag_carrier_id == self.id:
                self.ai_state = "escape"
                self.role = Role.CARRIER
            elif game_state.flag_carrier_id is not None and game_state.flag_carrier_id != -1:
                # Someone has the flag, try to intercept
                carrier = robot_manager.get_robot_by_id(game_state.flag_carrier_id)
                if carrier and carrier.team != self.team:
                    if self.position.distance_to(carrier.position) < 100:
                        self.ai_state = "intercept"
                    else:
                        self.ai_state = "pursue"
                else:
                    # No carrier, go for flag
                    self.ai_state = "capture"
            else:
                # Go for enemy flag
                distance_to_flag = self.position.distance_to(objective_pos)
                if distance_to_flag < 50:
                    self.ai_state = "capture"
                else:
                    # Check if we're close to our base and flag is safe
                    if self.position.distance_to(base_pos) < 150 and not enemies:
                        self.ai_state = "defend_base"
                    else:
                        # Find best path to flag
                        self.ai_state = "pursue"

        elif game_state.mode == GameMode.ESCORT_PAYLOAD:
            # Escort payload to destination
            payload_pos = game_state.payload_position
            destination_pos = game_state.payload_destination
            if self.team == 0:
                # Red team escorts payload
                if self.position.distance_to(payload_pos) < 50 and not self.is_carrier:
                    self.ai_state = "escort"
                    self.role = Role.CARRIER
                elif self.position.distance_to(destination_pos) < 100:
                    self.ai_state = "defend_payload"
                else:
                    self.ai_state = "pursue_payload"
            else:
                # Blue team defends
                if self.position.distance_to(payload_pos) < 150:
                    self.ai_state = "defend_payload"
                else:
                    self.ai_state = "patrol"

        elif game_state.mode == GameMode.DOMINATION:
            # Control points
            control_points = game_state.control_points
            closest_point = min(control_points, key=lambda cp: self.position.distance_to(cp.position))
            distance = self.position.distance_to(closest_point.position)

            if closest_point.owner == self.team:
                self.ai_state = "defend_point"
            elif closest_point.owner == -1:  # Neutral
                if distance < 50:
                    self.ai_state = "capture_point"
                else:
                    self.ai_state = "pursue_point"
            else:  # Enemy owns it
                if distance < 50:
                    self.ai_state = "attack_point"
                else:
                    self.ai_state = "pursue_point"

        # Default fallback
        if not self.is_alive:
            return

        # Adjust role based on team needs
        self._adjust_role_based_on_team_needs(teammates, enemies)

        # Adjust behavior based on health
        if self.health < self.max_health * 0.3 and self.ai_state not in ["retreat", "escape"]:
            self.ai_state = "retreat"

        # If no enemies nearby and we're not in objective, patrol
        if not enemies and self.ai_state == "patrol":
            self.ai_state = "patrol"

    def _adjust_role_based_on_team_needs(self, teammates: List['Robot'], enemies: List['Robot']):
        """Adjust robot's role dynamically based on team composition and enemy situation."""
        if len(teammates) == 0:
            return

        # Count roles
        role_counts = defaultdict(int)
        for t in teammates:
            role_counts[t.role] += 1

        # Adjust role based on team needs
        enemy_count = len(enemies)
        if enemy_count == 0:
            # No enemies, all become scouts or support
            self.role = Role.SCATTER if role_counts[Role.SCATTER] < 1 else Role.SUPPORT
            return

        if self.role == Role.ATTACKER:
            if role_counts[Role.ATTACKER] > 2 and enemy_count < 3:
                self.role = Role.SUPPORT
            elif role_counts[Role.DEFENDER] == 0:
                self.role = Role.DEFENDER
        elif self.role == Role.DEFENDER:
            if role_counts[Role.DEFENDER] > 1 and enemy_count > 2:
                self.role = Role.ATTACKER
        elif self.role == Role.SUPPORT:
            if role_counts[Role.SUPPORT] > 1 and enemy_count > 0:
                if role_counts[Role.ATTACKER] < 2:
                    self.role = Role.ATTACKER
                else:
                    self.role = Role.SCATTER
        elif self.role == Role.SCATTER:
            if role_counts[Role.SCATTER] > 1 and enemy_count > 0:
                self.role = Role.ATTACKER

        # If we're the only one alive, become aggressive
        if len(teammates) == 1:
            self.role = Role.ATTACKER

    def move_toward(self, target: Vector2D, dt: float):
        """Move toward target with pathfinding (simplified)."""
        if not self.is_alive:
            return

        direction = (target - self.position).normalize()
        speed = self.speed
        # Apply power-up speed boost
        if PowerUpType.SPEED_BOOST in self.power_ups:
            speed *= 1.5

        # Limit movement to avoid overshooting
        distance_to_target = self.position.distance_to(target)
        if distance_to_target < speed * dt:
            self.velocity = direction * distance_to_target / dt
        else:
            self.velocity = direction * speed

        # Update position
        self.position += self.velocity * dt

        # Keep robot within map bounds
        self.position.x = max(0, min(MAP_SIZE[0], self.position.x))
        self.position.y = max(0, min(MAP_SIZE[1], self.position.y))

    def shoot_at(self, target: Vector2D, game_state: 'GameState') -> bool:
        """Attempt to shoot at target with current weapon."""
        if not self.is_alive or self.weapon.cooldown > 0 or self.weapon.ammo_left <= 0:
            return False

        # Calculate distance to target
        distance = self.position.distance_to(target)

        # Check if target is within range
        if distance > self.weapon.range:
            return False

        # Check if target is visible (simplified)
        if not self.can_see(target, game_state.hazards):
            return False

        # Fire weapon
        self.weapon.cooldown = self.weapon.fire_rate
        self.weapon.ammo_left -= 1

        # Create projectile
        direction = (target - self.position).normalize()
        projectile = Projectile(
            self.id,
            self.team,
            self.position + direction * 10,  # Offset to avoid spawning inside robot
            direction * self.weapon.projectile_speed,
            self.weapon.damage,
            self.weapon.type,
            self.weapon.spread
        )
        game_state.projectiles.append(projectile)

        # Play sound
        if self.weapon.type != WeaponType.MELEE:
            SOUND_EFFECTS['shoot'].play()

        return True

    def melee_attack(self, target: 'Robot', game_state: 'GameState') -> bool:
        """Perform a melee attack on target."""
        if not self.is_alive:
            return False

        distance = self.position.distance_to(target.position)

        if distance > 50:  # Melee range
            return False

        # Check cooldown
        if self.cooldowns.get('melee', 0) > 0:
            return False

        # Apply damage
        if target.take_damage(self.weapon.damage * 2):
            # Kill target
            game_state.add_score(self.id, 50)
            SOUND_EFFECTS['explosion'].play()
        else:
            # Hit sound
            SOUND_EFFECTS['hit'].play()

        # Set cooldown
        self.cooldowns['melee'] = 1.5  # 1.5 second cooldown

        return True

    def can_interact_with_objective(self, game_state: 'GameState') -> bool:
        """Check if robot can interact with objective."""
        if not self.is_alive:
            return False

        if game_state.mode == GameMode.CAPTURE_THE_FLAG:
            if self.team == 0:
                flag_pos = game_state.flag_positions[1]  # Enemy flag
                base_pos = game_state.base_positions[0]  # Our base
            else:
                flag_pos = game_state.flag_positions[0]  # Enemy flag
                base_pos = game_state.base_positions[1]  # Our base

            # Can pick up enemy flag
            if game_state.flag_carrier_id is None and self.position.distance_to(flag_pos) < 50:
                return True
            # Can return flag to base
            elif game_state.flag_carrier_id == self.id and self.position.distance_to(base_pos) < 50:
                return True

        elif game_state.mode == GameMode.ESCORT_PAYLOAD:
            if self.position.distance_to(game_state.payload_position) < 50:
                return True

        elif game_state.mode == GameMode.DOMINATION:
            for point in game_state.control_points:
                if self.position.distance_to(point.position) < 50:
                    return True

        return False

    def interact_with_objective(self, game_state: 'GameState') -> bool:
        """Interact with objective based on game mode."""
        if not self.is_alive:
            return False

        if game_state.mode == GameMode.CAPTURE_THE_FLAG:
            if self.team == 0:
                enemy_flag = game_state.flag_positions[1]
                our_base = game_state.base_positions[0]
            else:
                enemy_flag = game_state.flag_positions[0]
                our_base = game_state.base_positions[1]

            # Pick up enemy flag
            if game_state.flag_carrier_id is None and self.position.distance_to(enemy_flag) < 50:
                game_state.flag_carrier_id = self.id
                game_state.flag_position = self.position
                game_state.flag_pickup_time = time.time()
                SOUND_EFFECTS['capture'].play()
                return True

            # Return flag to base
            elif game_state.flag_carrier_id == self.id and self.position.distance_to(our_base) < 50:
                game_state.flag_carrier_id = -1  # Flag returned
                game_state.flag_position = our_base
                game_state.team_scores[self.team] += 10
                game_state.objective_completed = True
                SOUND_EFFECTS['capture'].play()
                return True

        elif game_state.mode == GameMode.ESCORT_PAYLOAD:
            if self.position.distance_to(game_state.payload_position) < 50:
                # Take control of payload
                game_state.payload_carrier_id = self.id
                game_state.payload_position = self.position
                game_state.payload_progress = 0.0
                return True

        elif game_state.mode == GameMode.DOMINATION:
            for point in game_state.control_points:
                if self.position.distance_to(point.position) < 50:
                    if point.owner == -1:  # Neutral
                        point.owner = self.team
                        point.capture_progress = 0
                        game_state.team_scores[self.team] += 5
                        SOUND_EFFECTS['capture'].play()
                    elif point.owner == self.team:
                        point.capture_progress += 0.02
                        if point.capture_progress >= 1.0:
                            # Point captured
                            game_state.team_scores[self.team] += 10
                            point.owner = self.team
                            point.capture_progress = 0
                            SOUND_EFFECTS['capture'].play()
                    else:  # Enemy point
                        point.capture_progress -= 0.01
                        if point.capture_progress <= 0:
                            point.owner = self.team
                            point.capture_progress = 0
                            game_state.team_scores[self.team] += 10
                            SOUND_EFFECTS['capture'].play()
                    return True

        return False

@dataclass
class Projectile:
    owner_id: int
    team: int
    position: Vector2D
    velocity: Vector2D
    damage: float
    weapon_type: WeaponType
    spread: float = 0.0
    lifetime: float = 3.0
    created_time: float = field(default_factory=time.time)

    def update(self, dt: float) -> bool:
        """Update projectile position and check if it should expire."""
        self.position += self.velocity * dt
        self.lifetime -= dt
        return self.lifetime > 0

@dataclass
class PowerUp:
    type: PowerUpType
    position: Vector2D
    duration: float = 10.0
    spawn_time: float = field(default_factory=time.time)
    active: bool = True

    def collect(self) -> bool:
        """Mark power-up as collected."""
        self.active = False
        return True

@dataclass
class Hazard:
    type: HazardType
    position: Vector2D
    radius: float = 30
    damage_per_second: float = 5.0
    active: bool = True

    def affect_robot(self, robot: Robot, dt: float) -> bool:
        """Apply hazard effect to robot if within range."""
        if not robot.is_alive:
            return False

        distance = robot.position.distance_to(self.position)
        if distance < self.radius:
            # Apply damage
            robot.take_damage(self.damage_per_second * dt)
            return True
        return False

@dataclass
class ControlPoint:
    position: Vector2D
    owner: int = -1  # -1 = neutral, 0/1 = team
    capture_progress: float = 0.0
    capture_rate: float = 0.005  # per second

@dataclass
class GameState:
    mode: GameMode
    time: float = 0.0
    team_scores: Dict[int, int] = field(default_factory=lambda: {0: 0, 1: 0})
    flag_positions: List[Vector2D] = field(default_factory=list)
    flag_carrier_id: int = None  # robot id of carrier, -1 = in base, None = not in play
    flag_position: Vector2D = field(default_factory=lambda: Vector2D(0, 0))
    flag_pickup_time: float = 0.0
    payload_position: Vector2D = field(default_factory=lambda: Vector2D(0, 0))
    payload_destination: Vector2D = field(default_factory=lambda: Vector2D(0, 0))
    payload_carrier_id: int = None
    payload_progress: float = 0.0
    control_points: List[ControlPoint] = field(default_factory=list)
    power_ups: List[PowerUp] = field(default_factory=list)
    hazards: List[Hazard] = field(default_factory=list)
    projectiles: List[Projectile] = field(default_factory=list)
    objective_completed: bool = False
    game_over: bool = False
    winner: Optional[int] = None

    def __post_init__(self):
        if not self.flag_positions:
            # Default flag positions
            self.flag_positions = [
                Vector2D(100, 300),  # Red team's flag (team 0)
                Vector2D(900, 300)   # Blue team's flag (team 1)
