@dataclass
class AgentMessage:
    sender: AgentRole
    receiver: AgentRole
    type: str  # e.g., "proposal", "notification", "request", "alert"
    content: Dict[str, Any]
    timestamp: float = field(default_factory=time.time)

    def __str__(self):
        return f"[{self.sender.value}] -> [{self.receiver.value}]: {self.type} - {self.content}"

class AgentCommunicationBus:
    def __init__(self):
        self.queue = queue.Queue()
        self.history = []

    def send(self, message: AgentMessage):
        self.queue.put(message)
        self.history.append(message)

    def receive_all(self) -> List[AgentMessage]:
        messages = []
        while not self.queue.empty():
            messages.append(self.queue.get())
        return messages

    def get_recent_messages(self, role: AgentRole, limit: int = 10) -> List[AgentMessage]:
        return [m for m in self.history[-limit:] if m.receiver == role]

