    defenders: List[str] = field(default_factory=list)
    attackers: List[str] = field(default_factory=list)

    def update_capture(self, team: Team, robots_in_range: List[str]):
        """Update capture progress based on robots in range."""
        if team == self.team:
            # Team already controlling - increase slowly
            self.capture_progress += len(robots_in_range) * 0.1
        else:
            # Enemy team trying to capture
            self.capture_progress -= len(robots_in_range) * 0.3

        # Clamp progress
        self.capture_progress = max(0, min(self.capture_progress, self.capture_threshold))

        # Capture if threshold reached
        if self.capture_progress >= self.capture_threshold and team != self.team:
            self.is_captured = True
            self.team = team
            self.capture_time = time.time()
            self.capture_progress = 0.0
        elif self.capture_progress <= 0 and self.is_captured and self.team != team:
            self.is_captured = False
            self.capture_progress = 0.0

@dataclass
class PowerUp:
    id: str
    type: PowerUpType
    position: Vector2D
    duration: float = 10.0
    value: float = 1.0
    is_active: bool = True
    spawn_time: float = field(default_factory=time.time)

    def is_expired(self) -> bool:
        return time.time() - self.spawn_time > 30.0  # Spawns refresh after 30 seconds

@dataclass
class Hazard:
    id: str
    type: HazardType
    position: Vector2D
    radius: float
    damage_per_second: float
    active: bool = True
    spawn_time: float = field(default_factory=time.time)

    def affect_robot(self, robot: Robot) -> float:
        """Apply hazard damage to robot and return damage amount."""
        if not self.active:
            return 0.0
        damage = self.damage_per_second * 0.1  # Damage per tick (assuming 10 ticks/sec)
        robot.take_damage(damage)
        return damage

@dataclass
class GameState:
    timestamp: float = field(default_factory=time.time)
    robots: Dict[str, Robot] = field(default_factory=dict)
    objectives: Dict[str, Objective] = field(default_factory=dict)
    powerups: Dict[str, PowerUp] = field(default_factory=dict)
    hazards: Dict[str, Hazard] = field(default_factory=dict)
    score: Dict[Team, float] = field(default_factory=lambda: {Team.RED: 0, Team.BLUE: 0})
    round_time: float = 0.0
    max_round_time: float = 300.0  # 5 minutes max
    game_phase: str = "setup"  # setup, active, ending
    winner: Optional[Team] = None
    last_milestone_time: float = 0.0
    difficulty_level: float = 0.5  # 0.0 to 1.0, 0.5 is normal

class AIController(ABC):
    """Abstract base class for AI controllers."""

    @abstractmethod
    def decide_action(self, robot: Robot, game_state: GameState, team_mates: List[Robot]) -> Dict:
        """Decide what action the robot should take next."""
        pass

class AdaptiveAIController(AIController):
    """Advanced AI controller that adapts based on performance and environment."""

    def __init__(self):
        self.learning_rate = 0.1
        self.exploration_rate = 0.3
        self.strategy_history = deque(maxlen=100)  # Last 100 decisions
        self.performance_metrics = {
            'kills': 0,
            'deaths': 0,
            'objectives_completed': 0,
            'team_assists': 0,
            'survival_time': 0
        }
        self.adaptation_timer = 0
        self.survival_time = 0

    def decide_action(self, robot: Robot, game_state: GameState, team_mates: List[Robot]) -> Dict:
        """Main decision-making function."""

        # Update performance metrics
        self.survival_time += 1

        # Adapt difficulty level based on performance
        self._adapt_difficulty(robot, game_state)

        # Get context information
        enemy_robots = self._get_enemy_robots(robot, game_state)
        nearby_objectives = self._get_nearby_objectives(robot, game_state)
        nearby_powerups = self._get_nearby_powerups(robot, game_state)
        nearby_hazards = self._get_nearby_hazards(robot, game_state)

        # Determine current role effectiveness
        role_effectiveness = self._evaluate_role_effectiveness(robot, team_mates, game_state)

        # If robot is low on health, prioritize survival
        if robot.health < robot.max_health * 0.3:
            return self._survival_strategy(robot, nearby_powerups, nearby_hazards)

        # If robot has no weapons or ammo, try to find power-ups or weapons
        if not robot.current_weapon or robot.current_weapon.current_ambo <= 0:
            return self._find_supplies_strategy(robot, nearby_powerups)

        # Decision tree based on role
        if robot.role == RobotRole.ATTACKER:
            return self._attacker_strategy(robot, enemy_robots, nearby_objectives, team_mates)
        elif robot.role == RobotRole.DEFENDER:
            return self._defender_strategy(robot, nearby_objectives, enemy_robots, team_mates)
        elif robot.role == RobotRole.SUPPORT:
            return self._support_strategy(robot, team_mates, enemy_robots)
        elif robot.role == RobotRole.SCOUT:
            return self._scout_strategy(robot, enemy_robots, nearby_objectives)
        elif robot.role == RobotRole.CAPTURER:
            return self._capturer_strategy(robot, nearby_objectives, team_mates)

        # Default fallback
        return self._default_strategy(robot, enemy_robots, nearby_objectives)

    def _adapt_difficulty(self, robot: Robot, game_state: GameState):
        """Adjust difficulty based on robot's performance."""
        if len(self.strategy_history) < 10:
            return  # Need more data

        # Calculate win rate approximation
        win_rate = self.performance_metrics['kills'] / max(1, self.performance_metrics['deaths'])

        # If robot is doing exceptionally well, increase difficulty
        if win_rate > 2.0 and self.adaptation_timer <= 0:
            game_state.difficulty_level = min(1.0, game_state.difficulty_level + 0.1)
            self.adaptation_timer = 60  # Cooldown
        elif win_rate < 0.5 and self.adaptation_timer <= 0:
            game_state.difficulty_level = max(0.1, game_state.difficulty_level - 0.1)
            self.adaptation_timer = 60  # Cooldown

        self.adaptation_timer -= 1

    def _get_enemy_robots(self, robot: Robot, game_state: GameState) -> List[Robot]:
        """Get all enemy robots."""
        return [r for r in game_state.robots.values() 
                if r.team != robot.team and r.is_alive()]

    def _get_nearby_objectives(self, robot: Robot, game_state: GameState) -> List[Objective]:
        """Get objectives within detection range."""
        nearby = []
        for obj in game_state.objectives.values():
            if robot.position.distance_to(obj.position) < 50.0:  # Detection range
                nearby.append(obj)
        return nearby

    def _get_nearby_powerups(self, robot: Robot, game_state: GameState) -> List[PowerUp]:
        """Get power-ups within detection range."""
        nearby = []
        for pu in game_state.powerups.values():
            if pu.is_active and robot.position.distance_to(pu.position) < 30.0:
                nearby.append(pu)
        return nearby

    def _get_nearby_hazards(self, robot: Robot, game_state: GameState) -> List[Hazard]:
        """Get hazards within detection range."""
        nearby = []
        for h in game_state.hazards.values():
            if h.active and robot.position.distance_to(h.position) < 20.0:
                nearby.append(h)
        return nearby

    def _evaluate_role_effectiveness(self, robot: Robot, team_mates: List[Robot], game_state: GameState) -> float:
        """Evaluate how well the robot's current role is working."""
        # Simple evaluation based on objective progress and enemy proximity
        if robot.role == RobotRole.ATTACKER:
            # Count enemies killed and objectives captured
            return self.performance_metrics['kills'] / max(1, len(game_state.robots) - len(team_mates))
        elif robot.role == RobotRole.DEFENDER:
            # Count objectives defended
            defended = sum(1 for obj in game_state.objectives.values() 
                          if obj.team == robot.team and obj.is_captured)
            return defended / max(1, len(game_state.objectives))
        elif robot.role == RobotRole.SUPPORT:
            # Count team mates healed or shielded
            return self.performance_metrics['team_assists'] / max(1, len(team_mates))
        elif robot.role == RobotRole.SCOUT:
            # Count enemy positions discovered
            return len(self.strategy_history) / 100.0  # Proportion of decisions involving scouting
        elif robot.role == RobotRole.CAPTURER:
            # Count capture progress made
            return self.performance_metrics['objectives_completed'] / max(1, len(game_state.objectives))

        return 0.5  # Default

    def _survival_strategy(self, robot: Robot, nearby_powerups: List[PowerUp], nearby_hazards: List[Hazard]) -> Dict:
        """Strategy when robot is critically low on health."""
        # Look for healing power-ups first
        for pu in nearby_powerups:
            if pu.type == PowerUpType.REGENERATION:
                return {
                    'action': 'move',
                    'target': pu.position,
                    'reason': 'seeking regeneration'
                }

        # Look for shield power-ups
        for pu in nearby_powerups:
            if pu.type == PowerUpType.SHIELD:
                return {
                    'action': 'move',
                    'target': pu.position,
                    'reason': 'seeking shield'
                }

        # Avoid hazards
        for hazard in nearby_hazards:
            # Move away from hazard
            direction = robot.position - hazard.position
            if direction.magnitude() > 0:
                direction = direction.normalize()
                return {
                    'action': 'move',
                    'target': robot.position + direction * 10,
                    'reason': 'avoiding hazard'
                }

        # Fallback: move to nearest teammate
        nearest_teammate = self._find_nearest_teammate(robot, game_state)
        if nearest_teammate:
            return {
                'action': 'move',
                'target': nearest_teammate.position,
                'reason': 'seeking teammate support'
            }

        # Just move randomly
        return {
            'action': 'move',
            'target': robot.position + Vector2D(random.uniform(-5, 5), random.uniform(-5, 5)),
            'reason': 'survival mode'
        }

    def _find_supplies_strategy(self, robot: Robot, nearby_powerups: List[PowerUp]) -> Dict:
        """Strategy when robot needs supplies (ammo, weapons)."""
        # Look for weapons or ammo power-ups
        for pu in nearby_powerups:
            if pu.type == PowerUpType.DAMAGE_BOOST:
                return {
                    'action': 'move',
                    'target': pu.position,
                    'reason': 'seeking damage boost'
                }

        # Look for regeneration or shield
        for pu in nearby_powerups:
            if pu.type == PowerUpType.REGENERATION or pu.type == PowerUpType.SHIELD:
                return {
                    'action': 'move',
                    'target': pu.position,
                    'reason': 'seeking health support'
                }

        # Try to find a teammate with excess ammo
        nearest_teammate = self._find_nearest_teammate(robot, game_state)
        if nearest_teammate and nearest_teammate.current_weapon and nearest_teammate.current_weapon.current_ammo > 10:
            return {
                'action': 'move',
                'target': nearest_teammate.position,
                'reason': 'seeking teammate for ammo'
            }

        # Fallback: move towards objective
        objectives = self._get_nearby_objectives(robot, game_state)
        if objectives:
            return {
                'action': 'move',
                'target': objectives[0].position,
                'reason': 'moving toward objective'
            }

        # Random movement
        return {
            'action': 'move',
            'target': robot.position + Vector2D(random.uniform(-5, 5), random.uniform(-5, 5)),
            'reason': 'searching for supplies'
        }

    def _attacker_strategy(self, robot: Robot, enemy_robots: List[Robot], 
                          nearby_objectives: List[Objective], team_mates: List[Robot]) -> Dict:
        """Strategy for attacker role."""

        # If an enemy is close enough to attack, attack
        if enemy_robots:
            nearest_enemy = min(enemy_robots, key=lambda e: robot.position.distance_to(e.position))
            if robot.position.distance_to(nearest_enemy.position) < robot.current_weapon.range:
                # Check if we can fire
                if robot.can_fire():
                    return {
                        'action': 'attack',
                        'target': nearest_enemy.id,
                        'reason': 'enemy in range'
                    }
                else:
                    # Move closer if possible
                    return {
                        'action': 'move',
                        'target': nearest_enemy.position,
                        'reason': 'approaching enemy'
                    }

        # Look for objectives to capture
        if nearby_objectives:
            for obj in nearby_objectives:
                if not obj.is_captured or obj.team != robot.team:
                    # If objective is contested or enemy-controlled, capture it
                    if robot.position.distance_to(obj.position) < 10:
                        return {
                            'action': 'capture',
                            'target': obj.id,
                            'reason': 'capturing objective'
                        }
                    else:
                        return {
                            'action': 'move',
                            'target': obj.position,
                            'reason': 'moving to objective'
                        }

        # Look for power-ups
        nearby_powerups = self._get_nearby_powerups(robot, game_state)
        for pu in nearby_powerups:
            if pu.type in [PowerUpType.DAMAGE_BOOST, PowerUpType.SPEED_BOOST]:
                return {
                    'action': 'move',
                    'target': pu.position,
                    'reason': 'seeking attack power-up'
                }

        # If no immediate targets, patrol objective areas
        objectives = game_state.objectives.values()
        if objectives:
            target_obj = random.choice(list(objectives))
            return {
                'action': 'move',
                'target': target_obj.position,
                'reason': 'patrolling objective area'
            }

        # Random movement
        return {
            'action': 'move',
            'target': robot.position + Vector2D(random.uniform(-10, 10), random.uniform(-10, 10)),
            'reason': 'no targets found'
        }

    def _defender_strategy(self, robot: Robot, nearby_objectives: List[Objective], 
                          enemy_robots: List[Robot], team_mates: List[Robot]) -> Dict:
        """Strategy for defender role."""

        # If enemy is near a defended objective, attack
        if enemy_robots and nearby_objectives:
            # Find the objective we're defending
            our_objectives = [obj for obj in nearby_objectives if obj.team == robot.team]
            if our_objectives:
                target_obj = our_objectives[0]
                nearest_enemy = min(enemy_robots, key=lambda e: e.position.distance_to(target_obj.position))

                if robot.position.distance_to(nearest_enemy.position) < robot.current_weapon.range:
                    if robot.can_fire():
                        return {
                            'action': 'attack',
                            'target': nearest_enemy.id,
                            'reason': 'defending objective'
                        }
                    else:
                        return {
                            'action': 'move',
                            'target': nearest_enemy.position,
                            'reason': 'intercepting enemy'
                        }
                else:
                    # Move toward enemy approaching objective
                    return {
                        'action': 'move',
                        'target': nearest_enemy.position,
                        'reason': 'intercepting enemy'
                    }

        # If no enemies nearby, stay near objective
        if nearby_objectives:
            our_objectives = [obj for obj in nearby_objectives if obj.team == robot.team]
            if our_objectives:
                return {
                    'action': 'move',
                    'target': our_objectives[0].position,
                    'reason': 'defending objective'
                }

        # Look for power-ups that help defense
        nearby_powerups = self._get_nearby_powerups(robot, game_state)
        for pu in nearby_powerups:
            if pu.type == PowerUpType.SHIELD:
                return {
                    'action': 'move',
                    'target': pu.position,
                    'reason': 'seeking shield for defense'
                }

        # Stay near teammate if possible
        if team_mates:
            nearest_teammate = self._find_nearest_teammate(robot, game_state)
            if nearest_teammate:
                return {
                    'action': 'move',
                    'target': nearest_teammate.position,
                    'reason': 'staying with team'
                }

        # Patrol randomly
        return {
            'action': 'move',
            'target': robot.position + Vector2D(random.uniform(-8, 8), random.uniform(-8, 8)),
            'reason': 'patrolling'
        }

    def _support_strategy(self, robot: Robot, team_mates: List[Robot], enemy_robots: List[Robot]) -> Dict:
        """Strategy for support role."""

        # Look for teammates who need healing
        low_health_teammates = [m for m in team_mates 
                               if m.health < m.max_health * 0.5 and m.is_alive()]

        if low_health_teammates:
            nearest_low_health = min(low_health_teammates, 
                                   key=lambda m: robot.position.distance_to(m.position))

            # If close enough, use support ability
            if robot.position.distance_to(nearest_low_health.position) < 15.0:
                # Find if we have a healing ability
                if robot.current_weapon.type == WeaponType.SUPPORT and robot.can_fire():
                    return {
                        'action': 'support',
                        'target': nearest_low_health.id,
                        'reason': 'healing teammate'
                    }
                else:
                    # Move closer to heal
                    return {
                        'action': 'move',
                        'target': nearest_low_health.position,
                        'reason': 'moving to heal teammate'
                    }

        # Look for teammates who need shields
        low_shield_teammates = [m for m in team_mates 
                               if m.shield < m.shield_max * 0.3 and m.is_alive()]

        if low_shield_teammates:
            nearest_low_shield = min(low_shield_teammates, 
                                   key=lambda m: robot.position.distance_to(m.position))

            if robot.position.distance_to(nearest_low_shield.position) < 15.0:
                if robot.current_weapon.type == WeaponType.SUPPORT and robot.can_fire():
                    return {
                        'action': 'support',
                        'target': nearest_low_shield.id,
                        'reason': 'shielding teammate'
                    }
                else:
                    return {
                        'action': 'move',
                        'target': nearest_low_shield.position,
                        'reason': 'moving to shield teammate'
                    }

        # Look for enemy robots to disrupt
        if enemy_robots:
            nearest_enemy = min(enemy_robots, key=lambda e: robot.position.distance_to(e.position))
            if robot.position.distance_to(nearest_enemy.position) < robot.current_weapon.range:
                if robot.can_fire():
                    return {
                        'action': 'attack',
                        'target': nearest_enemy.id,
                        'reason': 'disrupting enemy'
                    }

        # Look for power-ups for team
        nearby_powerups = self._get_nearby_powerups(robot, game_state)
        for pu in nearby_powerups:
            if pu.type in [PowerUpType.REGENERATION, PowerUpType.SHIELD]:
                # We're support, so we might want to get it for team
                return {
                    'action': 'move',
                    'target': pu.position,
                    'reason': 'collecting team support power-up'
                }

        # Move toward nearest objective
        objectives = game_state.objectives.values()
        if objectives:
            target_obj = random.choice(list(objectives))
            return {
                'action': 'move',
                'target': target_obj.position,
                'reason': 'supporting objective'
            }

        # Default: move toward teammate with lowest health
        if team_mates:
            lowest_health_teammate = min(team_mates, key=lambda m: m.health)
            return {
                'action': 'move',
                'target': lowest_health_teammate.position,
                'reason': 'supporting lowest health teammate'
            }

        return {
            'action': 'move',
            'target': robot.position + Vector2D(random.uniform(-5, 5), random.uniform(-5, 5)),
            'reason': 'support patrol'
        }

    def _scout_strategy(self, robot: Robot, enemy_robots: List[Robot], 
                       nearby_objectives: List[Objective]) -> Dict:
        """Strategy for scout role."""

        # Look for enemies that aren't being targeted by team
        if enemy_robots:
            # Find an enemy that's isolated
            isolated_enemies = []
            for enemy in enemy_robots:
                # If no teammate is close to this enemy
                teammate_close = False
                for teammate in game_state.robots.values():
                    if teammate.team == robot.team and teammate.is_alive():
                        if teammate.position.distance_to(enemy.position) < 20:
                            teammate_close = True
                            break
                if not teammate_close:
                    isolated_enemies.append(enemy)

            if isolated_enemies:
                nearest_isolated = min(isolated_enemies, key=lambda e: robot.position.distance_to(e.position))
                if robot.position.distance_to(nearest_isolated.position) < robot.current_weapon.range:
                    if robot.can_fire():
                        return {
                            'action': 'attack',
                            'target': nearest_isolated.id,
                            'reason': 'attacking isolated enemy'
                        }
                else:
                    return {
                        'action': 'move',
                        'target': nearest_isolated.position,
                        'reason': 'scouting enemy'
                    }

        # Look for objectives that need reconnaissance
        if nearby_objectives:
            # Look for objectives that are contested or enemy-owned
            contested_objectives = [obj for obj in nearby_objectives if obj.is_captured and obj.team != robot.team]
            if contested_objectives:
                target_obj = min(contested_objectives, key=lambda o: robot.position.distance_to(o.position))
                return {
                    'action': 'move',
                    'target': target_obj.position,
                    'reason': 'reconnoitering enemy objective'
                }

        # Look for power-ups (scouts benefit from speed)
        nearby_powerups = self._get_nearby_powerups(robot, game_state)
        for pu in nearby_powerups:
            if pu.type == PowerUpType.SPEED_BOOST:
                return {
                    'action': 'move',
                    'target': pu.position,
                    'reason': 'seeking speed boost'
                }

        # Patrol random areas
        return {
            'action': 'move',
            'target': robot.position + Vector2D(random.uniform(-15, 15), random.uniform(-15, 15)),
            'reason': 'exploring'
        }

    def _capturer_strategy(self, robot: Robot, nearby_objectives: List[Objective], 
                          team_mates: List[Robot]) -> Dict:
        """Strategy for capturer role."""

        # Look for objectives to capture
        if nearby_objectives:
            # Find objectives that are not captured or captured by enemy
            capturable = [obj for obj in nearby_objectives 
                         if not obj.is_captured or obj.team != robot.team]

            if capturable:
                target_obj = min(capturable, key=lambda o: robot.position.distance_to(o.position))

                # If close enough, start capturing
                if robot.position.distance_to(target_obj.position) < 8:
                    return {
                        'action': 'capture',
                        'target': target_obj.id,
                        'reason': 'capturing objective'
                    }
                else:
                    return {
                        'action': 'move',
                        'target': target_obj.position,
                        'reason': 'moving to capture objective'
                    }

        # Look for team members to coordinate with
        if team_mates:
            # Move toward teammates to form capture group
            nearest_teammate = self._find_nearest_teammate(robot, game_state)
            if nearest_teammate:
                return {
                    'action': 'move',
                    'target': nearest_teammate.position,
                    'reason': 'coordinating with team for capture'
                }

        # Look for power-ups that help capture
        nearby_powerups = self._get_nearby_powerups(robot, game_state)
        for pu in nearby_powerups:
            if pu.type == PowerUpType.SPEED_BOOST:
                return {
                    'action': 'move',
                    'target': pu.position,
                    'reason': 'seeking speed boost for capture'
                }

        # Default: move toward a random objective
        objectives = game_state.objectives.values()
        if objectives:
            target_obj = random.choice(list(objectives))
            return {
                'action': 'move',
                'target': target_obj.position,
                'reason': 'searching for objective to capture'
            }

        return {
            'action': 'move',
            'target': robot.position + Vector2D(random.uniform(-10, 10), random.uniform(-10, 10)),
            'reason': 'capturer patrol'
        }

    def _default_strategy(self, robot: Robot, enemy_robots: List[Robot], nearby_objectives: List[Objective]) -> Dict:
        """Fallback strategy when no specific role applies."""

        # If there are enemies nearby, attack
        if enemy_robots:
            nearest_enemy = min(enemy_robots, key=lambda e: robot.position.distance_to(e.position))
            if robot.position.distance_to(nearest_enemy.position) < robot.current_weapon.range:
                if robot.can_fire():
                    return {
                        'action': 'attack',
                        'target': nearest_enemy.id,
                        'reason': 'default attack'
                    }
                else:
                    return {
                        'action': 'move',
                        'target': nearest_enemy.position,
                        'reason': 'approaching enemy'
                    }

        # If there are objectives nearby, go to them
        if nearby_objectives:
            target_obj = min(nearby_objectives, key=lambda o: robot.position.distance_to(o.position))
            return {
                'action': 'move',
                'target': target_obj.position,
                'reason': 'default objective pursuit'
            }

        # Look for power-ups
        nearby_powerups = self._get_nearby_powerups(robot, game_state)
        if nearby_powerups:
            closest_powerup = min(nearby_powerups, key=lambda p: robot.position.distance_to(p.position))
            return {
                'action': 'move',
                'target': closest_powerup.position,
                'reason': 'default power-up pursuit'
            }

        # Just move randomly
        return {
            'action': 'move',
            'target': robot.position + Vector2D(random.uniform(-8, 8), random.uniform(-8, 8)),
