        nearby_powerups = self._get_nearby_powerups(robot, game_state)
        nearby_hazards = self._get_nearby_hazards(robot, game_state)

        # Determine current role effectiveness
        role_effectiveness = self._evaluate_role_effectiveness(robot, team_mates, game_state)

        # If robot is low on health, prioritize survival
        if robot.health < robot.max_health * 0.3:
            return self._survival_strategy(robot, nearby_powerups, nearby_hazards)

