    def _find_nearest_teammate(self, robot: Robot, game_state: GameState) -> Optional[Robot]:
        """Find the nearest teammate."""
        teammates = [r for r in game_state.robots.values() 
                    if r.team == robot.team and r.is_alive() and r.id != robot.id]
        if not teammates:
            return None
        return min(teammates, key=lambda m: robot.position.distance_to(m.position))

