@dataclass
class Vector2D:
    x: float = 0.0
    y: float = 0.0

    def __add__(self, other):
        return Vector2D(self.x + other.x, self.y + other.y)

    def __sub__(self, other):
        return Vector2D(self.x - other.x, self.y - other.y)

    def __mul__(self, scalar):
        return Vector2D(self.x * scalar, self.y * scalar)

    def __truediv__(self, scalar):
        if scalar == 0:
            return Vector2D(0, 0)
        return Vector2D(self.x / scalar, self.y / scalar)

    def magnitude(self):
        return math.sqrt(self.x**2 + self.y**2)

    def normalize(self):
        mag = self.magnitude()
        if mag == 0:
            return Vector2D(0, 0)
        return self / mag

    def distance_to(self, other):
        return (self - other).magnitude()

    def to_tuple(self):
        return (self.x, self.y)

@dataclass
class Weapon:
    name: str
    type: WeaponType
    damage: float
    range: float
    fire_rate: float  # seconds between shots
    ammo: int
    max_ammo: int
    reload_time: float = 2.0
    splash_radius: float = 0.0  # for explosives
    accuracy: float = 1.0  # 0.0 to 1.0

    def __post_init__(self):
        self.current_ammo = self.ammo
        self.last_fired = 0.0

@dataclass
class Robot:
    id: str
    team: Team
    position: Vector2D
    health: float
    max_health: float
    speed: float
    role: RobotRole
    weapons: List[Weapon]
    current_weapon_index: int = 0
    velocity: Vector2D = field(default_factory=lambda: Vector2D(0, 0))
    shield: float = 0.0
    shield_regen_rate: float = 0.1
    shield_max: float = 100.0
    cooldowns: Dict[str, float] = field(default_factory=dict)  # ability cooldowns
    knowledge: Dict = field(default_factory=dict)  # memory of past battles
    last_action: str = ""
    last_action_time: float = 0.0
    objectives: List[ObjectiveType] = field(default_factory=list)

    def __post_init__(self):
        self.current_weapon = self.weapons[self.current_weapon_index] if self.weapons else None

    def take_damage(self, damage: float) -> bool:
        """Apply damage to robot, considering shield first."""
        if self.shield > 0:
            shield_absorbed = min(damage, self.shield)
            self.shield -= shield_absorbed
            damage -= shield_absorbed

        if damage > 0:
            self.health -= damage
            if self.health <= 0:
                self.health = 0
                return False  # Robot is defeated
        return True

    def heal(self, amount: float):
        """Heal robot."""
        self.health = min(self.max_health, self.health + amount)

    def add_shield(self, amount: float):
        """Add shield to robot."""
        self.shield = min(self.shield_max, self.shield + amount)

    def is_alive(self) -> bool:
        return self.health > 0

    def can_fire(self) -> bool:
        """Check if weapon is ready to fire."""
        if not self.current_weapon:
            return False
        return time.time() - self.current_weapon.last_fired >= self.current_weapon.fire_rate

    def fire_weapon(self) -> Optional[Dict]:
        """Fire current weapon if possible. Returns projectile data or None."""
        if not self.current_weapon or not self.can_fire():
            return None

        # Reduce ammo and reset timer
        self.current_weapon.current_ammo -= 1
        self.current_weapon.last_fired = time.time()

        # Handle reload if out of ammo
        if self.current_weapon.current_ammo <= 0:
            self._reload_weapon()

        # Return projectile data
        return {
            'source': self.id,
            'team': self.team,
            'position': self.position,
            'target': None,  # Will be set by AI
            'damage': self.current_weapon.damage,
            'type': self.current_weapon.type,
            'range': self.current_weapon.range,
            'splash_radius': self.current_weapon.splash_radius,
            'speed': 15.0,
            'creator': self
        }

    def _reload_weapon(self):
        """Reload current weapon."""
        self.current_weapon.current_ammo = self.current_weapon.max_ammo

    def select_weapon(self, index: int):
        """Select a weapon by index."""
        if 0 <= index < len(self.weapons):
            self.current_weapon_index = index
            self.current_weapon = self.weapons[index]

    def update_cooldowns(self, dt: float):
        """Update all cooldowns."""
        for ability, cooldown in list(self.cooldowns.items()):
            self.cooldowns[ability] = max(0, cooldown - dt)

    def can_use_ability(self, ability: str) -> bool:
        """Check if ability is ready to use."""
        return self.cooldowns.get(ability, 0) <= 0

    def use_ability(self, ability: str):
        """Use ability and set cooldown."""
        if self.can_use_ability(ability):
            self.cooldowns[ability] = 5.0  # 5 second cooldown for most abilities
            return True
        return False

@dataclass
class Objective:
    id: str
    type: ObjectiveType
    position: Vector2D
    team: Team
    capture_progress: float = 0.0
    is_captured: bool = False
    capture_time: float = 0.0
    capture_threshold: float = 100.0
    defenders: List[str] = field(default_factory=list)
    attackers: List[str] = field(default_factory=list)

    def update_capture(self, team: Team, robots_in_range: List[str]):
        """Update capture progress based on robots in range."""
        if team == self.team:
            # Team already controlling - increase slowly
            self.capture_progress += len(robots_in_range) * 0.1
        else:
            # Enemy team trying to capture
            self.capture_progress -= len(robots_in_range) * 0.3

        # Clamp progress
        self.capture_progress = max(0, min(self.capture_progress, self.capture_threshold))

        # Capture if threshold reached
        if self.capture_progress >= self.capture_threshold and team != self.team:
            self.is_captured = True
            self.team = team
            self.capture_time = time.time()
            self.capture_progress = 0.0
        elif self.capture_progress <= 0 and self.is_captured and self.team != team:
            self.is_captured = False
            self.capture_progress = 0.0

@dataclass
class PowerUp:
    id: str
    type: PowerUpType
    position: Vector2D
    duration: float = 10.0
    value: float = 1.0
    is_active: bool = True
    spawn_time: float = field(default_factory=time.time)

    def is_expired(self) -> bool:
        return time.time() - self.spawn_time > 30.0  # Spawns refresh after 30 seconds

@dataclass
class Hazard:
    id: str
    type: HazardType
    position: Vector2D
    radius: float
    damage_per_second: float
    active: bool = True
    spawn_time: float = field(default_factory=time.time)

    def affect_robot(self, robot: Robot) -> float:
        """Apply hazard damage to robot and return damage amount."""
        if not self.active:
            return 0.0
        damage = self.damage_per_second * 0.1  # Damage per tick (assuming 10 ticks/sec)
        robot.take_damage(damage)
        return damage

@dataclass
class GameState:
    timestamp: float = field(default_factory=time.time)
    robots: Dict[str, Robot] = field(default_factory=dict)
    objectives: Dict[str, Objective] = field(default_factory=dict)
    powerups: Dict[str, PowerUp] = field(default_factory=dict)
    hazards: Dict[str, Hazard] = field(default_factory=dict)
    score: Dict[Team, float] = field(default_factory=lambda: {Team.RED: 0, Team.BLUE: 0})
    round_time: float = 0.0
    max_round_time: float = 300.0  # 5 minutes max
    game_phase: str = "setup"  # setup, active, ending
    winner: Optional[Team] = None
    last_milestone_time: float = 0.0
    difficulty_level: float = 0.5  # 0.0 to 1.0, 0.5 is normal

class AIController(ABC):
    """Abstract base class for AI controllers."""

    @abstractmethod
    def decide_action(self, robot: Robot, game_state: GameState, team_mates: List[Robot]) -> Dict:
        """Decide what action the robot should take next."""
        pass

class AdaptiveAIController(AIController):
    """Advanced AI controller that adapts based on performance and environment."""

    def __init__(self):
        self.learning_rate = 0.1
        self.exploration_rate = 0.3
        self.strategy_history = deque(maxlen=100)  # Last 100 decisions
        self.performance_metrics = {
            'kills': 0,
            'deaths': 0,
            'objectives_completed': 0,
            'team_assists': 0,
            'survival_time': 0
        }
        self.adaptation_timer = 0
        self.survival_time = 0

    def decide_action(self, robot: Robot, game_state: GameState, team_mates: List[Robot]) -> Dict:
        """Main decision-making function."""

        # Update performance metrics
        self.survival_time += 1

        # Adapt difficulty level based on performance
        self._adapt_difficulty(robot, game_state)

        # Get context information
        enemy_robots = self._get_enemy_robots(robot, game_state)
        nearby_objectives = self._get_nearby_objectives(robot, game_state)
        nearby_powerups = self._get_nearby_powerups(robot, game_state)
        nearby_hazards = self._get_nearby_hazards(robot, game_state)

        # Determine current role effectiveness
        role_effectiveness = self._evaluate_role_effectiveness(robot, team_mates, game_state)

        # If robot is low on health, prioritize survival
        if robot.health < robot.max_health * 0.3:
            return self._survival_strategy(robot, nearby_powerups, nearby_hazards)

        # If robot has no weapons or ammo, try to find power-ups or weapons
        if not robot.current_weapon or robot.current_weapon.current_ambo <= 0:
            return self._find_supplies_strategy(robot, nearby_powerups)

        # Decision tree based on role
        if robot.role == RobotRole.ATTACKER:
            return self._attacker_strategy(robot, enemy_robots, nearby_objectives, team_mates)
        elif robot.role == RobotRole.DEFENDER:
            return self._defender_strategy(robot, nearby_objectives, enemy_robots, team_mates)
        elif robot.role == RobotRole.SUPPORT:
            return self._support_strategy(robot, team_mates, enemy_robots)
        elif robot.role == RobotRole.SCOUT:
            return self._scout_strategy(robot, enemy_robots, nearby_objectives)
        elif robot.role == RobotRole.CAPTURER:
            return self._capturer_strategy(robot, nearby_objectives, team_mates)

        # Default fallback
        return self._default_strategy(robot, enemy_robots, nearby_objectives)

    def _adapt_difficulty(self, robot: Robot, game_state: GameState):
        """Adjust difficulty based on robot's performance."""
        if len(self.strategy_history) < 10:
            return  # Need more data

        # Calculate win rate approximation
        win_rate = self.performance_metrics['kills'] / max(1, self.performance_metrics['deaths'])

        # If robot is doing exceptionally well, increase difficulty
        if win_rate > 2.0 and self.adaptation_timer <= 0:
            game_state.difficulty_level = min(1.0, game_state.difficulty_level + 0.1)
            self.adaptation_timer = 60  # Cooldown
        elif win_rate < 0.5 and self.adaptation_timer <= 0:
            game_state.difficulty_level = max(0.1, game_state.difficulty_level - 0.1)
            self.adaptation_timer = 60  # Cooldown

        self.adaptation_timer -= 1

    def _get_enemy_robots(self, robot: Robot, game_state: GameState) -> List[Robot]:
        """Get all enemy robots."""
        return [r for r in game_state.robots.values() 
                if r.team != robot.team and r.is_alive()]

    def _get_nearby_objectives(self, robot: Robot, game_state: GameState) -> List[Objective]:
        """Get objectives within detection range."""
        nearby = []
        for obj in game_state.objectives.values():
            if robot.position.distance_to(obj.position) < 50.0:  # Detection range
                nearby.append(obj)
        return nearby

    def _get_nearby_powerups(self, robot: Robot, game_state: GameState) -> List[PowerUp]:
        """Get power-ups within detection range."""
        nearby = []
        for pu in game_state.powerups.values():
            if pu.is_active and robot.position.distance_to(pu.position) < 30.0:
                nearby.append(pu)
        return nearby

    def _get_nearby_hazards(self, robot: Robot, game_state: GameState) -> List[Hazard]:
        """Get hazards within detection range."""
        nearby = []
        for h in game_state.hazards.values():
            if h.active and robot.position.distance_to(h.position) < 20.0:
                nearby.append(h)
        return nearby

    def _evaluate_role_effectiveness(self, robot: Robot, team_mates: List[Robot], game_state: GameState) -> float:
        """Evaluate how well the robot's current role is working."""
        # Simple evaluation based on objective progress and enemy proximity
        if robot.role == RobotRole.ATTACKER:
            # Count enemies killed and objectives captured
            return self.performance_metrics['kills'] / max(1, len(game_state.robots) - len(team_mates))
        elif robot.role == RobotRole.DEFENDER:
            # Count objectives defended
            defended = sum(1 for obj in game_state.objectives.values() 
                          if obj.team == robot.team and obj.is_captured)
            return defended / max(1, len(game_state.objectives))
        elif robot.role == RobotRole.SUPPORT:
            # Count team mates healed or shielded
            return self.performance_metrics['team_assists'] / max(1, len(team_mates))
        elif robot.role == RobotRole.SCOUT:
            # Count enemy positions discovered
            return len(self.strategy_history) / 100.0  # Proportion of decisions involving scouting
        elif robot.role == RobotRole.CAPTURER:
            # Count capture progress made
            return self.performance_metrics['objectives_completed'] / max(1, len(game_state.objectives))

        return 0.5  # Default

