    type: WeaponType
    damage: float
    range: float
    fire_rate: float  # seconds between shots
    ammo: int
    max_ammo: int
    reload_time: float = 2.0
    splash_radius: float = 0.0  # for explosives
    accuracy: float = 1.0  # 0.0 to 1.0

    def __post_init__(self):
        self.current_ammo = self.ammo
        self.last_fired = 0.0

@dataclass
class Robot:
    id: str
    team: Team
    position: Vector2D
    health: float
    max_health: float
    speed: float
    role: RobotRole
    weapons: List[Weapon]
    current_weapon_index: int = 0
    velocity: Vector2D = field(default_factory=lambda: Vector2D(0, 0))
    shield: float = 0.0
    shield_regen_rate: float = 0.1
    shield_max: float = 100.0
    cooldowns: Dict[str, float] = field(default_factory=dict)  # ability cooldowns
    knowledge: Dict = field(default_factory=dict)  # memory of past battles
    last_action: str = ""
    last_action_time: float = 0.0
    objectives: List[ObjectiveType] = field(default_factory=list)

    def __post_init__(self):
        self.current_weapon = self.weapons[self.current_weapon_index] if self.weapons else None

    def take_damage(self, damage: float) -> bool:
        """Apply damage to robot, considering shield first."""
        if self.shield > 0:
            shield_absorbed = min(damage, self.shield)
            self.shield -= shield_absorbed
            damage -= shield_absorbed

        if damage > 0:
            self.health -= damage
            if self.health <= 0:
                self.health = 0
                return False  # Robot is defeated
        return True

    def heal(self, amount: float):
        """Heal robot."""
        self.health = min(self.max_health, self.health + amount)

    def add_shield(self, amount: float):
        """Add shield to robot."""
        self.shield = min(self.shield_max, self.shield + amount)

    def is_alive(self) -> bool:
        return self.health > 0

    def can_fire(self) -> bool:
        """Check if weapon is ready to fire."""
        if not self.current_weapon:
            return False
        return time.time() - self.current_weapon.last_fired >= self.current_weapon.fire_rate

    def fire_weapon(self) -> Optional[Dict]:
        """Fire current weapon if possible. Returns projectile data or None."""
        if not self.current_weapon or not self.can_fire():
            return None

        # Reduce ammo and reset timer
        self.current_weapon.current_ammo -= 1
        self.current_weapon.last_fired = time.time()

        # Handle reload if out of ammo
        if self.current_weapon.current_ammo <= 0:
            self._reload_weapon()

        # Return projectile data
        return {
            'source': self.id,
            'team': self.team,
            'position': self.position,
            'target': None,  # Will be set by AI
            'damage': self.current_weapon.damage,
            'type': self.current_weapon.type,
            'range': self.current_weapon.range,
            'splash_radius': self.current_weapon.splash_radius,
            'speed': 15.0,
            'creator': self
        }

    def _reload_weapon(self):
        """Reload current weapon."""
        self.current_weapon.current_ammo = self.current_weapon.max_ammo

    def select_weapon(self, index: int):
        """Select a weapon by index."""
        if 0 <= index < len(self.weapons):
            self.current_weapon_index = index
            self.current_weapon = self.weapons[index]

    def update_cooldowns(self, dt: float):
        """Update all cooldowns."""
        for ability, cooldown in list(self.cooldowns.items()):
            self.cooldowns[ability] = max(0, cooldown - dt)

    def can_use_ability(self, ability: str) -> bool:
        """Check if ability is ready to use."""
        return self.cooldowns.get(ability, 0) <= 0

    def use_ability(self, ability: str):
        """Use ability and set cooldown."""
        if self.can_use_ability(ability):
            self.cooldowns[ability] = 5.0  # 5 second cooldown for most abilities
            return True
        return False

@dataclass
class Objective:
    id: str
    type: ObjectiveType
    position: Vector2D
    team: Team
    capture_progress: float = 0.0
    is_captured: bool = False
    capture_time: float = 0.0
    capture_threshold: float = 100.0
    defenders: List[str] = field(default_factory=list)
    attackers: List[str] = field(default_factory=list)

    def update_capture(self, team: Team, robots_in_range: List[str]):
        """Update capture progress based on robots in range."""
        if team == self.team:
            # Team already controlling - increase slowly
            self.capture_progress += len(robots_in_range) * 0.1
        else:
            # Enemy team trying to capture
            self.capture_progress -= len(robots_in_range) * 0.3

        # Clamp progress
        self.capture_progress = max(0, min(self.capture_progress, self.capture_threshold))

        # Capture if threshold reached
        if self.capture_progress >= self.capture_threshold and team != self.team:
            self.is_captured = True
            self.team = team
            self.capture_time = time.time()
            self.capture_progress = 0.0
        elif self.capture_progress <= 0 and self.is_captured and self.team != team:
            self.is_captured = False
            self.capture_progress = 0.0

