import json
import uuid
from datetime import datetime
from typing import List, Dict, Optional, Any
from dataclasses import dataclass, field
from enum import Enum


# ----------------------------
# ENUMERATIONS AND DATA CLASSES
# ----------------------------

class Role(Enum):
    COACH = "coach"
    PLAYER = "player"

class EventType(Enum):
    PRACTICE = "practice"
    MATCH = "match"
    MEETING = "meeting"
    OTHER = "other"

@dataclass
class User:
    id: str = field(default_factory=lambda: str(uuid.uuid4()))
    name: str = ""
    email: str = ""
    role: Role = Role.PLAYER
    team_id: str = ""
    created_at: datetime = field(default_factory=datetime.now)
    is_active: bool = True

@dataclass
class Event:
    id: str = field(default_factory=lambda: str(uuid.uuid4()))
    title: str = ""
    type: EventType = EventType.OTHER
    start_time: datetime = field(default_factory=datetime.now)
    end_time: datetime = field(default_factory=datetime.now)
    location: str = ""
    description: str = ""
    attendees: List[str] = field(default_factory=list)  # List of user IDs
    created_by: str = ""  # Coach ID
    created_at: datetime = field(default_factory=datetime.now)

@dataclass
class PerformanceMetric:
    player_id: str = ""
    metric_name: str = ""
    value: float = 0.0
    unit: str = ""
    timestamp: datetime = field(default_factory=datetime.now)
    source: str = "manual"  # "manual" or "wearable"
    notes: str = ""


# ----------------------------
# MAIN TEAMSYNC APPLICATION
# ----------------------------

class TeamSync:
    def __init__(self):
        self.users: Dict[str, User] = {}  # user_id -> User
        self.events: Dict[str, Event] = {}  # event_id -> Event
        self.performance_metrics: List[PerformanceMetric] = []
        self.team_id: str = str(uuid.uuid4())  # Single team for simplicity

    # USER MANAGEMENT MODULE
    def add_user(self, name: str, email: str, role: Role) -> User:
        if any(user.email == email for user in self.users.values()):
            raise ValueError(f"User with email {email} already exists.")
        user = User(name=name, email=email, role=role, team_id=self.team_id)
        self.users[user.id] = user
        return user

    def get_user(self, user_id: str) -> Optional[User]:
        return self.users.get(user_id)

    def update_user(self, user_id: str, name: str = None, email: str = None, is_active: bool = None) -> bool:
        user = self.get_user(user_id)
        if not user:
            return False
        if name is not None:
            user.name = name
        if email is not None:
            if any(u.email == email and u.id != user_id for u in self.users.values()):
                raise ValueError(f"Email {email} is already in use by another user.")
            user.email = email
        if is_active is not None:
            user.is_active = is_active
        return True

    def delete_user(self, user_id: str) -> bool:
        if user_id not in self.users:
            return False
        # Soft delete: deactivate instead of removing to preserve metric history
        self.users[user_id].is_active = False
        return True

    def get_coaches(self) -> List[User]:
        return [user for user in self.users.values() if user.role == Role.COACH]

    def get_players(self) -> List[User]:
        return [user for user in self.users.values() if user.role == Role.PLAYER and user.is_active]

    # SCHEDULING AND COMMUNICATION MODULE
    def create_event(self, title: str, event_type: EventType, start_time: datetime, end_time: datetime, 
                     location: str, description: str, coach_id: str, attendee_ids: List[str]) -> Event:
        if coach_id not in self.users or self.users[coach_id].role != Role.COACH:
            raise ValueError("Only coaches can create events.")
        for attendee_id in attendee_ids:
            if attendee_id not in self.users or not self.users[attendee_id].is_active:
                raise ValueError(f"Invalid or inactive attendee: {attendee_id}")
        event = Event(
            title=title,
            type=event_type,
            start_time=start_time,
            end_time=end_time,
            location=location,
            description=description,
            attendees=attendee_ids,
            created_by=coach_id
        )
        self.events[event.id] = event
        return event

    def get_events_by_user(self, user_id: str) -> List[Event]:
        return [event for event in self.events.values() if user_id in event.attendees]

    def get_events_by_date(self, date: datetime) -> List[Event]:
        start_of_day = date.replace(hour=0, minute=0, second=0, microsecond=0)
        end_of_day = date.replace(hour=23, minute=59, second=59, microsecond=999999)
        return [
            event for event in self.events.values()
            if start_of_day <= event.start_time <= end_of_day
        ]

    def send_announcement(self, coach_id: str, message: str, to_all: bool = True, recipient_ids: List[str] = None) -> str:
        if coach_id not in self.users or self.users[coach_id].role != Role.COACH:
            raise ValueError("Only coaches can send announcements.")
        if to_all:
            recipients = [user.id for user in self.get_players()]
        else:
            recipients = recipient_ids or []
            for r in recipients:
                if r not in self.users or not self.users[r].is_active:
                    raise ValueError(f"Invalid recipient: {r}")
        # In a real app, this would trigger push/email/SMS
        # Here we simulate by logging the announcement
        announcement = {
            "from": coach_id,
            "message": message,
            "to": recipients,
            "timestamp": datetime.now().isoformat()
        }
        # Store in memory for demo (in production, store in DB)
        if not hasattr(self, '_announcements'):
            self._announcements = []
        self._announcements.append(announcement)
        return f"Announcement sent to {len(recipients)} recipients."

    # PERFORMANCE TRACKING MODULE
    def add_performance_metric(self, player_id: str, metric_name: str, value: float, unit: str, 
                              source: str = "manual", notes: str = "") -> PerformanceMetric:
        if player_id not in self.users or self.users[player_id].role != Role.PLAYER or not self.users[player_id].is_active:
            raise ValueError("Invalid or inactive player.")
        if source not in ["manual", "wearable"]:
            raise ValueError("Source must be 'manual' or 'wearable'.")
        metric = PerformanceMetric(
            player_id=player_id,
            metric_name=metric_name,
            value=value,
            unit=unit,
            source=source,
            notes=notes
        )
        self.performance_metrics.append(metric)
        return metric

    def get_player_performance(self, player_id: str, metric_name: str = None) -> List[PerformanceMetric]:
        metrics = [m for m in self.performance_metrics if m.player_id == player_id]
        if metric_name:
            metrics = [m for m in metrics if m.metric_name == metric_name]
        return sorted(metrics, key=lambda m: m.timestamp)

    def get_team_performance_stats(self, metric_name: str) -> Dict[str, Any]:
        player_metrics = {}
        for player in self.get_players():
            metrics = self.get_player_performance(player.id, metric_name)
