class UserManagement:
    def __init__(self):
        self.players: Dict[str, Player] = {}
        self.coaches: Dict[str, Player] = {}

    def add_player(self, player_id: str, name: str, email: str, role: str = "", team: str = "") -> Player:
        if player_id in self.players or player_id in self.coaches:
            raise ValueError(f"Player or coach with ID {player_id} already exists")
        player = Player(player_id, name, email, role, team)
        self.players[player_id] = player
        return player

    def add_coach(self, coach_id: str, name: str, email: str) -> Player:
        if coach_id in self.players or coach_id in self.coaches:
            raise ValueError(f"Player or coach with ID {coach_id} already exists")
        coach = Player(coach_id, name, email, role="Coach", team="")
        self.coaches[coach_id] = coach
        return coach

    def get_player(self, player_id: str) -> Optional[Player]:
        return self.players.get(player_id)

    def get_coach(self, coach_id: str) -> Optional[Player]:
        return self.coaches.get(coach_id)

    def update_player_profile(self, player_id: str, **kwargs) -> bool:
        player = self.get_player(player_id)
        if not player:
            return False
        for key, value in kwargs.items():
            if hasattr(player, key):
                setattr(player, key, value)
        return True

    def list_players(self) -> List[Player]:
        return list(self.players.values())

