class SchedulingAndCommunication:
    def __init__(self, user_management: UserManagement):
        self.user_management = user_management
        self.events: Dict[str, Event] = {}
        self.messages: Dict[str, Message] = {}
        self.message_queue = queue.Queue()
        self._setup_message_thread()

    def create_event(self, event_id: str, title: str, event_type: EventType, start_time: str, end_time: str, location: str, description: str = "", attendee_ids: List[str] = None) -> Event:
        if attendee_ids is None:
            attendee_ids = []
        # Validate all attendees exist
        for pid in attendee_ids:
            if pid not in self.user_management.players and pid not in self.user_management.coaches:
                raise ValueError(f"Attendee with ID {pid} does not exist")
        event = Event(event_id, title, event_type, start_time, end_time, location, description, attendee_ids)
        self.events[event_id] = event
        return event

    def get_event(self, event_id: str) -> Optional[Event]:
        return self.events.get(event_id)

    def update_event(self, event_id: str, **kwargs) -> bool:
        event = self.get_event(event_id)
        if not event:
            return False
        for key, value in kwargs.items():
            if hasattr(event, key):
                setattr(event, key, value)
        return True

    def delete_event(self, event_id: str) -> bool:
        if event_id in self.events:
            del self.events[event_id]
            return True
        return False

    def send_message(self, sender_id: str, recipient_ids: List[str], content: str) -> Message:
        if sender_id not in self.user_management.players and sender_id not in self.user_management.coaches:
            raise ValueError(f"Sender with ID {sender_id} does not exist")
        for rid in recipient_ids:
            if rid not in self.user_management.players and rid not in self.user_management.coaches:
                raise ValueError(f"Recipient with ID {rid} does not exist")
        message_id = f"msg_{int(time.time()*1000)}_{random.randint(1000,9999)}"
        message = Message(message_id, sender_id, recipient_ids, content, time.strftime("%Y-%m-%dT%H:%M:%SZ"))
        # Initialize read status for all recipients
        message.read_status = {rid: False for rid in recipient_ids}
        self.messages[message_id] = message
        self.message_queue.put(message)
        return message

    def _setup_message_thread(self):
        def message_worker():
            while True:
                try:
                    message = self.message_queue.get(timeout=1)
                    # In a real app, this would trigger push notifications or email
                    # Here we just log
                    print(f"[Notification] Message sent: {message.content} to {message.recipient_ids}")
                    self.message_queue.task_done()
                except queue.Empty:
                    continue
        thread = threading.Thread(target=message_worker, daemon=True)
        thread.start()

    def get_unread_messages(self, player_id: str) -> List[Message]:
        return [
            msg for msg in self.messages.values()
            if player_id in msg.recipient_ids and not msg.read_status.get(player_id, False)
        ]

    def mark_message_as_read(self, message_id: str, player_id: str) -> bool:
        message = self.messages.get(message_id)
        if not message or player_id not in message.recipient_ids:
            return False
        message.read_status[player_id] = True
        return True

